function getResolvedSectoresCatalog(): SectorIafEntity[] {
  const archivedIds = state.archiveGovernance.archivedCatalogIds;
  const raw = state.domainData.iafSectors;
  const mapped: SectorIafEntity[] =
    raw && raw.length > 0
      ? raw.map((sec, idx) => {
          const fallback =
            INITIAL_SECTORES_IAF.find((s) => s.id === sec.id || s.sector === sec.sector) ||
            INITIAL_SECTORES_IAF[idx % INITIAL_SECTORES_IAF.length];
          return {
            id: sec.id || fallback.id,
            sector: sec.sector || fallback.sector,
            descripcion: sec.descripcion || fallback.descripcion,
            subsectores_count:
              sec.subsectores_count ??
              (fallback.sector === sec.sector ? fallback.subsectores_count : 1),
            auditores_count:
              sec.auditores_count ??
              (fallback.sector === sec.sector ? fallback.auditores_count : 1),
          };
        })
      : [...INITIAL_SECTORES_IAF];
  return mapped
    .filter((s) => !archivedIds.has(s.id))
    .sort((a, b) => a.sector - b.sector);
}

function getResolvedSubsectoresCatalog(): SubsectorIafEntity[] {
  const archivedIds = state.archiveGovernance.archivedCatalogIds;
  const raw =
    state.domainData.iafSubsectors.length > 0
      ? state.domainData.iafSubsectors
      : INITIAL_SUBSECTORES_IAF;
  return raw.filter((sub) => !archivedIds.has(sub.id));
}

function getScopedAuditsForSharedNav(): ProgramacionAuditEntity[] {
  const rawAudits =
    state.domainData.programacionAudits.length > 0
      ? state.domainData.programacionAudits
      : isApprovedStaff()
      ? buildSeededProgramsFallback().flatMap((p) => p.auditorias)
      : [];
  return scopeProgramacionAuditsForProfile(
    rawAudits,
    state.profile,
    state.authorizedClientOrgIds
  );
}

function syncSharedSelectionState(opts: {
  preferredCertId?: string | null;
  preferredAuditId?: string | null;
}): {
  selectedCertId: string | null;
  selectedAuditId: string | null;
  audit: ProgramacionAuditEntity | null;
  programId: string | null;
} {
  const scopedAudits = getScopedAuditsForSharedNav();
  const resolved = resolveSharedAuditSelection({
    selectedCertId: state.auditoriasSelection.selectedCertId,
    selectedAuditId: state.auditoriasSelection.selectedAuditId,
    audits: scopedAudits,
    preferredCertId: opts.preferredCertId,
    preferredAuditId: opts.preferredAuditId,
  });
  state.auditoriasSelection = {
    selectedCertId: resolved.selectedCertId,
    selectedAuditId: resolved.selectedAuditId,
  };
  return resolved;
}

function navigateAuditDetailWithSharedSelection(
  targetSubviewRaw: string,
  resolved: {
    selectedCertId: string | null;
    selectedAuditId: string | null;
    audit: ProgramacionAuditEntity | null;
    programId: string | null;
  }
): void {
  const normalized = normalizeAuditCardSubview(targetSubviewRaw) || 'designacion/tipo';
  const effectiveSub =
    normalized === 'relacion' ||
    normalized === 'resultado' ||
    normalized === 'revision' ||
    normalized === 'resumen' ||
    normalized === 'tiempo' ||
    normalized === 'auditor' ||
    normalized === 'proceso' ||
    normalized === 'turno' ||
    normalized === 'designacion/tipo' ||
    normalized === 'designacion/fecha' ||
    normalized === 'designacion/sitio' ||
    normalized === 'designacion/temporal'
      ? normalized
      : 'designacion/tipo';

  state.auditoriasSelection = {
    selectedCertId: resolved.selectedCertId,
    selectedAuditId: resolved.selectedAuditId,
  };
  state.activeRoute = 'auditorias';
  state.activeSubSection = effectiveSub;

  const targetProgramId =
    resolved.programId ||
    resolved.audit?.id_programa_auditoria ||
    state.designacionTipoDomain.selectedProgramId ||
    state.designacionSitioDomain.selectedProgramId ||
    state.designacionTemporalDomain.selectedProgramId ||
    state.tiempoDomain.selectedProgramId ||
    state.asignacionDomain.selectedProgramId ||
    null;
  const targetAuditId = resolved.selectedAuditId;

  if (effectiveSub === 'relacion') {
    state.relacionDomain.selectedCertId = resolved.selectedCertId;
    state.relacionDomain.selectedAuditId = targetAuditId;
    state.relacionDomain.pickerTargetGroupKey = null;
    state.relacionDomain.savingAuditId = null;
    state.relacionDomain.editErrorMessage = null;
  } else if (effectiveSub === 'designacion/tipo') {
    state.designacionTipoDomain.selectedCertId = resolved.selectedCertId;
    state.designacionTipoDomain.selectedAuditId = targetAuditId;
    state.designacionTipoDomain.selectedProgramId = targetProgramId;
    state.designacionTipoDomain.editErrorMessage = null;
  } else if (effectiveSub === 'designacion/fecha') {
    state.designacionFechaDomain.selectedCertId = resolved.selectedCertId;
    state.designacionFechaDomain.selectedAuditId = targetAuditId;
    state.designacionFechaDomain.draftAuditId = null;
    state.designacionFechaDomain.drafts = null;
    state.designacionFechaDomain.editorMode = null;
    state.designacionFechaDomain.editingLocalId = null;
    state.designacionFechaDomain.editorDraft = null;
    state.designacionFechaDomain.saving = false;
    state.designacionFechaDomain.editErrorMessage = null;
  } else if (effectiveSub === 'designacion/sitio') {
    const isSwitchingContext =
      state.activeSubSection !== 'designacion/sitio' ||
      state.designacionSitioDomain.selectedCertId !== resolved.selectedCertId ||
      state.designacionSitioDomain.selectedAuditId !== targetAuditId;
    state.designacionSitioDomain.selectedCertId = resolved.selectedCertId;
    state.designacionSitioDomain.selectedAuditId = targetAuditId;
    state.designacionSitioDomain.selectedProgramId = targetProgramId;
    state.designacionSitioDomain.coverageModalCertId = null;
    state.designacionSitioDomain.coverageModalAuditId = null;
    state.designacionSitioDomain.coverageWindowOffset = 0;
    state.designacionSitioDomain.editErrorMessage = null;
    if (isSwitchingContext) {
      state.designacionSitioDomain.isSitePanelExpandedByAuditId = {};
      state.designacionSitioDomain.detailFilterMode = DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.filterMode;
      state.designacionSitioDomain.notAuditedLastN =
        DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.notAuditedLastN;
      state.designacionSitioDomain.detailSortMode = DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.sortMode;
      state.designacionSitioDomain.detailSearchQuery =
        DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.searchQuery ?? '';
    }
  } else if (effectiveSub === 'designacion/temporal') {
    state.designacionTemporalDomain.selectedCertId = resolved.selectedCertId;
    state.designacionTemporalDomain.selectedAuditId = targetAuditId;
    state.designacionTemporalDomain.selectedProgramId = targetProgramId;
    state.designacionTemporalDomain.draftAuditId = null;
    state.designacionTemporalDomain.batchDraft = null;
    state.designacionTemporalDomain.confirmDisableBatch = false;
    state.designacionTemporalDomain.editErrorMessage = null;
  } else if (effectiveSub === 'tiempo') {
    state.tiempoDomain.selectedCertId = resolved.selectedCertId;
    state.tiempoDomain.selectedAuditId = targetAuditId;
    state.tiempoDomain.selectedProgramId = targetProgramId;
    state.tiempoDomain.editErrorMessage = null;
  } else if (effectiveSub === 'auditor') {
    state.asignacionDomain.selectedCertId = resolved.selectedCertId;
    state.asignacionDomain.selectedAuditId = targetAuditId;
    state.asignacionDomain.selectedProgramId = targetProgramId;
    state.asignacionDomain.draftTargetKind = 'REGULAR';
    state.asignacionDomain.draftTargetId = null;
    state.asignacionDomain.editErrorMessage = null;
  } else if (effectiveSub === 'proceso') {
    state.programaProcesosDomain.selectedCertId = resolved.selectedCertId;
    state.programaProcesosDomain.selectedAuditId = targetAuditId;
    state.programaProcesosDomain.selectedProgramId = targetProgramId;
    state.programaProcesosDomain.openHistoryDrawerProcessIds = [];
    state.programaProcesosDomain.savingSitePlanId = null;
    state.programaProcesosDomain.editErrorMessage = null;
    state.programaDomain.selectedAuditId = targetAuditId;
    state.programaDomain.activeMiniStep = 'procesos';
    state.programaDomain.openHistoryDrawerProcessIds = [];
    state.programaDomain.editErrorMessage = null;
  } else if (effectiveSub === 'turno') {
    state.programaTurnosDomain.selectedCertId = resolved.selectedCertId;
    state.programaTurnosDomain.selectedAuditId = targetAuditId;
    state.programaTurnosDomain.selectedProgramId = targetProgramId;
    state.programaTurnosDomain.focusedSitePlanId = null;
    state.programaTurnosDomain.onlyPending = false;
    state.programaTurnosDomain.batchSelectedTpsIdsBySitePlanId = {};
    state.programaTurnosDomain.savingSitePlanId = null;
    state.programaTurnosDomain.editErrorMessage = null;
    state.programaDomain.selectedAuditId = targetAuditId;
    state.programaDomain.activeMiniStep = 'turnos';
    state.programaDomain.openHistoryDrawerProcessIds = [];
    state.programaDomain.editErrorMessage = null;
  } else if (effectiveSub === 'resultado') {
    state.resultadoDomain.selectedCertId = resolved.selectedCertId;
    state.resultadoDomain.selectedResultAuditId = targetAuditId;
    state.resultadoDomain.activeAuditIdForDecision =
      targetAuditId || state.resultadoDomain.activeAuditIdForDecision;
    state.resultadoDomain.selectedAuditId = targetAuditId || 'ALL';
    state.resultadoDomain.recommendationError = null;
    state.resultadoDomain.recommendationSuccess = null;
    state.resultadoDomain.realDateFormDraft = undefined;
    state.resultadoDomain.newRealDateDraft = '';
    state.resultadoDomain.savingRealDate = false;
    state.resultadoDomain.realDateError = null;
    state.resultadoDomain.realDateSuccess = null;
    state.resultadoDomain.newNcDraft = { id_requisito: '', tipo: 'NC_MENOR', descripcion: '' };
    state.resultadoDomain.savingNewNc = false;
    state.resultadoDomain.findingFormError = null;
    state.resultadoDomain.ncDatesDraftByFindingId = {};
    state.resultadoDomain.savingFindingId = null;
    state.resultadoDomain.findingDatesError = null;
    state.resultadoDomain.findingDatesSuccess = null;
    state.resultadoDomain.closingDateDraft = undefined;
    state.resultadoDomain.closingError = null;
    state.resultadoDomain.closingSuccess = null;
    state.resultadoDomain.isNcOffsetsModalOpen = false;
  } else if (effectiveSub === 'revision') {
    state.revisionDomain.selectedCertId = resolved.selectedCertId;
    state.revisionDomain.selectedAuditId = targetAuditId;
    state.revisionDomain.formDraft = undefined;
    state.revisionDomain.editErrorMessage = null;
    state.revisionDomain.saveSuccessMessage = null;
  } else if (effectiveSub === 'resumen') {
    state.resumenDomain.selectedCertId = resolved.selectedCertId;
    state.resumenDomain.selectedAuditId = targetAuditId;
    state.resumenAuditId = targetAuditId;
  }

  const isCertBasedSub =
    effectiveSub === 'relacion' ||
    effectiveSub.startsWith('designacion/') ||
    effectiveSub === 'tiempo' ||
    effectiveSub === 'auditor' ||
    effectiveSub === 'proceso' ||
    effectiveSub === 'turno' ||
    effectiveSub === 'resultado' ||
    effectiveSub === 'revision' ||
    effectiveSub === 'resumen';
  const subLabel = getSubviewLabel('auditorias', effectiveSub);
  const certNumLabel = resolved.audit?.numero_certificado || 'Certificado';
  const auditCode =
    resolved.audit?.codigo_auditoria || resolved.audit?.numero_certificado || 'Auditoría';
  const baseTrail = resetBreadcrumbToDomain('auditorias', effectiveSub);
  state.breadcrumbs =
    resolved.selectedCertId || targetAuditId || targetProgramId
      ? pushBreadcrumb(baseTrail, {
          id: `detail-${effectiveSub}-${resolved.selectedCertId || targetAuditId || targetProgramId}`,
          label: isCertBasedSub
            ? certNumLabel.length > 24
              ? `${certNumLabel.slice(0, 21)}...`
              : certNumLabel
            : auditCode.length > 24
            ? `${auditCode.slice(0, 21)}...`
            : auditCode,
          route: 'auditorias',
          subview: effectiveSub,
          entityType: isCertBasedSub ? 'cert' : 'programa_auditoria',
          entityId: isCertBasedSub
            ? resolved.selectedCertId || targetAuditId || targetProgramId
            : targetAuditId || targetProgramId,
          tooltip: `${subLabel} > ${isCertBasedSub ? certNumLabel : auditCode}`,
        })
      : baseTrail;

  syncUrlHash('auditorias', effectiveSub);
  render();
}

