  document.getElementById('vinculoAssignModal')?.addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      state.vinculoDomain = closeAssignCertModalState(state.vinculoDomain);
      renderVinculoPreservingScroll();
    }
  });

  document
    .querySelectorAll<HTMLElement>('[data-action="toggle-assign-modal-box"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const boxId = btn.dataset.vinculoId || '';
        if (!boxId) return;
        state.vinculoDomain = toggleAssignModalBoxExpanded(state.vinculoDomain, boxId);
        renderVinculoPreservingScroll();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="confirm-assign-cert-to-box"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const targetBoxId = btn.dataset.vinculoId || '';
        const certId = btn.dataset.certId || '';
        const congId = state.vinculoDomain.selectedConglomeradoId || '';
        if (!targetBoxId || !certId || !congId) return;

        const plan = validateAssignCertToBox({
          certId,
          targetBoxId,
          conglomeradoId: congId,
          vinculos: state.domainData.allVinculos,
          certificados: state.domainData.allCertificadosDetailed,
          organizaciones: state.domainData.allOrganizaciones,
        });

        if (!plan.allowed) {
          state.vinculoDomain.assignModalErrorMessage = plan.errorMessage;
          renderVinculoPreservingScroll();
          return;
        }

        const cert = state.domainData.allCertificadosDetailed.find(
          (c) => !c.deleted_at && c.id === certId
        );
        const targetBox = state.domainData.allVinculos.find(
          (v) => !v.deleted_at && v.id === targetBoxId
        );
        if (!cert || !targetBox) return;

        const prevVinculos = state.domainData.allVinculos;
        const newLinkId = crypto.randomUUID();
        const org = state.domainData.allOrganizaciones.find(
          (o) => !o.deleted_at && o.id === cert.id_organizacion
        );
        const newMember: VinculoCertificadoItem = {
          id: newLinkId,
          id_vinculo: targetBox.id,
          id_certificado: cert.id,
          numero_certificado: cert.numero_certificado,
          norma_codigo: cert.norma_codigo,
          id_organizacion: cert.id_organizacion,
          organizacion_nombre: org?.nombre || cert.organizacion_nombre,
          organizacion_abreviacion:
            org?.abreviacion ?? cert.organizacion_abreviacion ?? null,
          tipo_vinculacion_override: null,
          estatus: cert.estatus,
          deleted_at: null,
        };

        const nextNivel = plan.derivedNivel ?? targetBox.nivel_vinculacion;
        const nextEsVinculada = plan.derivedEsVinculada ?? targetBox.es_vinculada;
        const boxMetadataChanged =
          nextNivel !== targetBox.nivel_vinculacion ||
          nextEsVinculada !== targetBox.es_vinculada;

        state.domainData.allVinculos = state.domainData.allVinculos.map((v) =>
          v.id === targetBox.id
            ? {
                ...v,
                nivel_vinculacion: nextNivel,
                es_vinculada: nextEsVinculada,
                certificados: [
                  ...v.certificados.filter(
                    (vc) => !vc.deleted_at && vc.id_certificado !== cert.id
                  ),
                  newMember,
                ],
              }
            : v
        );
        state.vinculoDomain = closeAssignCertModalState(state.vinculoDomain);
        state.vinculoDomain.editErrorMessage = null;

        void (async () => {
          if (boxMetadataChanged) {
            const { error: boxErr } = await supabase
              .from('vinculo')
              .update({
                nivel_vinculacion: nextNivel,
                es_vinculada: nextEsVinculada,
              })
              .eq('id', targetBox.id);
            if (boxErr) {
              state.domainData.allVinculos = prevVinculos;
              const msg = formatZeroUuidError(
                boxErr,
                'No se pudo actualizar la caja destino al asignar el certificado.'
              );
              state.vinculoDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              renderVinculoPreservingScroll();
              return;
            }
          }

          const { error: linkErr } = await supabase.from('vinculo_certificado').insert({
            id: newLinkId,
            id_vinculo: targetBox.id,
            id_certificado: cert.id,
            tipo_vinculacion_override: null,
          });
          if (linkErr) {
            state.domainData.allVinculos = prevVinculos;
            const msg = formatZeroUuidError(
              linkErr,
              'No se pudo asignar el certificado a la caja seleccionada.'
            );
            state.vinculoDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            renderVinculoPreservingScroll();
          }
        })();

        showFloatingToast(
          `Certificado ${cert.numero_certificado} asignado a «${targetBox.etiqueta}».`,
          'success'
        );
        renderVinculoPreservingScroll();
      });
    });

  const quickCreateForm = document.getElementById(
    'assignModalQuickCreateBoxForm'
  ) as HTMLFormElement | null;
  if (quickCreateForm) {
    quickCreateForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!isApprovedStaff()) return;
      const certId = quickCreateForm.dataset.certId || '';
      const congId = state.vinculoDomain.selectedConglomeradoId || '';
      if (!isValidUuid(certId) || !isValidUuid(congId)) return;

      const cert = state.domainData.allCertificadosDetailed.find(
        (c) => !c.deleted_at && c.id === certId
      );
      if (!cert) return;

      const fd = new FormData(quickCreateForm);
      const etiqueta = String(fd.get('etiqueta') || '');
      const tipoVinculacion = parseVinculoNatureFromInput(
        String(fd.get('tipo_vinculacion') || 'Combinada')
      );
      const check = validateVinculoBoxMetadataDraft({
        etiqueta,
        tipo_vinculacion: tipoVinculacion,
        certs: [
          {
            id_certificado: cert.id,
            id_organizacion: cert.id_organizacion,
            norma_codigo: cert.norma_codigo,
          },
        ],
      });
      if (!check.valid) {
        state.vinculoDomain.assignModalErrorMessage = check.errorMessage;
        renderVinculoPreservingScroll();
        return;
      }

      const prevVinculos = state.domainData.allVinculos;
      const newBoxId = crypto.randomUUID();
      const newLinkId = crypto.randomUUID();
      const cong = state.domainData.allConglomerados.find((g) => g.id === congId);
      const org = state.domainData.allOrganizaciones.find(
        (o) => !o.deleted_at && o.id === cert.id_organizacion
      );
      const newBox: VinculoEntity = {
        id: newBoxId,
        id_grupo_empresarial: congId,
        grupo_nombre: cong?.nombre || 'Conglomerado',
        codigo_vinculo: generateUniqueVinculoCode(check.es_vinculada, newBoxId),
        etiqueta: etiqueta.trim(),
        nivel_vinculacion: check.nivel_vinculacion,
        tipo_vinculacion: check.tipo_vinculacion,
        es_vinculada: check.es_vinculada,
        tiene_sitio_temporal: false,
        notas: null,
        certificados: [
          {
            id: newLinkId,
            id_vinculo: newBoxId,
            id_certificado: cert.id,
            numero_certificado: cert.numero_certificado,
            norma_codigo: cert.norma_codigo,
            id_organizacion: cert.id_organizacion,
            organizacion_nombre: org?.nombre || cert.organizacion_nombre,
            organizacion_abreviacion:
              org?.abreviacion ?? cert.organizacion_abreviacion ?? null,
            tipo_vinculacion_override: null,
            estatus: cert.estatus,
            deleted_at: null,
          },
        ],
        deleted_at: null,
      };

      state.domainData.allVinculos = [newBox, ...state.domainData.allVinculos];
      state.vinculoDomain = closeAssignCertModalState(state.vinculoDomain);
      state.vinculoDomain.editErrorMessage = null;

      void (async () => {
        const { error: boxErr } = await supabase.from('vinculo').insert({
          id: newBox.id,
          id_grupo_empresarial: newBox.id_grupo_empresarial,
          codigo_vinculo: newBox.codigo_vinculo,
          etiqueta: newBox.etiqueta,
          nivel_vinculacion: newBox.nivel_vinculacion,
          tipo_vinculacion: newBox.tipo_vinculacion,
          es_vinculada: newBox.es_vinculada,
          tiene_sitio_temporal: false,
          notas: null,
        });
        if (boxErr) {
          state.domainData.allVinculos = prevVinculos;
          const msg = formatZeroUuidError(
            boxErr,
            'No se pudo crear la nueva caja agrupadora.'
          );
          state.vinculoDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 5500);
          renderVinculoPreservingScroll();
          return;
        }
        const { error: linkErr } = await supabase.from('vinculo_certificado').insert({
          id: newLinkId,
          id_vinculo: newBox.id,
          id_certificado: cert.id,
          tipo_vinculacion_override: null,
        });
        if (linkErr) {
          state.domainData.allVinculos = prevVinculos;
          const msg = formatZeroUuidError(
            linkErr,
            'Se creó la caja pero no se pudo asociar el certificado.'
          );
          state.vinculoDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 5500);
          renderVinculoPreservingScroll();
        }
      })();

      showFloatingToast(
        `Caja «${newBox.etiqueta}» creada con ${cert.numero_certificado}.`,
        'success'
      );
      renderVinculoPreservingScroll();
    });
  }

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-cert-nature-override"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        if (!isApprovedStaff()) return;
        const boxId = sel.dataset.vinculoId || '';
        const certId = sel.dataset.certId || '';
        const requestedOverride = sel.value.trim() ? sel.value.trim() : null;
        const box = state.domainData.allVinculos.find((v) => !v.deleted_at && v.id === boxId);
        if (!box || !certId) return;

        const linkItem = box.certificados.find(
          (vc) => !vc.deleted_at && vc.id_certificado === certId
        );
        if (!linkItem) return;

        const validation = validateCertNatureOverride({
          box,
          certId,
          requestedOverride,
        });
        const applied = applyCertNatureOverrideInBox({
          box,
          certId,
          requestedOverride,
        });
        if (!validation.valid || !applied.valid || !applied.updatedBox) {
          const msg =
            validation.errorMessage ||
            applied.errorMessage ||
            'No se pudo actualizar la naturaleza del certificado.';
          state.vinculoDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 5000);
          renderVinculoPreservingScroll();
          return;
        }

        const prevVinculos = state.domainData.allVinculos;
        state.domainData.allVinculos = state.domainData.allVinculos.map((v) =>
          v.id === box.id ? applied.updatedBox! : v
        );
        state.vinculoDomain.editErrorMessage = null;

        void (async () => {
          if (!isValidUuid(linkItem.id)) return;
          const { error } = await supabase
            .from('vinculo_certificado')
            .update({
              tipo_vinculacion_override: validation.normalizedOverride,
            })
            .eq('id', linkItem.id);
          if (error) {
            state.domainData.allVinculos = prevVinculos;
            const msg = formatZeroUuidError(
              error,
              'No se pudo guardar la naturaleza específica del certificado.'
            );
            state.vinculoDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            renderVinculoPreservingScroll();
          }
        })();

        showFloatingToast(
          validation.normalizedOverride
            ? `Naturaleza de ${linkItem.numero_certificado} ajustada a ${validation.normalizedOverride}.`
            : `${linkItem.numero_certificado} hereda la naturaleza de la caja (${box.tipo_vinculacion}).`,
          'success'
        );
        renderVinculoPreservingScroll();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="detach-cert-to-libre"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const boxId = btn.dataset.vinculoId || '';
        const certId = btn.dataset.certId || '';
        const box = state.domainData.allVinculos.find((v) => !v.deleted_at && v.id === boxId);
        if (!box || !certId) return;

        const linkItem = box.certificados.find(
          (vc) => !vc.deleted_at && vc.id_certificado === certId
        );
        if (!linkItem) return;

        const check = canDetachCertificateFromVinculo(
          certId,
          boxId,
          state.domainData.auditPrograms,
          state.domainData.programacionAudits
        );
        if (!check.allowed) {
          state.vinculoDomain.editErrorMessage = check.reason;
          if (check.reason) showFloatingToast(check.reason, 'warning', 5500);
          renderVinculoPreservingScroll();
          return;
        }

        const prevVinculos = state.domainData.allVinculos;
        state.domainData.allVinculos = state.domainData.allVinculos.map((v) =>
          v.id === boxId
            ? {
                ...v,
                certificados: v.certificados.filter(
                  (vc) => !vc.deleted_at && vc.id_certificado !== certId
                ),
              }
            : v
        );
        state.vinculoDomain.editErrorMessage = null;

        void (async () => {
          if (!isValidUuid(linkItem.id)) return;
          const { error: arcErr } = await supabase.rpc('archive_record', {
            p_table: 'vinculo_certificado',
            p_record_id: linkItem.id,
            p_reason: 'Certificado devuelto a estado LIBRE desde Certificación → Vínculo',
          });
          if (arcErr) {
            state.domainData.allVinculos = prevVinculos;
            const msg = formatZeroUuidError(
              arcErr,
              'No se pudo desvincular el certificado de la caja.'
            );
            state.vinculoDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            renderVinculoPreservingScroll();
          }
        })();

        showFloatingToast(
          `Certificado ${linkItem.numero_certificado} devuelto a LIBRE.`,
          'success'
        );
        renderVinculoPreservingScroll();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="archive-vinculo-box"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const boxId = btn.dataset.vinculoId || '';
        const box = state.domainData.allVinculos.find((v) => !v.deleted_at && v.id === boxId);
        if (!box) return;

        const check = canArchiveVinculoBox(
          box,
          state.domainData.auditPrograms,
          state.domainData.programacionAudits
        );
        if (!check.allowed) {
          state.vinculoDomain.editErrorMessage = check.reason;
          if (check.reason) showFloatingToast(check.reason, 'warning', 5500);
          renderVinculoPreservingScroll();
          return;
        }

        const prevVinculos = state.domainData.allVinculos;
        state.domainData.allVinculos = state.domainData.allVinculos.filter(
          (v) => v.id !== boxId
        );
        if (state.vinculoDomain.editingBoxId === boxId) {
          state.vinculoDomain.editingBoxId = null;
          state.vinculoDomain.boxFormDraft = undefined;
        }
        state.vinculoDomain.editErrorMessage = null;

        void (async () => {
          const { error } = await supabase.rpc('archive_record', {
            p_table: 'vinculo',
            p_record_id: boxId,
            p_reason: 'Caja agrupadora vacía archivada desde Certificación → Vínculo',
          });
          if (error && !/no se encontró un registro activo/i.test(error.message || '')) {
            state.domainData.allVinculos = prevVinculos;
            const msg = formatZeroUuidError(
              error,
              'No se pudo archivar la caja agrupadora vacía.'
            );
            state.vinculoDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            renderVinculoPreservingScroll();
          }
        })();

        showFloatingToast(`Caja «${box.etiqueta}» archivada.`, 'success');
        renderVinculoPreservingScroll();
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 5.1 SHELL CERTIFICATE-BASED (`1. Designación`)
  // ===============================================
  const applyCertificateSectionSelection = (
    rawSubview: string,
    certId: string,
    preferredAuditId: string | null = null
  ): void => {
    if (!certId) return;
    const subview = normalizeDomainSubview('auditorias', rawSubview || 'designacion/tipo');
    const scopedAudits = getScopedAuditsForSharedNav();
    const fallbackAuditId =
      preferredAuditId ??
      (state.auditoriasSelection.selectedCertId === certId
        ? state.auditoriasSelection.selectedAuditId
        : null);
    const resolvedAudit = resolveDefaultAuditForCertificate(certId, fallbackAuditId, scopedAudits);

    clearAllEntitySelections();
    state.activeRoute = 'auditorias';
    state.activeSubSection = subview;
    state.auditoriasSelection = {
      selectedCertId: certId,
      selectedAuditId: resolvedAudit?.id ?? null,
    };

    if (subview === 'relacion') {
      state.relacionDomain.selectedCertId = certId;
      state.relacionDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.relacionDomain.pickerTargetGroupKey = null;
      state.relacionDomain.savingAuditId = null;
      state.relacionDomain.editErrorMessage = null;
    } else if (subview === 'designacion/tipo') {
      state.designacionTipoDomain.selectedCertId = certId;
      state.designacionTipoDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.designacionTipoDomain.selectedProgramId = resolvedAudit?.id_programa_auditoria ?? null;
      state.designacionTipoDomain.editErrorMessage = null;
    } else if (subview === 'designacion/fecha') {
      state.designacionFechaDomain.selectedCertId = certId;
      state.designacionFechaDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.designacionFechaDomain.draftAuditId = null;
      state.designacionFechaDomain.drafts = null;
      state.designacionFechaDomain.editorMode = null;
      state.designacionFechaDomain.editingLocalId = null;
      state.designacionFechaDomain.editorDraft = null;
      state.designacionFechaDomain.saving = false;
      state.designacionFechaDomain.editErrorMessage = null;
    } else if (subview === 'designacion/sitio') {
      state.designacionSitioDomain.selectedCertId = certId;
      state.designacionSitioDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.designacionSitioDomain.selectedProgramId = resolvedAudit?.id_programa_auditoria ?? null;
      state.designacionSitioDomain.coverageModalCertId = null;
      state.designacionSitioDomain.coverageModalAuditId = null;
      state.designacionSitioDomain.coverageWindowOffset = 0;
      state.designacionSitioDomain.editErrorMessage = null;
    } else if (subview === 'designacion/temporal') {
      state.designacionTemporalDomain.selectedCertId = certId;
      state.designacionTemporalDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.designacionTemporalDomain.selectedProgramId = resolvedAudit?.id_programa_auditoria ?? null;
      state.designacionTemporalDomain.draftAuditId = null;
      state.designacionTemporalDomain.batchDraft = null;
      state.designacionTemporalDomain.confirmDisableBatch = false;
      state.designacionTemporalDomain.editErrorMessage = null;
    } else if (subview === 'tiempo') {
      state.tiempoDomain.selectedCertId = certId;
      state.tiempoDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.tiempoDomain.selectedProgramId = resolvedAudit?.id_programa_auditoria ?? null;
      state.tiempoDomain.draftTimeBySitePlanId = {};
      state.tiempoDomain.savingSitePlanId = null;
      state.tiempoDomain.editErrorMessage = null;
    } else if (subview === 'auditor') {
      state.asignacionDomain.selectedCertId = certId;
      state.asignacionDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.asignacionDomain.selectedProgramId = resolvedAudit?.id_programa_auditoria ?? null;
      state.asignacionDomain.draftTargetKind = 'REGULAR';
      state.asignacionDomain.draftTargetId = null;
      state.asignacionDomain.draftAuditorId = '';
      state.asignacionDomain.draftRol = 'AUDITOR';
      state.asignacionDomain.draftDays = '1.00';
      state.asignacionDomain.editErrorMessage = null;
    } else if (subview === 'proceso') {
      state.programaProcesosDomain.selectedCertId = certId;
      state.programaProcesosDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.programaProcesosDomain.selectedProgramId =
        resolvedAudit?.id_programa_auditoria ?? null;
      state.programaProcesosDomain.openHistoryDrawerProcessIds = [];
      state.programaProcesosDomain.savingSitePlanId = null;
      state.programaProcesosDomain.editErrorMessage = null;
      state.programaDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.programaDomain.activeMiniStep = 'procesos';
      state.programaDomain.openHistoryDrawerProcessIds = [];
      state.programaDomain.editErrorMessage = null;
    } else if (subview === 'turno') {
      state.programaTurnosDomain.selectedCertId = certId;
      state.programaTurnosDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.programaTurnosDomain.selectedProgramId =
        resolvedAudit?.id_programa_auditoria ?? null;
      state.programaTurnosDomain.focusedSitePlanId = null;
      state.programaTurnosDomain.onlyPending = false;
      state.programaTurnosDomain.batchSelectedTpsIdsBySitePlanId = {};
      state.programaTurnosDomain.savingSitePlanId = null;
      state.programaTurnosDomain.editErrorMessage = null;
      state.programaDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.programaDomain.activeMiniStep = 'turnos';
      state.programaDomain.openHistoryDrawerProcessIds = [];
      state.programaDomain.editErrorMessage = null;
    } else if (subview === 'resultado') {
      state.resultadoDomain.selectedCertId = certId;
      state.resultadoDomain.selectedResultAuditId = resolvedAudit?.id ?? null;
      state.resultadoDomain.activeAuditIdForDecision = resolvedAudit?.id ?? '';
      state.resultadoDomain.selectedAuditId = resolvedAudit?.id ?? 'ALL';
      state.resultadoDomain.newRealDateDraft = '';
      state.resultadoDomain.realDateError = null;
      state.resultadoDomain.realDateSuccess = null;
      state.resultadoDomain.newNcDraft = { id_requisito: '', tipo: 'NC_MENOR', descripcion: '' };
      state.resultadoDomain.findingFormError = null;
      state.resultadoDomain.ncDatesDraftByFindingId = {};
      state.resultadoDomain.findingDatesError = null;
      state.resultadoDomain.findingDatesSuccess = null;
      state.resultadoDomain.isNcOffsetsModalOpen = false;
    } else if (subview === 'revision') {
      state.revisionDomain.selectedCertId = certId;
      state.revisionDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.revisionDomain.formDraft = undefined;
      state.revisionDomain.editErrorMessage = null;
      state.revisionDomain.saveSuccessMessage = null;
    } else if (subview === 'resumen') {
      state.resumenDomain.selectedCertId = certId;
      state.resumenDomain.selectedAuditId = resolvedAudit?.id ?? null;
      state.resumenAuditId = resolvedAudit?.id ?? null;
    }

    const certsPool =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;
    const certMeta = certsPool.find((c) => c.id === certId);
    const certLabel =
      certMeta?.numero_certificado || resolvedAudit?.numero_certificado || 'Certificado';
    const subLabel = getSubviewLabel('auditorias', subview);
    const certBreadcrumbMeta = buildCertBreadcrumbMeta({
      certId,
      numero_certificado: certLabel,
      version_numero: resolvedAudit?.version_numero ?? certMeta?.version_actual_numero,
      organizacion_abreviacion: certMeta?.organizacion_abreviacion,
      contextPrefix: subLabel,
    });

    state.breadcrumbs = pushBreadcrumb(resetBreadcrumbToDomain('auditorias', subview), {
      id: `detail-${subview}-${certId}`,
      label: certBreadcrumbMeta.label,
      route: 'auditorias',
      subview,
      entityType: 'cert',
      entityId: certId,
      tooltip: certBreadcrumbMeta.tooltip,
    });
    syncUrlHash('auditorias', subview);
    render();
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="select-section-cert"]')
    .forEach((el) => {
      const openCert = (): void => {
        const certId = el.dataset.certId || '';
        const currentSub = normalizeDomainSubview('auditorias', state.activeSubSection);
        applyCertificateSectionSelection(currentSub, certId, null);
      };
      el.addEventListener('click', openCert);
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openCert();
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="back-to-section-multi-view"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const subview = normalizeDomainSubview(
          'auditorias',
          btn.dataset.subview || state.activeSubSection || 'designacion/tipo'
        );
        clearAllEntitySelections();
        state.activeRoute = 'auditorias';
        state.activeSubSection = subview;
        state.breadcrumbs = resetBreadcrumbToDomain('auditorias', subview);
        syncUrlHash('auditorias', subview);
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="select-section-audit"]')
    .forEach((el) => {
      if (el instanceof HTMLSelectElement) {
        el.addEventListener('change', () => {
          const auditId = el.value || '';
          const scopedAudits = getScopedAuditsForSharedNav();
          const matchedAudit = scopedAudits.find((a) => a.id === auditId);
          const certId =
            el.dataset.certId ||
            matchedAudit?.id_certificado ||
            state.auditoriasSelection.selectedCertId ||
            '';
          const currentSub = normalizeDomainSubview('auditorias', state.activeSubSection);
          applyCertificateSectionSelection(currentSub, certId, auditId || null);
        });
      } else {
        el.addEventListener('click', () => {
          const auditId = el.dataset.auditId || '';
          if (!auditId) return;
          const scopedAudits = getScopedAuditsForSharedNav();
          const matchedAudit = scopedAudits.find((a) => a.id === auditId);
          const certId =
            el.dataset.certId ||
            matchedAudit?.id_certificado ||
            state.auditoriasSelection.selectedCertId ||
            '';
          const currentSub = normalizeDomainSubview('auditorias', state.activeSubSection);
          applyCertificateSectionSelection(currentSub, certId, auditId);
        });
      }
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="step-section-audit"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const auditId = btn.dataset.auditId || '';
        if (!auditId) return;
        const scopedAudits = getScopedAuditsForSharedNav();
        const matchedAudit = scopedAudits.find((a) => a.id === auditId);
        const certId =
          btn.dataset.certId ||
          matchedAudit?.id_certificado ||
          state.auditoriasSelection.selectedCertId ||
          '';
        const currentSub = normalizeDomainSubview('auditorias', state.activeSubSection);
        applyCertificateSectionSelection(currentSub, certId, auditId);
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="select-linked-sibling-audit"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const auditId = btn.dataset.auditId || '';
        if (!auditId) return;
        const scopedAudits = getScopedAuditsForSharedNav();
        const matchedAudit = scopedAudits.find((a) => a.id === auditId);
        const certId = btn.dataset.certId || matchedAudit?.id_certificado || '';
        const currentSub = normalizeDomainSubview('auditorias', state.activeSubSection);
        applyCertificateSectionSelection(currentSub, certId, auditId);
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="jump-resumen-section"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const targetSubview = btn.dataset.targetSubview || btn.dataset.sectionKey || '';
        if (!targetSubview) return;
        const certId = btn.dataset.certId || state.auditoriasSelection.selectedCertId || null;
        const auditId = btn.dataset.auditId || state.auditoriasSelection.selectedAuditId || null;
        const resolved = syncSharedSelectionState({
          preferredCertId: certId,
          preferredAuditId: auditId,
        });
        navigateAuditDetailWithSharedSelection(targetSubview, resolved);
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 3.2 `1. RELACIÓN` (MULTI, PICKER & DETAIL)
  // ===============================================
  document
    .querySelectorAll<HTMLElement>('[data-action="open-relacion-picker"]')
    .forEach((el) => {
      const openPicker = (): void => {
        const groupKey = el.dataset.groupKey || '';
        if (!groupKey) return;
        state.relacionDomain.pickerTargetGroupKey = groupKey;
        state.relacionDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      };
      el.addEventListener('click', openPicker);
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openPicker();
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="close-relacion-picker"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        state.relacionDomain.pickerTargetGroupKey = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document.getElementById('relacionPickerModal')?.addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      state.relacionDomain.pickerTargetGroupKey = null;
      void runWithPlannerPreservedViewport(async () => {
        render();
      });
    }
  });

  document
    .querySelectorAll<HTMLElement>('[data-action="select-relacion-audit"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const certId = btn.dataset.certId || '';
        const auditId = btn.dataset.auditId || null;
        if (!certId) return;
        state.relacionDomain.pickerTargetGroupKey = null;
        applyCertificateSectionSelection('relacion', certId, auditId);
      });
    });

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-audit-relacion"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        if (!isApprovedStaff() || state.relacionDomain.savingAuditId) return;
        const auditId = sel.dataset.auditId || '';
        const nextNature = sel.value || '';
        if (!auditId || !nextNature) return;
        void runWithPlannerPreservedViewport(() =>
          updateSingleAuditRelacion(auditId, nextNature)
        );
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="apply-relacion-vinculo-base"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff() || state.relacionDomain.savingAuditId) return;
        const auditId = btn.dataset.auditId || '';
        const baseNature = btn.dataset.baseNature || '';
        if (!auditId || !baseNature) return;
        void runWithPlannerPreservedViewport(() =>
          updateSingleAuditRelacion(auditId, baseNature)
        );
      });
    });

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-batch-relacion"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        if (!isApprovedStaff() || state.relacionDomain.savingAuditId) return;
        const auditId = sel.dataset.auditId || '';
        const nextNature = sel.value || '';
        if (!auditId || !nextNature) return;
        void runWithPlannerPreservedViewport(() =>
          updateSingleAuditRelacion(auditId, nextNature, { applyToBatchProgram: true })
        );
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — DESIGNACIÓN -> TIPO
  // ===============================================
  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-step3-audit-tipo"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        if (!isApprovedStaff() || state.designacionTipoDomain.savingAuditId) return;
        const auditId = sel.dataset.auditId || '';
        const tipoId = sel.value || '';
        if (!auditId) return;
        void runWithPlannerPreservedViewport(() =>
          updateSingleStep3AuditTipo(auditId, tipoId)
        );
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 4.2 DESIGNACIÓN -> FECHA
  // ===============================================
  const getCurrentFechaAudit = (auditIdHint?: string): ProgramacionAuditEntity | null => {
    const targetId =
      auditIdHint ||
      state.designacionFechaDomain.selectedAuditId ||
      state.auditoriasSelection.selectedAuditId;
    if (!targetId) return null;
    return getScopedAuditsForSharedNav().find((a) => a.id === targetId) ?? null;
  };

  const ensureFechaDraftsForAudit = (auditIdHint?: string): {
    auditId: string;
    drafts: PlannedDateRowDraft[];
  } | null => {
    const audit = getCurrentFechaAudit(auditIdHint);
    if (!audit) return null;
    if (
      state.designacionFechaDomain.draftAuditId === audit.id &&
      state.designacionFechaDomain.drafts !== null
    ) {
      return {
        auditId: audit.id,
        drafts: sortPlannedDraftsAscending(
          state.designacionFechaDomain.drafts.map((d) => ({ ...d }))
        ),
      };
    }
    const built = sortPlannedDraftsAscending(buildPlannedDateDraftsFromAudit(audit));
    state.designacionFechaDomain.draftAuditId = audit.id;
    state.designacionFechaDomain.drafts = built;
    return { auditId: audit.id, drafts: built.map((d) => ({ ...d })) };
  };

  const syncFechaEditorDraftFromDom = (): PlannedDateRowDraft | null => {
    const base = state.designacionFechaDomain.editorDraft;
    if (!base) return null;
    const form = document.getElementById('plannedDateEditorForm') as HTMLFormElement | null;
    if (!form) return { ...base };

    const tipoEl = form.querySelector<HTMLSelectElement>('#fechaEditorTipoSelect');
    const mesEl = form.querySelector<HTMLSelectElement>('#fechaEditorMesSelect');
    const anioEl = form.querySelector<HTMLInputElement>('#fechaEditorAnioInput');
    const singleDayEl = form.querySelector<HTMLInputElement>('#fechaEditorSingleDayToggle');
    const exactaEl = form.querySelector<HTMLInputElement>('#fechaEditorExactaInput');
    const finEl = form.querySelector<HTMLInputElement>('#fechaEditorFinInput');
    const obsEl = form.querySelector<HTMLInputElement>('#fechaEditorObsInput');

    const nextTipo: 'PREPROGRAMADA_MES' | 'PROGRAMADA_EXACTA' =
      tipoEl?.value === 'PROGRAMADA_EXACTA'
        ? 'PROGRAMADA_EXACTA'
        : tipoEl?.value === 'PREPROGRAMADA_MES'
        ? 'PREPROGRAMADA_MES'
        : base.tipo_fecha;
    const singleDay = singleDayEl ? singleDayEl.checked : base.singleDay;
    const fecha_inicio = exactaEl ? exactaEl.value : base.fecha_inicio;
    const fecha_fin = singleDay ? fecha_inicio : finEl ? finEl.value : base.fecha_fin;

    const syncedDraft: PlannedDateRowDraft = {
      ...base,
      tipo_fecha: nextTipo,
      mes: mesEl ? Number(mesEl.value) || base.mes : base.mes,
      anio: anioEl ? Number(anioEl.value) || base.anio : base.anio,
      singleDay,
      fecha_inicio,
      fecha_fin,
      observacion: obsEl ? obsEl.value : base.observacion,
    };
    state.designacionFechaDomain.editorDraft = syncedDraft;
    return syncedDraft;
  };

  const closePlannedDateModal = (): void => {
    state.designacionFechaDomain.editorMode = null;
    state.designacionFechaDomain.editingLocalId = null;
    state.designacionFechaDomain.editorDraft = null;
    state.designacionFechaDomain.editErrorMessage = null;
    render();
  };

  const openEditPlannedDateModal = (auditIdHint: string, localId: string): void => {
    if (!isApprovedStaff() || state.designacionFechaDomain.saving) return;
    const ensured = ensureFechaDraftsForAudit(auditIdHint);
    if (!ensured || !localId) return;
    const target = ensured.drafts.find((d) => d.localId === localId);
    if (!target) return;
    state.designacionFechaDomain.editorMode = 'edit';
    state.designacionFechaDomain.editingLocalId = target.localId;
    state.designacionFechaDomain.editorDraft = { ...target };
    state.designacionFechaDomain.editErrorMessage = null;
    render();
  };

  const handleDeletePlannedDate = (auditIdHint: string, localId: string): void => {
    if (!isApprovedStaff() || state.designacionFechaDomain.saving) return;
    const ensured = ensureFechaDraftsForAudit(auditIdHint);
    if (!ensured || !localId) return;
    const removal = removePlannedDateDraftSafely(ensured.drafts, localId);
    if (!removal.valid) {
      const errMsg =
        removal.error || 'La fecha programada inicial puede editarse, pero no eliminarse.';
      state.designacionFechaDomain.editErrorMessage = errMsg;
      showFloatingToast(errMsg, 'warning');
      render();
      return;
    }
    const nextAscending = sortPlannedDraftsAscending(removal.drafts);
    state.designacionFechaDomain.draftAuditId = ensured.auditId;
    state.designacionFechaDomain.drafts = nextAscending;
    state.designacionFechaDomain.editErrorMessage = null;
    void runWithPlannerPreservedViewport(() =>
      saveLinkedBatchProgrammedDates(ensured.auditId, nextAscending)
    );
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="open-add-planned-date"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff() || state.designacionFechaDomain.saving) return;
        const ensured = ensureFechaDraftsForAudit(btn.dataset.auditId);
        if (!ensured) return;
        const nextRow = createEmptyPlannedDateDraft(ensured.drafts.length);
        state.designacionFechaDomain.editorMode = 'add';
        state.designacionFechaDomain.editingLocalId = null;
        state.designacionFechaDomain.editorDraft = nextRow;
        state.designacionFechaDomain.editErrorMessage = null;
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="open-edit-planned-date"]')
    .forEach((el) => {
      el.addEventListener('click', () => {
        openEditPlannedDateModal(el.dataset.auditId || '', el.dataset.localId || '');
      });
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openEditPlannedDateModal(el.dataset.auditId || '', el.dataset.localId || '');
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="delete-planned-date"]')
    .forEach((el) => {
      el.addEventListener('click', () => {
        handleDeletePlannedDate(el.dataset.auditId || '', el.dataset.localId || '');
      });
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleDeletePlannedDate(el.dataset.auditId || '', el.dataset.localId || '');
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="close-planned-date-modal"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        closePlannedDateModal();
      });
    });

  const plannedDateEditorModalEl = document.getElementById('plannedDateEditorModal');
  if (plannedDateEditorModalEl) {
    plannedDateEditorModalEl.addEventListener('click', (e) => {
      if (e.target === plannedDateEditorModalEl) {
        closePlannedDateModal();
      }
    });
  }

  const fechaEditorTipoSelect = document.getElementById(
    'fechaEditorTipoSelect'
  ) as HTMLSelectElement | null;
  if (fechaEditorTipoSelect) {
    fechaEditorTipoSelect.addEventListener('change', () => {
      if (!isApprovedStaff()) return;
      const syncedDraft = syncFechaEditorDraftFromDom();
      if (!syncedDraft) return;
      const nextMode =
        fechaEditorTipoSelect.value === 'PROGRAMADA_EXACTA'
          ? 'PROGRAMADA_EXACTA'
          : 'PREPROGRAMADA_MES';
      state.designacionFechaDomain.editorDraft = togglePlannedDateDraftMode(
        syncedDraft,
        nextMode
      );
      state.designacionFechaDomain.editErrorMessage = null;
      render();
    });
  }

  const fechaEditorSingleDayToggle = document.getElementById(
    'fechaEditorSingleDayToggle'
  ) as HTMLInputElement | null;
  if (fechaEditorSingleDayToggle) {
    fechaEditorSingleDayToggle.addEventListener('change', () => {
      if (!isApprovedStaff()) return;
      const syncedDraft = syncFechaEditorDraftFromDom();
      if (!syncedDraft) return;
      const nextSingle = fechaEditorSingleDayToggle.checked;
      state.designacionFechaDomain.editorDraft = {
        ...syncedDraft,
        singleDay: nextSingle,
        fecha_fin: nextSingle
          ? syncedDraft.fecha_inicio
          : syncedDraft.fecha_fin || syncedDraft.fecha_inicio,
      };
      state.designacionFechaDomain.editErrorMessage = null;
      render();
    });
  }

  document
    .querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-fecha-editor-field]')
    .forEach((field) => {
      if (field.id === 'fechaEditorTipoSelect') return;
      field.addEventListener('input', () => {
        syncFechaEditorDraftFromDom();
      });
      field.addEventListener('change', () => {
        syncFechaEditorDraftFromDom();
      });
    });

  const plannedDateEditorForm = document.getElementById(
    'plannedDateEditorForm'
  ) as HTMLFormElement | null;
  if (plannedDateEditorForm) {
    plannedDateEditorForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!isApprovedStaff() || state.designacionFechaDomain.saving) return;
      const draft = syncFechaEditorDraftFromDom();
      const ensured = ensureFechaDraftsForAudit(plannedDateEditorForm.dataset.auditId);
      if (!draft || !ensured) return;

      const mode = state.designacionFechaDomain.editorMode;
      const rawNextDrafts =
        mode === 'edit'
          ? ensured.drafts.map((row) =>
              row.localId === draft.localId ? { ...draft } : row
            )
          : [...ensured.drafts, { ...draft }];
      const nextAscending = sortPlannedDraftsAscending(rawNextDrafts);

      state.designacionFechaDomain.draftAuditId = ensured.auditId;
      state.designacionFechaDomain.drafts = nextAscending;
      void runWithPlannerPreservedViewport(() =>
        saveLinkedBatchProgrammedDates(ensured.auditId, nextAscending)
      );
    });
  }

  // ===============================================
  // DOMAIN AUDITORÍA — DESIGNACIÓN -> SITIO
  // ===============================================
  document
    .querySelectorAll<HTMLElement>('[data-action="open-sitio-coverage-modal"]')
    .forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const certId = btn.dataset.certId || state.designacionSitioDomain.selectedCertId || null;
        const auditId = btn.dataset.auditId || state.designacionSitioDomain.selectedAuditId || null;
        if (!certId && !auditId) return;
        state.designacionSitioDomain.coverageModalCertId = certId;
        state.designacionSitioDomain.coverageModalAuditId = auditId;
        state.designacionSitioDomain.coverageWindowOffset = 0;
        state.designacionSitioDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="toggle-sitio-panel-collapse"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const auditId =
          btn.dataset.auditId || state.designacionSitioDomain.selectedAuditId || '';
        if (!auditId) return;
        const prevMap = state.designacionSitioDomain.isSitePanelExpandedByAuditId || {};
        state.designacionSitioDomain.isSitePanelExpandedByAuditId = {
          ...prevMap,
          [auditId]: !prevMap[auditId],
        };
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-sitio-detail-filter"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        const val = sel.value as SitioDetailFilterMode;
        const validFilters: readonly SitioDetailFilterMode[] = [
          'ALL',
          'SELECTED',
          'UNSELECTED',
          'LINK_SELECTED',
          'NOT_AUDITED_LAST_N',
          'SHARED_ONLY',
          'UNVISITED_CYCLE',
        ];
        const nextFilter: SitioDetailFilterMode = validFilters.includes(val) ? val : 'ALL';
        state.designacionSitioDomain.detailFilterMode = nextFilter;
        if (
          nextFilter === 'NOT_AUDITED_LAST_N' &&
          (!Number.isFinite(state.designacionSitioDomain.notAuditedLastN) ||
            state.designacionSitioDomain.notAuditedLastN < 0)
        ) {
          state.designacionSitioDomain.notAuditedLastN = 1;
        }
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLInputElement>('[data-action="change-sitio-last-n"]')
    .forEach((inp) => {
      inp.addEventListener('input', () => {
        const raw = inp.value.trim();
        if (raw === '') {
          // Allow user to temporarily clear the digit without losing focus or clobbering value
          return;
        }
        const parsed = Number(raw);
        if (!Number.isFinite(parsed)) return;
        state.designacionSitioDomain.notAuditedLastN = Math.max(0, Math.trunc(parsed));
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
      inp.addEventListener('change', () => {
        const raw = inp.value.trim();
        const parsed = raw === '' ? 1 : Number(raw);
        state.designacionSitioDomain.notAuditedLastN = Number.isFinite(parsed)
          ? Math.max(0, Math.trunc(parsed))
          : 1;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-sitio-detail-sort"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        const val = sel.value as SitioDetailSortMode;
        const validSorts: readonly SitioDetailSortMode[] = [
          'SITE_NUMBER',
          'SELECTED_FIRST',
          'LEAST_RECENTLY_AUDITED',
          'PERSONAL_DESC',
          'NAME_ASC',
        ];
        state.designacionSitioDomain.detailSortMode = validSorts.includes(val)
          ? val
          : 'SITE_NUMBER';
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLInputElement>('[data-action="change-sitio-detail-search"]')
    .forEach((inp) => {
      inp.addEventListener('input', () => {
        state.designacionSitioDomain.detailSearchQuery = inp.value;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="reset-sitio-detail-filters"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        state.designacionSitioDomain.detailFilterMode = DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.filterMode;
        state.designacionSitioDomain.detailSearchQuery =
          DEFAULT_SITIO_DETAIL_QUERY_OPTIONS.searchQuery ?? '';
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="close-sitio-coverage-modal"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        state.designacionSitioDomain.coverageModalCertId = null;
        state.designacionSitioDomain.coverageModalAuditId = null;
        state.designacionSitioDomain.coverageWindowOffset = 0;
        state.designacionSitioDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  const sitioCoverageModalBackdrop = document.getElementById('sitioCoverageModal');
  if (sitioCoverageModalBackdrop) {
    sitioCoverageModalBackdrop.addEventListener('click', (e) => {
      if (e.target === sitioCoverageModalBackdrop) {
        state.designacionSitioDomain.coverageModalCertId = null;
        state.designacionSitioDomain.coverageModalAuditId = null;
        state.designacionSitioDomain.coverageWindowOffset = 0;
        state.designacionSitioDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      }
    });
  }

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-sitio-coverage-sort"]')
    .forEach((sel) => {
      sel.addEventListener('change', () => {
        const val = sel.value as SiteCoverageSortMode;
        const validModes: readonly SiteCoverageSortMode[] = [
          'SITE_NUMBER',
          'UNVISITED_FIRST',
          'LEAST_AUDITED',
          'CURRENT_FIRST',
          'NAME_ASC',
        ];
        state.designacionSitioDomain.coverageSortMode = validModes.includes(val)
          ? val
          : 'SITE_NUMBER';
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="page-sitio-coverage-window"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        const delta = Number(btn.dataset.delta || '0');
        if (!Number.isFinite(delta) || delta === 0) return;
        state.designacionSitioDomain.coverageWindowOffset += Math.trunc(delta);
        render();
      });
    });

  document
    .querySelectorAll<HTMLInputElement>('input[data-action="toggle-step4-site"]')
    .forEach((chk) => {
      chk.addEventListener('change', () => {
        const isHqLocked = chk.dataset.hqLocked === 'true';
        if (!isApprovedStaff() || isHqLocked) {
          chk.checked = chk.dataset.currentlySelected === 'true';
          return;
        }
        const auditId = chk.dataset.auditId || '';
        const siteId = chk.dataset.siteId || '';
        const saId = chk.dataset.sitioAuditoriaId || undefined;
        if (!auditId || !siteId) return;
        void toggleSiteInAudit(auditId, siteId, saId);
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 5.1 DESIGNACIÓN -> TEMPORAL
  // ===============================================
  const syncBatchTemporalDraftFromForm = (auditIdHint?: string): {
    auditId: string;
    draft: BatchTemporalFormDraft;
  } | null => {
    const form = document.getElementById('batchTemporalSiteForm') as HTMLFormElement | null;
    const auditId =
      auditIdHint ||
      form?.dataset.auditId ||
      state.designacionTemporalDomain.selectedAuditId ||
      state.auditoriasSelection.selectedAuditId ||
      '';
    if (!auditId) return null;

    const existingDraft =
      state.designacionTemporalDomain.draftAuditId === auditId &&
      state.designacionTemporalDomain.batchDraft
        ? state.designacionTemporalDomain.batchDraft
        : (() => {
            const auditsPool = getScopedAuditsForSharedNav();
            const activeAudit = auditsPool.find((a) => a.id === auditId) ?? null;
            const res = resolveLinkedBatchTemporalState(
              activeAudit,
              auditsPool,
              state.domainData.auditPrograms,
              state.domainData.allTemporalSites
            );
            return createBatchTemporalDraftFromResolution(res);
          })();

    if (!form) {
      return { auditId, draft: existingDraft };
    }

    const fd = new FormData(form);
    const daysRaw = Number(fd.get('tiempo_auditoria') ?? existingDraft.tiempo_auditoria);
    const nextDraft: BatchTemporalFormDraft = {
      etiqueta: String(fd.get('etiqueta') ?? existingDraft.etiqueta),
      ubicacion: String(fd.get('ubicacion') ?? existingDraft.ubicacion),
      tiempo_auditoria: Number.isFinite(daysRaw) ? daysRaw : existingDraft.tiempo_auditoria,
      fecha_tentativa: String(fd.get('fecha_tentativa') ?? existingDraft.fecha_tentativa),
      notas: String(fd.get('notas') ?? existingDraft.notas),
    };
    state.designacionTemporalDomain.draftAuditId = auditId;
    state.designacionTemporalDomain.batchDraft = nextDraft;
    return { auditId, draft: nextDraft };
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="toggle-batch-temporal-switch"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const auditId = btn.dataset.auditId || '';
        const nextValue = btn.dataset.nextValue === 'true';
        if (!auditId) return;
        void runWithPlannerPreservedViewport(() =>
          toggleBatchTemporalSwitch(auditId, nextValue, false)
        );
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="cancel-disable-batch-temporal"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        state.designacionTemporalDomain.confirmDisableBatch = false;
        state.designacionTemporalDomain.editErrorMessage = null;
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="confirm-disable-batch-temporal"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const auditId = btn.dataset.auditId || '';
        if (!auditId) return;
        void runWithPlannerPreservedViewport(() =>
          toggleBatchTemporalSwitch(auditId, false, true)
        );
      });
    });

  const batchTemporalForm = document.getElementById(
    'batchTemporalSiteForm'
  ) as HTMLFormElement | null;
  if (batchTemporalForm) {
    batchTemporalForm
      .querySelectorAll<HTMLInputElement | HTMLTextAreaElement>('[data-temporal-field]')
      .forEach((field) => {
        field.addEventListener('input', () => {
          syncBatchTemporalDraftFromForm(batchTemporalForm.dataset.auditId);
        });
      });

    batchTemporalForm
      .querySelectorAll<HTMLElement>('[data-action="step-temporal-days"]')
      .forEach((btn) => {
        btn.addEventListener('click', () => {
          if (!isApprovedStaff()) return;
          const synced = syncBatchTemporalDraftFromForm(batchTemporalForm.dataset.auditId);
          if (!synced) return;
          const delta = Number(btn.dataset.delta || '0');
          const base =
            Number.isFinite(synced.draft.tiempo_auditoria) && synced.draft.tiempo_auditoria > 0
              ? synced.draft.tiempo_auditoria
              : 1.0;
          const nextDays = Math.max(0.25, roundAuditDaysQuarter(base + delta));
          state.designacionTemporalDomain.draftAuditId = synced.auditId;
          state.designacionTemporalDomain.batchDraft = {
            ...synced.draft,
            tiempo_auditoria: nextDays,
          };
          state.designacionTemporalDomain.editErrorMessage = null;
          render();
        });
      });

    batchTemporalForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!isApprovedStaff()) return;
      const synced = syncBatchTemporalDraftFromForm(batchTemporalForm.dataset.auditId);
      if (!synced) return;
      void runWithPlannerPreservedViewport(() =>
        saveBatchTemporalSite(synced.auditId, synced.draft)
      );
    });
  }

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 6.2 TIEMPO (0.25d)
  // ===============================================
  const getTiempoProgramPool = (): ProgramaAuditoriaEntity[] =>
    state.domainData.auditPrograms.length > 0
      ? state.domainData.auditPrograms
      : isApprovedStaff()
      ? buildSeededProgramsFallback()
      : [];

  const openTiempoProgramDetail = (programId: string): void => {
    if (!programId) return;
    const target = getTiempoProgramPool().find((p) => p.id === programId);
    const activeAuditsForProg = sortAuditsByRecencyDesc(
      (target?.auditorias || []).filter((a) => !a.deleted_at)
    );
    if (activeAuditsForProg[0]?.id_certificado) {
      applyCertificateSectionSelection(
        'tiempo',
        activeAuditsForProg[0].id_certificado,
        activeAuditsForProg[0].id
      );
      return;
    }
    clearAllEntitySelections();
    state.activeRoute = 'auditorias';
    state.activeSubSection = 'tiempo';
    state.tiempoDomain.selectedProgramId = programId;
    state.tiempoDomain.editErrorMessage = null;
    const rawLabel = (target?.etiqueta || 'Certificado').trim() || 'Certificado';
    const compactLabel = rawLabel.length > 24 ? `${rawLabel.slice(0, 21)}...` : rawLabel;
    state.breadcrumbs = pushBreadcrumb(state.breadcrumbs, {
      id: `tiempo-${programId}`,
      label: compactLabel,
      route: 'auditorias',
      subview: 'tiempo',
      entityType: 'programa_auditoria',
      entityId: programId,
      tooltip: `Tiempo > ${rawLabel}`,
    });
    syncUrlHash('auditorias', 'tiempo');
    render();
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="select-tiempo-program"]')
    .forEach((el) => {
      el.addEventListener('click', () => {
        openTiempoProgramDetail(el.dataset.programId || '');
      });
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openTiempoProgramDetail(el.dataset.programId || '');
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="back-to-tiempo-list"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        clearAllEntitySelections();
        state.activeRoute = 'auditorias';
        state.activeSubSection = 'tiempo';
        state.breadcrumbs = resetBreadcrumbToDomain('auditorias', 'tiempo');
        syncUrlHash('auditorias', 'tiempo');
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="step-tiempo-site-days"]')
    .forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!isApprovedStaff()) return;
        const sitePlanId = btn.dataset.sitePlanId || '';
        const auditId = btn.dataset.auditId || '';
        const siteName = btn.dataset.siteName || 'Sitio';
        const currentDays = Number(btn.dataset.currentDays || 0);
        const delta = Number(btn.dataset.delta || 0);
        if (!sitePlanId || !Number.isFinite(delta)) return;
        const nextDays = Math.max(0.25, roundAuditDaysQuarter(currentDays + delta));
        state.tiempoDomain.draftTimeBySitePlanId[sitePlanId] = nextDays.toFixed(2);
        await runWithPlannerPreservedViewport(() =>
          saveSiteAuditTime(sitePlanId, nextDays, auditId || undefined, siteName)
        );
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="set-tiempo-site-days-preset"]')
    .forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!isApprovedStaff()) return;
        const sitePlanId = btn.dataset.sitePlanId || '';
        const auditId = btn.dataset.auditId || '';
        const siteName = btn.dataset.siteName || 'Sitio';
        const presetDays = roundAuditDaysQuarter(Number(btn.dataset.days || 0));
        if (!sitePlanId || !Number.isFinite(presetDays) || presetDays < 0.25) return;
        state.tiempoDomain.draftTimeBySitePlanId[sitePlanId] = presetDays.toFixed(2);
        await runWithPlannerPreservedViewport(() =>
          saveSiteAuditTime(sitePlanId, presetDays, auditId || undefined, siteName)
        );
      });
    });

  document
    .querySelectorAll<HTMLInputElement>('[data-action="change-tiempo-site-days"]')
    .forEach((input) => {
      input.addEventListener('change', async () => {
        if (!isApprovedStaff()) return;
        const sitePlanId = input.dataset.sitePlanId || '';
        const auditId = input.dataset.auditId || '';
        const siteName = input.dataset.siteName || 'Sitio';
        if (!sitePlanId) return;
        const rawStr = input.value.trim();
        state.tiempoDomain.draftTimeBySitePlanId[sitePlanId] = input.value;
        const parsed = rawStr === '' ? Number.NaN : Number(rawStr);
        await runWithPlannerPreservedViewport(() =>
          saveSiteAuditTime(sitePlanId, parsed, auditId || undefined, siteName)
        );
      });
    });

  document
    .querySelectorAll<HTMLSelectElement>('[data-action="change-tiempo-site-modality"]')
    .forEach((select) => {
      select.addEventListener('change', async () => {
        if (!isApprovedStaff()) return;
        const sitePlanId = select.dataset.sitePlanId || '';
        const auditId = select.dataset.auditId || '';
        const siteName = select.dataset.siteName || 'Sitio';
        const val = select.value;
        if (
          !sitePlanId ||
          (val !== 'Presencial' && val !== 'Remota' && val !== 'Mixta')
        ) {
          return;
        }
        await runWithPlannerPreservedViewport(() =>
          saveSiteAuditModality(sitePlanId, val, auditId || undefined, siteName)
        );
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 6.1 AUDITOR (0.25d)
  // ===============================================
  const getAsignacionProgramPool = (): ProgramaAuditoriaEntity[] =>
    state.domainData.auditPrograms.length > 0
      ? state.domainData.auditPrograms
      : isApprovedStaff()
      ? buildSeededProgramsFallback()
      : [];

  const openAsignacionProgramDetail = (programId: string): void => {
    if (!programId) return;
    const target = getAsignacionProgramPool().find((p) => p.id === programId);
    const activeAuditsForProg = sortAuditsByRecencyDesc(
      (target?.auditorias || []).filter((a) => !a.deleted_at)
    );
    if (activeAuditsForProg[0]?.id_certificado) {
      applyCertificateSectionSelection(
        'auditor',
        activeAuditsForProg[0].id_certificado,
        activeAuditsForProg[0].id
      );
      return;
    }
    clearAllEntitySelections();
    state.activeRoute = 'auditorias';
    state.activeSubSection = 'auditor';
    state.asignacionDomain.selectedProgramId = programId;
    state.asignacionDomain.draftTargetKind = 'REGULAR';
    state.asignacionDomain.draftTargetId = null;
    state.asignacionDomain.editErrorMessage = null;
    const rawLabel = (target?.etiqueta || 'Certificado').trim() || 'Certificado';
    const compactLabel = rawLabel.length > 24 ? `${rawLabel.slice(0, 21)}...` : rawLabel;
    state.breadcrumbs = pushBreadcrumb(state.breadcrumbs, {
      id: `auditor-${programId}`,
      label: compactLabel,
      route: 'auditorias',
      subview: 'auditor',
      entityType: 'programa_auditoria',
      entityId: programId,
      tooltip: `Auditor > ${rawLabel}`,
    });
    syncUrlHash('auditorias', 'auditor');
    render();
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="select-asignacion-program"]')
    .forEach((el) => {
      el.addEventListener('click', () => {
        openAsignacionProgramDetail(el.dataset.programId || '');
      });
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openAsignacionProgramDetail(el.dataset.programId || '');
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="back-to-asignacion-list"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        clearAllEntitySelections();
        state.activeRoute = 'auditorias';
        state.activeSubSection = 'auditor';
        state.breadcrumbs = resetBreadcrumbToDomain('auditorias', 'auditor');
        syncUrlHash('auditorias', 'auditor');
        render();
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="open-asignacion-add-form"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!isApprovedStaff()) return;
        const kind = btn.dataset.targetKind === 'TEMPORAL' ? 'TEMPORAL' : 'REGULAR';
        const targetId = btn.dataset.targetId || '';
        const remainingRaw = Number(btn.dataset.remainingDays || 1);
        const remainingDays =
          Number.isFinite(remainingRaw) && remainingRaw >= 0.25
            ? roundAuditDaysQuarter(remainingRaw)
            : 0.25;
        state.asignacionDomain.draftTargetKind = kind;
        state.asignacionDomain.draftTargetId = targetId || null;
        state.asignacionDomain.draftAuditorId = '';
        state.asignacionDomain.draftRol = 'AUDITOR';
        state.asignacionDomain.draftDays = remainingDays.toFixed(2);
        state.asignacionDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="cancel-asignacion-add-form"]')
    .forEach((btn) => {
      btn.addEventListener('click', () => {
        state.asignacionDomain.draftTargetId = null;
        state.asignacionDomain.editErrorMessage = null;
        void runWithPlannerPreservedViewport(async () => {
          render();
        });
      });
    });

  const normalizeAsignacionRole = (raw: string): AuditorSiteRole =>
    raw === 'AUDITOR_LIDER' ||
    raw === 'EXPERTO_TECNICO' ||
    raw === 'AUDITOR_EN_ENTRENAMIENTO'
      ? raw
      : 'AUDITOR';

  document
    .querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-action="change-asignacion-draft-field"]')
    .forEach((fieldEl) => {
      fieldEl.addEventListener('change', () => {
        const container = fieldEl.closest<HTMLElement>('[data-target-id]');
        const targetId = container?.dataset.targetId || null;
        const targetKind =
          container?.dataset.targetKind === 'TEMPORAL' ? 'TEMPORAL' : 'REGULAR';
        if (targetId) {
          state.asignacionDomain.draftTargetKind = targetKind;
          state.asignacionDomain.draftTargetId = targetId;
          const audSel = document.getElementById(
            `asignacionAuditorSelect_${targetId}`
          ) as HTMLSelectElement | null;
          const roleSel = document.getElementById(
            `asignacionRolSelect_${targetId}`
          ) as HTMLSelectElement | null;
          const daysInput = document.getElementById(
            `asignacionDaysInput_${targetId}`
          ) as HTMLInputElement | null;
          if (audSel) state.asignacionDomain.draftAuditorId = audSel.value;
          if (roleSel) state.asignacionDomain.draftRol = normalizeAsignacionRole(roleSel.value);
          if (daysInput) state.asignacionDomain.draftDays = daysInput.value;
        }
        const field = fieldEl.dataset.field;
        if (field === 'auditorId') {
          state.asignacionDomain.draftAuditorId = fieldEl.value;
        } else if (field === 'rol') {
          state.asignacionDomain.draftRol = normalizeAsignacionRole(fieldEl.value);
        } else if (field === 'days') {
          state.asignacionDomain.draftDays = fieldEl.value;
        }
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="submit-asignacion-auditor"]')
    .forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!isApprovedStaff()) return;
        const kind = btn.dataset.targetKind === 'TEMPORAL' ? 'TEMPORAL' : 'REGULAR';
        const targetId = btn.dataset.targetId || '';
        const auditId = btn.dataset.auditId || '';
        if (!targetId) return;

        const audSel = document.getElementById(
          `asignacionAuditorSelect_${targetId}`
        ) as HTMLSelectElement | null;
        const roleSel = document.getElementById(
          `asignacionRolSelect_${targetId}`
        ) as HTMLSelectElement | null;
        const daysInput = document.getElementById(
          `asignacionDaysInput_${targetId}`
        ) as HTMLInputElement | null;

        const auditorId = audSel ? audSel.value : state.asignacionDomain.draftAuditorId || '';
        const rolAuditor = normalizeAsignacionRole(
          roleSel ? roleSel.value : state.asignacionDomain.draftRol
        );
        const rawDays = Number(daysInput ? daysInput.value : state.asignacionDomain.draftDays);
        const days = Number.isFinite(rawDays) ? rawDays : 0;

        state.asignacionDomain.draftTargetKind = kind;
        state.asignacionDomain.draftTargetId = targetId;
        state.asignacionDomain.draftAuditorId = auditorId;
        state.asignacionDomain.draftRol = rolAuditor;
        state.asignacionDomain.draftDays = daysInput ? daysInput.value : state.asignacionDomain.draftDays;

        await runWithPlannerPreservedViewport(async () => {
          if (kind === 'TEMPORAL') {
            await upsertTemporalSiteAuditor({
              temporalSiteId: targetId,
              auditorId,
              rol_auditor: rolAuditor,
              tiempo_auditoria: days,
              auditId: auditId || null,
            });
          } else {
            await upsertRegularSiteAuditor({
              sitioAuditoriaId: targetId,
              auditorId,
              rol_auditor: rolAuditor,
              tiempo_auditoria: days,
              asignacion_completa_sitio: true,
              auditId: auditId || null,
            });
          }
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="step-asignacion-auditor-days"]')
    .forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!isApprovedStaff()) return;
        const kind = btn.dataset.targetKind === 'TEMPORAL' ? 'TEMPORAL' : 'REGULAR';
        const targetId = btn.dataset.targetId || '';
        const auditId = btn.dataset.auditId || '';
        const auditorId = btn.dataset.auditorId || '';
        const role = normalizeAsignacionRole(btn.dataset.rol || 'AUDITOR');
        const wholeSite = btn.dataset.wholeSite !== 'false';
        const currentDays = Number(btn.dataset.currentDays || 0);
        const delta = Number(btn.dataset.delta || 0);
        if (!targetId || !auditorId || !Number.isFinite(delta)) return;
        const nextDays = roundAuditDaysQuarter(currentDays + delta);

        await runWithPlannerPreservedViewport(async () => {
          if (kind === 'TEMPORAL') {
            await upsertTemporalSiteAuditor({
              temporalSiteId: targetId,
              auditorId,
              rol_auditor: role,
              tiempo_auditoria: nextDays,
              auditId: auditId || null,
            });
          } else {
            await upsertRegularSiteAuditor({
              sitioAuditoriaId: targetId,
              auditorId,
              rol_auditor: role,
              tiempo_auditoria: nextDays,
              asignacion_completa_sitio: wholeSite,
              auditId: auditId || null,
            });
          }
        });
      });
    });

  document
    .querySelectorAll<HTMLElement>('[data-action="remove-asignacion-auditor"]')
    .forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!isApprovedStaff()) return;
        const kind = btn.dataset.targetKind === 'TEMPORAL' ? 'TEMPORAL' : 'REGULAR';
        const assignmentId = btn.dataset.assignmentId || '';
        const targetId = btn.dataset.targetId || '';
        const auditId = btn.dataset.auditId || '';
        if (!assignmentId) return;

        await runWithPlannerPreservedViewport(async () => {
          if (kind === 'TEMPORAL') {
            await archiveTemporalSiteAuditor(
              assignmentId,
              targetId || null,
              auditId || null
            );
          } else {
            await archiveRegularSiteAuditor(assignmentId, auditId || null);
          }
        });
      });
    });

  // ===============================================
  // DOMAIN AUDITORÍA — STEP 7.1 `4. PROCESO` Y `5. TURNO` (MATRIZ ANTI-FATIGA)
  // ===============================================
  const openProgramaAuditDetail = (auditId: string): void => {
    if (!auditId) return;
    const currentNormalized = normalizeDomainSubview('auditorias', state.activeSubSection);
    const targetSub = currentNormalized === 'turno' ? 'turno' : 'proceso';
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : isApprovedStaff()
        ? buildSeededProgramsFallback().flatMap((p) => p.auditorias)
        : [];
    const targetAudit = auditsPool.find((a) => a.id === auditId);
    if (targetAudit?.id_certificado) {
      applyCertificateSectionSelection(targetSub, targetAudit.id_certificado, auditId);
      return;
    }
    clearAllEntitySelections();
    state.activeRoute = 'auditorias';
    state.activeSubSection = targetSub;
    if (targetSub === 'turno') {
      state.programaTurnosDomain.selectedAuditId = auditId;
      state.programaTurnosDomain.editErrorMessage = null;
    } else {
      state.programaProcesosDomain.selectedAuditId = auditId;
      state.programaProcesosDomain.editErrorMessage = null;
    }
    state.programaDomain.selectedAuditId = auditId;
    state.programaDomain.activeMiniStep = targetSub === 'turno' ? 'turnos' : 'procesos';
    state.programaDomain.openHistoryDrawerProcessIds = [];
    state.programaDomain.editErrorMessage = null;
    syncUrlHash('auditorias', targetSub);
    render();
  };

  document
    .querySelectorAll<HTMLElement>('[data-action="select-programa-audit"]')
    .forEach((el) => {
      el.addEventListener('click', () => {
        openProgramaAuditDetail(el.dataset.auditId || '');
      });
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openProgramaAuditDetail(el.dataset.auditId || '');
        }
      });
    });

  document
