async function handleSignOut(): Promise<void> {
  if (isSigningOut) return;
  isSigningOut = true;
  try {
    resetClientSessionState();
    await supabase.auth.signOut({ scope: 'local' });
  } catch (err) {
    console.warn('Error during signOut cleanup:', err);
  } finally {
    isSigningOut = false;
  }
}

async function handleResetDatabase(): Promise<void> {
  if (state.auth.resettingDb) return;

  state.auth = {
    ...state.auth,
    resettingDb: true,
    resetErrorMessage: null,
    errorMessage: null,
    successMessage: null,
  };
  render();

  try {
    const response = await fetch('/api/reset-db', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
    });

    const payload = (await response.json()) as {
      ok?: boolean;
      error?: string;
      executedFiles?: Array<{ file: string; durationMs: number }>;
      totalDurationMs?: number;
    };

    if (!response.ok || !payload.ok) {
      throw new Error(payload.error || `Reset failed with status ${response.status}.`);
    }

    const fileNames = (payload.executedFiles || []).map((item) => item.file);
    state.auth = {
      ...state.auth,
      resetModalOpen: false,
      resettingDb: false,
      resetErrorMessage: null,
      errorMessage: null,
      successMessage: formatResetSummary(fileNames, payload.totalDurationMs),
    };
    void loadLiveCertificates();
  } catch (err) {
    state.auth = {
      ...state.auth,
      resettingDb: false,
      resetErrorMessage: err instanceof Error ? err.message : 'Unable to reset database.',
    };
  }

  render();
}

async function loadUserSession(user: User | null): Promise<void> {
  state.booting = false;
  if (!user) {
    activeSessionLoadKey = null;
    state.user = null;
    state.profile = null;
    render();
    return;
  }

  if (activeSessionLoadKey === user.id || state.user?.id === user.id) {
    return;
  }
  activeSessionLoadKey = user.id;

  try {
    const { data: profileData, error } = await supabase
      .from('profiles')
      .select('id, nombre, role, status, created_at')
      .eq('id', user.id)
      .maybeSingle();

    if (isSigningOut) return;

    if (error || !profileData) {
      state.user = user;
      state.profile = {
        id: user.id,
        nombre: (user.user_metadata?.nombre as string | undefined) || user.email || 'User',
        role: ((user.user_metadata?.role as UserRole | undefined) || 'CLIENT'),
        status: 'PENDING',
      };
    } else {
      state.user = user;
      state.profile = profileData as UserProfile;
    }

    state.profileForm = {
      nombreInput: state.profile.nombre,
      savingProfile: false,
      profileFeedback: null,
      profileError: null,
      passwordSectionOpen: false,
      newPasswordInput: '',
      confirmPasswordInput: '',
      savingPassword: false,
      passwordFeedback: null,
      passwordError: null,
    };

    if (state.profile.role === 'CLIENT') {
      const { data: orgAccessRows } = await supabase
        .from('client_organization_access')
        .select('id_organizacion, estado, fecha_solicitud, organizacion:id_organizacion ( nombre, rif )')
        .eq('id_usuario', user.id)
        .is('deleted_at', null);
      const rows = Array.isArray(orgAccessRows) ? orgAccessRows : [];
      state.clientAccessRows = rows.map((row: Record<string, unknown>) => {
        const org = (row.organizacion as Record<string, unknown> | null) || null;
        return {
          id_organizacion: String(row.id_organizacion || ''),
          organizacion_nombre: org?.nombre ? String(org.nombre) : 'Organización vinculada',
          rif: org?.rif ? String(org.rif) : undefined,
          estado: String(row.estado || 'PENDING') as UserStatus,
          fecha_solicitud: row.fecha_solicitud ? String(row.fecha_solicitud) : undefined,
        };
      });
      state.authorizedClientOrgIds =
        state.profile.status === 'APPROVED'
          ? state.clientAccessRows
              .filter((r) => r.estado === 'APPROVED' && Boolean(r.id_organizacion))
              .map((r) => r.id_organizacion)
          : [];
    } else {
      state.clientAccessRows = [];
      state.authorizedClientOrgIds = [];
    }

    const initialNav = parseHashRoute();
    if (canAccessRoute(state.profile, initialNav.route)) {
      state.activeRoute = initialNav.route;
      state.activeSubSection = initialNav.subview;
    } else {
      state.activeRoute = 'dashboard';
      state.activeSubSection = null;
    }
    syncUrlHash(state.activeRoute, state.activeSubSection, true);
    state.breadcrumbs = resetBreadcrumbToDomain(state.activeRoute, state.activeSubSection);
    state.openMenu = null;
    render();

    if (isApprovedStaff()) {
      void loadApprovalProfiles();
    }

    if (state.profile?.status === 'APPROVED') {
      void loadLiveCertificates();
      void loadDomainData();
      void loadLiveAudits();
    }
  } finally {
    if (activeSessionLoadKey === user.id) {
      activeSessionLoadKey = null;
    }
  }
}

function getEffectiveRequirementsCatalog(): RequisitoLtree[] {
  if (state.domainData.requirementsCatalog.length > 0) {
    return state.domainData.requirementsCatalog;
  }
  const bundled = getBundledNormaCatalog();
  return bundled.requirementsCatalog.length > 0
    ? bundled.requirementsCatalog
    : getAllSeededNormaRequirements();
}

function buildCertBreadcrumbMeta(params: {
  certId?: string | null;
  numero_certificado?: string | null;
  version_numero?: number | null;
  organizacion_abreviacion?: string | null;
  contextPrefix?: string;
}): { label: string; tooltip: string } {
  const matchedCert = params.certId
    ? state.domainData.allCertificadosDetailed.find((c) => c.id === params.certId) ||
      INITIAL_CERTIFICADOS_DETAILED.find((c) => c.id === params.certId)
    : undefined;
  const matchedOrg = matchedCert?.id_organizacion
    ? state.domainData.allOrganizaciones.find((o) => o.id === matchedCert.id_organizacion)
    : undefined;
  return formatCertificadoBreadcrumbMeta({
    numero_certificado:
      params.numero_certificado || matchedCert?.numero_certificado || 'Certificado',
    version_numero: params.version_numero ?? matchedCert?.version_actual_numero ?? 1,
    organizacion_abreviacion:
      params.organizacion_abreviacion ??
      matchedCert?.organizacion_abreviacion ??
      matchedOrg?.abreviacion,
    contextPrefix: params.contextPrefix,
  });
}

function buildCertificateCoberturaCache(
  cert: CertificadoDetailEntity,
  requirementsCatalog: ReadonlyArray<RequisitoLtree> = getEffectiveRequirementsCatalog(),
  targetVersionId?: string
): CertificateCoberturaCache {
  return evaluateCertificateVersionCoverage({
    cert,
    requirementsCatalog,
    targetVersionId,
    archivedProcesoIds: state.domainData.archivedProcesoIds,
    archivedNoAplicableIds: state.domainData.archivedNoAplicableIds,
  }).cobertura;
}

function refreshCoverageCachesForCert(certId: string, targetVersionId?: string): void {
  const catalog = getEffectiveRequirementsCatalog();
  let updatedCert: CertificadoDetailEntity | null = null;
  let activeCache: CertificateCoberturaCache | null = null;

  state.domainData.allCertificadosDetailed = state.domainData.allCertificadosDetailed.map((c) => {
    if (c.id !== certId) return c;
    const effectiveVersionId =
      (targetVersionId || '').trim() ||
      (c.selected_version_id || '').trim() ||
      (c.id_certificado_version || '').trim() ||
      undefined;
    const evalRes = evaluateCertificateVersionCoverage({
      cert: c,
      requirementsCatalog: catalog,
      targetVersionId: effectiveVersionId,
      archivedProcesoIds: state.domainData.archivedProcesoIds,
      archivedNoAplicableIds: state.domainData.archivedNoAplicableIds,
    });
    const isActiveVersion =
      !effectiveVersionId || effectiveVersionId === c.id_certificado_version;
    const nextVersions = c.versiones
      ? c.versiones.map((v) =>
          v.id === evalRes.versionId ? { ...v, cobertura: evalRes.cobertura } : v
        )
      : undefined;
    activeCache = isActiveVersion
      ? evalRes.cobertura
      : buildCertificateCoberturaCache(c, catalog, c.id_certificado_version);
    updatedCert = {
      ...c,
      cobertura: isActiveVersion ? evalRes.cobertura : activeCache,
      versiones: nextVersions,
    };
    return updatedCert;
  });

  if (!updatedCert || !activeCache) return;
  const searchSnap = buildCertificateSearchRecordFromDetail(updatedCert);
  state.exploration.records = state.exploration.records.map((rec) =>
    rec.id === certId ? { ...rec, ...searchSnap } : rec
  );
}

async function loadLiveCertificates(): Promise<void> {
  if (state.exploration.loading) return;
  state.exploration.loading = true;
  render();

  const queryWithVersionFallback = async (
    table: string,
    selectWithVersion: string,
    selectLegacy: string,
    applyOrder?: boolean
  ): Promise<{ data: Array<Record<string, unknown>> | null; error: unknown }> => {
    const runQuery = async (cols: string) => {
      const base = supabase.from(table).select(cols).is('deleted_at', null);
      const res = applyOrder
        ? await base.order('version_numero', { ascending: false })
        : await base;
      return {
        data: (res.data as unknown as Array<Record<string, unknown>> | null) ?? null,
        error: res.error,
      };
    };
    const primary = await runQuery(selectWithVersion);
    if (primary.error && isMissingTableOrSchemaError(primary.error)) {
      return runQuery(selectLegacy);
    }
    return primary;
  };

  try {
    const [
      certsRes,
      certVersionsRes,
      alcancesRes,
      alcancesCompartidosRes,
      fechasRes,
      contactosRes,
      contactosCompartidosRes,
      telefonosRes,
      emailsRes,
      noAplicablesRes,
      turnosPorSitioRes,
      turnosCompartidosRes,
      sitiosRes,
      sitiosCompartidosRes,
      procesosRes,
      procesosCompartidosRes,
      reqsPorProcesoRes,
      procesosPorSitioRes,
    ] = await Promise.all([
      queryWithVersionFallback(
        'certificado',
        `
          id,
          numero_certificado,
          multisitio,
          created_at,
          id_organizacion,
          id_norma,
          id_estatus,
          id_sector_iaf,
          id_subsector_iaf,
          organizacion:id_organizacion ( id, nombre, abreviacion, rif, direccion_fiscal ),
          norma:id_norma ( id, esquema, codigo, titulo, norma ),
          estatus:id_estatus ( id, estatus ),
          sector_iaf:id_sector_iaf ( id, sector ),
          subsector_iaf:id_subsector_iaf ( id, codigo, descripcion, categoria_riesgo )
        `,
        `
          id,
          numero_certificado,
          multisitio,
          created_at,
          id_organizacion,
          id_norma,
          id_estatus,
          id_sector_iaf,
          id_subsector_iaf,
          organizacion:id_organizacion ( id, nombre, rif, direccion_fiscal ),
          norma:id_norma ( id, esquema, codigo, titulo, norma ),
          estatus:id_estatus ( id, estatus ),
          sector_iaf:id_sector_iaf ( id, sector ),
          subsector_iaf:id_subsector_iaf ( id, codigo, descripcion, categoria_riesgo )
        `
      ),
      (async () => {
        const res = await supabase
          .from('certificado_version')
          .select(
            'id, id_certificado, id_organizacion_version, version_numero, es_version_actual, notas_version, id_estatus, id_sector_iaf, id_subsector_iaf, multisitio, deleted_at'
          )
          .is('deleted_at', null)
          .order('version_numero', { ascending: false });
        return {
          data: (res.data as unknown as Array<Record<string, unknown>> | null) ?? null,
          error: res.error,
        };
      })(),
      supabase
        .from('alcance')
        .select('id, id_certificado, alcance_es, alcance_en, created_at, updated_at, deleted_at')
        .is('deleted_at', null),
      supabase
        .from('alcance_certificado_compartido')
        .select('id, id_alcance, id_certificado, created_at, deleted_at')
        .is('deleted_at', null),
      queryWithVersionFallback(
        'fecha_certificado',
        'id, id_certificado, id_certificado_version, fecha, tipo_fecha',
        'id, id_certificado, fecha, tipo_fecha'
      ),
      queryWithVersionFallback(
        'contacto_certificado',
        'id, id_certificado, id_certificado_version, nombre, cargo',
        'id, id_certificado, nombre, cargo'
      ),
      queryWithVersionFallback(
        'contacto_certificado_compartido',
        'id, id_contacto, id_certificado, id_certificado_version',
        'id, id_contacto, id_certificado'
      ),
      supabase
        .from('telefono_contacto_certificado')
        .select('id, id_contacto, telefono, tipo_telefono')
        .is('deleted_at', null),
      supabase
        .from('email_contacto_certificado')
        .select('id, id_contacto, email, tipo_email')
        .is('deleted_at', null),
      queryWithVersionFallback(
        'requisitos_no_aplicables_certificado',
        `
          id,
          id_certificado,
          id_certificado_version,
          id_requisito,
          justificacion,
          requisito:id_requisito ( id, codigo, ruta_materializada )
        `,
        `
          id,
          id_certificado,
          id_requisito,
          justificacion,
          requisito:id_requisito ( id, codigo, ruta_materializada )
        `
      ),
      supabase
        .from('turnos_por_sitio')
        .select(`
          id,
          id_sitio,
          id_turno,
          sitio:id_sitio ( id, id_certificado, nombre_sitio ),
          turno:id_turno ( id, hora_entrada, hora_salida )
        `)
        .is('deleted_at', null),
      queryWithVersionFallback(
        'turno_certificado_compartido',
        `
          id,
          id_turno,
          id_certificado,
          id_certificado_version,
          id_certificado_origen,
          turno:id_turno ( id, hora_entrada, hora_salida )
        `,
        `
          id,
          id_turno,
          id_certificado,
          id_certificado_origen,
          turno:id_turno ( id, hora_entrada, hora_salida )
        `
      ),
      queryWithVersionFallback(
        'sitio',
        'id, id_certificado, id_certificado_version, numero_sitio, nombre_sitio, direccion_sitio, personal_count',
        'id, id_certificado, numero_sitio, nombre_sitio, direccion_sitio, personal_count'
      ),
      queryWithVersionFallback(
        'sitio_certificado_compartido',
        'id, id_sitio, id_certificado, id_certificado_version, numero_sitio',
        'id, id_sitio, id_certificado, numero_sitio'
      ),
      queryWithVersionFallback(
        'proceso',
        'id, id_certificado, id_certificado_version, nombre_proceso, tipo',
        'id, id_certificado, nombre_proceso, tipo'
      ),
      queryWithVersionFallback(
        'proceso_certificado_compartido',
        'id, id_proceso, id_certificado, id_certificado_version, sincronizar_requisitos',
        'id, id_proceso, id_certificado, sincronizar_requisitos'
      ),
      (async () => {
        const res = await supabase
          .from('requisitos_por_proceso')
          .select(
            'id_proceso, id_certificado, id_certificado_version, id_requisito, requisito:id_requisito ( id, codigo, ruta_materializada )'
          );
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('requisitos_por_proceso')
            .select(
              'id_proceso, id_certificado, id_requisito, requisito:id_requisito ( id, codigo, ruta_materializada )'
            );
        }
        return res;
      })(),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('procesos_por_sitio')
          .select('id, id_sitio, id_proceso, id_certificado, id_certificado_version')
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          const fallbackRes = await supabase
            .from('procesos_por_sitio')
            .select('id, id_sitio, id_proceso, id_certificado')
            .is('deleted_at', null)
            .order('id', { ascending: true })
            .range(from, to);
          return {
            data: (fallbackRes.data as Array<Record<string, unknown>> | null) ?? null,
            error: fallbackRes.error,
          };
        }
        return {
          data: (res.data as Array<Record<string, unknown>> | null) ?? null,
          error: res.error,
        };
      }, 1000),
    ]);

    const { data, error } = certsRes;

    const telefonosByContacto = new Map<string, TelefonoContactoEntity[]>();
    if (!telefonosRes.error && Array.isArray(telefonosRes.data)) {
      for (const row of telefonosRes.data as Array<Record<string, unknown>>) {
        const contactId = String(row.id_contacto || '');
        if (!contactId) continue;
        const list = telefonosByContacto.get(contactId) || [];
        list.push({
          id: String(row.id),
          id_contacto: contactId,
          telefono: String(row.telefono || ''),
          tipo_telefono: String(row.tipo_telefono || 'Oficina'),
        });
        telefonosByContacto.set(contactId, list);
      }
    }

    const emailsByContacto = new Map<string, EmailContactoEntity[]>();
    if (!emailsRes.error && Array.isArray(emailsRes.data)) {
      for (const row of emailsRes.data as Array<Record<string, unknown>>) {
        const contactId = String(row.id_contacto || '');
        if (!contactId) continue;
        const list = emailsByContacto.get(contactId) || [];
        list.push({
          id: String(row.id),
          id_contacto: contactId,
          email: String(row.email || ''),
          tipo_email: String(row.tipo_email || 'Trabajo'),
        });
        emailsByContacto.set(contactId, list);
      }
    }

    const fechasByCert = new Map<string, FechaCertificadoEntity[]>();
    if (!fechasRes.error && Array.isArray(fechasRes.data)) {
      for (const row of fechasRes.data as Array<Record<string, unknown>>) {
        const certId = String(row.id_certificado || '');
        if (!certId) continue;
        const list = fechasByCert.get(certId) || [];
        list.push({
          id: String(row.id),
          id_certificado: certId,
          id_certificado_version: row.id_certificado_version
            ? String(row.id_certificado_version)
            : undefined,
          fecha: String(row.fecha || '').slice(0, 10),
          tipo_fecha: String(row.tipo_fecha || ''),
        });
        fechasByCert.set(certId, list);
      }
    }

    const reqLookupCatalog = [
      ...state.domainData.requirementsCatalog,
      ...getAllSeededNormaRequirements(),
    ];
    const noAplicablesByCert = new Map<string, NonApplicableRequirementEntity[]>();
    if (!noAplicablesRes.error && Array.isArray(noAplicablesRes.data)) {
      for (const row of noAplicablesRes.data as Array<Record<string, unknown>>) {
        const certId = String(row.id_certificado || '');
        const reqId = String(row.id_requisito || '');
        if (!certId || !reqId) continue;
        const reqObj = (row.requisito as Record<string, unknown> | null) || null;
        const matchedCatalogReq =
          reqLookupCatalog.find((r) => r.id === reqId) ||
          (reqObj?.codigo
            ? reqLookupCatalog.find(
                (r) => r.codigo.trim().toLowerCase() === String(reqObj.codigo).trim().toLowerCase()
              )
            : undefined);
        const reqCodigo = reqObj?.codigo
          ? String(reqObj.codigo)
          : matchedCatalogReq?.codigo || '4.3';
        const list = noAplicablesByCert.get(certId) || [];
        list.push({
          id: String(row.id),
          id_certificado: certId,
          id_certificado_version: row.id_certificado_version
            ? String(row.id_certificado_version)
            : undefined,
          id_requisito: reqId,
          requisito_codigo: reqCodigo,
          requisito_titulo: matchedCatalogReq?.titulo || `Cláusula ${reqCodigo}`,
          ruta_materializada: reqObj?.ruta_materializada
            ? String(reqObj.ruta_materializada)
            : matchedCatalogReq?.ruta_materializada || reqCodigo,
          justificacion: String(row.justificacion || ''),
        });
        noAplicablesByCert.set(certId, list);
      }
    }

    // Version lookup maps for child entities & sharing links
    const contactoOwnVersionById = new Map<string, string>();
    for (const row of !contactosRes.error && Array.isArray(contactosRes.data) ? contactosRes.data : []) {
      const id = String(row.id || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (id && verId) contactoOwnVersionById.set(id, verId);
    }
    const contactoShareVersionByCertAndId = new Map<string, string>();
    for (const row of !contactosCompartidosRes.error && Array.isArray(contactosCompartidosRes.data)
      ? contactosCompartidosRes.data
      : []) {
      const cid = String(row.id_contacto || '');
      const certId = String(row.id_certificado || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (cid && certId && verId) contactoShareVersionByCertAndId.set(`${certId}::${cid}`, verId);
    }

    const sitioOwnVersionById = new Map<string, string>();
    for (const row of !sitiosRes.error && Array.isArray(sitiosRes.data) ? sitiosRes.data : []) {
      const id = String(row.id || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (id && verId) sitioOwnVersionById.set(id, verId);
    }
    const sitioShareVersionByCertAndId = new Map<string, string>();
    for (const row of !sitiosCompartidosRes.error && Array.isArray(sitiosCompartidosRes.data)
      ? sitiosCompartidosRes.data
      : []) {
      const sid = String(row.id_sitio || '');
      const certId = String(row.id_certificado || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (sid && certId && verId) sitioShareVersionByCertAndId.set(`${certId}::${sid}`, verId);
    }

    const procesoOwnVersionById = new Map<string, string>();
    for (const row of !procesosRes.error && Array.isArray(procesosRes.data) ? procesosRes.data : []) {
      const id = String(row.id || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (id && verId) procesoOwnVersionById.set(id, verId);
    }
    const procesoShareVersionByCertAndId = new Map<string, string>();
    for (const row of !procesosCompartidosRes.error && Array.isArray(procesosCompartidosRes.data)
      ? procesosCompartidosRes.data
      : []) {
      const pid = String(row.id_proceso || '');
      const certId = String(row.id_certificado || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (pid && certId && verId) procesoShareVersionByCertAndId.set(`${certId}::${pid}`, verId);
    }

    const ppsVersionById = new Map<string, string>();
    for (const row of !procesosPorSitioRes.error && Array.isArray(procesosPorSitioRes.data)
      ? procesosPorSitioRes.data
      : []) {
      const id = String(row.id || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (id && verId) ppsVersionById.set(id, verId);
    }

    const turnoShareVersionByCertAndId = new Map<string, string>();
    for (const row of !turnosCompartidosRes.error && Array.isArray(turnosCompartidosRes.data)
      ? turnosCompartidosRes.data
      : []) {
      const tid = String(row.id_turno || '');
      const certId = String(row.id_certificado || '');
      const verId = row.id_certificado_version ? String(row.id_certificado_version) : '';
      if (tid && certId && verId) turnoShareVersionByCertAndId.set(`${certId}::${tid}`, verId);
    }

    const visibleCertMeta: VisibleCertMetadata[] =
      !error && Array.isArray(data)
        ? (data as Array<Record<string, unknown>>).map((row) => {
            const orgObj = (row.organizacion as Record<string, unknown> | null) || null;
            const normaObj = (row.norma as Record<string, unknown> | null) || null;
            return {
              id: String(row.id || ''),
              numero_certificado: String(row.numero_certificado || 'FN-CERT-000'),
              organizacion_nombre: orgObj?.nombre ? String(orgObj.nombre) : undefined,
              norma_codigo: normaObj?.codigo
                ? String(normaObj.codigo)
                : normaObj?.norma
                ? String(normaObj.norma)
                : undefined,
            };
          })
        : [];

    const { contactosByCert, sitiosByCert, procesosByCert, turnosByCert } =
      assembleSharedCertificateCollections({
        visibleCerts: visibleCertMeta,
        contactosRows:
          !contactosRes.error && Array.isArray(contactosRes.data)
            ? (contactosRes.data as Array<Record<string, unknown>>)
            : [],
        telefonosByContacto,
        emailsByContacto,
        contactosCompartidosRows:
          !contactosCompartidosRes.error && Array.isArray(contactosCompartidosRes.data)
            ? (contactosCompartidosRes.data as Array<Record<string, unknown>>)
            : [],
        sitiosRows:
          !sitiosRes.error && Array.isArray(sitiosRes.data)
            ? (sitiosRes.data as Array<Record<string, unknown>>)
            : [],
        sitiosCompartidosRows:
          !sitiosCompartidosRes.error && Array.isArray(sitiosCompartidosRes.data)
            ? (sitiosCompartidosRes.data as Array<Record<string, unknown>>)
            : [],
        procesosRows:
          !procesosRes.error && Array.isArray(procesosRes.data)
            ? (procesosRes.data as Array<Record<string, unknown>>)
            : [],
        procesosCompartidosRows:
          !procesosCompartidosRes.error && Array.isArray(procesosCompartidosRes.data)
            ? (procesosCompartidosRes.data as Array<Record<string, unknown>>)
            : [],
        reqsPorProcesoRows:
          !reqsPorProcesoRes.error && Array.isArray(reqsPorProcesoRes.data)
            ? (reqsPorProcesoRes.data as Array<Record<string, unknown>>)
            : [],
        reqLookupCatalog,
        procesosPorSitioRows:
          !procesosPorSitioRes.error && Array.isArray(procesosPorSitioRes.data)
            ? (procesosPorSitioRes.data as Array<Record<string, unknown>>)
            : [],
        turnosPorSitioRows:
          !turnosPorSitioRes.error && Array.isArray(turnosPorSitioRes.data)
            ? (turnosPorSitioRes.data as Array<Record<string, unknown>>)
            : [],
        turnosCompartidosRows:
          !turnosCompartidosRes.error && Array.isArray(turnosCompartidosRes.data)
            ? (turnosCompartidosRes.data as Array<Record<string, unknown>>)
            : [],
        shiftCatalog: state.domainData.shiftCatalog,
        formatTurnoTime,
      });

    const alcanceByCertId = !alcancesRes.error
      ? assembleAlcanceByCertificate({
          certificados: visibleCertMeta,
          rawAlcances: Array.isArray(alcancesRes.data)
            ? (alcancesRes.data as unknown as RawAlcanceRow[])
            : [],
          rawSharedAlcances:
            !alcancesCompartidosRes.error && Array.isArray(alcancesCompartidosRes.data)
              ? (alcancesCompartidosRes.data as unknown as RawAlcanceCompartidoRow[])
              : [],
        })
      : null;

    const effectiveCatalog = getEffectiveRequirementsCatalog();
    const orgById = new Map(state.domainData.allOrganizaciones.map((o) => [o.id, o]));
    const orgVersionAbrevById = new Map<string, string>();
    for (const org of state.domainData.allOrganizaciones) {
      for (const ver of org.versiones || []) {
        if (ver.abreviacion) {
          orgVersionAbrevById.set(ver.id, ver.abreviacion);
        }
      }
      if (org.id_organizacion_version_actual && org.abreviacion) {
        orgVersionAbrevById.set(org.id_organizacion_version_actual, org.abreviacion);
      }
    }
    const estatusById = new Map(state.domainData.estatusCatalog.map((e) => [e.id, e]));
    const sectorById = new Map(
      state.domainData.iafSectors.map((s) => [
        s.id,
        {
          ...s,
          subsectores_count: s.subsectores_count ?? 0,
          auditores_count: s.auditores_count ?? 0,
        },
      ])
    );
    const subsectorById = new Map(state.domainData.iafSubsectors.map((sub) => [sub.id, sub]));
    const rawCertVersions: RawCertificadoVersionRow[] =
      !certVersionsRes.error && Array.isArray(certVersionsRes.data)
        ? (certVersionsRes.data as unknown as RawCertificadoVersionRow[])
        : [];

    if (!error && Array.isArray(data) && data.length > 0) {
      const existingById = new Map<string, CertificadoDetailEntity>();
      for (const seededCert of INITIAL_ENRICHED_SEED_CERTS.certificados) {
        existingById.set(seededCert.id, seededCert);
      }
      for (const currentCert of state.domainData.allCertificadosDetailed) {
        existingById.set(currentCert.id, currentCert);
      }
      const loadedDetailed: CertificadoDetailEntity[] = [];

      const loaded: CertificateRecord[] = await Promise.all(
        data.map(async (row: Record<string, unknown>) => {
          const certId = String(row.id);
          const org = (row.organizacion as Record<string, unknown> | null) || null;
          const norma = (row.norma as Record<string, unknown> | null) || null;
          const estatus = (row.estatus as Record<string, unknown> | null) || null;
          const sectorIaf = (row.sector_iaf as Record<string, unknown> | null) || null;
          const subsectorIaf = (row.subsector_iaf as Record<string, unknown> | null) || null;
          const seedMatch = existingById.get(certId);
          const resolvedOrgId = org?.id
            ? String(org.id)
            : row.id_organizacion
            ? String(row.id_organizacion)
            : seedMatch?.id_organizacion || '';
          const matchedOrg = resolvedOrgId ? orgById.get(resolvedOrgId) : undefined;
          const resolvedOrgAbrev =
            (org?.abreviacion ? String(org.abreviacion).trim() : '') ||
            matchedOrg?.abreviacion ||
            seedMatch?.organizacion_abreviacion;

          const liveFechas: FechaCertificadoEntity[] = !fechasRes.error
            ? fechasByCert.get(certId) || []
            : seedMatch?.fechas || [];
          const liveContactos: ContactoCertificadoEntity[] = !contactosRes.error
            ? (contactosByCert.get(certId) || []).map((c) => ({
                ...c,
                id_certificado_version: c.sharedFromCertId
                  ? contactoShareVersionByCertAndId.get(`${certId}::${c.id}`)
                  : contactoOwnVersionById.get(c.id),
              }))
            : seedMatch?.contactos || [];

          const resolvedEstatusLabel = estatus?.estatus
            ? String(estatus.estatus)
            : seedMatch?.estatus || 'Activo';
          const defaultEmisionFallback =
            resolvedEstatusLabel === 'Estudio' ? 'Pendiente' : '2024-03-15';
          const defaultVencimientoFallback =
            resolvedEstatusLabel === 'Estudio' ? 'En Estudio' : '2027-03-14';
          const derivedVigencia = deriveCertificateVigenciaDates(
            liveFechas,
            seedMatch?.fecha_emision || defaultEmisionFallback,
            seedMatch?.fecha_vencimiento || defaultVencimientoFallback
          );

          const sectorNum = sectorIaf?.sector
            ? Number(sectorIaf.sector)
            : seedMatch?.sector_iaf || 17;
          const matchedSectorMeta =
            state.domainData.iafSectors.find((s) => s.sector === sectorNum) ||
            INITIAL_SECTORES_IAF.find((s) => s.sector === sectorNum);

          const resolvedSubsectorId = row.id_subsector_iaf
            ? String(row.id_subsector_iaf)
            : subsectorIaf?.id
            ? String(subsectorIaf.id)
            : seedMatch?.id_subsector_iaf || state.domainData.iafSubsectors[0]?.id || '';
          const matchedSubsectorFallback =
            state.domainData.iafSubsectors.find((sub) => sub.id === resolvedSubsectorId) ||
            INITIAL_SUBSECTORES_IAF.find((sub) => sub.id === resolvedSubsectorId);

          const riskRaw = subsectorIaf?.categoria_riesgo
            ? String(subsectorIaf.categoria_riesgo)
            : matchedSubsectorFallback?.categoria_riesgo || seedMatch?.subsector_categoria_riesgo;
          const resolvedRisk: 'ALTO' | 'MEDIO' | 'BAJO' | undefined =
            riskRaw === 'ALTO' || riskRaw === 'MEDIO' || riskRaw === 'BAJO'
              ? riskRaw
              : undefined;

          const liveNoAplicables: NonApplicableRequirementEntity[] = !noAplicablesRes.error
            ? noAplicablesByCert.get(certId) || []
            : seedMatch?.noAplicables || [];

          const seedProcsById = new Map((seedMatch?.procesos || []).map((p) => [p.id, p]));
          const baseProcesos: ProcessEntity[] = !procesosRes.error
            ? (procesosByCert.get(certId) || []).map((dbProc) => {
                const seedProc = seedProcsById.get(dbProc.id);
                const useSeedReqs =
                  reqsPorProcesoRes.error && seedProc && seedProc.clausulas_cubiertas.length > 0;
                const clausulas = useSeedReqs
                  ? [...seedProc.clausulas_cubiertas]
                  : dbProc.clausulas_cubiertas;
                const detalles = useSeedReqs
                  ? [...(seedProc.requisitos_detalle || [])]
                  : dbProc.requisitos_detalle;
                const resolvedProcVersion = dbProc.sharedFromCertId
                  ? procesoShareVersionByCertAndId.get(`${certId}::${dbProc.id}`)
                  : procesoOwnVersionById.get(dbProc.id);
                return {
                  ...dbProc,
                  id_certificado_version: resolvedProcVersion,
                  responsable: seedProc?.responsable,
                  clausulas_cubiertas: clausulas,
                  requisitos_detalle: detalles,
                  requisitos_by_certificado: dbProc.requisitos_by_certificado
                    ? {
                        ...dbProc.requisitos_by_certificado,
                        [certId]: {
                          clausulas_cubiertas: clausulas,
                          requisitos_detalle: detalles,
                        },
                      }
                    : undefined,
                };
              })
            : (seedMatch?.procesos || []).map((p) => ({
                ...p,
                clausulas_cubiertas: [...p.clausulas_cubiertas],
                requisitos_detalle: p.requisitos_detalle ? [...p.requisitos_detalle] : undefined,
              }));

          const seedSitesById = new Map((seedMatch?.sitios || []).map((s) => [s.id, s]));
          const baseSitios: SiteEntity[] = !sitiosRes.error
            ? (sitiosByCert.get(certId) || []).map((dbSite) => {
                const seedSite = seedSitesById.get(dbSite.id);
                const resolvedSiteVersion = dbSite.sharedFromCertId
                  ? sitioShareVersionByCertAndId.get(`${certId}::${dbSite.id}`)
                  : sitioOwnVersionById.get(dbSite.id);
                const mappedPps = (dbSite.procesos_por_sitio || []).map((link) => ({
                  ...link,
                  id_certificado_version: ppsVersionById.get(link.id) ?? resolvedSiteVersion,
                }));
                return {
                  ...dbSite,
                  id_certificado_version: resolvedSiteVersion,
                  tipo_sitio: seedSite?.tipo_sitio || dbSite.tipo_sitio,
                  personal_count: dbSite.personal_count ?? seedSite?.personal_count,
                  actividades: seedSite?.actividades,
                  turnos_vinculados: turnosPorSitioRes.error
                    ? [...(seedSite?.turnos_vinculados || [])]
                    : dbSite.turnos_vinculados || [],
                  turnos_por_sitio: turnosPorSitioRes.error
                    ? (seedSite?.turnos_por_sitio || []).map((t) => ({ ...t }))
                    : dbSite.turnos_por_sitio || [],
                  procesos_por_sitio: procesosPorSitioRes.error
                    ? seedSite?.procesos_por_sitio
                      ? seedSite.procesos_por_sitio.map((l) => ({ ...l }))
                      : []
                    : mappedPps,
                  procesos_vinculados: procesosPorSitioRes.error
                    ? [...(seedSite?.procesos_vinculados || [])]
                    : dbSite.procesos_vinculados || [],
                };
              })
            : (seedMatch?.sitios || []).map((s) => ({
                ...s,
                turnos_vinculados: [...(s.turnos_vinculados || [])],
                turnos_por_sitio: (s.turnos_por_sitio || []).map((t) => ({ ...t })),
                procesos_por_sitio: s.procesos_por_sitio
                  ? s.procesos_por_sitio.map((l) => ({ ...l }))
                  : [],
                procesos_vinculados: [...(s.procesos_vinculados || [])],
              }));

          let sitesCount = !sitiosRes.error ? baseSitios.length : 1;
          if (sitiosRes.error) {
            try {
              const { count } = await supabase
                .from('sitio')
                .select('id', { count: 'exact', head: true })
                .eq('id_certificado', certId)
                .is('deleted_at', null);
              if (typeof count === 'number') {
                sitesCount = count;
              }
            } catch {
              // Keep default
            }
          }

          const seedTurnosById = new Map((seedMatch?.turnos || []).map((t) => [t.id, t]));
          const baseTurnos: ShiftEntity[] =
            turnosPorSitioRes.error && turnosCompartidosRes.error
              ? (seedMatch?.turnos || []).map((t) => ({
                  ...t,
                  sitios_vinculados: [...(t.sitios_vinculados || [])],
                }))
              : (turnosByCert.get(certId) || []).map((dbTurno) => {
                  const seedTurno = seedTurnosById.get(dbTurno.id);
                  return {
                    ...dbTurno,
                    id_certificado_version: dbTurno.sharedFromCertId
                      ? turnoShareVersionByCertAndId.get(`${certId}::${dbTurno.id}`)
                      : dbTurno.id_certificado_version,
                    empleados_activos: seedTurno?.empleados_activos ?? dbTurno.empleados_activos,
                  };
                });

          const resolvedAlcanceDetalle: AlcanceCertificadoEntity | null =
            alcanceByCertId !== null
              ? alcanceByCertId.get(certId) ?? null
              : seedMatch?.alcanceDetalle ?? null;
          const resolvedAlcanceText = resolvedAlcanceDetalle
            ? resolvedAlcanceDetalle.alcance_es
            : '';

          const baseCertDetailEntry: CertificadoDetailEntity = {
            id: certId,
            numero_certificado: String(row.numero_certificado || 'FN-CERT-000'),
            id_organizacion: resolvedOrgId,
            organizacion_nombre: org?.nombre
              ? String(org.nombre)
              : seedMatch?.organizacion_nombre || 'Organización Registrada',
            organizacion_abreviacion: resolvedOrgAbrev,
            organizacion_rif: org?.rif
              ? String(org.rif)
              : seedMatch?.organizacion_rif || 'RIF No Registrado',
            direccion_fiscal: org?.direccion_fiscal
              ? String(org.direccion_fiscal)
              : seedMatch?.direccion_fiscal,
            id_norma: norma?.id
              ? String(norma.id)
              : row.id_norma
              ? String(row.id_norma)
              : seedMatch?.id_norma || '',
            norma_codigo: norma?.codigo
              ? String(norma.codigo)
              : norma?.norma
              ? String(norma.norma)
              : seedMatch?.norma_codigo || 'ISO 9001:2015',
            norma_titulo: norma?.titulo
              ? String(norma.titulo)
              : seedMatch?.norma_titulo || 'Sistema de Gestión',
            esquema: norma?.esquema
              ? String(norma.esquema)
              : seedMatch?.esquema || 'SGC - Calidad',
            id_estatus: estatus?.id
              ? String(estatus.id)
              : row.id_estatus
              ? String(row.id_estatus)
              : seedMatch?.id_estatus || '',
            estatus: resolvedEstatusLabel,
            id_sector_iaf: sectorIaf?.id
              ? String(sectorIaf.id)
              : row.id_sector_iaf
              ? String(row.id_sector_iaf)
              : seedMatch?.id_sector_iaf || '',
            sector_iaf: sectorNum,
            sector_iaf_descripcion:
              matchedSectorMeta?.descripcion ||
              seedMatch?.sector_iaf_descripcion ||
              `Sector ${sectorNum}`,
            id_subsector_iaf: resolvedSubsectorId,
            subsector_iaf_codigo: subsectorIaf?.codigo
              ? String(subsectorIaf.codigo)
              : matchedSubsectorFallback?.codigo || seedMatch?.subsector_iaf_codigo,
            subsector_iaf_descripcion: subsectorIaf?.descripcion
              ? String(subsectorIaf.descripcion)
              : matchedSubsectorFallback?.descripcion || seedMatch?.subsector_iaf_descripcion,
            subsector_categoria_riesgo: resolvedRisk,
            organismo_acreditador_codigo: seedMatch?.organismo_acreditador_codigo,
            organismo_acreditador_nombre: seedMatch?.organismo_acreditador_nombre,
            numero_acreditacion: seedMatch?.numero_acreditacion,
            fecha_emision: derivedVigencia.fecha_emision,
            fecha_vencimiento: derivedVigencia.fecha_vencimiento,
            alcance: resolvedAlcanceText,
            alcanceDetalle: resolvedAlcanceDetalle,
            multisitio: Boolean(row.multisitio),
            sitios: baseSitios,
            procesos: baseProcesos,
            turnos: baseTurnos,
            noAplicables: liveNoAplicables,
            auditorias: seedMatch?.auditorias || [],
            fechas: liveFechas,
            contactos: liveContactos,
          };

          const certDetailEntry = assembleCertificateVersionsAndChildCollections({
            cert: baseCertDetailEntry,
            rawVersions: rawCertVersions.length > 0 ? rawCertVersions : undefined,
            estatusById,
            sectorById,
            subsectorById,
            orgVersionAbrevById,
            requirementsCatalog: effectiveCatalog,
            archivedProcesoIds: state.domainData.archivedProcesoIds,
            archivedNoAplicableIds: state.domainData.archivedNoAplicableIds,
          });

          if (!certDetailEntry.cobertura) {
            certDetailEntry.cobertura = buildCertificateCoberturaCache(
              certDetailEntry,
              effectiveCatalog,
              certDetailEntry.id_certificado_version
            );
          }

          loadedDetailed.push(certDetailEntry);

          const searchRecord = buildCertificateSearchRecordFromDetail(certDetailEntry);
          return {
            ...searchRecord,
            sitios_count: !sitiosRes.error ? certDetailEntry.sitios.length : sitesCount,
          };
        })
      );

      // Merge with sample records only for ADMIN/WORKER staff so CLIENT & AUDITOR stay strictly scoped to authorized live DB records
      if (isApprovedStaff()) {
        const enrichedSeed = normalizeSeededCertificadosWithVersionAndAlcance(
          INITIAL_CERTIFICADOS_DETAILED,
          state.domainData.allOrganizaciones,
          effectiveCatalog
        );
        const existingCodes = new Set(loaded.map((item) => item.numero_certificado));
        const existingDetailIds = new Set(loadedDetailed.map((item) => item.id));
        const supplemental = enrichedSeed.searchRecords.filter(
          (s) => !existingCodes.has(s.numero_certificado)
        );
        const supplementalDetailed = enrichedSeed.certificados.filter(
          (s) => !existingDetailIds.has(s.id) && !existingCodes.has(s.numero_certificado)
        );
        state.exploration.records = [...loaded, ...supplemental];
        state.domainData.allCertificadosDetailed = [...loadedDetailed, ...supplementalDetailed];
      } else {
        state.exploration.records = loaded;
        state.domainData.allCertificadosDetailed = loadedDetailed;
      }
    } else {
      if (isApprovedStaff()) {
        const enrichedSeed = normalizeSeededCertificadosWithVersionAndAlcance(
          INITIAL_CERTIFICADOS_DETAILED,
          state.domainData.allOrganizaciones,
          effectiveCatalog
        );
        state.exploration.records = enrichedSeed.searchRecords;
        state.domainData.allCertificadosDetailed = enrichedSeed.certificados;
      } else {
        state.exploration.records = [];
        state.domainData.allCertificadosDetailed = [];
      }
    }
  } catch {
    if (isApprovedStaff()) {
      const enrichedSeed = normalizeSeededCertificadosWithVersionAndAlcance(
        INITIAL_CERTIFICADOS_DETAILED,
        state.domainData.allOrganizaciones,
        getEffectiveRequirementsCatalog()
      );
      state.exploration.records = enrichedSeed.searchRecords;
      state.domainData.allCertificadosDetailed = enrichedSeed.certificados;
    } else {
      state.exploration.records = [];
      state.domainData.allCertificadosDetailed = [];
    }
  } finally {
    if (state.domainData.programacionAudits.length > 0) {
      state.domainData.programacionAudits = state.domainData.programacionAudits.map((a) => {
        const versionMeta = resolveAuditCertificateVersionMeta({
          id_certificado: a.id_certificado,
          rawIdCertificadoVersion: a.id_certificado_version,
          rawVersionNumero: a.version_numero,
          certificados: state.domainData.allCertificadosDetailed,
        });
        return {
          ...a,
          id_certificado_version: versionMeta.id_certificado_version,
          version_numero: versionMeta.version_numero,
        };
      });
    }
    state.exploration.loading = false;
    render();
  }
}

async function loadDomainData(): Promise<void> {
  if (state.domainData.loading) return;
  state.domainData.loading = true;

  try {
    const [
      auditorsRes,
      gruposRes,
      orgsRes,
      orgVersionsRes,
      clientAccessesRes,
      sitesRes,
      processesRes,
      shiftsRes,
      standardsRes,
      requirementsPagedResInitial,
      translationsPagedRes,
      iafRes,
      iafSubsectorsRes,
      estatusRes,
      tipoAuditoriaRes,
      metodologiaRes,
      findingsRes,
      organismosRes,
      acreditacionesRes,
      vinculosRes,
    ] = await Promise.all([
      supabase
        .from('auditor')
        .select(`
          id,
          nombre,
          normas:norma_auditor (
            id_norma,
            norma:id_norma ( id, codigo, titulo, norma, esquema )
          ),
          sectores:sector_iaf_auditor (
            id_sector_iaf,
            sector:id_sector_iaf ( id, sector )
          ),
          subsectores:subsector_iaf_auditor (
            id_subsector_iaf,
            created_at,
            subsector:id_subsector_iaf ( id, id_sector_iaf, codigo, descripcion, categoria_riesgo )
          )
        `)
        .is('deleted_at', null),
      (async () => {
        const res = await supabase
          .from('grupo_empresarial')
          .select('id, codigo_grupo, nombre, abreviacion, es_individual_auto, notas, created_at, updated_at')
          .is('deleted_at', null)
          .order('nombre', { ascending: true });
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('grupo_empresarial')
            .select('id, codigo_grupo, nombre, es_individual_auto, notas, created_at, updated_at')
            .is('deleted_at', null)
            .order('nombre', { ascending: true });
        }
        return res;
      })(),
      (async () => {
        const res = await supabase
          .from('organizacion')
          .select('id, id_grupo_empresarial, nombre, abreviacion, rif, direccion_fiscal')
          .is('deleted_at', null);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('organizacion')
            .select('id, id_grupo_empresarial, nombre, rif, direccion_fiscal')
            .is('deleted_at', null);
        }
        return res;
      })(),
      supabase
        .from('organizacion_version')
        .select(
          'id, id_organizacion, version_numero, es_version_actual, notas_version, nombre, abreviacion, rif, direccion_fiscal, created_at, updated_at, deleted_at'
        )
        .is('deleted_at', null)
        .order('version_numero', { ascending: false }),
      isApprovedStaff()
        ? supabase
            .from('client_organization_access')
            .select(
              'id, id_usuario, id_organizacion, estado, aprobado_por, fecha_solicitud, fecha_respuesta, motivo_rechazo, organizacion:id_organizacion ( nombre, rif )'
            )
            .is('deleted_at', null)
            .order('fecha_solicitud', { ascending: false })
        : Promise.resolve({ data: null, error: null }),
      supabase
        .from('sitio')
        .select(`
          id,
          numero_sitio,
          nombre_sitio,
          direccion_sitio,
          personal_count,
          certificado:id_certificado ( numero_certificado )
        `)
        .is('deleted_at', null),
      supabase
        .from('proceso')
        .select(`
          id,
          nombre_proceso,
          certificado:id_certificado ( numero_certificado )
        `)
        .is('deleted_at', null),
      supabase
        .from('turno')
        .select('id, hora_entrada, hora_salida')
        .is('deleted_at', null),
      supabase
        .from('norma')
        .select('id, esquema, codigo, titulo, estatus, fecha_publicacion, norma')
        .is('deleted_at', null)
        .order('codigo', { ascending: true }),
      fetchAllPagedRows<RawRequisitoRow>(async (from, to) => {
        const res = await supabase
          .from('requisito')
          .select(`
            id,
            id_norma,
            id_requisito_padre,
            codigo,
            explicit_code,
            es_obligatorio,
            obligatorio_origen,
            ruta_materializada,
            norma:id_norma ( id, codigo, norma )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return {
          data: (res.data as RawRequisitoRow[] | null) ?? null,
          error: res.error,
        };
      }, 1000),
      fetchAllPagedRows<RawRequisitoTraduccionRow>(async (from, to) => {
        const res = await supabase
          .from('requisito_traduccion')
          .select('id, id_requisito, lang, title, content_html, updated_at')
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return {
          data: (res.data as RawRequisitoTraduccionRow[] | null) ?? null,
          error: res.error,
        };
      }, 1000),
      supabase
        .from('sector_iaf')
        .select('id, sector, descripcion')
        .is('deleted_at', null),
      supabase
        .from('subsector_iaf')
        .select('id, id_sector_iaf, codigo, descripcion, categoria_riesgo')
        .is('deleted_at', null),
      supabase
        .from('estatus')
        .select('id, estatus')
        .is('deleted_at', null),
      (async () => {
        const res = await supabase
          .from('tipo_auditoria')
          .select('id, tipo, abreviacion')
          .is('deleted_at', null);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('tipo_auditoria')
            .select('id, tipo')
            .is('deleted_at', null);
        }
        return res;
      })(),
      supabase
        .from('metodologia_auditoria')
        .select('id, metodologia')
        .is('deleted_at', null),
      (async () => {
        const res = await supabase
          .from('hallazgo')
          .select(`
            id,
            id_auditoria,
            id_requisito,
            id_proceso,
            id_sitio,
            tipo,
            descripcion,
            evidencia,
            fecha_limite_plan,
            fecha_entrega_plan,
            fecha_limite_cierre,
            fecha_cierre_real,
            cerrado,
            created_at,
            auditoria:id_auditoria (
              tipo_auditoria:id_tipo_auditoria ( tipo ),
              certificado:id_certificado (
                numero_certificado,
                organizacion:id_organizacion ( nombre )
              )
            ),
            requisito:id_requisito ( codigo ),
            proceso:id_proceso ( nombre_proceso ),
            sitio:id_sitio ( nombre_sitio )
          `)
          .is('deleted_at', null);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('hallazgo')
            .select(`
              id,
              id_auditoria,
              id_requisito,
              id_proceso,
              tipo,
              descripcion,
              evidencia,
              cerrado,
              created_at,
              auditoria:id_auditoria (
                tipo_auditoria:id_tipo_auditoria ( tipo ),
                certificado:id_certificado (
                  numero_certificado,
                  organizacion:id_organizacion ( nombre )
                )
              ),
              requisito:id_requisito ( codigo ),
              proceso:id_proceso ( nombre_proceso )
            `)
            .is('deleted_at', null);
        }
        return res;
      })(),
      supabase
        .from('organismo_acreditacion')
        .select('id, codigo, nombre, pais, sitio_web')
        .is('deleted_at', null),
      supabase
        .from('acreditacion_norma')
        .select(`
          id,
          id_organismo,
          id_norma,
          id_estatus,
          numero_acreditacion,
          fecha_concesion,
          fecha_vencimiento,
          deleted_at,
          organismo:id_organismo ( id, codigo, nombre, pais, sitio_web, deleted_at ),
          norma:id_norma ( id, codigo, titulo, norma, esquema, deleted_at ),
          estatus_ref:id_estatus ( id, estatus, deleted_at ),
          sectores:acreditacion_norma_sector_iaf (
            id,
            id_acreditacion_norma,
            id_sector_iaf,
            deleted_at,
            sector_iaf:id_sector_iaf ( id, sector, descripcion, deleted_at )
          )
        `)
        .is('deleted_at', null),
      (async () => {
        const res = await supabase
          .from('vinculo')
          .select(`
            id,
            id_grupo_empresarial,
            codigo_vinculo,
            etiqueta,
            nivel_vinculacion,
            tipo_vinculacion,
            es_vinculada,
            tiene_sitio_temporal,
            notas,
            deleted_at,
            grupo:id_grupo_empresarial ( nombre, abreviacion ),
            vinculo_certificado (
              id,
              id_vinculo,
              id_certificado,
              tipo_vinculacion_override,
              deleted_at,
              certificado:id_certificado (
                numero_certificado,
                id_organizacion,
                organizacion:id_organizacion ( nombre, abreviacion ),
                norma:id_norma ( codigo, norma ),
                estatus:id_estatus ( estatus )
              )
            )
          `)
          .is('deleted_at', null)
          .order('etiqueta', { ascending: true });
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          return supabase
            .from('vinculo')
            .select(`
              id,
              id_grupo_empresarial,
              codigo_vinculo,
              etiqueta,
              nivel_vinculacion,
              tipo_vinculacion,
              es_vinculada,
              tiene_sitio_temporal,
              notas,
              deleted_at,
              grupo:id_grupo_empresarial ( nombre ),
              vinculo_certificado (
                id,
                id_vinculo,
                id_certificado,
                deleted_at,
                certificado:id_certificado (
                  numero_certificado,
                  id_organizacion,
                  organizacion:id_organizacion ( nombre ),
                  norma:id_norma ( codigo, norma ),
                  estatus:id_estatus ( estatus )
                )
              )
            `)
            .is('deleted_at', null)
            .order('etiqueta', { ascending: true });
        }
        return res;
      })(),
    ]);

    // Audits are hydrated via paginated loadLiveAudits() without obsolete flat date columns

    // Process Auditors (hydrating M:N norma_auditor, sector_iaf_auditor, subsector_iaf_auditor)
    if (!auditorsRes.error && Array.isArray(auditorsRes.data) && auditorsRes.data.length > 0) {
      const hydratedAuditorsDetailed: AuditorDetailEntity[] = auditorsRes.data.map(
        (row: Record<string, unknown>) => {
          const audId = String(row.id);
          const audNombre = String(row.nombre || 'Auditor Evaluador');
          const seedMatch = INITIAL_AUDITORES_DETAILED.find((a) => a.id === audId);

          const normasRaw = Array.isArray(row.normas)
            ? (row.normas as Array<Record<string, unknown>>)
            : [];
          const normaLinks: AuditorNormaLink[] = [];
          const seenNormaIds = new Set<string>();
          for (const n of normasRaw) {
            const inner = (n.norma as Record<string, unknown> | null) || null;
            const idNorma = String(inner?.id || n.id_norma || '').trim();
            if (!idNorma || seenNormaIds.has(idNorma)) continue;
            seenNormaIds.add(idNorma);
            const normaCodigo = String(inner?.codigo || inner?.norma || 'Norma ISO');
            normaLinks.push({
              id_auditor: audId,
              id_norma: idNorma,
              norma_codigo: normaCodigo,
              norma_titulo: inner?.titulo ? String(inner.titulo) : undefined,
              esquema: inner?.esquema ? String(inner.esquema) : undefined,
            });
          }
          normaLinks.sort((a, b) => a.norma_codigo.localeCompare(b.norma_codigo, 'es'));

          const sectoresRaw = Array.isArray(row.sectores)
            ? (row.sectores as Array<Record<string, unknown>>)
            : [];
          const sectorLinks: AuditorSectorLink[] = [];
          const seenSectorIds = new Set<string>();
          for (const s of sectoresRaw) {
            const inner = (s.sector as Record<string, unknown> | null) || null;
            const idSector = String(inner?.id || s.id_sector_iaf || '').trim();
            const secNum = Number(inner?.sector);
            if (!idSector || !Number.isFinite(secNum) || seenSectorIds.has(idSector)) continue;
            seenSectorIds.add(idSector);
            sectorLinks.push({
              id_auditor: audId,
              id_sector_iaf: idSector,
              sector_numero: secNum,
              sector_descripcion: resolveSectorIafDescription(secNum),
            });
          }
          sectorLinks.sort((a, b) => a.sector_numero - b.sector_numero);

          const subsectoresRaw = Array.isArray(row.subsectores)
            ? (row.subsectores as Array<Record<string, unknown>>)
            : [];
          const subsectorLinks: AuditorSubsectorLink[] = [];
          const seenSubIds = new Set<string>();
          for (const subRow of subsectoresRaw) {
            const inner = (subRow.subsector as Record<string, unknown> | null) || null;
            const idSub = String(inner?.id || subRow.id_subsector_iaf || '').trim();
            if (!idSub || seenSubIds.has(idSub)) continue;
            seenSubIds.add(idSub);
            const subCodigo = String(inner?.codigo || '—');
            const idSec = String(inner?.id_sector_iaf || '').trim();
            const matchedSector = sectorLinks.find((sl) => sl.id_sector_iaf === idSec);
            const parsedSecNum =
              matchedSector?.sector_numero ?? (Number(subCodigo.split('.')[0]) || 17);
            subsectorLinks.push({
              id_auditor: audId,
              id_subsector_iaf: idSub,
              id_sector_iaf: idSec,
              sector_numero: parsedSecNum,
              subsector_codigo: subCodigo,
              subsector_descripcion: String(inner?.descripcion || 'Sub-Sector IAF'),
              categoria_riesgo: inner?.categoria_riesgo
                ? String(inner.categoria_riesgo)
                : undefined,
              created_at: subRow.created_at ? String(subRow.created_at) : undefined,
            });
          }
          subsectorLinks.sort((a, b) =>
            a.subsector_codigo.localeCompare(b.subsector_codigo, 'es', { numeric: true })
          );

          const normasList = normaLinks.map((l) => l.norma_codigo);
          const iafList = sectorLinks.map((l) => l.sector_numero);

          return {
            id: audId,
            nombre: audNombre,
            titulo_profesional:
              seedMatch?.titulo_profesional || 'Auditor Técnico Evaluador',
            codigo_credencial: seedMatch?.codigo_credencial || '',
            email: seedMatch?.email || '',
            telefono: seedMatch?.telefono || '',
            biografia: seedMatch?.biografia || '',
            instituto_registro: seedMatch?.instituto_registro || 'FONDONORMA',
            categoria_profesional:
              seedMatch?.categoria_profesional || 'Auditor Técnico Calificado',
            calificacion: seedMatch?.calificacion || 'Calificado',
            normas_acreditadas: normasList,
            sectores_iaf: iafList,
            competencias: seedMatch?.competencias || [],
            normaLinks,
            sectorLinks,
            subsectorLinks,
            historialAuditorias: seedMatch?.historialAuditorias || [],
          };
        }
      );

      const dbAuditorIds = new Set(hydratedAuditorsDetailed.map((a) => a.id));
      const mergedAuditors = isApprovedStaff()
        ? [
            ...hydratedAuditorsDetailed,
            ...INITIAL_AUDITORES_DETAILED.filter((s) => !dbAuditorIds.has(s.id)),
          ]
        : hydratedAuditorsDetailed;

      state.domainData.allAuditorsDetailed = mergedAuditors;
      state.domainData.auditors = mergedAuditors.map((aud) => ({
        id: aud.id,
        nombre: aud.nombre,
        normas: aud.normas_acreditadas,
        sectores_iaf: aud.sectores_iaf,
        rol: aud.categoria_profesional || 'Auditor Técnico Calificado',
      }));
    }

    // Process Conglomerados (grupo_empresarial) & link into Organizations
    if (!gruposRes.error && Array.isArray(gruposRes.data) && gruposRes.data.length > 0) {
      const gruposFromDb: ConglomeradoEntity[] = gruposRes.data.map(
        (row: Record<string, unknown>) => ({
          id: String(row.id),
          codigo_grupo: row.codigo_grupo ? String(row.codigo_grupo) : null,
          nombre: String(row.nombre || 'Conglomerado Empresarial'),
          abreviacion: row.abreviacion ? String(row.abreviacion) : null,
          es_individual_auto: Boolean(row.es_individual_auto),
          notas: row.notas ? String(row.notas) : null,
          created_at: row.created_at ? String(row.created_at) : undefined,
          updated_at: row.updated_at ? String(row.updated_at) : undefined,
          deleted_at: null,
        })
      );
      const dbGroupIds = new Set(gruposFromDb.map((g) => g.id));
      state.domainData.allConglomerados = isApprovedStaff()
        ? [...gruposFromDb, ...INITIAL_CONGLOMERADOS.filter((s) => !dbGroupIds.has(s.id))]
        : gruposFromDb;
    } else if (!isApprovedStaff()) {
      state.domainData.allConglomerados = [];
    }

    const groupNameLookup = new Map<string, string>();
    for (const g of state.domainData.allConglomerados) {
      groupNameLookup.set(g.id, g.nombre);
    }

    // Process Vínculos (`vinculo` + `vinculo_certificado`)
    if (!vinculosRes.error && Array.isArray(vinculosRes.data) && vinculosRes.data.length > 0) {
      const vinculosFromDb: VinculoEntity[] = vinculosRes.data.map(
        (row: Record<string, unknown>) => {
          const grupoObj = (row.grupo as Record<string, unknown> | null) || null;
          const groupId = String(row.id_grupo_empresarial || '');
          const rawLinks = Array.isArray(row.vinculo_certificado)
            ? (row.vinculo_certificado as Record<string, unknown>[])
            : [];
          const certItems: VinculoCertificadoItem[] = rawLinks
            .filter((lk) => !lk.deleted_at)
            .map((lk) => {
              const certObj = (lk.certificado as Record<string, unknown> | null) || null;
              const orgObj = (certObj?.organizacion as Record<string, unknown> | null) || null;
              const normaObj = (certObj?.norma as Record<string, unknown> | null) || null;
              const estatusObj = (certObj?.estatus as Record<string, unknown> | null) || null;
              const rawOverride = lk.tipo_vinculacion_override
                ? String(lk.tipo_vinculacion_override)
                : '';
              const parsedOverride: AuditLinkNature | null =
                rawOverride === 'Multisitio' || rawOverride === 'Mixta'
                  ? 'Mixta'
                  : rawOverride === 'Individual' ||
                    rawOverride === 'Combinada' ||
                    rawOverride === 'Integrada' ||
                    rawOverride === 'Conjunta' ||
                    rawOverride === 'Simultánea' ||
                    rawOverride === 'Multientidad'
                  ? rawOverride
                  : null;
              return {
                id: String(lk.id || ''),
                id_vinculo: String(lk.id_vinculo || row.id || ''),
                id_certificado: String(lk.id_certificado || ''),
                numero_certificado: String(certObj?.numero_certificado || 'CERT'),
                norma_codigo: String(normaObj?.codigo || normaObj?.norma || 'ISO'),
                id_organizacion: String(certObj?.id_organizacion || ''),
                organizacion_nombre: String(orgObj?.nombre || 'Organización'),
                organizacion_abreviacion: orgObj?.abreviacion
                  ? String(orgObj.abreviacion)
                  : null,
                tipo_vinculacion_override: parsedOverride,
                estatus: String(estatusObj?.estatus || 'ACTIVO'),
                deleted_at: null,
              };
            });

          const rawNivel = String(row.nivel_vinculacion || 'INDIVIDUAL');
          const nivel: AuditLinkLevel =
            rawNivel === 'NIVEL_1_INTRA_ORG' || rawNivel === 'NIVEL_2_INTER_ORG'
              ? rawNivel
              : 'INDIVIDUAL';
          const rawTipo = String(row.tipo_vinculacion || 'Individual');
          const tipo: AuditLinkNature =
            rawTipo === 'Multisitio' || rawTipo === 'Mixta'
              ? 'Mixta'
              : rawTipo === 'Individual' ||
                rawTipo === 'Combinada' ||
                rawTipo === 'Integrada' ||
                rawTipo === 'Conjunta' ||
                rawTipo === 'Simultánea' ||
                rawTipo === 'Multientidad'
              ? rawTipo
              : 'Individual';

          return {
            id: String(row.id),
            id_grupo_empresarial: groupId,
            grupo_nombre:
              (grupoObj?.nombre ? String(grupoObj.nombre) : undefined) ||
              groupNameLookup.get(groupId) ||
              'Conglomerado',
            codigo_vinculo: row.codigo_vinculo ? String(row.codigo_vinculo) : null,
            etiqueta: String(row.etiqueta || 'Vínculo'),
            nivel_vinculacion: nivel,
            tipo_vinculacion: tipo,
            es_vinculada: Boolean(row.es_vinculada),
            tiene_sitio_temporal: Boolean(row.tiene_sitio_temporal),
            notas: row.notas ? String(row.notas) : null,
            certificados: certItems,
            deleted_at: null,
          };
        }
      );
      state.domainData.allVinculos = vinculosFromDb;
    } else if (!isApprovedStaff()) {
      state.domainData.allVinculos = [];
    }

    // Process Organizations & `organizacion_version` (`version_numero DESC`)
    if (!orgsRes.error && Array.isArray(orgsRes.data) && orgsRes.data.length > 0) {
      const hydratedOrgs = hydrateOrganizacionesWithVersions({
        rawOrganizaciones: orgsRes.data as unknown as RawOrganizacionRow[],
        rawOrganizacionVersions:
          !orgVersionsRes.error && Array.isArray(orgVersionsRes.data)
            ? (orgVersionsRes.data as unknown as RawOrganizacionVersionRow[])
            : undefined,
        groupNameById: groupNameLookup,
        includeSeedFallback: isApprovedStaff(),
        seedOrganizaciones: INITIAL_ORGANIZACIONES,
      });
      state.domainData.allOrganizaciones = hydratedOrgs.allOrganizaciones;
      state.domainData.organizations = hydratedOrgs.organizations;
    } else if (!isApprovedStaff()) {
      state.domainData.allOrganizaciones = [];
      state.domainData.organizations = [];
    } else {
      const hydratedFallback = hydrateOrganizacionesWithVersions({
        rawOrganizacionVersions:
          !orgVersionsRes.error && Array.isArray(orgVersionsRes.data)
            ? (orgVersionsRes.data as unknown as RawOrganizacionVersionRow[])
            : undefined,
        groupNameById: groupNameLookup,
        includeSeedFallback: true,
        seedOrganizaciones: INITIAL_ORGANIZACIONES,
      });
      state.domainData.allOrganizaciones = hydratedFallback.allOrganizaciones;
      state.domainData.organizations = hydratedFallback.organizations;
    }

    // Process Client Organization Accesses (strictly for approved ADMIN/WORKER staff)
    if (
      isApprovedStaff() &&
      !clientAccessesRes.error &&
      Array.isArray(clientAccessesRes.data)
    ) {
      state.domainData.allClientAccesses = clientAccessesRes.data.map(
        (row: Record<string, unknown>) => {
          const orgObj = (row.organizacion as Record<string, unknown> | null) || null;
          const userId = String(row.id_usuario || '');
          const approverId = row.aprobado_por ? String(row.aprobado_por) : null;
          const matchedUser = state.approvals.profiles.find((p) => p.id === userId);
          const matchedApprover = approverId
            ? state.approvals.profiles.find((p) => p.id === approverId)
            : undefined;
          const rawEstado = String(row.estado || 'PENDING');
          const estado: ClientAccessEstado =
            rawEstado === 'APPROVED' || rawEstado === 'REJECTED' ? rawEstado : 'PENDING';
          return {
            id: String(row.id),
            id_usuario: userId,
            usuario_nombre: matchedUser?.nombre,
            usuario_role: matchedUser?.role || 'CLIENT',
            id_organizacion: String(row.id_organizacion || ''),
            organizacion_nombre: orgObj?.nombre ? String(orgObj.nombre) : undefined,
            organizacion_rif: orgObj?.rif ? String(orgObj.rif) : undefined,
            estado,
            aprobado_por: approverId,
            aprobado_por_nombre: matchedApprover?.nombre || null,
            fecha_solicitud: row.fecha_solicitud ? String(row.fecha_solicitud) : '',
            fecha_respuesta: row.fecha_respuesta ? String(row.fecha_respuesta) : null,
            motivo_rechazo: row.motivo_rechazo ? String(row.motivo_rechazo) : null,
            deleted_at: null,
          };
        }
      );
    } else if (!isApprovedStaff()) {
      state.domainData.allClientAccesses = [];
    }

    // Process Sites
    if (!sitesRes.error && Array.isArray(sitesRes.data) && sitesRes.data.length > 0) {
      state.domainData.sites = sitesRes.data.map((row: Record<string, unknown>) => {
        const certObj = (row.certificado as Record<string, unknown> | null) || {};
        return {
          id: String(row.id),
          numero_sitio: Number(row.numero_sitio) || 1,
          nombre_sitio: String(row.nombre_sitio),
          direccion_sitio: String(row.direccion_sitio),
          numero_certificado: String(certObj.numero_certificado || 'FN-QMS-2024-001'),
          turnos_count: 2,
        };
      });
    }

    // Process Processes
    if (!processesRes.error && Array.isArray(processesRes.data) && processesRes.data.length > 0) {
      state.domainData.processes = processesRes.data.map((row: Record<string, unknown>) => {
        const certObj = (row.certificado as Record<string, unknown> | null) || {};
        return {
          id: String(row.id),
          nombre_proceso: String(row.nombre_proceso),
          numero_certificado: String(certObj.numero_certificado || 'FN-QMS-2024-001'),
          clausulas_cubiertas: ['4.1', '8.5'],
        };
      });
    }

    // Process Shifts
    if (!shiftsRes.error && Array.isArray(shiftsRes.data) && shiftsRes.data.length > 0) {
      state.domainData.shifts = shiftsRes.data.map((row: Record<string, unknown>, idx: number) => ({
        id: String(row.id),
        hora_entrada: String(row.hora_entrada),
        hora_salida: String(row.hora_salida),
        descripcion: idx === 0 ? 'Turno Matutino Operativo' : 'Turno Vespertino / Nocturno',
        sitios_vinculados: ['Planta Valencia'],
      }));
      const liveShiftCatalog: TurnoCatalogItem[] = shiftsRes.data.map(
        (row: Record<string, unknown>, idx: number) => {
          const seedMatch = INITIAL_TURNO_CATALOG.find((t) => t.id === String(row.id));
          return {
            id: String(row.id),
            hora_entrada: String(row.hora_entrada),
            hora_salida: String(row.hora_salida),
            descripcion:
              seedMatch?.descripcion ||
              (idx === 0 ? 'Turno Matutino Operativo' : `Turno Operativo ${idx + 1}`),
          };
        }
      );
      const liveIds = new Set(liveShiftCatalog.map((t) => t.id));
      state.domainData.shiftCatalog = [
        ...liveShiftCatalog,
        ...INITIAL_TURNO_CATALOG.filter((t) => !liveIds.has(t.id)),
      ];
    }

    // Process Standards, Requirements & Bilingual Translations (paginated >1,000 rows + graceful offline/unmigrated fallback)
    let requirementsPagedRes = requirementsPagedResInitial;
    if (requirementsPagedRes.error && isMissingTableOrSchemaError(requirementsPagedRes.error)) {
      requirementsPagedRes = await fetchAllPagedRows<RawRequisitoRow>(async (from, to) => {
        const res = await supabase
          .from('requisito')
          .select(`
            id,
            id_norma,
            id_requisito_padre,
            codigo,
            ruta_materializada,
            norma:id_norma ( id, codigo, norma )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return {
          data: (res.data as RawRequisitoRow[] | null) ?? null,
          error: res.error,
        };
      }, 1000);
    }

    const translationsTableMissing = Boolean(
      translationsPagedRes.error && isMissingTableOrSchemaError(translationsPagedRes.error)
    );
    const rawNormas =
      !standardsRes.error && Array.isArray(standardsRes.data)
        ? (standardsRes.data as RawNormaRow[])
        : null;
    const rawRequisitos =
      !requirementsPagedRes.error && requirementsPagedRes.data.length > 0
        ? requirementsPagedRes.data
        : null;
    const rawTranslations =
      !translationsPagedRes.error && !translationsTableMissing
        ? translationsPagedRes.data
        : null;

    const hydratedNormaBundle = assembleHydratedNormasAndRequisitos({
      rawNormas,
      rawRequisitos,
      rawTranslations,
      translationsTableMissing,
      existingStandardsFallback: buildNormaEntitiesForDependencyCheck(),
    });

    state.domainData.standards = hydratedNormaBundle.standards.map((std) => ({
      id: std.id,
      esquema: std.esquema,
      codigo: std.codigo,
      titulo: std.titulo,
      estatus: std.estatus,
      fecha_publicacion: std.fecha_publicacion,
      norma: std.norma,
      clausulas_count: std.clausulas_count,
      acreditaciones_count: std.acreditaciones_count,
    }));
    state.domainData.requirementsCatalog = hydratedNormaBundle.requirementsCatalog;
    state.domainData.requirements = hydratedNormaBundle.requirements;

    state.domainData.allCertificadosDetailed = state.domainData.allCertificadosDetailed.map(
      (cert) => ({
        ...cert,
        cobertura: buildCertificateCoberturaCache(
          cert,
          hydratedNormaBundle.requirementsCatalog
        ),
      })
    );

    // Process IAF Sectors (with legacy fallback if descripcion column is pending migration)
    let iafRows =
      !iafRes.error && Array.isArray(iafRes.data) ? (iafRes.data as Array<Record<string, unknown>>) : null;
    if (iafRes.error && isMissingTableOrSchemaError(iafRes.error)) {
      const legacyIafRes = await supabase
        .from('sector_iaf')
        .select('id, sector')
        .is('deleted_at', null);
      if (!legacyIafRes.error && Array.isArray(legacyIafRes.data)) {
        iafRows = legacyIafRes.data as Array<Record<string, unknown>>;
      }
    }
    if (iafRows && iafRows.length > 0) {
      state.domainData.iafSectors = iafRows.map((row: Record<string, unknown>) => {
        const secNum = Number(row.sector);
        const customDesc = row.descripcion ? String(row.descripcion) : null;
        return {
          id: String(row.id),
          sector: secNum,
          descripcion: resolveSectorIafDescription(secNum, customDesc),
        };
      });
    }

    // Process IAF Subsectors
    if (
      !iafSubsectorsRes.error &&
      Array.isArray(iafSubsectorsRes.data) &&
      iafSubsectorsRes.data.length > 0
    ) {
      const sectorPool =
        state.domainData.iafSectors.length > 0
          ? state.domainData.iafSectors
          : INITIAL_SECTORES_IAF;
      const hydratedSubsectors: SubsectorIafEntity[] = iafSubsectorsRes.data.map(
        (row: Record<string, unknown>) => {
          const subId = String(row.id || '');
          const sectorId = String(row.id_sector_iaf || '');
          const codigo = String(row.codigo || '');
          const seedMatch =
            INITIAL_SUBSECTORES_IAF.find((s) => s.id === subId) ||
            INITIAL_SUBSECTORES_IAF.find((s) => s.codigo === codigo);
          const matchedSector =
            sectorPool.find((sec) => sec.id === sectorId) ||
            INITIAL_SECTORES_IAF.find((sec) => sec.id === sectorId);
          const parsedSectorNum =
            matchedSector?.sector ??
            seedMatch?.sector_numero ??
            (Number(codigo.split('.')[0]) || 17);
          const rawRisk = String(row.categoria_riesgo || seedMatch?.categoria_riesgo || 'MEDIO');
          const categoriaRiesgo: 'ALTO' | 'MEDIO' | 'BAJO' =
            rawRisk === 'ALTO' || rawRisk === 'BAJO' ? rawRisk : 'MEDIO';
          return {
            id: subId,
            id_sector_iaf: sectorId || seedMatch?.id_sector_iaf || '',
            sector_numero: parsedSectorNum,
            codigo: codigo || seedMatch?.codigo || `${parsedSectorNum}.1`,
            descripcion: String(row.descripcion || seedMatch?.descripcion || 'Sub-Sector IAF'),
            categoria_riesgo: categoriaRiesgo,
            auditores_nombres: seedMatch?.auditores_nombres || [],
          };
        }
      );
      const seenSubIds = new Set(hydratedSubsectors.map((s) => s.id));
      const seenSubCodes = new Set(hydratedSubsectors.map((s) => s.codigo));
      state.domainData.iafSubsectors = [
        ...hydratedSubsectors,
        ...INITIAL_SUBSECTORES_IAF.filter(
          (s) => !seenSubIds.has(s.id) && !seenSubCodes.has(s.codigo)
        ),
      ];
      state.domainData.iafSectors = state.domainData.iafSectors.map((sec) => ({
        ...sec,
        subsectores_count: state.domainData.iafSubsectors.filter(
          (sub) => sub.id_sector_iaf === sec.id || sub.sector_numero === sec.sector
        ).length,
      }));
    }

    // Process Catalogs
    const mergedCatalogs: CatalogItem[] = [];
    if (!estatusRes.error && Array.isArray(estatusRes.data)) {
      const hydratedEstatus: EstatusCatalogItem[] = [];
      estatusRes.data.forEach((r: Record<string, unknown>) => {
        if (r.estatus) {
          const val = String(r.estatus);
          mergedCatalogs.push({ categoria: 'estatus', valor: val });
          const seedMatch = INITIAL_ESTATUS_CATALOG.find(
            (e) => e.estatus.toLowerCase() === val.toLowerCase()
          );
          if (r.id) {
            hydratedEstatus.push({
              id: String(r.id),
              estatus: seedMatch?.estatus || val,
              descripcion: seedMatch?.descripcion || `Estado operativo ${val}.`,
              categoria_aplicable: seedMatch?.categoria_aplicable || 'Certificados, Auditorías',
              color_token: seedMatch?.color_token || 'slate',
              usage_count: seedMatch?.usage_count ?? 0,
            });
          }
        }
      });
      if (hydratedEstatus.length > 0) {
        const seenNames = new Set(hydratedEstatus.map((e) => e.estatus.toLowerCase()));
        state.domainData.estatusCatalog = [
          ...hydratedEstatus,
          ...INITIAL_ESTATUS_CATALOG.filter((e) => !seenNames.has(e.estatus.toLowerCase())),
        ];
      }
    }
    if (!tipoAuditoriaRes.error && Array.isArray(tipoAuditoriaRes.data)) {
      const hydratedTipos: TipoAuditoriaCatalogItem[] = [];
      tipoAuditoriaRes.data.forEach((r: Record<string, unknown>) => {
        if (r.tipo) {
          const val = String(r.tipo);
          mergedCatalogs.push({ categoria: 'tipo_auditoria', valor: val });
          if (r.id) {
            hydratedTipos.push(
              buildTipoAuditoriaCatalogItem({
                id: String(r.id),
                tipo: val,
                abreviacion: r.abreviacion ? String(r.abreviacion) : null,
              })
            );
          }
        }
      });
      if (hydratedTipos.length > 0) {
        const seenTipos = new Set(hydratedTipos.map((t) => t.tipo.toLowerCase()));
        state.domainData.tiposCatalog = [
          ...hydratedTipos,
          ...INITIAL_TIPOS_AUDITORIA_CATALOG.filter((t) => !seenTipos.has(t.tipo.toLowerCase())),
        ];
      }
    }
    if (!metodologiaRes.error && Array.isArray(metodologiaRes.data)) {
      const hydratedMetodologias: MetodologiaAuditoriaCatalogItem[] = [];
      metodologiaRes.data.forEach((r: Record<string, unknown>) => {
        if (r.metodologia) {
          const val = String(r.metodologia);
          mergedCatalogs.push({ categoria: 'metodologia', valor: val });
          if (r.id) {
            hydratedMetodologias.push(
              buildMetodologiaAuditoriaCatalogItem({
                id: String(r.id),
                metodologia: val,
              })
            );
          }
        }
      });
      if (hydratedMetodologias.length > 0) {
        const seenMets = new Set(
          hydratedMetodologias.map((m) => m.metodologia.toLowerCase())
        );
        state.domainData.metodologiasCatalog = [
          ...hydratedMetodologias,
          ...INITIAL_METODOLOGIAS_CATALOG.filter(
            (m) => !seenMets.has(m.metodologia.toLowerCase())
          ),
        ];
      }
    }
    if (mergedCatalogs.length > 0) {
      state.domainData.catalogs = mergedCatalogs;
    }

    // Process Findings (hydrate both legacy findings & Step 10.2 phase5Findings)
    if (!findingsRes.error && Array.isArray(findingsRes.data) && findingsRes.data.length > 0) {
      const prevPhase5ById = new Map(state.domainData.phase5Findings.map((f) => [f.id, f]));
      const loadedPhase5Findings: Phase5FindingEntity[] = findingsRes.data.map(
        (row: Record<string, unknown>, idx: number) => {
          const aud = (row.auditoria as Record<string, unknown> | null) || {};
          const cert = (aud.certificado as Record<string, unknown> | null) || {};
          const org = (cert.organizacion as Record<string, unknown> | null) || {};
          const tipoAud = (aud.tipo_auditoria as Record<string, unknown> | null) || {};
          const req = (row.requisito as Record<string, unknown> | null) || {};
          const proc = (row.proceso as Record<string, unknown> | null) || {};
          const sitioObj = (row.sitio as Record<string, unknown> | null) || null;

          const id = String(row.id);
          const prev = prevPhase5ById.get(id);
          const isClosed = Boolean(row.cerrado);
          const fechaLimitePlan = row.fecha_limite_plan
            ? String(row.fecha_limite_plan).slice(0, 10)
            : prev?.fecha_limite_plan ?? null;
          const fechaEntregaPlan = row.fecha_entrega_plan
            ? String(row.fecha_entrega_plan).slice(0, 10)
            : prev?.fecha_entrega_plan ?? null;
          const fechaLimiteCierre = row.fecha_limite_cierre
            ? String(row.fecha_limite_cierre).slice(0, 10)
            : prev?.fecha_limite_cierre ?? null;
          const fechaCierreReal = row.fecha_cierre_real
            ? String(row.fecha_cierre_real).slice(0, 10)
            : prev?.fecha_cierre_real ?? null;

          const lifecycle: FindingLifecycleStatus = isClosed
            ? 'Cerrado'
            : fechaEntregaPlan
            ? 'Plan de Acción Enviado'
            : prev?.estado_ciclo || 'Abierto';

          const yearTag = row.created_at
            ? String(row.created_at).slice(0, 4)
            : String(new Date().getFullYear());

          const hydratedReqMeta = state.domainData.requirements.find(
            (r) => r.id === String(row.id_requisito)
          );
          const procId = row.id_proceso ? String(row.id_proceso) : null;

          return {
            id,
            codigo_hallazgo:
              prev?.codigo_hallazgo || `HAL-${yearTag}-${String(idx + 1).padStart(3, '0')}`,
            id_auditoria: String(row.id_auditoria),
            auditoria_tipo: String(tipoAud.tipo || 'Auditoría'),
            numero_certificado: String(cert.numero_certificado || 'Certificado Activo'),
            organizacion_nombre: String(org.nombre || 'Organización Registrada'),
            id_requisito: String(row.id_requisito),
            requisito_codigo: String(req.codigo || hydratedReqMeta?.codigo || '8.5'),
            requisito_titulo: hydratedReqMeta?.titulo || prev?.requisito_titulo || '',
            id_proceso: procId,
            proceso_nombre: proc.nombre_proceso
              ? String(proc.nombre_proceso)
              : procId
              ? 'Proceso Operativo'
              : 'Por cláusula',
            id_sitio: row.id_sitio ? String(row.id_sitio) : prev?.id_sitio ?? null,
            sitio_nombre: sitioObj?.nombre_sitio
              ? String(sitioObj.nombre_sitio)
              : prev?.sitio_nombre || 'Sede Principal',
            tipo: (row.tipo as FindingType) || 'NC_MENOR',
            descripcion: String(row.descripcion || ''),
            evidencia: row.evidencia ? String(row.evidencia) : null,
            estado_ciclo: lifecycle,
            analisis_causa_raiz: prev?.analisis_causa_raiz || '',
            plan_accion_correctiva: prev?.plan_accion_correctiva || '',
            comentarios_verificacion: prev?.comentarios_verificacion || '',
            fecha_limite:
              fechaLimiteCierre || prev?.fecha_limite || fechaLimitePlan || 'Pendiente',
            fecha_limite_plan: fechaLimitePlan,
            fecha_entrega_plan: fechaEntregaPlan,
            fecha_limite_cierre: fechaLimiteCierre ?? prev?.fecha_limite ?? null,
            fecha_cierre_real: fechaCierreReal,
            fecha_cierre: fechaCierreReal ?? prev?.fecha_cierre ?? null,
            cerrado: isClosed,
            created_at: row.created_at ? String(row.created_at) : undefined,
            deleted_at: null,
          };
        }
      );

      if (isApprovedStaff()) {
        const existingIds = new Set(loadedPhase5Findings.map((f) => f.id));
        const supplementalLegacy = INITIAL_FINDINGS.filter((f) => !existingIds.has(f.id));
        const supplementalPhase5 = INITIAL_PHASE5_FINDINGS.filter((f) => !existingIds.has(f.id));
        state.domainData.findings = [...loadedPhase5Findings, ...supplementalLegacy];
        state.domainData.phase5Findings = [...loadedPhase5Findings, ...supplementalPhase5];
      } else {
        state.domainData.findings = loadedPhase5Findings;
        state.domainData.phase5Findings = loadedPhase5Findings;
      }
    } else if (findingsRes.error && !isMissingTableOrSchemaError(findingsRes.error)) {
      state.domainData.findings = isApprovedStaff() ? [...INITIAL_FINDINGS] : [];
      state.domainData.phase5Findings = isApprovedStaff()
        ? INITIAL_PHASE5_FINDINGS.map((f) => ({ ...f }))
        : [];
    } else if (!findingsRes.error && Array.isArray(findingsRes.data) && findingsRes.data.length === 0) {
      state.domainData.findings = isApprovedStaff() ? [...INITIAL_FINDINGS] : [];
      state.domainData.phase5Findings = isApprovedStaff()
        ? INITIAL_PHASE5_FINDINGS.map((f) => ({ ...f }))
        : [];
    } else {
      state.domainData.findings = isApprovedStaff() ? [...INITIAL_FINDINGS] : [];
      state.domainData.phase5Findings = isApprovedStaff()
        ? INITIAL_PHASE5_FINDINGS.map((f) => ({ ...f }))
        : [];
    }
    // Process Organisms & Accreditations (Phase 4.1.3)
    if (!organismosRes.error && Array.isArray(organismosRes.data) && organismosRes.data.length > 0) {
      state.domainData.allOrganismos = organismosRes.data.map((row: Record<string, unknown>) => ({
        id: String(row.id),
        codigo: String(row.codigo || ''),
        nombre: String(row.nombre || ''),
        pais: String(row.pais || ''),
        sitio_web: row.sitio_web ? String(row.sitio_web) : undefined,
      }));
    }

    if (
      !acreditacionesRes.error &&
      Array.isArray(acreditacionesRes.data) &&
      acreditacionesRes.data.length > 0
    ) {
      const lookupNormas: NormaEntity[] = state.domainData.standards.map((s, idx) => {
        const fallback = INITIAL_NORMAS[idx % INITIAL_NORMAS.length];
        return {
          id: s.id || fallback.id,
          codigo: s.codigo || s.norma || fallback.codigo,
          titulo: s.titulo || fallback.titulo,
          estatus: (s.estatus as NormaEntity['estatus']) || fallback.estatus || 'Vigente',
          esquema: s.esquema || fallback.esquema,
          fecha_publicacion: s.fecha_publicacion || fallback.fecha_publicacion,
          norma: s.norma || fallback.norma,
          clausulas_count: s.clausulas_count || fallback.clausulas_count || 7,
          acreditaciones_count: s.acreditaciones_count || fallback.acreditaciones_count || 1,
        };
      });

      const lookupSectores: SectorIafEntity[] = state.domainData.iafSectors.map((sec, idx) => {
        const fallback = INITIAL_SECTORES_IAF[idx % INITIAL_SECTORES_IAF.length];
        return {
          id: sec.id || fallback.id,
          sector: sec.sector || fallback.sector,
          descripcion: sec.descripcion || fallback.descripcion,
          subsectores_count: sec.subsectores_count ?? fallback.subsectores_count,
          auditores_count: sec.auditores_count ?? fallback.auditores_count,
        };
      });

      const mappedAccreditations = mapSupabaseAcreditacionRows(
        acreditacionesRes.data as SupabaseAcreditacionJoinRow[],
        {
          organismos: state.domainData.allOrganismos,
          normas: lookupNormas.length > 0 ? lookupNormas : INITIAL_NORMAS,
          sectores: lookupSectores.length > 0 ? lookupSectores : INITIAL_SECTORES_IAF,
          estatusList: getResolvedEstatusCatalog(),
        }
      );

      if (mappedAccreditations.length > 0) {
        state.domainData.allAcreditaciones = mappedAccreditations;
      }
    }
  } catch (err) {
    console.warn('Fallback to seeded domain records:', err);
  } finally {
    state.domainData.loading = false;
    render();
  }
}

function buildSeededProgramsFallback(): ProgramaAuditoriaEntity[] {
  const byProgram = new Map<string, ProgramacionAuditEntity[]>();
  for (const audit of [...INITIAL_PROGRAMACION_AUDITS, ...INITIAL_HISTORICAL_CLOSED_AUDITS]) {
    const progId = audit.id_programa_auditoria || `prog-${audit.id}`;
    const matchedTipo = INITIAL_TIPOS_AUDITORIA_CATALOG.find(
      (t) => t.tipo.toLowerCase() === audit.tipo_auditoria.trim().toLowerCase()
    );
    const existingFechas = audit.fechas ? audit.fechas.map((f) => ({ ...f })) : [];
    const fallbackFechas: AuditDateEntry[] =
      existingFechas.length > 0
        ? existingFechas
        : audit.fecha_inicio
        ? [
            {
              id: `fecha-seed-${audit.id}`,
              id_auditoria: audit.id,
              numero_secuencia: 1,
              tag: 'Programación',
              tipo_fecha: 'PROGRAMADA_EXACTA',
              anio: null,
              mes: null,
              fecha_inicio: audit.fecha_inicio,
              fecha_fin: audit.fecha_fin || audit.fecha_inicio,
              observacion: 'Programación inicial.',
              deleted_at: null,
            },
          ]
        : [];
    const list = byProgram.get(progId) || [];
    const synthesizedSitiosPlan: AuditoriaSitioPlanItem[] =
      audit.sitiosPlan && audit.sitiosPlan.length > 0
        ? audit.sitiosPlan
        : (audit.sitiosMuestreo || [])
            .filter((sm) => sm.muestreado !== false)
            .map((sm, smIdx) => {
              const auditTail = audit.id.slice(-4).replace(/[^0-9a-f]/gi, '0').padStart(4, '0');
              const siteTail = String(smIdx + 1).padStart(8, '0');
              return {
                id: `82000000-0000-4000-8000-${auditTail}${siteTail}`,
                id_auditoria: audit.id,
                id_sitio: sm.id_sitio,
                numero_sitio: sm.numero_sitio,
                nombre_sitio: sm.nombre_sitio,
                direccion_sitio: sm.direccion_sitio || undefined,
                modalidad_evaluacion: sm.modalidad_evaluacion === 'Remota' ? 'Remota' : 'Presencial',
                tiempo_auditoria: Number(sm.dias_asignados ?? 1),
                fecha_inicio: sm.fecha_asignada || audit.fecha_inicio || null,
                fecha_fin: sm.fecha_asignada || audit.fecha_fin || null,
                notas_sitio: sm.notas || null,
                procesos: [],
                equipoSitio: [],
                deleted_at: null,
              };
            });
    const versionMeta = resolveAuditCertificateVersionMeta({
      id_certificado: audit.id_certificado,
      rawIdCertificadoVersion: audit.id_certificado_version,
      rawVersionNumero: audit.version_numero,
      certificados:
        state.domainData.allCertificadosDetailed.length > 0
          ? state.domainData.allCertificadosDetailed
          : INITIAL_ENRICHED_SEED_CERTS.certificados,
    });
    list.push({
      ...audit,
      id_certificado_version: versionMeta.id_certificado_version,
      version_numero: versionMeta.version_numero,
      organizacion_abreviacion:
        audit.organizacion_abreviacion ??
        (
          (state.domainData.allCertificadosDetailed.length > 0
            ? state.domainData.allCertificadosDetailed
            : INITIAL_ENRICHED_SEED_CERTS.certificados
          ).find((c) => c.id === audit.id_certificado)?.organizacion_abreviacion ?? null
        ),
      id_tipo_auditoria: audit.id_tipo_auditoria ?? matchedTipo?.id ?? null,
      tipo_auditoria_abreviacion:
        audit.tipo_auditoria_abreviacion ?? matchedTipo?.abreviacion ?? null,
      fechas: fallbackFechas,
      latestDate: audit.latestDate ?? fallbackFechas[0] ?? null,
      sitiosPlan: synthesizedSitiosPlan,
      equipo: audit.equipo.map((m) => ({ ...m })),
      sitiosMuestreo: audit.sitiosMuestreo.map((s) => ({ ...s })),
      matrizNormativa: audit.matrizNormativa.map((n) => ({ ...n })),
      recomendacion: audit.recomendacion ? { ...audit.recomendacion } : null,
    });
    byProgram.set(progId, list);
  }
  const programs: ProgramaAuditoriaEntity[] = [];
  for (const [progId, audits] of byProgram.entries()) {
    const first = audits[0];
    const isLinked = audits.length > 1;
    const distinctOrgs = new Set(audits.map((a) => a.organizacion_nombre));
    const certIds = new Set(audits.map((a) => a.id_certificado));
    const matchedVinculo = INITIAL_VINCULOS.find(
      (v) => !v.deleted_at && v.certificados.some((vc) => !vc.deleted_at && certIds.has(vc.id_certificado))
    );
    const nivel: AuditLinkLevel = matchedVinculo
      ? matchedVinculo.nivel_vinculacion
      : !isLinked
      ? 'INDIVIDUAL'
      : distinctOrgs.size > 1
      ? 'NIVEL_2_INTER_ORG'
      : 'NIVEL_1_INTRA_ORG';
    const tipo: AuditLinkNature = matchedVinculo
      ? matchedVinculo.tipo_vinculacion
      : !isLinked
      ? 'Individual'
      : 'Combinada';
    const programAuditsWithTemporalFlag = audits.map((a) => ({
      ...a,
      tipo_vinculacion: a.tipo_vinculacion ?? tipo,
      tiene_sitio_temporal:
        a.tiene_sitio_temporal ?? matchedVinculo?.tiene_sitio_temporal ?? false,
    }));
    const program: ProgramaAuditoriaEntity = {
      id: progId,
      id_vinculo: matchedVinculo?.id ?? null,
      id_grupo_empresarial: matchedVinculo?.id_grupo_empresarial ?? null,
      codigo_programa: first?.codigo_auditoria || null,
      etiqueta: first
        ? `${first.organizacion_nombre} · ${first.numero_certificado}`
        : 'Programa de Auditoría',
      nivel_vinculacion: nivel,
      tipo_vinculacion: tipo,
      es_vinculada: matchedVinculo ? matchedVinculo.es_vinculada : isLinked,
      tiene_sitio_temporal: matchedVinculo?.tiene_sitio_temporal ?? false,
      id_ciclo_origen: null,
      notas: null,
      deleted_at: null,
      auditorias: programAuditsWithTemporalFlag,
    };
    computeProgramPlanningStatus(program);
    programs.push(program);
  }
  return programs;
}

async function loadLiveAudits(): Promise<void> {
  if (state.domainData.auditsLoading) return;
  state.domainData.auditsLoading = true;

  const parseNivelVinculacion = (raw: unknown): AuditLinkLevel => {
    const val = String(raw || 'INDIVIDUAL');
    if (val === 'NIVEL_1_INTRA_ORG' || val === 'NIVEL_2_INTER_ORG') return val;
    return 'INDIVIDUAL';
  };

  const parseTipoVinculacion = (raw: unknown): AuditLinkNature => {
    const val = String(raw || 'Individual');
    if (val === 'Multisitio' || val === 'Mixta') return 'Mixta';
    if (
      val === 'Individual' ||
      val === 'Combinada' ||
      val === 'Integrada' ||
      val === 'Conjunta' ||
      val === 'Simultánea' ||
      val === 'Multientidad'
    ) {
      return val;
    }
    return 'Individual';
  };

  const parseOptionalTipoVinculacion = (raw: unknown): AuditLinkNature | null => {
    if (raw === null || raw === undefined) return null;
    const val = String(raw).trim();
    if (!val) return null;
    if (val === 'Multisitio' || val === 'Mixta') return 'Mixta';
    if (
      val === 'Individual' ||
      val === 'Combinada' ||
      val === 'Integrada' ||
      val === 'Conjunta' ||
      val === 'Simultánea' ||
      val === 'Multientidad'
    ) {
      return val;
    }
    return null;
  };

  const parseCycleStatus = (raw: unknown): AuditCycleStatus => {
    const val = String(raw || 'Borrador');
    if (
      val === 'Borrador' ||
      val === 'En Programación' ||
      val === 'Programada' ||
      val === 'En Ejecución' ||
      val === 'Auditada' ||
      val === 'Cerrada' ||
      val === 'Reprogramada' ||
      val === 'Cancelada'
    ) {
      return val;
    }
    return 'Borrador';
  };

  const parseDateTag = (raw: unknown): AuditDateTag =>
    String(raw || '') === 'Reprogramación' ? 'Reprogramación' : 'Programación';

  const parseDatePrecision = (raw: unknown): AuditDatePrecision => {
    const val = String(raw || '');
    if (val === 'REAL') return 'REAL';
    if (val === 'PROGRAMADA_EXACTA') return 'PROGRAMADA_EXACTA';
    return 'PREPROGRAMADA_MES';
  };

  const parseSiteModalidad = (raw: unknown): SiteEvaluationModality | null => {
    const val = String(raw || '');
    if (val === 'Presencial' || val === 'Remota' || val === 'Mixta') return val;
    return null;
  };

  const parseAuditMethodology = (raw: unknown): AuditMethodology => {
    const val = String(raw || 'Presencial').trim().toLowerCase();
    if (val.includes('remot')) return 'Remota';
    if (val.includes('mixt') || val.includes('híbr') || val.includes('hibr')) return 'Mixta';
    return 'Presencial';
  };

  const parseAuditorSiteRole = (raw: unknown): AuditorSiteRole => {
    const val = String(raw || 'AUDITOR');
    if (
      val === 'AUDITOR_LIDER' ||
      val === 'AUDITOR' ||
      val === 'AUDITOR_EN_ENTRENAMIENTO' ||
      val === 'EXPERTO_TECNICO'
    ) {
      return val;
    }
    return 'AUDITOR';
  };

  const toAuditTeamRole = (role: AuditorSiteRole): AuditTeamRole => {
    if (role === 'AUDITOR_LIDER') return 'Auditor Líder';
    if (role === 'EXPERTO_TECNICO') return 'Experto Técnico';
    return 'Auditor de Equipo';
  };

  const parseProcessRole = (raw: unknown): AuditorProcessRole => {
    const val = String(raw || 'EVALUADOR');
    if (
      val === 'LIDER_PROCESO' ||
      val === 'EVALUADOR' ||
      val === 'APOYO_TECNICO' ||
      val === 'OBSERVADOR'
    ) {
      return val;
    }
    return 'EVALUADOR';
  };

  const toLegacyEstatus = (cycle: AuditCycleStatus): string => {
    switch (cycle) {
      case 'En Ejecución':
        return 'En Ejecución';
      case 'Auditada':
        return 'Completado';
      case 'Cerrada':
        return 'Cerrado';
      case 'Reprogramada':
        return 'Reprogramada';
      case 'Cancelada':
        return 'Cancelada';
      default:
        return 'Planificado';
    }
  };

  try {
    const [
      programasRes,
      auditoriasRes,
      fechasRes,
      alertConfigRes,
      sitiosAuditRes,
      turnosSitioAuditRes,
      procesosSitioAuditRes,
      turnosProcesoAuditRes,
      equipoSitioRes,
      equipoProcesoRes,
      equipoAuditRes,
      comentariosRes,
      temporalSitesRes,
      temporalCertLinksRes,
      temporalTeamRes,
      sharedSitiosRes,
    ] = await Promise.all([
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('programa_auditoria')
          .select(
            'id, id_vinculo, id_grupo_empresarial, codigo_programa, etiqueta, nivel_vinculacion, tipo_vinculacion, es_vinculada, tiene_sitio_temporal, id_ciclo_origen, notas, created_at, updated_at, deleted_at'
          )
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('auditoria')
          .select(`
            id,
            id_programa_auditoria,
            codigo_auditoria,
            id_certificado,
            id_certificado_version,
            id_tipo_auditoria,
            id_metodologia,
            tipo_vinculacion,
            tiempo_auditoria,
            estado_ciclo,
            fecha_cierre_auditoria,
            revisado,
            fecha_revision,
            revisado_por,
            documentacion_completa,
            resumen_revision,
            tiene_sitio_temporal,
            objetivo,
            created_at,
            updated_at,
            deleted_at,
            tipo_auditoria:id_tipo_auditoria ( id, tipo, abreviacion ),
            metodologia:id_metodologia ( id, metodologia ),
            certificado_version:id_certificado_version ( id, version_numero ),
            certificado:id_certificado (
              id,
              numero_certificado,
              id_organizacion,
              id_norma,
              id_sector_iaf,
              organizacion:id_organizacion ( id, nombre, abreviacion, direccion_fiscal ),
              norma:id_norma ( id, codigo, norma, esquema ),
              sector_iaf:id_sector_iaf ( id, sector )
            )
          `)
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .range(from, to);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          const fallbackRes = await supabase
            .from('auditoria')
            .select(`
              id,
              id_programa_auditoria,
              codigo_auditoria,
              id_certificado,
              id_tipo_auditoria,
              id_metodologia,
              tiempo_auditoria,
              estado_ciclo,
              tiene_sitio_temporal,
              objetivo,
              created_at,
              updated_at,
              deleted_at,
              tipo_auditoria:id_tipo_auditoria ( id, tipo ),
              metodologia:id_metodologia ( id, metodologia ),
              certificado:id_certificado (
                id,
                numero_certificado,
                id_organizacion,
                id_norma,
                id_sector_iaf,
                organizacion:id_organizacion ( id, nombre, direccion_fiscal ),
                norma:id_norma ( id, codigo, norma, esquema ),
                sector_iaf:id_sector_iaf ( id, sector )
              )
            `)
            .is('deleted_at', null)
            .order('created_at', { ascending: false })
            .range(from, to);
          return {
            data: (fallbackRes.data as Array<Record<string, unknown>> | null) ?? null,
            error: fallbackRes.error,
          };
        }
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('auditoria_fecha')
          .select(
            'id, id_auditoria, numero_secuencia, tag, tipo_fecha, anio, mes, fecha_inicio, fecha_fin, observacion, created_at, updated_at, deleted_at'
          )
          .is('deleted_at', null)
          .order('numero_secuencia', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      (async () => {
        const res = await supabase
          .from('configuracion_alerta_auditoria')
          .select(
            'id, clave, dias_aviso_proxima, dias_aviso_preprogramada_sin_confirmar, alertar_atrasadas, alertar_conflicto_auditor, alertar_desfase_dias_o_span, ciclos_rotacion_auditor_lider, alertas_activas, dias_limite_plan_nc, dias_limite_plan_accion, dias_limite_cierre_nc, updated_by, updated_at'
          )
          .is('deleted_at', null)
          .limit(1);
        if (res.error && isMissingTableOrSchemaError(res.error)) {
          const fallbackRes = await supabase
            .from('configuracion_alerta_auditoria')
            .select(
              'id, clave, dias_aviso_proxima, dias_aviso_preprogramada_sin_confirmar, alertar_atrasadas, alertar_conflicto_auditor, alertar_desfase_dias_o_span, ciclos_rotacion_auditor_lider, alertas_activas, dias_limite_plan_accion, dias_limite_cierre_nc, updated_by, updated_at'
            )
            .is('deleted_at', null)
            .limit(1);
          if (fallbackRes.error && isMissingTableOrSchemaError(fallbackRes.error)) {
            return supabase
              .from('configuracion_alerta_auditoria')
              .select(
                'id, clave, dias_aviso_proxima, dias_aviso_preprogramada_sin_confirmar, alertar_atrasadas, alertar_conflicto_auditor, alertar_desfase_dias_o_span, ciclos_rotacion_auditor_lider, alertas_activas, updated_by, updated_at'
              )
              .is('deleted_at', null)
              .limit(1);
          }
          return fallbackRes;
        }
        return res;
      })(),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('sitios_por_auditoria')
          .select(`
            id,
            id_auditoria,
            id_sitio,
            tiempo_auditoria,
            modalidad_evaluacion,
            fecha_inicio,
            fecha_fin,
            notas_sitio,
            created_at,
            deleted_at,
            sitio:id_sitio ( id, numero_sitio, nombre_sitio, direccion_sitio )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('turnos_sitio_auditoria')
          .select(`
            id,
            id_sitios_por_auditoria,
            id_turnos_por_sitio,
            created_at,
            deleted_at,
            turnos_por_sitio:id_turnos_por_sitio (
              id,
              id_turno,
              turno:id_turno ( id, hora_entrada, hora_salida )
            )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('procesos_sitio_auditoria')
          .select(`
            id,
            id_sitios_por_auditoria,
            id_procesos_por_sitio,
            id_proceso,
            notas,
            created_at,
            updated_at,
            deleted_at,
            proceso:id_proceso ( id, nombre_proceso, tipo )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('turnos_proceso_sitio_auditoria')
          .select('id, id_procesos_sitio_auditoria, id_turnos_sitio_auditoria, created_at, deleted_at')
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('equipo_auditor_sitio')
          .select(`
            id,
            id_sitios_por_auditoria,
            id_auditor,
            rol_auditor,
            tiempo_auditoria,
            asignacion_completa_sitio,
            created_at,
            updated_at,
            deleted_at,
            auditor:id_auditor ( id, nombre )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('equipo_auditor_proceso_sitio')
          .select(`
            id,
            id_procesos_sitio_auditoria,
            id_auditor,
            rol_en_proceso,
            created_at,
            deleted_at,
            auditor:id_auditor ( id, nombre )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('equipo_auditor')
          .select(`
            id_auditoria,
            id_auditor,
            rol_auditor,
            auditor:id_auditor ( id, nombre )
          `)
          .order('id_auditoria', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('comentarios_por_auditoria')
          .select('id, id_auditoria, comentario, timestamp, deleted_at')
          .is('deleted_at', null)
          .order('timestamp', { ascending: false })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('auditoria_sitio_temporal')
          .select('id, id_auditoria, etiqueta, comentario, tiempo_auditoria, created_at, updated_at, deleted_at')
          .is('deleted_at', null)
          .order('created_at', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('auditoria_sitio_temporal_certificado')
          .select('id, id_sitio_temporal, id_auditoria_certificado, created_at, deleted_at')
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('equipo_auditor_sitio_temporal')
          .select(`
            id,
            id_sitio_temporal,
            id_auditor,
            rol_auditor,
            tiempo_auditoria,
            deleted_at,
            auditor:id_auditor ( id, nombre )
          `)
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
      fetchAllPagedRows<Record<string, unknown>>(async (from, to) => {
        const res = await supabase
          .from('sitio_certificado_compartido')
          .select('id_sitio, id_certificado, numero_sitio')
          .is('deleted_at', null)
          .order('id_sitio', { ascending: true })
          .range(from, to);
        return { data: (res.data as Array<Record<string, unknown>> | null) ?? null, error: res.error };
      }, 1000),
    ]);

    // Resolve Alert Config with fallback to DEFAULT_AUDIT_ALERT_CONFIG
    let resolvedAlertConfig: AlertConfigEntity = { ...DEFAULT_AUDIT_ALERT_CONFIG };
    if (!alertConfigRes.error && Array.isArray(alertConfigRes.data) && alertConfigRes.data.length > 0) {
      const cfg = alertConfigRes.data[0] as Record<string, unknown>;
      resolvedAlertConfig = {
        id: cfg.id ? String(cfg.id) : DEFAULT_AUDIT_ALERT_CONFIG.id,
        clave: String(cfg.clave || 'DEFAULT'),
        dias_aviso_proxima: Math.max(
          1,
          Number(cfg.dias_aviso_proxima ?? DEFAULT_AUDIT_ALERT_CONFIG.dias_aviso_proxima)
        ),
        dias_aviso_preprogramada_sin_confirmar: Math.max(
          1,
          Number(
            cfg.dias_aviso_preprogramada_sin_confirmar ??
              DEFAULT_AUDIT_ALERT_CONFIG.dias_aviso_preprogramada_sin_confirmar
          )
        ),
        alertar_atrasadas: Boolean(
          cfg.alertar_atrasadas ?? DEFAULT_AUDIT_ALERT_CONFIG.alertar_atrasadas
        ),
        alertar_conflicto_auditor: Boolean(
          cfg.alertar_conflicto_auditor ?? DEFAULT_AUDIT_ALERT_CONFIG.alertar_conflicto_auditor
        ),
        alertar_desfase_dias_o_span: Boolean(
          cfg.alertar_desfase_dias_o_span ??
            DEFAULT_AUDIT_ALERT_CONFIG.alertar_desfase_dias_o_span
        ),
        ciclos_rotacion_auditor_lider: Math.max(
          2,
          Number(
            cfg.ciclos_rotacion_auditor_lider ??
              DEFAULT_AUDIT_ALERT_CONFIG.ciclos_rotacion_auditor_lider
          )
        ),
        alertas_activas: Boolean(
          cfg.alertas_activas ?? DEFAULT_AUDIT_ALERT_CONFIG.alertas_activas
        ),
        dias_limite_plan_nc: Math.max(
          1,
          Number(
            cfg.dias_limite_plan_nc ??
              cfg.dias_limite_plan_accion ??
              DEFAULT_AUDIT_ALERT_CONFIG.dias_limite_plan_nc ??
              DEFAULT_AUDIT_ALERT_CONFIG.dias_limite_plan_accion
          )
        ),
        dias_limite_plan_accion: Math.max(
          1,
          Number(
            cfg.dias_limite_plan_nc ??
              cfg.dias_limite_plan_accion ??
              DEFAULT_AUDIT_ALERT_CONFIG.dias_limite_plan_accion
          )
        ),
        dias_limite_cierre_nc: Math.max(
          1,
          Number(cfg.dias_limite_cierre_nc ?? DEFAULT_AUDIT_ALERT_CONFIG.dias_limite_cierre_nc)
        ),
      };
    }
    state.domainData.auditAlertConfig = resolvedAlertConfig;

    // If live queries failed (e.g. unmigrated/offline), fall back ONLY for approved staff
    if (auditoriasRes.error || programasRes.error) {
      if (isApprovedStaff()) {
        const seededPrograms = buildSeededProgramsFallback();
        state.domainData.auditPrograms = seededPrograms;
        state.domainData.programacionAudits = seededPrograms.flatMap((p) => p.auditorias);
        state.domainData.unprogrammedCertificates = findUnprogrammedCertificatesByStatus(
          state.domainData.allCertificadosDetailed,
          seededPrograms
        );
        state.domainData.auditAlerts = computeAuditAlerts(seededPrograms, resolvedAlertConfig);
      } else {
        state.domainData.auditPrograms = [];
        state.domainData.programacionAudits = [];
        state.domainData.audits = [];
        state.domainData.unprogrammedCertificates = {
          items: [],
          countsByEstatus: {},
          totalUnprogrammed: 0,
        };
        state.domainData.auditAlerts = [];
      }
      return;
    }

    // Index child collections bottom-up
    const shiftMetaByTurnosSitioAuditId = new Map<
      string,
      { id_turnos_por_sitio: string; descripcion: string; hora_entrada?: string; hora_salida?: string }
    >();
    if (!turnosSitioAuditRes.error) {
      for (const row of turnosSitioAuditRes.data) {
        const id = String(row.id || '');
        const tpsId = String(row.id_turnos_por_sitio || '');
        if (!id || !tpsId) continue;
        const tpsObj = (row.turnos_por_sitio as Record<string, unknown> | null) || null;
        const turnoObj = (tpsObj?.turno as Record<string, unknown> | null) || null;
        const horaEntrada = turnoObj?.hora_entrada ? String(turnoObj.hora_entrada) : undefined;
        const horaSalida = turnoObj?.hora_salida ? String(turnoObj.hora_salida) : undefined;
        const desc =
          horaEntrada && horaSalida
            ? `Turno ${formatTurnoTime(horaEntrada)} – ${formatTurnoTime(horaSalida)}`
            : 'Turno Operativo';
        shiftMetaByTurnosSitioAuditId.set(id, {
          id_turnos_por_sitio: tpsId,
          descripcion: desc,
          hora_entrada: horaEntrada,
          hora_salida: horaSalida,
        });
      }
    }

    const turnosProcesoByProcAuditId = new Map<string, AuditoriaTurnoProcesoLink[]>();
    if (!turnosProcesoAuditRes.error) {
      for (const row of turnosProcesoAuditRes.data) {
        const id = String(row.id || '');
        const procAuditId = String(row.id_procesos_sitio_auditoria || '');
        const turnoSitioAuditId = String(row.id_turnos_sitio_auditoria || '');
        if (!id || !procAuditId || !turnoSitioAuditId) continue;
        const shiftMeta = shiftMetaByTurnosSitioAuditId.get(turnoSitioAuditId);
        const list = turnosProcesoByProcAuditId.get(procAuditId) || [];
        list.push({
          id,
          id_procesos_sitio_auditoria: procAuditId,
          id_turnos_sitio_auditoria: turnoSitioAuditId,
          id_turnos_por_sitio: shiftMeta?.id_turnos_por_sitio,
          descripcion_turno: shiftMeta?.descripcion || 'Turno Operativo',
          hora_entrada: shiftMeta?.hora_entrada,
          hora_salida: shiftMeta?.hora_salida,
          deleted_at: null,
        });
        turnosProcesoByProcAuditId.set(procAuditId, list);
      }
    }

    const auditoresProcesoByProcAuditId = new Map<string, AuditoriaEquipoProcesoLink[]>();
    if (!equipoProcesoRes.error) {
      for (const row of equipoProcesoRes.data) {
        const id = String(row.id || '');
        const procAuditId = String(row.id_procesos_sitio_auditoria || '');
        const auditorId = String(row.id_auditor || '');
        if (!id || !procAuditId || !auditorId) continue;
        const audObj = (row.auditor as Record<string, unknown> | null) || null;
        const list = auditoresProcesoByProcAuditId.get(procAuditId) || [];
        list.push({
          id,
          id_procesos_sitio_auditoria: procAuditId,
          id_auditor: auditorId,
          auditor_nombre: audObj?.nombre ? String(audObj.nombre) : 'Auditor Calificado',
          rol_en_proceso: parseProcessRole(row.rol_en_proceso),
          deleted_at: null,
        });
        auditoresProcesoByProcAuditId.set(procAuditId, list);
      }
    }

    const procesosBySiteAuditId = new Map<string, AuditoriaProcesoSitioItem[]>();
    if (!procesosSitioAuditRes.error) {
      for (const row of procesosSitioAuditRes.data) {
        const id = String(row.id || '');
        const siteAuditId = String(row.id_sitios_por_auditoria || '');
        const procSitioId = String(row.id_procesos_por_sitio || '');
        const procId = String(row.id_proceso || '');
        if (!id || !siteAuditId || !procId) continue;
        const procObj = (row.proceso as Record<string, unknown> | null) || null;
        const list = procesosBySiteAuditId.get(siteAuditId) || [];
        list.push({
          id,
          id_sitios_por_auditoria: siteAuditId,
          id_procesos_por_sitio: procSitioId,
          id_proceso: procId,
          proceso_nombre: procObj?.nombre_proceso ? String(procObj.nombre_proceso) : 'Proceso Operativo',
          notas: row.notas ? String(row.notas) : null,
          turnos: turnosProcesoByProcAuditId.get(id) || [],
          equipoProceso: auditoresProcesoByProcAuditId.get(id) || [],
          deleted_at: null,
        });
        procesosBySiteAuditId.set(siteAuditId, list);
      }
    }

    const auditoresSitioBySiteAuditId = new Map<string, AuditoriaEquipoSitioItem[]>();
    if (!equipoSitioRes.error) {
      for (const row of equipoSitioRes.data) {
        const id = String(row.id || '');
        const siteAuditId = String(row.id_sitios_por_auditoria || '');
        const auditorId = String(row.id_auditor || '');
        if (!id || !siteAuditId || !auditorId) continue;
        const audObj = (row.auditor as Record<string, unknown> | null) || null;
        const list = auditoresSitioBySiteAuditId.get(siteAuditId) || [];
        list.push({
          id,
          id_sitios_por_auditoria: siteAuditId,
          id_auditor: auditorId,
          auditor_nombre: audObj?.nombre ? String(audObj.nombre) : 'Auditor Calificado',
          rol_auditor: parseAuditorSiteRole(row.rol_auditor),
          tiempo_auditoria: Number(row.tiempo_auditoria ?? 0),
          asignacion_completa_sitio: Boolean(row.asignacion_completa_sitio),
          deleted_at: null,
        });
        auditoresSitioBySiteAuditId.set(siteAuditId, list);
      }
    }

    const auditCertByAuditId = new Map<string, string>();
    for (const row of auditoriasRes.data) {
      const aid = String(row.id || '');
      const cid = String(row.id_certificado || '');
      if (aid && cid) {
        auditCertByAuditId.set(aid, cid);
      }
    }

    const sharedNumeroByCertSitio = new Map<string, number>();
    if (!sharedSitiosRes.error && Array.isArray(sharedSitiosRes.data)) {
      for (const row of sharedSitiosRes.data) {
        const sitioId = String(row.id_sitio || '');
        const certId = String(row.id_certificado || '');
        const num = Number(row.numero_sitio);
        if (sitioId && certId && Number.isFinite(num)) {
          sharedNumeroByCertSitio.set(`${certId}::${sitioId}`, num);
        }
      }
    }

    const sitiosPlanByAuditId = new Map<string, AuditoriaSitioPlanItem[]>();
    if (!sitiosAuditRes.error) {
      for (const row of sitiosAuditRes.data) {
        const id = String(row.id || '');
        const auditId = String(row.id_auditoria || '');
        const sitioId = String(row.id_sitio || '');
        if (!id || !auditId || !sitioId) continue;
        const sitioObj = (row.sitio as Record<string, unknown> | null) || null;
        const certIdForAudit = auditCertByAuditId.get(auditId) || '';
        const sharedNumeroOverride = certIdForAudit
          ? sharedNumeroByCertSitio.get(`${certIdForAudit}::${sitioId}`)
          : undefined;
        const effectiveNumeroSitio =
          sharedNumeroOverride !== undefined
            ? sharedNumeroOverride
            : Number(sitioObj?.numero_sitio ?? 0);
        const list = sitiosPlanByAuditId.get(auditId) || [];
        list.push({
          id,
          id_auditoria: auditId,
          id_sitio: sitioId,
          numero_sitio: effectiveNumeroSitio,
          nombre_sitio: sitioObj?.nombre_sitio ? String(sitioObj.nombre_sitio) : 'Sede Operativa',
          direccion_sitio: sitioObj?.direccion_sitio ? String(sitioObj.direccion_sitio) : '',
          tiempo_auditoria: Number(row.tiempo_auditoria ?? 0),
          modalidad_evaluacion: parseSiteModalidad(row.modalidad_evaluacion),
          fecha_inicio: row.fecha_inicio ? String(row.fecha_inicio).slice(0, 10) : null,
          fecha_fin: row.fecha_fin ? String(row.fecha_fin).slice(0, 10) : null,
          notas_sitio: row.notas_sitio ? String(row.notas_sitio) : null,
          procesos: procesosBySiteAuditId.get(id) || [],
          equipoSitio: auditoresSitioBySiteAuditId.get(id) || [],
          deleted_at: null,
        });
        sitiosPlanByAuditId.set(auditId, list);
      }
      for (const [aid, list] of sitiosPlanByAuditId.entries()) {
        list.sort((a, b) => a.numero_sitio - b.numero_sitio);
        sitiosPlanByAuditId.set(aid, list);
      }
    }

    const fechasByAuditId = new Map<string, AuditDateEntry[]>();
    if (!fechasRes.error) {
      for (const row of fechasRes.data) {
        const id = String(row.id || '');
        const auditId = String(row.id_auditoria || '');
        if (!id || !auditId) continue;
        const list = fechasByAuditId.get(auditId) || [];
        list.push({
          id,
          id_auditoria: auditId,
          numero_secuencia: Math.max(1, Number(row.numero_secuencia ?? 1)),
          tag: parseDateTag(row.tag),
          tipo_fecha: parseDatePrecision(row.tipo_fecha),
          anio: row.anio !== null && row.anio !== undefined ? Number(row.anio) : null,
          mes: row.mes !== null && row.mes !== undefined ? Number(row.mes) : null,
          fecha_inicio: row.fecha_inicio ? String(row.fecha_inicio).slice(0, 10) : null,
          fecha_fin: row.fecha_fin ? String(row.fecha_fin).slice(0, 10) : null,
          observacion: row.observacion ? String(row.observacion) : null,
          deleted_at: null,
        });
        fechasByAuditId.set(auditId, list);
      }
      for (const [aid, list] of fechasByAuditId.entries()) {
        list.sort((a, b) => a.numero_secuencia - b.numero_secuencia);
        fechasByAuditId.set(aid, list);
      }
    }

    const equipoByAuditId = new Map<string, AuditTeamMember[]>();
    if (!equipoAuditRes.error) {
      for (const row of equipoAuditRes.data) {
        const auditId = String(row.id_auditoria || '');
        const auditorId = String(row.id_auditor || '');
        if (!auditId || !auditorId) continue;
        const audObj = (row.auditor as Record<string, unknown> | null) || null;
        const siteRole = parseAuditorSiteRole(row.rol_auditor);
        const list = equipoByAuditId.get(auditId) || [];
        list.push({
          id: `${auditId}:${auditorId}`,
          id_auditor: auditorId,
          nombre: audObj?.nombre ? String(audObj.nombre) : 'Auditor Calificado',
          rol: toAuditTeamRole(siteRole),
          competencia_norma: 'ISO',
          competencia_sector_iaf: 17,
          credencial_codigo: 'REG-AUD',
          estado_credencial: 'Vigente',
        });
        equipoByAuditId.set(auditId, list);
      }
    }

    const comentariosByAuditId = new Map<string, AuditCommentEntry[]>();
    if (!comentariosRes.error) {
      for (const row of comentariosRes.data) {
        const id = String(row.id || '');
        const auditId = String(row.id_auditoria || '');
        if (!id || !auditId) continue;
        const list = comentariosByAuditId.get(auditId) || [];
        list.push({
          id,
          id_auditoria: auditId,
          comentario: String(row.comentario || ''),
          timestamp: String(row.timestamp || ''),
          deleted_at: null,
        });
        comentariosByAuditId.set(auditId, list);
      }
    }

    // Assemble ProgramacionAuditEntity[]
    const hydratedAudits: ProgramacionAuditEntity[] = [];
    const auditsByProgramId = new Map<string, ProgramacionAuditEntity[]>();

    for (const row of auditoriasRes.data) {
      const auditId = String(row.id || '');
      const progId = String(row.id_programa_auditoria || '');
      const certId = String(row.id_certificado || '');
      if (!auditId || !certId) continue;

      const certObj = (row.certificado as Record<string, unknown> | null) || null;
      const orgObj = (certObj?.organizacion as Record<string, unknown> | null) || null;
      const normaObj = (certObj?.norma as Record<string, unknown> | null) || null;
      const sectorObj = (certObj?.sector_iaf as Record<string, unknown> | null) || null;
      const tipoObj = (row.tipo_auditoria as Record<string, unknown> | null) || null;
      const metObj = (row.metodologia as Record<string, unknown> | null) || null;

      const fechas = fechasByAuditId.get(auditId) || [];
      const latestDate = resolveLatestAuditDate(fechas);
      const sitiosPlan = sitiosPlanByAuditId.get(auditId) || [];
      const equipo = equipoByAuditId.get(auditId) || [];
      const lead =
        equipo.find((m) => m.rol === 'Auditor Líder') || equipo[0] || null;
      const cycleStatus = parseCycleStatus(row.estado_ciclo);
      const tiempoAuditoria = Number(row.tiempo_auditoria ?? 0);

      let derivedFechaInicio = '';
      let derivedFechaFin = '';
      let derivedFechaReprog: string | null = null;
      if (latestDate) {
        if (latestDate.tipo_fecha === 'REAL' || latestDate.tipo_fecha === 'PROGRAMADA_EXACTA') {
          derivedFechaInicio = latestDate.fecha_inicio || '';
          derivedFechaFin = latestDate.fecha_fin || derivedFechaInicio;
          if (latestDate.tag === 'Reprogramación') {
            derivedFechaReprog = latestDate.fecha_inicio;
          }
        } else if (latestDate.anio && latestDate.mes) {
          derivedFechaInicio = `${latestDate.anio}-${String(latestDate.mes).padStart(2, '0')}-01`;
          derivedFechaFin = derivedFechaInicio;
        }
      }

      const certVerObj = (row.certificado_version as Record<string, unknown> | null) || null;
      const versionMeta = resolveAuditCertificateVersionMeta({
        id_certificado: certId,
        rawIdCertificadoVersion: row.id_certificado_version
          ? String(row.id_certificado_version)
          : certVerObj?.id
          ? String(certVerObj.id)
          : null,
        rawVersionNumero:
          certVerObj?.version_numero !== null && certVerObj?.version_numero !== undefined
            ? Number(certVerObj.version_numero)
            : null,
        certificados:
          state.domainData.allCertificadosDetailed.length > 0
            ? state.domainData.allCertificadosDetailed
            : INITIAL_ENRICHED_SEED_CERTS.certificados,
      });

      const entity: ProgramacionAuditEntity = {
        id: auditId,
        id_programa_auditoria: progId,
        codigo_auditoria: row.codigo_auditoria
          ? String(row.codigo_auditoria)
          : `AUD-${String(certObj?.numero_certificado || 'CERT')}`,
        id_certificado: certId,
        id_certificado_version: versionMeta.id_certificado_version,
        version_numero: versionMeta.version_numero,
        numero_certificado: certObj?.numero_certificado
          ? String(certObj.numero_certificado)
          : 'Certificado Activo',
        id_organizacion: orgObj?.id
          ? String(orgObj.id)
          : certObj?.id_organizacion
          ? String(certObj.id_organizacion)
          : '',
        organizacion_nombre: orgObj?.nombre
          ? String(orgObj.nombre)
          : 'Organización Registrada',
        organizacion_abreviacion: orgObj?.abreviacion
          ? String(orgObj.abreviacion)
          : null,
        norma_codigo: normaObj?.codigo
          ? String(normaObj.codigo)
          : normaObj?.norma
          ? String(normaObj.norma)
          : 'ISO',
        sector_iaf: Number(sectorObj?.sector ?? 17),
        id_tipo_auditoria: row.id_tipo_auditoria ? String(row.id_tipo_auditoria) : null,
        tipo_auditoria: tipoObj?.tipo ? String(tipoObj.tipo) : 'Por definir',
        tipo_auditoria_abreviacion: tipoObj?.abreviacion ? String(tipoObj.abreviacion) : null,
        tipo_vinculacion: parseOptionalTipoVinculacion(row.tipo_vinculacion),
        metodologia: parseAuditMethodology(metObj?.metodologia),
        fecha_inicio: derivedFechaInicio,
        fecha_fin: derivedFechaFin,
        fecha_reprogramacion: derivedFechaReprog,
        fechas,
        latestDate,
        dias_auditor: tiempoAuditoria,
        tiempo_auditoria: tiempoAuditoria,
        estatus: toLegacyEstatus(cycleStatus),
        estado_ciclo: cycleStatus,
        fecha_cierre_auditoria: row.fecha_cierre_auditoria
          ? String(row.fecha_cierre_auditoria).slice(0, 10)
          : null,
        revisado: Boolean(row.revisado),
        fecha_revision: row.fecha_revision
          ? String(row.fecha_revision).slice(0, 10)
          : null,
        revisado_por: row.revisado_por ? String(row.revisado_por) : null,
        documentacion_completa: Boolean(row.documentacion_completa),
        resumen_revision: row.resumen_revision ? String(row.resumen_revision) : null,
        tiene_sitio_temporal: Boolean(row.tiene_sitio_temporal),
        objetivo: row.objetivo ? String(row.objetivo) : null,
        auditor_lider_id: lead?.id_auditor || '',
        auditor_lider: lead?.nombre || 'Por asignar',
        sede_principal_direccion: orgObj?.direccion_fiscal
          ? String(orgObj.direccion_fiscal)
          : sitiosPlan[0]?.direccion_sitio || '',
        equipo,
        sitiosMuestreo: sitiosPlan.map((sp) => ({
          id: sp.id,
          id_sitio: sp.id_sitio,
          numero_sitio: sp.numero_sitio,
          nombre_sitio: sp.nombre_sitio,
          direccion_sitio: sp.direccion_sitio || '',
          modalidad_evaluacion: sp.modalidad_evaluacion === 'Remota' ? 'Remota' : 'Presencial',
          fecha_asignada: sp.fecha_inicio || derivedFechaInicio,
          dias_asignados: sp.tiempo_auditoria,
          muestreado: true,
          notas: sp.notas_sitio || undefined,
        })),
        sitiosPlan,
        matrizNormativa: [],
        comentarios: comentariosByAuditId.get(auditId) || [],
        recomendacion: null,
        deleted_at: null,
      };

      hydratedAudits.push(entity);
      if (progId) {
        const list = auditsByProgramId.get(progId) || [];
        list.push(entity);
        auditsByProgramId.set(progId, list);
      }
    }

    // Assemble ProgramaAuditoriaEntity[]
    const hydratedPrograms: ProgramaAuditoriaEntity[] = [];
    for (const row of programasRes.data) {
      const progId = String(row.id || '');
      if (!progId) continue;
      const program: ProgramaAuditoriaEntity = {
        id: progId,
        id_vinculo: row.id_vinculo ? String(row.id_vinculo) : null,
        id_grupo_empresarial: row.id_grupo_empresarial ? String(row.id_grupo_empresarial) : null,
        codigo_programa: row.codigo_programa ? String(row.codigo_programa) : null,
        etiqueta: String(row.etiqueta || 'Programa de Auditoría'),
        nivel_vinculacion: parseNivelVinculacion(row.nivel_vinculacion),
        tipo_vinculacion: parseTipoVinculacion(row.tipo_vinculacion),
        es_vinculada: Boolean(row.es_vinculada),
        tiene_sitio_temporal: Boolean(row.tiene_sitio_temporal),
        id_ciclo_origen: row.id_ciclo_origen ? String(row.id_ciclo_origen) : null,
        notas: row.notas ? String(row.notas) : null,
        deleted_at: null,
        auditorias: auditsByProgramId.get(progId) || [],
      };
      computeProgramPlanningStatus(program);
      hydratedPrograms.push(program);
    }

    // Assemble AuditoriaSitioTemporalEntity[] (Step 5.2)
    const auditLookupById = new Map(hydratedAudits.map((a) => [a.id, a]));
    const certLinksByTemporalId = new Map<string, TemporalSiteCertLink[]>();
    if (!temporalCertLinksRes.error) {
      for (const row of temporalCertLinksRes.data) {
        const id = String(row.id || '');
        const siteTempId = String(row.id_sitio_temporal || '');
        const certAuditId = String(row.id_auditoria_certificado || '');
        if (!id || !siteTempId || !certAuditId) continue;
        const targetAudit = auditLookupById.get(certAuditId);
        const list = certLinksByTemporalId.get(siteTempId) || [];
        list.push({
          id,
          id_sitio_temporal: siteTempId,
          id_auditoria_certificado: certAuditId,
          numero_certificado: targetAudit?.numero_certificado || 'Certificado',
          organizacion_nombre: targetAudit?.organizacion_nombre || 'Organización',
          norma_codigo: targetAudit?.norma_codigo || 'ISO',
          deleted_at: null,
        });
        certLinksByTemporalId.set(siteTempId, list);
      }
    }

    const teamByTemporalId = new Map<string, TemporalSiteTeamAssignment[]>();
    if (!temporalTeamRes.error) {
      for (const row of temporalTeamRes.data) {
        const id = String(row.id || '');
        const siteTempId = String(row.id_sitio_temporal || '');
        const auditorId = String(row.id_auditor || '');
        if (!id || !siteTempId || !auditorId) continue;
        const audObj = (row.auditor as Record<string, unknown> | null) || null;
        const list = teamByTemporalId.get(siteTempId) || [];
        list.push({
          id,
          id_sitio_temporal: siteTempId,
          id_auditor: auditorId,
          auditor_nombre: audObj?.nombre ? String(audObj.nombre) : 'Auditor Calificado',
          rol_auditor: parseAuditorSiteRole(row.rol_auditor),
          tiempo_auditoria: roundAuditDaysQuarter(Number(row.tiempo_auditoria ?? 0)),
          deleted_at: null,
        });
        teamByTemporalId.set(siteTempId, list);
      }
    }

    const hydratedTemporalSites: AuditoriaSitioTemporalEntity[] = [];
    if (!temporalSitesRes.error) {
      for (const row of temporalSitesRes.data) {
        const id = String(row.id || '');
        const auditId = String(row.id_auditoria || '');
        if (!id || !auditId) continue;
        hydratedTemporalSites.push({
          id,
          id_auditoria: auditId,
          etiqueta: normalizeTemporalSiteLabel(row.etiqueta ? String(row.etiqueta) : ''),
          comentario: row.comentario ? String(row.comentario) : null,
          tiempo_auditoria: roundAuditDaysQuarter(Number(row.tiempo_auditoria ?? 0)),
          certificados: certLinksByTemporalId.get(id) || [],
          equipoTemporal: teamByTemporalId.get(id) || [],
          deleted_at: null,
        });
      }
    }

    // RBAC isolation: CLIENT and AUDITOR never receive local seed fallback
    if (hydratedPrograms.length > 0 || hydratedAudits.length > 0 || !isApprovedStaff()) {
      state.domainData.auditPrograms = hydratedPrograms;
      if (!temporalSitesRes.error) {
        state.domainData.allTemporalSites = hydratedTemporalSites;
      }
      state.domainData.programacionAudits = hydratedAudits;
      state.domainData.audits = hydratedAudits.map((a) => ({
        id: a.id,
        id_certificado: a.id_certificado,
        numero_certificado: a.numero_certificado,
        organizacion_nombre: a.organizacion_nombre,
        tipo_auditoria: a.tipo_auditoria,
        metodologia: a.metodologia,
        fecha_programacion: a.fecha_inicio || formatAuditDateLabel(a.latestDate || null),
        fecha_reprogramacion: a.fecha_reprogramacion || null,
        auditor_lider: a.auditor_lider,
        estatus: a.estatus,
      }));
    } else {
      const seededPrograms = buildSeededProgramsFallback();
      state.domainData.auditPrograms = seededPrograms;
      state.domainData.programacionAudits = seededPrograms.flatMap((p) => p.auditorias);
    }

    state.domainData.unprogrammedCertificates = findUnprogrammedCertificatesByStatus(
      state.domainData.allCertificadosDetailed,
      state.domainData.auditPrograms
    );
    state.domainData.auditAlerts = computeAuditAlerts(
      state.domainData.auditPrograms,
      resolvedAlertConfig
    );
  } catch (err) {
    console.warn('Error hydrating live audits:', err);
    if (!isApprovedStaff()) {
      state.domainData.auditPrograms = [];
      state.domainData.allTemporalSites = [];
      state.domainData.programacionAudits = [];
      state.domainData.audits = [];
      state.domainData.unprogrammedCertificates = {
        items: [],
        countsByEstatus: {},
        totalUnprogrammed: 0,
      };
      state.domainData.auditAlerts = [];
    }
  } finally {
    state.domainData.auditsLoading = false;
    render();
  }
}

// ============================================================================
// Step 2.2.2 — Persistencia Transaccional Progresiva (`Sitio` + Bloque 1 `Auditoría`)
// ============================================================================

async function fetchArchiveDependencySummarySafe(
  tableName: ArchivableTable,
  recordId: string
): Promise<ReturnType<typeof computeLocalArchiveDependencySummary>> {
  const validRecordId = assertValidUuid(recordId, getArchiveTableDisplayLabel(tableName));
  const localSummary = computeLocalArchiveDependencySummary(tableName, validRecordId, {
    organizaciones: state.domainData.allOrganizaciones,
    certificates: state.domainData.allCertificadosDetailed,
    auditors: state.domainData.allAuditorsDetailed,
    programs: state.domainData.auditPrograms,
    audits: state.domainData.programacionAudits,
    findings: state.domainData.phase5Findings,
    normas: buildNormaEntitiesForDependencyCheck(),
    requisitos: state.domainData.requirementsCatalog,
    subsectores:
      state.domainData.iafSubsectors.length > 0
        ? state.domainData.iafSubsectors
        : INITIAL_SUBSECTORES_IAF,
    acreditaciones: state.domainData.allAcreditaciones,
    estatusList: getResolvedEstatusCatalog(),
    tiposList: getResolvedTiposCatalog(),
    metodologiasList: getResolvedMetodologiasCatalog(),
    archivedSiteIds: state.domainData.archivedSiteIds,
    archivedProcesoIds: state.domainData.archivedProcesoIds,
    archivedTurnoIds: state.domainData.archivedTurnoIds,
    archivedNoAplicableIds: state.domainData.archivedNoAplicableIds,
    archivedFechaIds: state.domainData.archivedFechaIds,
    archivedContactoIds: state.domainData.archivedContactoIds,
    archivedTelefonoIds: state.domainData.archivedTelefonoIds,
    archivedEmailIds: state.domainData.archivedEmailIds,
  });

  try {
    const { data, error } = await supabase.rpc('get_archive_dependency_summary', {
      p_table: tableName,
      p_record_id: validRecordId,
    });
    if (!error && data !== null && data !== undefined) {
      return mergeArchiveDependencySummaries(parseArchiveDependencySummary(data), localSummary);
    }
  } catch {
    // Fallback to local summary if RPC is unavailable
  }
  return localSummary;
}

function formatDependencyBlockedMessage(
  entityLabel: string,
  summary: ReturnType<typeof computeLocalArchiveDependencySummary>
): string {
  const breakdown = summary.dependencies
    .map((dep) => `${dep.count} ${stripRawUuidsFromText(dep.label)}`)
    .join(', ');
  const suffix = breakdown ? `: ${breakdown}` : '';
  return `No se puede archivar ${entityLabel} porque posee ${summary.total_active_dependencies} dependencia(s) activa(s)${suffix}.`;
}

function recomputeLocalAuditPlanningDerivedState(): void {
  state.domainData.unprogrammedCertificates = findUnprogrammedCertificatesByStatus(
    state.domainData.allCertificadosDetailed,
    state.domainData.auditPrograms
  );
  state.domainData.auditAlerts = computeAuditAlerts(
    state.domainData.auditPrograms,
    state.domainData.auditAlertConfig
  );
}

function resolveActiveCertIdFromContext(): string | null {
  if (state.certificadoDomain.selectedCertId) {
    return state.certificadoDomain.selectedCertId;
  }
  if (state.procesoDomain.selectedProcesoId && state.procesoDomain.prefillCertId) {
    return state.procesoDomain.prefillCertId;
  }
  if (state.sitioDomain.selectedSitioId && state.sitioDomain.prefillCertId) {
    return state.sitioDomain.prefillCertId;
  }
  for (let i = state.breadcrumbs.length - 1; i >= 0; i -= 1) {
    const crumb = state.breadcrumbs[i];
    if (crumb?.entityType === 'cert' && crumb.entityId) {
      return crumb.entityId;
    }
    if (
      (crumb?.entityType === 'proceso' ||
        crumb?.entityType === 'sitio' ||
        crumb?.entityType === 'turno') &&
      crumb.parentEntityId
    ) {
      return crumb.parentEntityId;
    }
  }
  return null;
}

/**
 * 1. Mutaciones `Sitio ↔ Proceso` (`procesos_por_sitio`)
 */
export async function upsertProcesoPorSitio(
  sitioId: string,
  procesoId: string,
  activeCertId?: string | null
): Promise<PersistenceMutationResult<{ id: string; restored: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validSitioId = assertValidUuid(sitioId, 'sitio');
    const validProcesoId = assertValidUuid(procesoId, 'proceso');
    const resolvedActiveCertId = activeCertId ?? resolveActiveCertIdFromContext();

    const currentSitio = resolveSitioDetailById({
      sitioId: validSitioId,
      activeCertId: resolvedActiveCertId,
      certificates: state.domainData.allCertificadosDetailed,
      programacionAudits: state.domainData.programacionAudits,
      shiftCatalog: state.domainData.shiftCatalog,
      archivedSiteIds: state.domainData.archivedSiteIds,
      archivedProcesoIds: state.domainData.archivedProcesoIds,
    });
    const targetCert = currentSitio
      ? state.domainData.allCertificadosDetailed.find((c) => c.id === currentSitio.id_certificado)
      : undefined;
    if (!currentSitio || !targetCert) {
      const msg = 'No se encontró la sede o su certificado asociado.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const validTargetCertId = assertValidUuid(targetCert.id, 'certificado de alcance');

    const validation = validateProcesoPorSitioAssignment(
      validSitioId,
      validProcesoId,
      targetCert,
      {
        archivedSiteIds: state.domainData.archivedSiteIds,
        archivedProcesoIds: state.domainData.archivedProcesoIds,
      }
    );
    if (!validation.valid || !validation.proceso) {
      const msg = stripRawUuidsFromText(
        validation.error || 'No se pudo vincular el proceso a este sitio.'
      );
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const linkedProceso = validation.proceso;
    let savedLinkId: string = crypto.randomUUID();
    let restored = false;
    let localFallback = false;

    const { data: existingRows, error: lookupError } = await supabase
      .from('procesos_por_sitio')
      .select('id, deleted_at')
      .eq('id_certificado', validTargetCertId)
      .eq('id_sitio', validSitioId)
      .eq('id_proceso', validProcesoId)
      .order('created_at', { ascending: false })
      .limit(1);

    if (lookupError) {
      if (!isMissingTableOrSchemaError(lookupError)) {
        const msg = formatZeroUuidError(lookupError, 'No se pudo consultar el vínculo proceso-sitio.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      localFallback = true;
    } else {
      const existingRow = Array.isArray(existingRows)
        ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
        : undefined;

      if (existingRow?.id) {
        if (existingRow.deleted_at) {
          const { data: restoredRow, error: restoreError } = await supabase
            .from('procesos_por_sitio')
            .update({ deleted_at: null, deleted_by: null })
            .eq('id', assertValidUuid(existingRow.id, 'vínculo proceso-sitio'))
            .select('id')
            .single();

          if (!restoreError && restoredRow?.id) {
            savedLinkId = String(restoredRow.id);
            restored = true;
          } else {
            const { data: insertedRow, error: insertError } = await supabase
              .from('procesos_por_sitio')
              .insert({
                id: savedLinkId,
                id_certificado: validTargetCertId,
                id_sitio: validSitioId,
                id_proceso: validProcesoId,
              })
              .select('id')
              .single();
            if (insertError) {
              if (!isMissingTableOrSchemaError(insertError)) {
                const msg = formatZeroUuidError(
                  insertError,
                  'No se pudo vincular el proceso a la sede.'
                );
                showFloatingToast(msg, 'warning');
                return { ok: false, error: msg };
              }
              localFallback = true;
            } else if (insertedRow?.id) {
              savedLinkId = String(insertedRow.id);
            }
          }
        } else {
          savedLinkId = String(existingRow.id);
        }
      } else {
        const { data: insertedRow, error: insertError } = await supabase
          .from('procesos_por_sitio')
          .insert({
            id: savedLinkId,
            id_certificado: validTargetCertId,
            id_sitio: validSitioId,
            id_proceso: validProcesoId,
          })
          .select('id')
          .single();

        if (insertError) {
          if (!isMissingTableOrSchemaError(insertError)) {
            const msg = formatZeroUuidError(
              insertError,
              'No se pudo vincular el proceso a la sede.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        } else if (insertedRow?.id) {
          savedLinkId = String(insertedRow.id);
        }
      }
    }

    const newLink: ProcesoPorSitioLink = {
      id: savedLinkId,
      id_certificado: validTargetCertId,
      id_sitio: validSitioId,
      id_proceso: linkedProceso.id,
      nombre_proceso: linkedProceso.nombre_proceso,
      tipo_proceso: linkedProceso.tipo,
      clausulas_cubiertas: linkedProceso.clausulas_cubiertas,
      requisitos_detalle: linkedProceso.requisitos_detalle,
      deleted_at: null,
    };

    state.domainData.allCertificadosDetailed = state.domainData.allCertificadosDetailed.map((c) => {
      if (c.id !== validTargetCertId) return c;
      return {
        ...c,
        sitios: c.sitios.map((s) => {
          if (s.id !== validSitioId) return s;
          const nextLinks = [
            ...(s.procesos_por_sitio || []).filter(
              (l) =>
                !l.deleted_at &&
                (!l.id_certificado || l.id_certificado === validTargetCertId) &&
                l.id_proceso !== linkedProceso.id
            ),
            newLink,
          ];
          const nextNames = Array.from(
            new Set([...(s.procesos_vinculados || []), linkedProceso.nombre_proceso])
          );
          return {
            ...s,
            procesos_por_sitio: nextLinks,
            procesos_vinculados: nextNames,
          };
        }),
      };
    });

    recordPhase5SessionLog(
      'procesos_por_sitio',
      savedLinkId,
      restored ? 'UPDATE' : 'INSERT',
      restored ? { deleted_at: 'archivado' } : null,
      {
        accion: restored ? 'RESTAURAR_PROCESO_SITIO' : 'VINCULAR_PROCESO_SITIO',
        sitio: currentSitio.nombre_sitio,
        proceso: linkedProceso.nombre_proceso,
      }
    );

    showFloatingToast(
      restored
        ? `Proceso "${linkedProceso.nombre_proceso}" restaurado en Sitio ${currentSitio.numero_sitio}.`
        : `Proceso "${linkedProceso.nombre_proceso}" vinculado al Sitio ${currentSitio.numero_sitio}.`,
      'success'
    );
    render();
    return { ok: true, data: { id: savedLinkId, restored }, restored, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo vincular el proceso al sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

export async function archiveProcesoPorSitio(
  sitioId: string,
  linkId: string,
  reason = 'Desvinculación desde detalle de Sitio'
): Promise<PersistenceMutationResult<{ id: string }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validSitioId = assertValidUuid(sitioId, 'sitio');
    const validLinkId = assertValidUuid(linkId, 'vínculo proceso-sitio');

    const currentSitio = resolveSitioDetailById({
      sitioId: validSitioId,
      activeCertId: resolveActiveCertIdFromContext(),
      certificates: state.domainData.allCertificadosDetailed,
      programacionAudits: state.domainData.programacionAudits,
      shiftCatalog: state.domainData.shiftCatalog,
      archivedSiteIds: state.domainData.archivedSiteIds,
      archivedProcesoIds: state.domainData.archivedProcesoIds,
    });
    if (!currentSitio) {
      const msg = 'No se encontró la sede solicitada.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const targetLink = currentSitio.procesos.find((p) => p.id === validLinkId);
    if (!targetLink) {
      const msg = 'No se encontró el vínculo activo del proceso en este sitio.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const summary = await fetchArchiveDependencySummarySafe('procesos_por_sitio', validLinkId);
    if (!summary.can_archive) {
      const msg = formatDependencyBlockedMessage(
        `el vínculo con "${targetLink.nombre_proceso}"`,
        summary
      );
      showFloatingToast(msg, 'warning', 6000);
      return { ok: false, error: msg, dependencySummary: summary };
    }

    let localFallback = false;
    const { error: archiveErr } = await supabase.rpc('archive_record', {
      p_table: 'procesos_por_sitio',
      p_record_id: validLinkId,
      p_reason: sanitizeArchiveReason(reason) || 'Desvinculación desde detalle de Sitio',
    });

    if (archiveErr) {
      if (!isMissingTableOrSchemaError(archiveErr)) {
        const msg = formatZeroUuidError(archiveErr, 'No se pudo desvincular el proceso del sitio.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      localFallback = true;
    }

    state.domainData.allCertificadosDetailed = state.domainData.allCertificadosDetailed.map((c) => {
      if (c.id !== currentSitio.id_certificado) return c;
      return {
        ...c,
        sitios: c.sitios.map((s) => {
          if (s.id !== validSitioId) return s;
          return {
            ...s,
            procesos_por_sitio: (s.procesos_por_sitio || []).filter(
              (l) => l.id !== validLinkId && l.id_proceso !== targetLink.id_proceso
            ),
            procesos_vinculados: (s.procesos_vinculados || []).filter(
              (lbl) =>
                lbl.trim().toLowerCase() !== targetLink.nombre_proceso.trim().toLowerCase() &&
                lbl !== targetLink.id_proceso
            ),
          };
        }),
      };
    });

    recordPhase5SessionLog(
      'procesos_por_sitio',
      validLinkId,
      'UPDATE',
      { proceso_vinculado: targetLink.nombre_proceso, deleted_at: null },
      { accion: 'ARCHIVAR_PROCESO_SITIO', proceso: targetLink.nombre_proceso }
    );

    showFloatingToast(
      `Vínculo con "${targetLink.nombre_proceso}" archivado en Sitio ${currentSitio.numero_sitio}.`,
      'success'
    );
    render();
    return { ok: true, data: { id: validLinkId }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo archivar el vínculo proceso-sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 2. Mutaciones Paso 1 (`saveProgramaAuditoriaStep1`)
 */
export async function saveProgramaAuditoriaStep1(
  input: SaveProgramaAuditoriaStep1Input,
  options?: { skipRender?: boolean }
): Promise<PersistenceMutationResult<{ programId: string; auditIds: string[] }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }

    const certCatalog =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;

    const validated = validateAndBuildStep1ProgramBundle(input, certCatalog);
    if (!validated.ok) {
      showFloatingToast(validated.error, 'warning');
      return { ok: false, error: validated.error };
    }

    const bundle = validated.value;
    const isEdit = Boolean(bundle.programId);
    let savedProgramId: string = bundle.programId || crypto.randomUUID();
    const savedAuditIds: string[] = [];
    const savedAuditCodesByCertId = new Map<string, string>();
    const reservedAuditCodes = new Set<string>();
    let effectiveCodigoPrograma: string | null = bundle.programaPayload.codigo_programa;
    let localFallback = false;

    const targetYear = resolveCampaignTargetYear({
      dateMode: bundle.initialDatePayload?.tipo_fecha ?? null,
      anio: bundle.initialDatePayload?.anio ?? null,
      fechaInicio: bundle.initialDatePayload?.fecha_inicio ?? null,
    });

    const fetchRemoteNextProgramCode = async (year: number): Promise<string | null> => {
      const { data, error } = await supabase.rpc('fn_next_programa_auditoria_codigo', {
        p_year: year,
      });
      if (error || typeof data !== 'string') return null;
      return data.trim() || null;
    };

    const fetchRemoteNextAuditCode = async (
      year: number,
      certShort: string
    ): Promise<string | null> => {
      const { data, error } = await supabase.rpc('fn_next_auditoria_codigo', {
        p_year: year,
        p_cert_short: certShort,
      });
      if (error || typeof data !== 'string') return null;
      return data.trim() || null;
    };

    const archiveRecordForRollback = async (
      table: 'programa_auditoria' | 'auditoria',
      recordId: string,
      reason: string
    ): Promise<void> => {
      await supabase.rpc('archive_record', {
        p_table: table,
        p_record_id: recordId,
        p_reason: reason,
      });
    };

    if (!isEdit) {
      const progOutcome = await insertWithUniqueCodeRetry<{ id: string }>({
        initialCode: bundle.programaPayload.codigo_programa,
        allocateCode: (_attempt, triedCodes) =>
          allocateProgramCodeWithFallback({
            targetYear,
            activePrograms: state.domainData.auditPrograms,
            triedCodes,
            fetchRemoteNextCode: fetchRemoteNextProgramCode,
          }),
        attemptInsert: async (candidateProgCode) => {
          const { data, error } = await supabase
            .from('programa_auditoria')
            .insert({
              id: savedProgramId,
              etiqueta: bundle.programaPayload.etiqueta,
              codigo_programa: candidateProgCode,
              nivel_vinculacion: bundle.programaPayload.nivel_vinculacion,
              tipo_vinculacion: bundle.programaPayload.tipo_vinculacion,
              es_vinculada: bundle.programaPayload.es_vinculada,
              id_ciclo_origen: bundle.programaPayload.id_ciclo_origen,
              notas: bundle.programaPayload.notas,
            })
            .select('id')
            .single();
          return {
            data: data?.id ? { id: String(data.id) } : undefined,
            error,
          };
        },
        isMissingSchemaError: isMissingTableOrSchemaError,
      });

      if (progOutcome.status === 'missing-schema') {
        localFallback = true;
        effectiveCodigoPrograma = progOutcome.code;
      } else if (progOutcome.status === 'error') {
        const msg = formatZeroUuidError(
          progOutcome.error,
          'No se pudo crear el programa de auditoría.'
        );
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      } else {
        effectiveCodigoPrograma = progOutcome.code;
        if (progOutcome.data?.id) {
          savedProgramId = progOutcome.data.id;
        }
      }

      const remotelyInsertedAuditIds: string[] = [];

      for (let i = 0; i < bundle.certificateRows.length; i += 1) {
        const certRow = bundle.certificateRows[i];
        let newAuditId: string = crypto.randomUUID();
        const certObj = certCatalog.find((c) => c.id === certRow.id_certificado);
        const activeCertVersionId =
          certObj?.versiones?.find((v) => !v.deleted_at && v.es_version_actual)?.id ??
          certObj?.id_certificado_version ??
          null;

        if (localFallback) {
          const fallbackCode =
            certRow.codigo_auditoria ||
            (await allocateAuditCodeWithFallback({
              targetYear,
              numeroCertificado: certObj?.numero_certificado,
              activeAudits: state.domainData.programacionAudits,
              reservedCodes: reservedAuditCodes,
            }));
          reservedAuditCodes.add(fallbackCode.toUpperCase());
          savedAuditCodesByCertId.set(certRow.id_certificado, fallbackCode);
        } else {
          const auditOutcome = await insertWithUniqueCodeRetry<{ id: string }>({
            initialCode: certRow.codigo_auditoria,
            allocateCode: (_attempt, triedCodes) =>
              allocateAuditCodeWithFallback({
                targetYear,
                numeroCertificado: certObj?.numero_certificado,
                activeAudits: state.domainData.programacionAudits,
                reservedCodes: reservedAuditCodes,
                triedCodes,
                fetchRemoteNextCode: fetchRemoteNextAuditCode,
              }),
            attemptInsert: async (candidateAuditCode) => {
              const { data, error } = await supabase
                .from('auditoria')
                .insert({
                  id: newAuditId,
                  id_programa_auditoria: assertValidUuid(savedProgramId, 'programa de auditoría'),
                  id_certificado: certRow.id_certificado,
                  ...(activeCertVersionId ? { id_certificado_version: activeCertVersionId } : {}),
                  id_tipo_auditoria: certRow.id_tipo_auditoria,
                  id_metodologia: certRow.id_metodologia,
                  codigo_auditoria: candidateAuditCode,
                  estado_ciclo: certRow.estado_ciclo,
                  objetivo: certRow.objetivo,
                })
                .select('id')
                .single();
              return {
                data: data?.id ? { id: String(data.id) } : undefined,
                error,
              };
            },
            isMissingSchemaError: isMissingTableOrSchemaError,
          });

          if (auditOutcome.status === 'missing-schema') {
            localFallback = true;
            reservedAuditCodes.add(auditOutcome.code.toUpperCase());
            savedAuditCodesByCertId.set(certRow.id_certificado, auditOutcome.code);
          } else if (auditOutcome.status === 'error') {
            await rollbackOrphanProgramAndAudits({
              programId: savedProgramId,
              insertedAuditIds: remotelyInsertedAuditIds,
              reason: 'Rollback por fallo al crear auditoría hija',
              archiveRecordFn: archiveRecordForRollback,
            });
            const msg = formatZeroUuidError(
              auditOutcome.error,
              'No se pudo vincular uno de los certificados al programa.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          } else {
            if (auditOutcome.data?.id) {
              newAuditId = auditOutcome.data.id;
            }
            remotelyInsertedAuditIds.push(newAuditId);
            reservedAuditCodes.add(auditOutcome.code.toUpperCase());
            savedAuditCodesByCertId.set(certRow.id_certificado, auditOutcome.code);
          }

          if (!localFallback && bundle.initialDatePayload) {
            const { count } = await supabase
              .from('auditoria_fecha')
              .select('id', { count: 'exact', head: true })
              .eq('id_auditoria', newAuditId)
              .is('deleted_at', null);

            if (!count || count === 0) {
              const { error: dateErr } = await supabase.from('auditoria_fecha').insert({
                id_auditoria: newAuditId,
                numero_secuencia: 1,
                tag: 'Programación',
                tipo_fecha: bundle.initialDatePayload.tipo_fecha,
                anio: bundle.initialDatePayload.anio,
                mes: bundle.initialDatePayload.mes,
                fecha_inicio: bundle.initialDatePayload.fecha_inicio,
                fecha_fin: bundle.initialDatePayload.fecha_fin,
                observacion: bundle.initialDatePayload.observacion,
              });
              if (dateErr && !isMissingTableOrSchemaError(dateErr)) {
                await rollbackOrphanProgramAndAudits({
                  programId: savedProgramId,
                  insertedAuditIds: remotelyInsertedAuditIds,
                  reason: 'Rollback por fallo al crear fecha inicial de auditoría hija',
                  archiveRecordFn: archiveRecordForRollback,
                });
                const msg = formatZeroUuidError(
                  dateErr,
                  'El programa se guardó, pero falló la fecha inicial.'
                );
                showFloatingToast(msg, 'warning');
                return { ok: false, error: msg };
              }
            }
          }
        }

        savedAuditIds.push(newAuditId);
      }
    } else {
      const validProgId = assertValidUuid(savedProgramId, 'programa de auditoría');
      let existingAudits: ExistingProgramAuditRef[] = [];
      let existingNivel: AuditLinkLevel | undefined;

      const { data: dbProgRow, error: dbProgErr } = await supabase
        .from('programa_auditoria')
        .select('id, nivel_vinculacion')
        .eq('id', validProgId)
        .is('deleted_at', null)
        .maybeSingle();

      if (dbProgErr) {
        if (!isMissingTableOrSchemaError(dbProgErr)) {
          const msg = formatZeroUuidError(
            dbProgErr,
            'No se pudo verificar el estado actual del programa.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else if (!dbProgRow && state.domainData.auditPrograms.some((p) => p.id === validProgId)) {
        localFallback = true;
      } else {
        existingNivel = dbProgRow?.nivel_vinculacion as AuditLinkLevel | undefined;
        const { data: dbAudits, error: dbAuditsErr } = await supabase
          .from('auditoria')
          .select('id, id_certificado, codigo_auditoria, deleted_at')
          .eq('id_programa_auditoria', validProgId)
          .is('deleted_at', null);

        if (dbAuditsErr && !isMissingTableOrSchemaError(dbAuditsErr)) {
          const msg = formatZeroUuidError(
            dbAuditsErr,
            'No se pudieron consultar las auditorías del programa.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        existingAudits = ((dbAudits as Array<Record<string, unknown>> | null) || []).map((r) => ({
          id: String(r.id),
          id_certificado: String(r.id_certificado),
          codigo_auditoria: r.codigo_auditoria ? String(r.codigo_auditoria) : null,
          deleted_at: null,
        }));
      }

      if (localFallback) {
        const localProg = state.domainData.auditPrograms.find((p) => p.id === validProgId);
        existingNivel = localProg?.nivel_vinculacion;
        existingAudits = (localProg?.auditorias || []).map((a) => ({
          id: a.id,
          id_certificado: a.id_certificado,
          codigo_auditoria: a.codigo_auditoria,
          deleted_at: a.deleted_at ?? null,
        }));
      }

      const diff = diffProgramAuditCertificates(existingAudits, bundle.certificateRows);

      // Verify dependencies before archiving removed certificates
      for (const removed of diff.toArchive) {
        const validRemovedAuditId = assertValidUuid(removed.id, 'auditoría');
        const depSummary = await fetchArchiveDependencySummarySafe('auditoria', validRemovedAuditId);
        if (!depSummary.can_archive) {
          const certLabel =
            state.domainData.allCertificadosDetailed.find((c) => c.id === removed.id_certificado)
              ?.numero_certificado || 'el certificado seleccionado';
          const msg = formatDependencyBlockedMessage(
            `la auditoría de ${certLabel}`,
            depSummary
          );
          showFloatingToast(msg, 'warning', 6000);
          return { ok: false, error: msg, dependencySummary: depSummary };
        }
      }

      const archiveRemovedAudits = async (): Promise<string | null> => {
        if (localFallback) return null;
        for (const removed of diff.toArchive) {
          const { error: arcErr } = await supabase.rpc('archive_record', {
            p_table: 'auditoria',
            p_record_id: assertValidUuid(removed.id, 'auditoría'),
            p_reason: 'Certificado retirado del programa de auditoría en Paso 1',
          });
          if (arcErr && !isMissingTableOrSchemaError(arcErr)) {
            return formatZeroUuidError(
              arcErr,
              'No se pudo archivar uno de los certificados retirados del programa.'
            );
          }
        }
        return null;
      };

      const archiveFirst = shouldArchiveBeforeProgramLevelUpdate(
        existingNivel,
        bundle.programaPayload.nivel_vinculacion
      );

      if (archiveFirst) {
        const arcMsg = await archiveRemovedAudits();
        if (arcMsg) {
          showFloatingToast(arcMsg, 'warning');
          return { ok: false, error: arcMsg };
        }
      }

      if (!localFallback) {
        const { error: progUpdErr } = await supabase
          .from('programa_auditoria')
          .update({
            etiqueta: bundle.programaPayload.etiqueta,
            codigo_programa: bundle.programaPayload.codigo_programa,
            nivel_vinculacion: bundle.programaPayload.nivel_vinculacion,
            tipo_vinculacion: bundle.programaPayload.tipo_vinculacion,
            es_vinculada: bundle.programaPayload.es_vinculada,
            id_ciclo_origen: bundle.programaPayload.id_ciclo_origen,
            notas: bundle.programaPayload.notas,
            updated_at: new Date().toISOString(),
          })
          .eq('id', validProgId)
          .is('deleted_at', null);

        if (progUpdErr) {
          if (!isMissingTableOrSchemaError(progUpdErr)) {
            const msg = formatZeroUuidError(
              progUpdErr,
              'No se pudo actualizar el programa de auditoría.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        }
      }

      if (!archiveFirst) {
        const arcMsg = await archiveRemovedAudits();
        if (arcMsg) {
          showFloatingToast(arcMsg, 'warning');
          return { ok: false, error: arcMsg };
        }
      }

      for (const upd of diff.toUpdate) {
        const validUpdAuditId = assertValidUuid(upd.auditId, 'auditoría');
        savedAuditIds.push(validUpdAuditId);
        if (!localFallback) {
          const { error: updErr } = await supabase
            .from('auditoria')
            .update({
              id_tipo_auditoria: upd.row.id_tipo_auditoria,
              id_metodologia: upd.row.id_metodologia,
              codigo_auditoria: upd.row.codigo_auditoria,
              estado_ciclo: upd.row.estado_ciclo,
              objetivo: upd.row.objetivo,
              updated_at: new Date().toISOString(),
            })
            .eq('id', validUpdAuditId)
            .is('deleted_at', null);

          if (updErr && !isMissingTableOrSchemaError(updErr)) {
            const msg = formatZeroUuidError(
              updErr,
              'No se pudo actualizar uno de los certificados del programa.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
        }
      }

      for (let i = 0; i < diff.toInsert.length; i += 1) {
        const ins = diff.toInsert[i];
        let newAuditId: string = crypto.randomUUID();
        const certObj = certCatalog.find((c) => c.id === ins.id_certificado);
        const activeCertVersionId =
          certObj?.versiones?.find((v) => !v.deleted_at && v.es_version_actual)?.id ??
          certObj?.id_certificado_version ??
          null;

        if (localFallback) {
          const fallbackCode =
            ins.codigo_auditoria ||
            (await allocateAuditCodeWithFallback({
              targetYear,
              numeroCertificado: certObj?.numero_certificado,
              activeAudits: state.domainData.programacionAudits,
              reservedCodes: reservedAuditCodes,
            }));
          reservedAuditCodes.add(fallbackCode.toUpperCase());
          savedAuditCodesByCertId.set(ins.id_certificado, fallbackCode);
        } else {
          const auditOutcome = await insertWithUniqueCodeRetry<{ id: string }>({
            initialCode: ins.codigo_auditoria,
            allocateCode: (_attempt, triedCodes) =>
              allocateAuditCodeWithFallback({
                targetYear,
                numeroCertificado: certObj?.numero_certificado,
                activeAudits: state.domainData.programacionAudits,
                reservedCodes: reservedAuditCodes,
                triedCodes,
                fetchRemoteNextCode: fetchRemoteNextAuditCode,
              }),
            attemptInsert: async (candidateAuditCode) => {
              const { data, error } = await supabase
                .from('auditoria')
                .insert({
                  id: newAuditId,
                  id_programa_auditoria: validProgId,
                  id_certificado: ins.id_certificado,
                  ...(activeCertVersionId ? { id_certificado_version: activeCertVersionId } : {}),
                  id_tipo_auditoria: ins.id_tipo_auditoria,
                  id_metodologia: ins.id_metodologia,
                  codigo_auditoria: candidateAuditCode,
                  estado_ciclo: ins.estado_ciclo,
                  objetivo: ins.objetivo,
                })
                .select('id')
                .single();
              return {
                data: data?.id ? { id: String(data.id) } : undefined,
                error,
              };
            },
            isMissingSchemaError: isMissingTableOrSchemaError,
          });

          if (auditOutcome.status === 'missing-schema') {
            localFallback = true;
            reservedAuditCodes.add(auditOutcome.code.toUpperCase());
            savedAuditCodesByCertId.set(ins.id_certificado, auditOutcome.code);
          } else if (auditOutcome.status === 'error') {
            const msg = formatZeroUuidError(
              auditOutcome.error,
              'No se pudo vincular el nuevo certificado al programa.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          } else {
            if (auditOutcome.data?.id) {
              newAuditId = auditOutcome.data.id;
            }
            reservedAuditCodes.add(auditOutcome.code.toUpperCase());
            savedAuditCodesByCertId.set(ins.id_certificado, auditOutcome.code);
          }

          if (!localFallback && bundle.initialDatePayload) {
            const { count } = await supabase
              .from('auditoria_fecha')
              .select('id', { count: 'exact', head: true })
              .eq('id_auditoria', newAuditId)
              .is('deleted_at', null);

            if (!count || count === 0) {
              const { error: dateErr } = await supabase.from('auditoria_fecha').insert({
                id_auditoria: newAuditId,
                numero_secuencia: 1,
                tag: 'Programación',
                tipo_fecha: bundle.initialDatePayload.tipo_fecha,
                anio: bundle.initialDatePayload.anio,
                mes: bundle.initialDatePayload.mes,
                fecha_inicio: bundle.initialDatePayload.fecha_inicio,
                fecha_fin: bundle.initialDatePayload.fecha_fin,
                observacion: bundle.initialDatePayload.observacion,
              });
              if (dateErr && !isMissingTableOrSchemaError(dateErr)) {
                const msg = formatZeroUuidError(
                  dateErr,
                  'El certificado se vinculó, pero falló su fecha inicial.'
                );
                showFloatingToast(msg, 'warning');
                return { ok: false, error: msg };
              }
            }
          }
        }

        savedAuditIds.push(newAuditId);
      }
    }

    if (localFallback) {
      const tiposCat = getResolvedTiposCatalog();
      const metCat = getResolvedMetodologiasCatalog();
      const existingProg = state.domainData.auditPrograms.find((p) => p.id === savedProgramId);
      const nextAudits: ProgramacionAuditEntity[] = bundle.certificateRows.map((row, idx) => {
        const existingAudit = existingProg?.auditorias.find(
          (a) => a.id_certificado === row.id_certificado && !a.deleted_at
        );
        const cert = certCatalog.find(
          (c) => c.id === row.id_certificado
        );
        const tipoLabel =
          tiposCat.find((t) => t.id === row.id_tipo_auditoria)?.tipo ||
          existingAudit?.tipo_auditoria ||
          'Por definir';
        const metRaw =
          metCat.find((m) => m.id === row.id_metodologia)?.metodologia ||
          existingAudit?.metodologia ||
          'Presencial';
        const metVal: AuditMethodology =
          metRaw.toLowerCase().includes('remot')
            ? 'Remota'
            : metRaw.toLowerCase().includes('mixt')
            ? 'Mixta'
            : 'Presencial';
        const resolvedAuditId = existingAudit?.id || savedAuditIds[idx] || crypto.randomUUID();
        const existingFechas = existingAudit?.fechas || [];
        const nextFechas: AuditDateEntry[] =
          !existingAudit && bundle.initialDatePayload && existingFechas.length === 0
            ? [
                {
                  id: crypto.randomUUID(),
                  id_auditoria: resolvedAuditId,
                  numero_secuencia: 1,
                  tag: 'Programación',
                  tipo_fecha: bundle.initialDatePayload.tipo_fecha,
                  anio: bundle.initialDatePayload.anio,
                  mes: bundle.initialDatePayload.mes,
                  fecha_inicio: bundle.initialDatePayload.fecha_inicio,
                  fecha_fin: bundle.initialDatePayload.fecha_fin,
                  observacion: bundle.initialDatePayload.observacion,
                  deleted_at: null,
                },
              ]
            : existingFechas;
        const latest = resolveLatestAuditDate(nextFechas);
        return {
          id: resolvedAuditId,
          id_programa_auditoria: savedProgramId,
          codigo_auditoria:
            row.codigo_auditoria ||
            savedAuditCodesByCertId.get(row.id_certificado) ||
            existingAudit?.codigo_auditoria ||
            `AUD-${targetYear}-${String(idx + 1).padStart(2, '0')}`,
          id_certificado: row.id_certificado,
          id_certificado_version:
            existingAudit?.id_certificado_version ??
            cert?.versiones?.find((v) => !v.deleted_at && v.es_version_actual)?.id ??
            cert?.id_certificado_version ??
            null,
          version_numero:
            existingAudit?.version_numero ??
            cert?.version_actual_numero ??
            1,
          numero_certificado: cert?.numero_certificado || existingAudit?.numero_certificado || 'Certificado',
          id_organizacion: cert?.id_organizacion || existingAudit?.id_organizacion || '',
          organizacion_nombre:
            cert?.organizacion_nombre || existingAudit?.organizacion_nombre || 'Organización',
          organizacion_abreviacion:
            cert?.organizacion_abreviacion ?? existingAudit?.organizacion_abreviacion ?? null,
          norma_codigo: cert?.norma_codigo || existingAudit?.norma_codigo || 'ISO',
          sector_iaf: cert?.sector_iaf || existingAudit?.sector_iaf || 17,
          tipo_auditoria: tipoLabel,
          metodologia: metVal,
          fecha_inicio: latest?.fecha_inicio || existingAudit?.fecha_inicio || '',
          fecha_fin: latest?.fecha_fin || existingAudit?.fecha_fin || '',
          fecha_reprogramacion: existingAudit?.fecha_reprogramacion ?? null,
          fechas: nextFechas,
          latestDate: latest,
          dias_auditor: existingAudit?.dias_auditor ?? 0,
          tiempo_auditoria: existingAudit?.tiempo_auditoria ?? 0,
          estatus: existingAudit?.estatus || 'Planificado',
          estado_ciclo: row.estado_ciclo,
          objetivo: row.objetivo,
          auditor_lider_id: existingAudit?.auditor_lider_id || '',
          auditor_lider: existingAudit?.auditor_lider || 'Por asignar',
          sede_principal_direccion: cert?.direccion_fiscal || existingAudit?.sede_principal_direccion || '',
          equipo: existingAudit?.equipo || [],
          sitiosMuestreo: existingAudit?.sitiosMuestreo || [],
          sitiosPlan: existingAudit?.sitiosPlan || [],
          matrizNormativa: existingAudit?.matrizNormativa || [],
          recomendacion: existingAudit?.recomendacion ?? null,
          deleted_at: null,
        };
      });

      const updatedProg: ProgramaAuditoriaEntity = {
        id: savedProgramId,
        codigo_programa: effectiveCodigoPrograma,
        etiqueta: bundle.programaPayload.etiqueta,
        nivel_vinculacion: bundle.programaPayload.nivel_vinculacion,
        tipo_vinculacion: bundle.programaPayload.tipo_vinculacion,
        es_vinculada: bundle.programaPayload.es_vinculada,
        id_ciclo_origen: bundle.programaPayload.id_ciclo_origen,
        notas: bundle.programaPayload.notas,
        auditorias: nextAudits,
        deleted_at: null,
      };
      state.domainData.auditPrograms = isEdit
        ? state.domainData.auditPrograms.map((p) => (p.id === savedProgramId ? updatedProg : p))
        : [updatedProg, ...state.domainData.auditPrograms];
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    recordPhase5SessionLog(
      'programa_auditoria',
      savedProgramId,
      isEdit ? 'UPDATE' : 'INSERT',
      null,
      {
        accion: isEdit ? 'ACTUALIZAR_PROGRAMA_PASO_1' : 'CREAR_PROGRAMA_PASO_1',
        etiqueta: bundle.programaPayload.etiqueta,
        nivel_vinculacion: bundle.programaPayload.nivel_vinculacion,
        tipo_vinculacion: bundle.programaPayload.tipo_vinculacion,
        certificados_vinculados: bundle.certificateRows.length,
      }
    );

    const warningNote = bundle.warnings.length > 0 ? ` (${bundle.warnings[0]})` : '';
    showFloatingToast(
      `Programa "${bundle.programaPayload.etiqueta}" guardado correctamente${warningNote}.`,
      'success'
    );
    if (!options?.skipRender) {
      render();
    }
    return {
      ok: true,
      data: { programId: savedProgramId, auditIds: savedAuditIds },
      warning: bundle.warnings[0],
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar el programa de auditoría.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 3. Gestor Multi-Fecha 1:N (`addOrUpdateAuditDateRevision`, `syncDateRevisionToProgram`)
 */
export async function updateAuditDateObservation(
  auditId: string,
  dateId: string,
  observacion: string | null
): Promise<PersistenceMutationResult<{ id: string }>> {
  return addOrUpdateAuditDateRevision(auditId, {
    action: 'update-observation',
    dateId,
    observacion,
  });
}

export async function archiveAuditDateRevision(
  auditId: string,
  dateId: string,
  reason = 'Corrección de entrada temporal en planificación'
): Promise<PersistenceMutationResult<{ id: string }>> {
  return addOrUpdateAuditDateRevision(auditId, {
    action: 'archive',
    dateId,
    reason,
  });
}

export async function addOrUpdateAuditDateRevision(
  auditId: string,
  payload: AuditDateRevisionPayload,
  options: { allowReal?: boolean } = {}
): Promise<PersistenceMutationResult<{ id: string; numero_secuencia?: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validAuditId = assertValidUuid(auditId, 'auditoría');
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (payload.action === 'archive') {
      const validDateId = assertValidUuid(payload.dateId, 'fecha de auditoría');
      if (!localFallback) {
        const { error: arcErr } = await supabase.rpc('archive_record', {
          p_table: 'auditoria_fecha',
          p_record_id: validDateId,
          p_reason:
            sanitizeArchiveReason(payload.reason) ||
            'Corrección de secuencia temporal en planificación',
        });

        if (arcErr) {
          if (!isMissingTableOrSchemaError(arcErr)) {
            const msg = formatZeroUuidError(
              arcErr,
              'No se pudo archivar la entrada de fecha seleccionada.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        }
      }

      if (localFallback) {
        state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
          ...p,
          auditorias: p.auditorias.map((a) => {
            if (a.id !== validAuditId) return a;
            const nextFechas = (a.fechas || []).filter((f) => f.id !== validDateId);
            const latest = resolveLatestAuditDate(nextFechas);
            return { ...a, fechas: nextFechas, latestDate: latest };
          }),
        }));
        state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
          (p) => p.auditorias
        );
        recomputeLocalAuditPlanningDerivedState();
      } else {
        await loadLiveAudits();
      }

      recordPhase5SessionLog(
        'auditoria_fecha',
        validDateId,
        'UPDATE',
        { deleted_at: null },
        { accion: 'ARCHIVAR_FECHA_AUDITORIA' }
      );
      showFloatingToast('Registro de fecha archivado correctamente.', 'success');
      render();
      return { ok: true, data: { id: validDateId }, localFallback };
    }

    if (payload.action === 'update-observation') {
      const validatedObs = validateAuditDateObservationUpdate(payload.dateId, payload.observacion);
      if (!validatedObs.ok) {
        showFloatingToast(validatedObs.error, 'warning');
        return { ok: false, error: validatedObs.error };
      }

      if (!localFallback) {
        const { error: updErr } = await supabase
          .from('auditoria_fecha')
          .update({
            observacion: validatedObs.observacion,
            updated_at: new Date().toISOString(),
          })
          .eq('id', validatedObs.dateId)
          .eq('id_auditoria', validAuditId)
          .is('deleted_at', null);

        if (updErr) {
          if (!isMissingTableOrSchemaError(updErr)) {
            const msg = formatZeroUuidError(
              updErr,
              'No se pudo actualizar la observación de la fecha.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        }
      }

      if (localFallback) {
        state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
          ...p,
          auditorias: p.auditorias.map((a) => {
            if (a.id !== validAuditId) return a;
            const nextFechas = (a.fechas || []).map((f) =>
              f.id === validatedObs.dateId ? { ...f, observacion: validatedObs.observacion } : f
            );
            return {
              ...a,
              fechas: nextFechas,
              latestDate: resolveLatestAuditDate(nextFechas),
            };
          }),
        }));
        state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
          (p) => p.auditorias
        );
        recomputeLocalAuditPlanningDerivedState();
      } else {
        await loadLiveAudits();
      }

      recordPhase5SessionLog('auditoria_fecha', validatedObs.dateId, 'UPDATE', null, {
        accion: 'ACTUALIZAR_OBSERVACION_FECHA',
        observacion: validatedObs.observacion,
      });
      showFloatingToast('Observación de fecha actualizada.', 'success');
      render();
      return { ok: true, data: { id: validatedObs.dateId }, localFallback };
    }

    // Create new 1:N sequence (preserving prior sequences intact)
    let existingFechas: AuditDateEntry[] = [];
    if (localFallback) {
      const localAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
      existingFechas = localAudit?.fechas || [];
    } else {
      const { data: dbFechas, error: fetchErr } = await supabase
        .from('auditoria_fecha')
        .select(
          'id, id_auditoria, numero_secuencia, tag, tipo_fecha, anio, mes, fecha_inicio, fecha_fin, observacion, deleted_at'
        )
        .eq('id_auditoria', validAuditId)
        .is('deleted_at', null)
        .order('numero_secuencia', { ascending: true });

      if (fetchErr) {
        if (!isMissingTableOrSchemaError(fetchErr)) {
          const msg = formatZeroUuidError(
            fetchErr,
            'No se pudo consultar el historial de fechas de la auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
        const localAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
        existingFechas = localAudit?.fechas || [];
      } else {
        existingFechas = ((dbFechas as Array<Record<string, unknown>> | null) || []).map((row) => ({
          id: String(row.id),
          id_auditoria: String(row.id_auditoria),
          numero_secuencia: Math.max(1, Number(row.numero_secuencia ?? 1)),
          tag: String(row.tag || '') === 'Reprogramación' ? 'Reprogramación' : 'Programación',
          tipo_fecha:
            String(row.tipo_fecha || '') === 'REAL'
              ? 'REAL'
              : String(row.tipo_fecha || '') === 'PROGRAMADA_EXACTA'
              ? 'PROGRAMADA_EXACTA'
              : 'PREPROGRAMADA_MES',
          anio: row.anio !== null && row.anio !== undefined ? Number(row.anio) : null,
          mes: row.mes !== null && row.mes !== undefined ? Number(row.mes) : null,
          fecha_inicio: row.fecha_inicio ? String(row.fecha_inicio).slice(0, 10) : null,
          fecha_fin: row.fecha_fin ? String(row.fecha_fin).slice(0, 10) : null,
          observacion: row.observacion ? String(row.observacion) : null,
          deleted_at: null,
        }));
      }
    }

    const built = buildAuditDateInsertPayload(validAuditId, existingFechas, payload, options);
    if (!built.ok) {
      showFloatingToast(built.error, 'warning');
      return { ok: false, error: built.error };
    }

    let savedDateId: string = crypto.randomUUID();
    if (!localFallback) {
      const { data: insertedDate, error: insErr } = await supabase
        .from('auditoria_fecha')
        .insert({
          id: savedDateId,
          ...built.value,
        })
        .select('id')
        .single();

      if (insErr) {
        if (!isMissingTableOrSchemaError(insErr)) {
          const msg = formatZeroUuidError(
            insErr,
            'No se pudo registrar la nueva fecha de auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else if (insertedDate?.id) {
        savedDateId = String(insertedDate.id);
      }
    }

    if (localFallback) {
      const newEntry: AuditDateEntry = {
        id: savedDateId,
        ...built.value,
        deleted_at: null,
      };
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
        ...p,
        auditorias: p.auditorias.map((a) => {
          if (a.id !== validAuditId) return a;
          const nextFechas = [...(a.fechas || []), newEntry];
          const latest = resolveLatestAuditDate(nextFechas);
          return {
            ...a,
            fechas: nextFechas,
            latestDate: latest,
            fecha_inicio: latest?.fecha_inicio || a.fecha_inicio,
            fecha_fin: latest?.fecha_fin || a.fecha_fin,
          };
        }),
      }));
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    recordPhase5SessionLog('auditoria_fecha', savedDateId, 'INSERT', null, {
      accion: built.value.tag === 'Programación' ? 'PROGRAMAR_FECHA' : 'REPROGRAMAR_FECHA',
      numero_secuencia: built.value.numero_secuencia,
      tipo_fecha: built.value.tipo_fecha,
      observacion: built.value.observacion,
    });

    showFloatingToast(
      `${built.value.tag} #${built.value.numero_secuencia} registrada correctamente.`,
      'success'
    );
    render();
    return {
      ok: true,
      data: { id: savedDateId, numero_secuencia: built.value.numero_secuencia },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar el registro de fecha.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * Step 10.2 — Registro independiente de fechas REALES de ejecución + conciliación Multi-Auditor
 */
export async function saveRealExecutionDates(
  auditId: string,
  input: { fecha_inicio: string; fecha_fin: string; observacion?: string | null }
): Promise<PersistenceMutationResult<{ id: string; capacityValid: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  const valErr = validateRealExecutionDateInput(input);
  if (valErr) {
    showFloatingToast(valErr, 'warning');
    return { ok: false, error: valErr };
  }

  try {
    const validAuditId = assertValidUuid(auditId, 'auditoría');
    const targetAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
    if (!targetAudit) {
      const msg = 'No se encontró la auditoría seleccionada para registrar fechas reales.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const startIso = input.fecha_inicio.trim();
    const endIso = input.fecha_fin.trim();
    const obsTrim = (input.observacion || '').trim() || null;

    const existingReal = resolveAuditRealWindow(targetAudit).entry;
    let savedId = existingReal?.id || crypto.randomUUID();
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (existingReal && isValidUuid(existingReal.id)) {
      if (!localFallback) {
        const { error: updErr } = await supabase
          .from('auditoria_fecha')
          .update({
            fecha_inicio: startIso,
            fecha_fin: endIso,
            observacion: obsTrim,
            updated_at: new Date().toISOString(),
          })
          .eq('id', existingReal.id)
          .eq('id_auditoria', validAuditId)
          .is('deleted_at', null);

        if (updErr) {
          if (!isMissingTableOrSchemaError(updErr)) {
            const msg = formatZeroUuidError(updErr, 'No se pudo actualizar la fecha REAL.');
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        } else {
          await loadLiveAudits();
        }
      }
    } else {
      const revRes = await addOrUpdateAuditDateRevision(
        validAuditId,
        {
          tipo_fecha: 'REAL',
          fecha_inicio: startIso,
          fecha_fin: endIso,
          observacion: obsTrim,
        },
        { allowReal: true }
      );
      if (!revRes.ok || !revRes.data) {
        return {
          ok: false,
          error: !revRes.ok ? revRes.error : 'No se pudo registrar la fecha REAL.',
        };
      }
      savedId = revRes.data.id;
      localFallback = Boolean(revRes.localFallback);
    }

    if (localFallback) {
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
        ...p,
        auditorias: p.auditorias.map((a) => {
          if (a.id !== validAuditId) return a;
          const prevFechas = a.fechas || [];
          const hasExistingReal = existingReal && prevFechas.some((f) => f.id === existingReal.id);
          const nextFechas: AuditDateEntry[] = hasExistingReal
            ? prevFechas.map((f) =>
                f.id === existingReal!.id
                  ? { ...f, fecha_inicio: startIso, fecha_fin: endIso, observacion: obsTrim }
                  : f
              )
            : [
                ...prevFechas,
                {
                  id: savedId,
                  id_auditoria: validAuditId,
                  numero_secuencia: prevFechas.length + 1,
                  tag: prevFechas.length === 0 ? 'Programación' : 'Reprogramación',
                  tipo_fecha: 'REAL',
                  anio: null,
                  mes: null,
                  fecha_inicio: startIso,
                  fecha_fin: endIso,
                  observacion: obsTrim,
                  deleted_at: null,
                },
              ];
          const latest = resolveLatestAuditDate(nextFechas);
          return {
            ...a,
            fechas: nextFechas,
            latestDate: latest,
            fecha_inicio: latest?.fecha_inicio || a.fecha_inicio,
            fecha_fin: latest?.fecha_fin || a.fecha_fin,
          };
        }),
      }));
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    }

    const updatedAudit =
      state.domainData.programacionAudits.find((a) => a.id === validAuditId) || targetAudit;
    const capacity = evaluateRealExecutionCapacity(
      updatedAudit,
      state.domainData.allTemporalSites,
      startIso,
      endIso
    );
    const auditFindings = state.domainData.phase5Findings.filter(
      (f) => !f.deleted_at && f.id_auditoria === validAuditId
    );
    state.resultadoDomain.closingDateDraft =
      computeDefaultAuditClosingDate(endIso, auditFindings) ?? undefined;
    state.resultadoDomain.realDateFormDraft = undefined;
    state.resultadoDomain.realDateError = null;
    state.resultadoDomain.realDateSuccess = `Fechas reales guardadas (${startIso} al ${endIso}). ${capacity.compactSummaryLabel}`;

    recordPhase5SessionLog('auditoria_fecha', savedId, 'UPDATE', null, {
      accion: 'REGISTRO_FECHAS_REALES_RESULTADO',
      fecha_inicio: startIso,
      fecha_fin: endIso,
      capacidad_concurrente_valida: capacity.isConcurrentScheduleValid,
    });

    showFloatingToast('Fechas reales de ejecución actualizadas.', 'success');
    render();
    return {
      ok: true,
      data: { id: savedId, capacityValid: capacity.isConcurrentScheduleValid },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudieron guardar las fechas reales.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * Step 8.1 — Resync open NC computed deadlines from MAX(fecha_real) on local findings state
 */
function resyncLocalOpenNcDeadlines(
  config: AlertConfigEntity = state.domainData.auditAlertConfig,
  onlyAuditId?: string
): void {
  const auditById = new Map(state.domainData.programacionAudits.map((a) => [a.id, a]));
  state.domainData.phase5Findings = state.domainData.phase5Findings.map((f) => {
    if (f.deleted_at || f.cerrado) return f;
    if (onlyAuditId && f.id_auditoria !== onlyAuditId) return f;
    if (f.tipo !== 'NC_MAYOR' && f.tipo !== 'NC_MENOR') return f;
    const audit = auditById.get(f.id_auditoria);
    const maxRealIso = resolveMaxRealDateIso(audit);
    if (!maxRealIso) {
      return {
        ...f,
        fecha_limite_plan: null,
        fecha_limite_cierre: null,
        fecha_limite: 'Pendiente',
      };
    }
    const limits = computeNcLimitsFromLatestReal(maxRealIso, config);
    return {
      ...f,
      fecha_limite_plan: limits.planLimitIso,
      fecha_limite_cierre: limits.cierreLimitIso,
      fecha_limite: limits.cierreLimitIso || limits.planLimitIso || f.fecha_limite,
    };
  });
}

/**
 * Step 8.1 — Agregar fecha real discreta (`tipo_fecha = 'REAL'`) + recálculo automático de plazos NC
 */
export async function addDiscreteRealDate(
  auditId: string,
  isoDate: string
): Promise<PersistenceMutationResult<{ id: string; isoDate: string }>> {
  const targetAudit = state.domainData.programacionAudits.find((a) => a.id === auditId);
  if (!targetAudit || !canMutateAuditExecution(targetAudit, state.profile)) {
    const msg = 'No tiene permisos de edición para registrar fechas reales en esta auditoría.';
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }

  const check = validateDiscreteRealDateAdd(targetAudit, isoDate);
  if (!check.ok) {
    showFloatingToast(check.error, 'warning');
    return { ok: false, error: check.error };
  }

  const cleanIso = check.isoDate;
  const existingFechas = targetAudit.fechas || [];
  const nextSeq =
    existingFechas.reduce((max, f) => Math.max(max, f.numero_secuencia || 0), 0) + 1;
  let savedId: string = crypto.randomUUID();
  let localFallback = !isApprovedStaff() || !isValidUuid(auditId);

  if (!localFallback) {
    localFallback = !(await isStep3RemoteSchemaAvailable());
  }

  if (!localFallback) {
    try {
      const { data, error } = await supabase
        .from('auditoria_fecha')
        .insert({
          id: savedId,
          id_auditoria: auditId,
          numero_secuencia: nextSeq,
          tag: existingFechas.length === 0 ? 'Programación' : 'Reprogramación',
          tipo_fecha: 'REAL',
          anio: null,
          mes: null,
          fecha_inicio: cleanIso,
          fecha_fin: cleanIso,
          observacion: 'Fecha real registrada en Resultado',
        })
        .select('id')
        .single();
      if (error) {
        if (!isMissingTableOrSchemaError(error)) {
          const msg = formatZeroUuidError(error, 'No se pudo registrar la fecha real.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else if (data?.id) {
        savedId = String(data.id);
      }
    } catch {
      localFallback = true;
    }
  }

  if (localFallback) {
    const newEntry: AuditDateEntry = {
      id: savedId,
      id_auditoria: auditId,
      numero_secuencia: nextSeq,
      tag: existingFechas.length === 0 ? 'Programación' : 'Reprogramación',
      tipo_fecha: 'REAL',
      anio: null,
      mes: null,
      fecha_inicio: cleanIso,
      fecha_fin: cleanIso,
      observacion: 'Fecha real registrada en Resultado',
      deleted_at: null,
    };
    const applyDateToAudit = (a: ProgramacionAuditEntity): ProgramacionAuditEntity => {
      if (a.id !== auditId) return a;
      const nextFechas = [...(a.fechas || []), newEntry];
      return {
        ...a,
        fechas: nextFechas,
        latestDate: resolveLatestAuditDate(nextFechas),
      };
    };
    state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
      ...p,
      auditorias: p.auditorias.map(applyDateToAudit),
    }));
    state.domainData.programacionAudits = state.domainData.programacionAudits.map(applyDateToAudit);
    recomputeLocalAuditPlanningDerivedState();
  } else {
    await loadLiveAudits();
  }

  resyncLocalOpenNcDeadlines(state.domainData.auditAlertConfig, auditId);
  recordPhase5SessionLog('auditoria_fecha', savedId, 'INSERT', null, {
    accion: 'AGREGAR_FECHA_REAL_RESULTADO',
    fecha_real: cleanIso,
  });
  showFloatingToast(`Fecha real ${formatIsoDateDmy(cleanIso)} registrada.`, 'success');
  return { ok: true, data: { id: savedId, isoDate: cleanIso }, localFallback };
}

/**
 * Step 8.1 — Retirar fecha real discreta (`archive_record`) + recálculo de plazos NC
 */
export async function removeDiscreteRealDate(
  auditId: string,
  dateId: string
): Promise<PersistenceMutationResult<{ id: string }>> {
  const targetAudit = state.domainData.programacionAudits.find((a) => a.id === auditId);
  if (!targetAudit || !canMutateAuditExecution(targetAudit, state.profile)) {
    const msg = 'No tiene permisos de edición para retirar fechas reales en esta auditoría.';
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }

  let localFallback = !isApprovedStaff() || !isValidUuid(auditId) || !isValidUuid(dateId);
  if (!localFallback) {
    localFallback = !(await isStep3RemoteSchemaAvailable());
  }

  if (!localFallback) {
    try {
      const { error } = await supabase.rpc('archive_record', {
        p_table: 'auditoria_fecha',
        p_record_id: dateId,
        p_reason: 'Corrección de fecha real en Resultado',
      });
      if (error) {
        if (!isMissingTableOrSchemaError(error)) {
          const msg = formatZeroUuidError(error, 'No se pudo retirar la fecha real.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    } catch {
      localFallback = true;
    }
  }

  if (localFallback) {
    const stripDateFromAudit = (a: ProgramacionAuditEntity): ProgramacionAuditEntity => {
      if (a.id !== auditId) return a;
      const nextFechas = (a.fechas || []).filter((f) => f.id !== dateId);
      const nextLatest = resolveLatestAuditDate(nextFechas);
      return {
        ...a,
        fechas: nextFechas,
        latestDate: nextLatest,
      };
    };
    state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
      ...p,
      auditorias: p.auditorias.map(stripDateFromAudit),
    }));
    state.domainData.programacionAudits =
      state.domainData.programacionAudits.map(stripDateFromAudit);
    recomputeLocalAuditPlanningDerivedState();
  } else {
    await loadLiveAudits();
  }

  resyncLocalOpenNcDeadlines(state.domainData.auditAlertConfig, auditId);
  recordPhase5SessionLog(
    'auditoria_fecha',
    dateId,
    'UPDATE',
    { deleted_at: null },
    { accion: 'ARCHIVAR_FECHA_REAL_RESULTADO' }
  );
  showFloatingToast('Fecha real retirada correctamente.', 'success');
  return { ok: true, data: { id: dateId }, localFallback };
}

/**
 * Step 8.1 — Registrar No Conformidad por cláusula únicamente (`id_proceso = NULL`)
 */
export async function createClauseOnlyNc(
  auditId: string,
  input: { id_requisito: string; tipo: string; descripcion: string }
): Promise<PersistenceMutationResult<{ id: string; codigo_hallazgo: string }>> {
  const audit = state.domainData.programacionAudits.find((a) => a.id === auditId);
  if (!audit || !canMutateAuditExecution(audit, state.profile)) {
    const msg = 'No tiene permisos de edición para registrar hallazgos en esta auditoría.';
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }

  const certCatalog =
    state.domainData.allCertificadosDetailed.length > 0
      ? state.domainData.allCertificadosDetailed
      : INITIAL_CERTIFICADOS_DETAILED;
  const versionSnapshot = resolveCertVersionSnapshotForAudit(audit, certCatalog);
  const excludedReqIds = new Set(
    versionSnapshot.noAplicables
      .map((na) => na.id_requisito)
      .filter((id): id is string => Boolean(id))
  );
  const allowedReqs = filterRequirementsForAuditNorma(
    state.domainData.requirements,
    audit.norma_codigo,
    excludedReqIds.size > 0 ? excludedReqIds : undefined
  );
  const validation = validateClauseNcDraft(
    {
      auditId,
      tipo: input.tipo,
      id_requisito: input.id_requisito,
      descripcion: input.descripcion,
    },
    allowedReqs
  );
  if (!validation.ok) {
    showFloatingToast(validation.error, 'warning');
    return { ok: false, error: validation.error };
  }

  const maxRealIso = resolveMaxRealDateIso(audit);
  const limits = maxRealIso
    ? computeNcLimitsFromLatestReal(maxRealIso, state.domainData.auditAlertConfig)
    : null;
  const planLimitIso = limits?.planLimitIso ?? null;
  const cierreLimitIso = limits?.cierreLimitIso ?? null;

  const nextCodeNum = state.domainData.phase5Findings.length + 1;
  let newId: string = isValidUuid(auditId) ? crypto.randomUUID() : `finding-nc-${Date.now()}`;
  const codigoHallazgo = `HAL-${new Date().getFullYear()}-${String(nextCodeNum).padStart(3, '0')}`;
  let persistedToDb = false;

  if (isValidUuid(auditId) && isValidUuid(validation.value.id_requisito)) {
    try {
      const { data: insData, error: insErr } = await supabase
        .from('hallazgo')
        .insert({
          id: newId,
          id_auditoria: auditId,
          id_requisito: validation.value.id_requisito,
          id_proceso: null,
          tipo: validation.value.tipo,
          descripcion: validation.value.descripcion,
          cerrado: false,
          fecha_limite_plan: planLimitIso,
          fecha_limite_cierre: cierreLimitIso,
        })
        .select('id, fecha_limite_plan, fecha_limite_cierre')
        .single();
      if (insErr && !isMissingTableOrSchemaError(insErr)) {
        const msg = formatZeroUuidError(
          insErr,
          'No se pudo registrar la No Conformidad en la base de datos.'
        );
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      if (!insErr && insData?.id) {
        newId = String(insData.id);
        persistedToDb = true;
      }
    } catch {
      // Local fallback keeps UX smooth in offline / unit test context
    }
  }

  const newFinding: Phase5FindingEntity = {
    id: newId,
    codigo_hallazgo: codigoHallazgo,
    id_auditoria: auditId,
    auditoria_tipo: audit.tipo_auditoria,
    numero_certificado: audit.numero_certificado,
    organizacion_nombre: audit.organizacion_nombre,
    id_requisito: validation.value.id_requisito,
    requisito_codigo: validation.value.requisito_codigo,
    requisito_titulo: validation.value.requisito_titulo,
    id_proceso: null,
    proceso_nombre: 'Por cláusula',
    id_sitio: null,
    sitio_nombre: 'Alcance General',
    tipo: validation.value.tipo,
    descripcion: validation.value.descripcion,
    evidencia: null,
    estado_ciclo: 'Abierto',
    analisis_causa_raiz: '',
    plan_accion_correctiva: '',
    comentarios_verificacion: '',
    fecha_limite: cierreLimitIso || planLimitIso || 'Pendiente',
    fecha_limite_plan: planLimitIso,
    fecha_entrega_plan: null,
    fecha_limite_cierre: cierreLimitIso,
    fecha_cierre_real: null,
    fecha_cierre: null,
    cerrado: false,
    created_at: new Date().toISOString(),
    deleted_at: null,
  };

  state.domainData.phase5Findings = [newFinding, ...state.domainData.phase5Findings];
  state.domainData.findings = [newFinding, ...state.domainData.findings];

  recordPhase5SessionLog('hallazgo', newId, 'INSERT', null, {
    auditoria: audit.codigo_auditoria || audit.numero_certificado,
    codigo_hallazgo: codigoHallazgo,
    tipo: validation.value.tipo,
    clausula: validation.value.requisito_codigo,
    id_proceso: null,
    fecha_limite_plan: planLimitIso,
    fecha_limite_cierre: cierreLimitIso,
    persisted_to_db: persistedToDb,
  });

  showFloatingToast(`No Conformidad ${codigoHallazgo} registrada correctamente.`, 'success');
  return { ok: true, data: { id: newId, codigo_hallazgo: codigoHallazgo }, localFallback: !persistedToDb };
}

/**
 * Step 8.1 — Guardar Fecha Real Plan y Fecha Real Cierre directamente por tarjeta NC
 */
export async function saveFindingRealDates(
  findingId: string,
  auditId: string,
  dates: { fecha_entrega_plan: string | null; fecha_cierre_real: string | null }
): Promise<PersistenceMutationResult<{ id: string; cerrado: boolean }>> {
  const existing = state.domainData.phase5Findings.find((f) => f.id === findingId);
  const audit = state.domainData.programacionAudits.find(
    (a) => a.id === (existing?.id_auditoria || auditId)
  );
  if (!existing || !audit || !canMutateAuditExecution(audit, state.profile)) {
    const msg = 'No tiene permisos de edición para actualizar esta No Conformidad.';
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }

  const planDate = dates.fecha_entrega_plan?.trim() || null;
  const cierreDate = dates.fecha_cierre_real?.trim() || null;
  const nextClosed = Boolean(cierreDate);

  const errMsg = validateFindingFollowUpDates({
    fecha_entrega_plan: planDate,
    fecha_cierre_real: cierreDate,
    cerrado: nextClosed,
  });
  if (errMsg) {
    showFloatingToast(errMsg, 'warning');
    return { ok: false, error: errMsg };
  }

  let localFallback = !isValidUuid(findingId);
  if (!localFallback) {
    try {
      const { error } = await supabase
        .from('hallazgo')
        .update({
          fecha_entrega_plan: planDate,
          fecha_cierre_real: cierreDate,
          cerrado: nextClosed,
        })
        .eq('id', findingId);
      if (error) {
        if (!isMissingTableOrSchemaError(error)) {
          const msg = formatZeroUuidError(
            error,
            'No se pudieron guardar las fechas reales de la No Conformidad.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    } catch {
      localFallback = true;
    }
  }

  const nextStatus: FindingLifecycleStatus = nextClosed
    ? 'Cerrado'
    : planDate
    ? 'Plan de Acción Enviado'
    : 'Abierto';

  state.domainData.phase5Findings = state.domainData.phase5Findings.map((f) =>
    f.id === findingId
      ? {
          ...f,
          fecha_entrega_plan: planDate,
          fecha_cierre_real: cierreDate,
          fecha_cierre: cierreDate,
          cerrado: nextClosed,
          estado_ciclo: nextStatus,
        }
      : f
  );
  state.domainData.findings = state.domainData.findings.map((f) =>
    f.id === findingId ? { ...f, cerrado: nextClosed } : f
  );

  if (state.resultadoDomain.ncDatesDraftByFindingId) {
    const nextDrafts = { ...state.resultadoDomain.ncDatesDraftByFindingId };
    delete nextDrafts[findingId];
    state.resultadoDomain.ncDatesDraftByFindingId = nextDrafts;
  }

  recordPhase5SessionLog(
    'hallazgo',
    findingId,
    'UPDATE',
    {
      fecha_entrega_plan: existing.fecha_entrega_plan || null,
      fecha_cierre_real: existing.fecha_cierre_real || null,
      cerrado: existing.cerrado,
    },
    {
      fecha_entrega_plan: planDate,
      fecha_cierre_real: cierreDate,
      cerrado: nextClosed,
    }
  );

  showFloatingToast(
    nextClosed
      ? `No Conformidad ${existing.codigo_hallazgo} cerrada ✓.`
      : `Fechas reales de ${existing.codigo_hallazgo} guardadas.`,
    'success'
  );
  return { ok: true, data: { id: findingId, cerrado: nextClosed }, localFallback };
}

/**
 * Step 10.2 — Cierre Formal de Auditoría (`estado_ciclo = 'Cerrada'` + `fecha_cierre_auditoria`)
 * Habilita la compuerta hacia Paso 11 (`Revisión`).
 */
export async function closeAuditWithClosingDate(
  auditId: string,
  closingDateIso: string
): Promise<PersistenceMutationResult<{ id: string; fecha_cierre_auditoria: string }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validAuditId = assertValidUuid(auditId, 'auditoría');
    const targetAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
    if (!targetAudit) {
      const msg = 'No se encontró la auditoría seleccionada para cierre.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const realWin = resolveAuditRealWindow(targetAudit);
    const validationErr = validateCloseAuditAction(
      validAuditId,
      realWin.realEndIso,
      closingDateIso.trim()
    );
    if (validationErr) {
      showFloatingToast(validationErr, 'warning');
      return { ok: false, error: validationErr };
    }

    const normalizedCloseIso = closingDateIso.trim();
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { error: updErr } = await supabase
        .from('auditoria')
        .update({
          estado_ciclo: 'Cerrada',
          fecha_cierre_auditoria: normalizedCloseIso,
          updated_at: new Date().toISOString(),
        })
        .eq('id', validAuditId)
        .is('deleted_at', null);

      if (updErr) {
        if (!isMissingTableOrSchemaError(updErr)) {
          const msg = formatZeroUuidError(
            updErr,
            'No se pudo cerrar formalmente la auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    const oldSnapshot = {
      estado_ciclo: targetAudit.estado_ciclo || 'Programada',
      fecha_cierre_auditoria: targetAudit.fecha_cierre_auditoria || null,
    };

    state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
      ...p,
      auditorias: p.auditorias.map((a) =>
        a.id === validAuditId
          ? {
              ...a,
              estado_ciclo: 'Cerrada',
              estatus: 'Cerrado',
              fecha_cierre_auditoria: normalizedCloseIso,
            }
          : a
      ),
    }));
    state.domainData.programacionAudits = state.domainData.programacionAudits.map((a) =>
      a.id === validAuditId
        ? {
            ...a,
            estado_ciclo: 'Cerrada',
            estatus: 'Cerrado',
            fecha_cierre_auditoria: normalizedCloseIso,
          }
        : a
    );
    state.domainData.audits = state.domainData.audits.map((a) =>
      a.id === validAuditId ? { ...a, estatus: 'Cerrado' } : a
    );
    recomputeLocalAuditPlanningDerivedState();

    state.resultadoDomain.closingDateDraft = normalizedCloseIso;
    state.resultadoDomain.closingError = null;
    state.resultadoDomain.closingSuccess = `Auditoría marcada como Cerrada (${normalizedCloseIso}). Paso 11 (Revisión) habilitado.`;

    recordPhase5SessionLog('auditoria', validAuditId, 'UPDATE', oldSnapshot, {
      estado_ciclo: 'Cerrada',
      fecha_cierre_auditoria: normalizedCloseIso,
    });

    showFloatingToast('Auditoría cerrada correctamente. Paso 11 (Revisión) habilitado.', 'success');
    render();
    return {
      ok: true,
      data: { id: validAuditId, fecha_cierre_auditoria: normalizedCloseIso },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo cerrar la auditoría.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * Step 11.1 — Aprobación de Revisión QA Post-Cierre (`revisado`, `fecha_revision`, `revisado_por`, `documentacion_completa`, `resumen_revision`)
 */
export async function saveAuditRevision(
  draft: RevisionFormDraft
): Promise<PersistenceMutationResult<{ id: string; fecha_revision: string; revisado: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.revisionDomain.savingRevision = false;
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validAuditId = assertValidUuid(draft.id_auditoria, 'auditoría');
    const targetAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
    const validationErr = validateRevisionDraft(draft, targetAudit);
    if (validationErr || !targetAudit) {
      state.revisionDomain.savingRevision = false;
      const msg = validationErr || 'No se encontró la auditoría seleccionada para revisión.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const normalizedDate = draft.fecha_revision.trim();
    const normalizedResumen = draft.resumen_revision.trim();
    const reviewerId = state.profile?.id || null;
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { error: updErr } = await supabase
        .from('auditoria')
        .update({
          revisado: Boolean(draft.revisado),
          fecha_revision: draft.revisado ? normalizedDate : null,
          revisado_por: draft.revisado ? reviewerId : null,
          documentacion_completa: Boolean(draft.documentacion_completa ?? true),
          resumen_revision: normalizedResumen || null,
          updated_at: new Date().toISOString(),
        })
        .eq('id', validAuditId)
        .is('deleted_at', null);

      if (updErr) {
        if (!isMissingTableOrSchemaError(updErr)) {
          state.revisionDomain.savingRevision = false;
          const msg = formatZeroUuidError(
            updErr,
            'No se pudo guardar la revisión de la auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    const oldSnapshot = {
      revisado: Boolean(targetAudit.revisado),
      fecha_revision: targetAudit.fecha_revision ?? null,
      revisado_por: targetAudit.revisado_por ?? null,
      documentacion_completa: Boolean(targetAudit.documentacion_completa),
      resumen_revision: targetAudit.resumen_revision ?? null,
    };

    const applyRevisionFields = (audit: ProgramacionAuditEntity): ProgramacionAuditEntity =>
      audit.id === validAuditId
        ? {
            ...audit,
            revisado: Boolean(draft.revisado),
            fecha_revision: draft.revisado ? normalizedDate : null,
            revisado_por: draft.revisado ? reviewerId : null,
            documentacion_completa: Boolean(draft.documentacion_completa ?? true),
            resumen_revision: normalizedResumen || null,
          }
        : audit;

    state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
      ...p,
      auditorias: p.auditorias.map(applyRevisionFields),
    }));
    state.domainData.programacionAudits = state.domainData.programacionAudits.map(applyRevisionFields);
    recomputeLocalAuditPlanningDerivedState();

    state.revisionDomain.savingRevision = false;
    state.revisionDomain.formDraft = undefined;
    state.revisionDomain.editErrorMessage = null;
    state.revisionDomain.saveSuccessMessage = `Revisión registrada (${formatIsoDateDmy(normalizedDate)}).`;

    recordPhase5SessionLog('auditoria', validAuditId, 'UPDATE', oldSnapshot, {
      revisado: Boolean(draft.revisado),
      fecha_revision: draft.revisado ? normalizedDate : null,
      revisado_por: state.profile?.nombre || 'Coordinador QA',
      resumen_revision: normalizedResumen || null,
    });

    showFloatingToast('Revisión de auditoría guardada correctamente.', 'success');
    render();
    return {
      ok: true,
      data: {
        id: validAuditId,
        fecha_revision: normalizedDate,
        revisado: Boolean(draft.revisado),
      },
      localFallback,
    };
  } catch (err) {
    state.revisionDomain.savingRevision = false;
    const msg = formatZeroUuidError(err, 'No se pudo guardar la revisión QA de la auditoría.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

export async function syncDateRevisionToProgram(
  programId: string,
  payload: AuditDateEntryInput
): Promise<PersistenceMutationResult<{ updatedAuditsCount: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validProgramId = assertValidUuid(programId, 'programa de auditoría');

    // Validate date payload shape before querying audits
    const probeCheck = buildAuditDateInsertPayload(
      '00000000-0000-0000-0000-000000000001',
      [],
      payload
    );
    if (!probeCheck.ok) {
      showFloatingToast(probeCheck.error, 'warning');
      return { ok: false, error: probeCheck.error };
    }

    let targetAuditIds: string[] = [];
    let localFallback = false;

    const { data: programAuditsRows, error: auditsErr } = await supabase
      .from('auditoria')
      .select('id')
      .eq('id_programa_auditoria', validProgramId)
      .is('deleted_at', null);

    if (auditsErr) {
      if (!isMissingTableOrSchemaError(auditsErr)) {
        const msg = formatZeroUuidError(
          auditsErr,
          'No se pudieron obtener las auditorías activas de la campaña.'
        );
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      localFallback = true;
    } else {
      targetAuditIds = ((programAuditsRows as Array<Record<string, unknown>> | null) || [])
        .map((r) => String(r.id || ''))
        .filter(Boolean);
    }

    if (localFallback) {
      const localProgram = state.domainData.auditPrograms.find((p) => p.id === validProgramId);
      targetAuditIds = (localProgram?.auditorias || [])
        .filter((a) => !a.deleted_at)
        .map((a) => a.id);
    }

    if (targetAuditIds.length === 0) {
      const msg = 'No hay auditorías activas en esta campaña para sincronizar la fecha.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    let updatedAuditsCount = 0;
    for (const rawAuditId of targetAuditIds) {
      const validAuditId = assertValidUuid(rawAuditId, 'auditoría');
      let existingFechas: AuditDateEntry[] = [];

      if (!localFallback) {
        const { data: dbFechas, error: fetchErr } = await supabase
          .from('auditoria_fecha')
          .select(
            'id, id_auditoria, numero_secuencia, tag, tipo_fecha, anio, mes, fecha_inicio, fecha_fin, observacion, deleted_at'
          )
          .eq('id_auditoria', validAuditId)
          .is('deleted_at', null)
          .order('numero_secuencia', { ascending: true });

        if (fetchErr && !isMissingTableOrSchemaError(fetchErr)) {
          const msg = formatZeroUuidError(
            fetchErr,
            'No se pudo consultar la secuencia temporal de una auditoría de la campaña.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        existingFechas = ((dbFechas as Array<Record<string, unknown>> | null) || []).map((row) => ({
          id: String(row.id),
          id_auditoria: String(row.id_auditoria),
          numero_secuencia: Math.max(1, Number(row.numero_secuencia ?? 1)),
          tag: String(row.tag || '') === 'Reprogramación' ? 'Reprogramación' : 'Programación',
          tipo_fecha:
            String(row.tipo_fecha || '') === 'REAL'
              ? 'REAL'
              : String(row.tipo_fecha || '') === 'PROGRAMADA_EXACTA'
              ? 'PROGRAMADA_EXACTA'
              : 'PREPROGRAMADA_MES',
          anio: row.anio !== null && row.anio !== undefined ? Number(row.anio) : null,
          mes: row.mes !== null && row.mes !== undefined ? Number(row.mes) : null,
          fecha_inicio: row.fecha_inicio ? String(row.fecha_inicio).slice(0, 10) : null,
          fecha_fin: row.fecha_fin ? String(row.fecha_fin).slice(0, 10) : null,
          observacion: row.observacion ? String(row.observacion) : null,
          deleted_at: null,
        }));
      } else {
        const localAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
        existingFechas = localAudit?.fechas || [];
      }

      const built = buildAuditDateInsertPayload(validAuditId, existingFechas, payload);
      if (!built.ok) {
        showFloatingToast(built.error, 'warning');
        return { ok: false, error: built.error };
      }

      const newDateId = crypto.randomUUID();
      if (!localFallback) {
        const { error: insErr } = await supabase.from('auditoria_fecha').insert({
          id: newDateId,
          ...built.value,
        });
        if (insErr) {
          if (!isMissingTableOrSchemaError(insErr)) {
            const msg = formatZeroUuidError(
              insErr,
              'Error al propagar la fecha a todas las auditorías de la campaña.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        }
      }

      if (localFallback) {
        const newEntry: AuditDateEntry = {
          id: newDateId,
          ...built.value,
          deleted_at: null,
        };
        state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
          ...p,
          auditorias: p.auditorias.map((a) => {
            if (a.id !== validAuditId) return a;
            const nextFechas = [...(a.fechas || []), newEntry];
            return {
              ...a,
              fechas: nextFechas,
              latestDate: resolveLatestAuditDate(nextFechas),
            };
          }),
        }));
      }

      updatedAuditsCount += 1;
    }

    if (localFallback) {
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    recordPhase5SessionLog('programa_auditoria', validProgramId, 'UPDATE', null, {
      accion: 'SINCRONIZAR_FECHA_CAMPANA',
      auditorias_actualizadas: updatedAuditsCount,
      tipo_fecha: payload.tipo_fecha,
      observacion: payload.observacion || null,
    });

    showFloatingToast(
      `Fecha aplicada a ${updatedAuditsCount} auditoría(s) activa(s) de la campaña.`,
      'success'
    );
    render();
    return { ok: true, data: { updatedAuditsCount }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo propagar la fecha a la campaña.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 3b. Step 3.3 — `Designación → Tipo`: creación desde Vínculo, reprogramaciones 1:N y tipos por certificado
 */
async function isStep3RemoteSchemaAvailable(): Promise<boolean> {
  const [progCheck, audCheck, dateCheck] = await Promise.all([
    supabase.from('programa_auditoria').select('id, id_vinculo, tiene_sitio_temporal').limit(1),
    supabase.from('auditoria').select('id, id_programa_auditoria, tiene_sitio_temporal').limit(1),
    supabase.from('auditoria_fecha').select('id, numero_secuencia, tipo_fecha').limit(1),
  ]);
  return (
    !isMissingTableOrSchemaError(progCheck.error) &&
    !isMissingTableOrSchemaError(audCheck.error) &&
    !isMissingTableOrSchemaError(dateCheck.error)
  );
}

export async function createStep3CampaignCycle(
  draft: Step3NewCycleDraft
): Promise<PersistenceMutationResult<{ programId: string; auditIds: string[] }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  const certCatalogForValidation =
    state.domainData.allCertificadosDetailed.length > 0
      ? state.domainData.allCertificadosDetailed
      : INITIAL_CERTIFICADOS_DETAILED;

  const validationError = validateStep3NewCycleDraft(
    draft,
    state.domainData.allVinculos,
    certCatalogForValidation
  );
  if (validationError) {
    state.designacionTipoDomain.editErrorMessage = validationError;
    render();
    return { ok: false, error: validationError };
  }

  try {
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }

    const vinculo = state.domainData.allVinculos.find(
      (v) => !v.deleted_at && v.id === draft.id_vinculo
    );
    if (!vinculo) {
      const msg = 'El vínculo seleccionado ya no está disponible.';
      state.designacionTipoDomain.editErrorMessage = msg;
      render();
      return { ok: false, error: msg };
    }

    const tiposCatalog = getResolvedTiposCatalog().filter((t) => !t.deleted_at);
    const certCatalog = certCatalogForValidation;
    const defaultMetodologia = getResolvedMetodologiasCatalog().find((m) => !m.deleted_at);

    const effectiveNivelVinculacion = deriveProgramLinkLevelFromCertSubset(
      draft.certTypes.map((c) => ({
        id_organizacion:
          certCatalog.find((cat) => cat.id === c.id_certificado)?.id_organizacion ??
          vinculo.certificados.find(
            (vc) => !vc.deleted_at && vc.id_certificado === c.id_certificado
          )?.id_organizacion ??
          null,
      }))
    );
    const rawProgramTipoVinculacion = deriveProgramLinkNatureFromCertSubset(
      draft.certTypes.map((c) => c.tipo_vinculacion)
    );
    const effectiveEsVinculada = effectiveNivelVinculacion !== 'INDIVIDUAL';
    const programTipoVinculacion: AuditLinkNature =
      effectiveNivelVinculacion === 'INDIVIDUAL'
        ? 'Individual'
        : rawProgramTipoVinculacion === 'Individual'
        ? vinculo.tipo_vinculacion !== 'Individual'
          ? vinculo.tipo_vinculacion
          : 'Mixta'
        : rawProgramTipoVinculacion;

    const exactGoalStart = (draft.fecha_programada || draft.fecha_inicio || '').trim();
    const exactGoalEnd = (draft.fecha_programada || draft.fecha_fin || exactGoalStart).trim();
    const newProgramId: string = crypto.randomUUID();
    const targetYear = resolveCampaignTargetYear({
      dateMode: draft.dateMode,
      anio: draft.anio,
      fechaInicio: exactGoalStart,
    });
    const etiqueta = draft.etiqueta.trim();
    let localFallback = !(await isStep3RemoteSchemaAvailable());
    let codigoPrograma = draft.codigo_programa.trim();

    const fetchRemoteNextProgramCode = async (year: number): Promise<string | null> => {
      const { data, error } = await supabase.rpc('fn_next_programa_auditoria_codigo', {
        p_year: year,
      });
      if (error || typeof data !== 'string') return null;
      return data.trim() || null;
    };

    const fetchRemoteNextAuditCode = async (
      year: number,
      certShort: string
    ): Promise<string | null> => {
      const { data, error } = await supabase.rpc('fn_next_auditoria_codigo', {
        p_year: year,
        p_cert_short: certShort,
      });
      if (error || typeof data !== 'string') return null;
      return data.trim() || null;
    };

    const archiveRecordForRollback = async (
      table: 'programa_auditoria' | 'auditoria',
      recordId: string,
      reason: string
    ): Promise<void> => {
      await supabase.rpc('archive_record', {
        p_table: table,
        p_record_id: recordId,
        p_reason: reason,
      });
    };

    if (!localFallback) {
      const progOutcome = await insertWithUniqueCodeRetry<null>({
        initialCode: codigoPrograma || null,
        allocateCode: (_attempt, triedCodes) =>
          allocateProgramCodeWithFallback({
            targetYear,
            activePrograms: state.domainData.auditPrograms,
            triedCodes,
            fetchRemoteNextCode: fetchRemoteNextProgramCode,
          }),
        attemptInsert: async (candidateCode) => {
          const { error: progErr } = await supabase.from('programa_auditoria').insert({
            id: newProgramId,
            id_vinculo: vinculo.id,
            id_grupo_empresarial: vinculo.id_grupo_empresarial,
            codigo_programa: candidateCode,
            etiqueta,
            nivel_vinculacion: effectiveNivelVinculacion,
            tipo_vinculacion: programTipoVinculacion,
            es_vinculada: effectiveEsVinculada,
            tiene_sitio_temporal: Boolean(vinculo.tiene_sitio_temporal),
            notas: draft.observacion.trim() || null,
          });
          return { error: progErr };
        },
        isMissingSchemaError: isMissingTableOrSchemaError,
      });

      if (progOutcome.status === 'missing-schema') {
        localFallback = true;
        codigoPrograma = progOutcome.code;
      } else if (progOutcome.status === 'error') {
        const msg = formatZeroUuidError(
          progOutcome.error,
          'No se pudo crear la campaña en Designación → Tipo.'
        );
        state.designacionTipoDomain.editErrorMessage = msg;
        render();
        return { ok: false, error: msg };
      } else {
        codigoPrograma = progOutcome.code;
      }
    }

    if (localFallback && !codigoPrograma) {
      codigoPrograma = await allocateProgramCodeWithFallback({
        targetYear,
        activePrograms: state.domainData.auditPrograms,
      });
    }

    const createdAudits: ProgramacionAuditEntity[] = [];
    const createdAuditIds: string[] = [];
    const remotelyInsertedAuditIds: string[] = [];
    const reservedAuditCodes = new Set<string>();

    for (let i = 0; i < draft.certTypes.length; i += 1) {
      const item = draft.certTypes[i];
      const auditId: string = crypto.randomUUID();
      const dateId: string = crypto.randomUUID();
      const certObj = certCatalog.find((c) => c.id === item.id_certificado);
      const activeCertVer =
        certObj?.versiones?.find((v) => !v.deleted_at && v.es_version_actual) ?? null;
      const activeCertVersionId =
        activeCertVer?.id ?? certObj?.id_certificado_version ?? null;
      const activeCertVersionNum =
        activeCertVer?.version_numero ?? certObj?.version_actual_numero ?? 1;
      const resolvedOrgAbrev =
        activeCertVer?.organizacion_abreviacion ??
        certObj?.organizacion_abreviacion ??
        item.organizacion_abreviacion ??
        null;
      const tipoObj = tiposCatalog.find((t) => t.id === item.id_tipo_auditoria);
      const certNumber = item.numero_certificado || certObj?.numero_certificado || 'CERT';
      let auditCode = '';

      if (!localFallback) {
        const auditOutcome = await insertWithUniqueCodeRetry<null>({
          initialCode: null,
          allocateCode: (_attempt, triedCodes) =>
            allocateAuditCodeWithFallback({
              targetYear,
              numeroCertificado: certNumber,
              activeAudits: state.domainData.programacionAudits,
              reservedCodes: reservedAuditCodes,
              triedCodes,
              fetchRemoteNextCode: fetchRemoteNextAuditCode,
            }),
          attemptInsert: async (candidateAuditCode) => {
            const { error: audErr } = await supabase.from('auditoria').insert({
              id: auditId,
              id_programa_auditoria: newProgramId,
              codigo_auditoria: candidateAuditCode,
              id_certificado: item.id_certificado,
              ...(activeCertVersionId ? { id_certificado_version: activeCertVersionId } : {}),
              id_tipo_auditoria: item.id_tipo_auditoria,
              id_metodologia: defaultMetodologia?.id ?? null,
              tipo_vinculacion: item.tipo_vinculacion,
              estado_ciclo: 'En Programación',
              tiene_sitio_temporal: Boolean(vinculo.tiene_sitio_temporal),
            });
            return { error: audErr };
          },
          isMissingSchemaError: isMissingTableOrSchemaError,
        });

        if (auditOutcome.status === 'missing-schema') {
          localFallback = true;
          auditCode = auditOutcome.code;
        } else if (auditOutcome.status === 'error') {
          await rollbackOrphanProgramAndAudits({
            programId: newProgramId,
            insertedAuditIds: remotelyInsertedAuditIds,
            reason: 'Rollback por fallo al crear auditoría hija',
            archiveRecordFn: archiveRecordForRollback,
          });
          const msg = formatZeroUuidError(
            auditOutcome.error,
            'No se pudo registrar una de las auditorías del vínculo.'
          );
          state.designacionTipoDomain.editErrorMessage = msg;
          render();
          return { ok: false, error: msg };
        } else {
          auditCode = auditOutcome.code;
          remotelyInsertedAuditIds.push(auditId);
          reservedAuditCodes.add(auditCode.toUpperCase());

          const { error: dateErr } = await supabase.from('auditoria_fecha').insert({
            id: dateId,
            id_auditoria: auditId,
            numero_secuencia: 1,
            tag: 'Programación',
            tipo_fecha: draft.dateMode,
            anio: draft.dateMode === 'PREPROGRAMADA_MES' ? draft.anio : null,
            mes: draft.dateMode === 'PREPROGRAMADA_MES' ? draft.mes : null,
            fecha_inicio: draft.dateMode === 'PROGRAMADA_EXACTA' ? exactGoalStart : null,
            fecha_fin: draft.dateMode === 'PROGRAMADA_EXACTA' ? exactGoalEnd : null,
            observacion: draft.observacion.trim() || 'Programación inicial de campaña.',
          });
          if (dateErr && !isMissingTableOrSchemaError(dateErr)) {
            await rollbackOrphanProgramAndAudits({
              programId: newProgramId,
              insertedAuditIds: remotelyInsertedAuditIds,
              reason: 'Rollback por fallo al registrar fecha inicial de auditoría hija',
              archiveRecordFn: archiveRecordForRollback,
            });
            const msg = formatZeroUuidError(
              dateErr,
              'La campaña se creó, pero falló el registro de la fecha inicial.'
            );
            state.designacionTipoDomain.editErrorMessage = msg;
            render();
            return { ok: false, error: msg };
          }
        }
      }

      if (localFallback && !auditCode) {
        auditCode = await allocateAuditCodeWithFallback({
          targetYear,
          numeroCertificado: certNumber,
          activeAudits: state.domainData.programacionAudits,
          reservedCodes: reservedAuditCodes,
        });
      }
      reservedAuditCodes.add(auditCode.toUpperCase());

      const initialDate: AuditDateEntry = {
        id: dateId,
        id_auditoria: auditId,
        numero_secuencia: 1,
        tag: 'Programación',
        tipo_fecha: draft.dateMode,
        anio: draft.dateMode === 'PREPROGRAMADA_MES' ? draft.anio : null,
        mes: draft.dateMode === 'PREPROGRAMADA_MES' ? draft.mes : null,
        fecha_inicio: draft.dateMode === 'PROGRAMADA_EXACTA' ? exactGoalStart : null,
        fecha_fin: draft.dateMode === 'PROGRAMADA_EXACTA' ? exactGoalEnd : null,
        observacion: draft.observacion.trim() || 'Programación inicial de campaña.',
        deleted_at: null,
      };
      const startIso =
        draft.dateMode === 'PROGRAMADA_EXACTA'
          ? exactGoalStart
          : `${draft.anio}-${String(draft.mes).padStart(2, '0')}-01`;
      const endIso =
        draft.dateMode === 'PROGRAMADA_EXACTA' ? exactGoalEnd : startIso;

      const versionSnapshot = resolveCertVersionSnapshotForAudit(
        {
          id_certificado: item.id_certificado,
          id_certificado_version: activeCertVersionId,
          version_numero: activeCertVersionNum,
          organizacion_nombre: item.organizacion_nombre,
          organizacion_abreviacion: resolvedOrgAbrev,
        },
        certCatalog
      );
      const hqSite = versionSnapshot.sitios.find((s) => Number(s.numero_sitio) === 0) ?? null;
      const initialSitiosPlan: AuditoriaSitioPlanItem[] = hqSite
        ? [
            {
              id: crypto.randomUUID(),
              id_auditoria: auditId,
              id_sitio: hqSite.id,
              numero_sitio: 0,
              nombre_sitio: hqSite.nombre_sitio,
              direccion_sitio: hqSite.direccion_sitio || undefined,
              modalidad_evaluacion: 'Presencial',
              tiempo_auditoria: 0,
              fecha_inicio: null,
              fecha_fin: null,
              notas_sitio: null,
              procesos: [],
              equipoSitio: [],
              deleted_at: null,
            },
          ]
        : [];

      createdAuditIds.push(auditId);
      createdAudits.push({
        id: auditId,
        id_programa_auditoria: newProgramId,
        codigo_auditoria: auditCode,
        id_certificado: item.id_certificado,
        id_certificado_version: activeCertVersionId,
        version_numero: activeCertVersionNum,
        numero_certificado: item.numero_certificado,
        id_organizacion: certObj?.id_organizacion || '',
        organizacion_nombre: item.organizacion_nombre,
        organizacion_abreviacion: resolvedOrgAbrev,
        norma_codigo: item.norma_codigo,
        sector_iaf: certObj?.sector_iaf ?? 17,
        id_tipo_auditoria: item.id_tipo_auditoria,
        tipo_auditoria: tipoObj?.tipo || 'Por definir',
        tipo_auditoria_abreviacion: tipoObj?.abreviacion ?? null,
        tipo_vinculacion: item.tipo_vinculacion,
        metodologia: 'Presencial',
        fecha_inicio: startIso,
        fecha_fin: endIso,
        fecha_reprogramacion: null,
        fechas: [initialDate],
        latestDate: initialDate,
        dias_auditor: 0,
        tiempo_auditoria: 0,
        estatus: 'Planificado',
        estado_ciclo: 'En Programación',
        tiene_sitio_temporal: Boolean(vinculo.tiene_sitio_temporal),
        objetivo: null,
        auditor_lider_id: '',
        auditor_lider: 'Por asignar',
        sede_principal_direccion: hqSite?.direccion_sitio || '',
        equipo: [],
        sitiosMuestreo: [],
        sitiosPlan: initialSitiosPlan,
        matrizNormativa: [],
        comentarios: [],
        recomendacion: null,
        deleted_at: null,
      });
    }

    if (localFallback) {
      const newProgram: ProgramaAuditoriaEntity = {
        id: newProgramId,
        id_vinculo: vinculo.id,
        id_grupo_empresarial: vinculo.id_grupo_empresarial,
        codigo_programa: codigoPrograma,
        etiqueta,
        nivel_vinculacion: effectiveNivelVinculacion,
        tipo_vinculacion: programTipoVinculacion,
        es_vinculada: effectiveEsVinculada,
        tiene_sitio_temporal: Boolean(vinculo.tiene_sitio_temporal),
        id_ciclo_origen: null,
        notas: draft.observacion.trim() || null,
        deleted_at: null,
        auditorias: createdAudits,
      };
      computeProgramPlanningStatus(newProgram);
      state.domainData.auditPrograms = [newProgram, ...state.domainData.auditPrograms];
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    state.designacionTipoDomain.selectedProgramId = newProgramId;
    state.designacionTipoDomain.editErrorMessage = null;
    const firstCreatedCertId = createdAudits[0]?.id_certificado ?? null;
    const firstCreatedAuditId = createdAudits[0]?.id ?? null;
    state.designacionTipoDomain.selectedCertId = firstCreatedCertId;
    state.designacionTipoDomain.selectedAuditId = firstCreatedAuditId;
    state.relacionDomain.selectedCertId = firstCreatedCertId;
    state.relacionDomain.selectedAuditId = firstCreatedAuditId;
    state.auditoriasSelection = {
      selectedCertId: firstCreatedCertId,
      selectedAuditId: firstCreatedAuditId,
    };
    state.activeRoute = 'auditorias';
    state.activeSubSection = 'designacion/tipo';
    const firstCertNum = createdAudits[0]?.numero_certificado || etiqueta;
    const firstCertBreadMeta = buildCertBreadcrumbMeta({
      certId: firstCreatedCertId,
      numero_certificado: firstCertNum,
      version_numero: createdAudits[0]?.version_numero,
      contextPrefix: 'Designación · Tipo',
    });
    state.breadcrumbs = pushBreadcrumb(resetBreadcrumbToDomain('auditorias', 'designacion/tipo'), {
      id: `detail-designacion/tipo-${firstCreatedCertId || newProgramId}`,
      label: firstCertBreadMeta.label,
      route: 'auditorias',
      subview: 'designacion/tipo',
      entityType: firstCreatedCertId ? 'cert' : 'programa_auditoria',
      entityId: firstCreatedCertId || newProgramId,
      tooltip: firstCertBreadMeta.tooltip,
    });
    syncUrlHash('auditorias', 'designacion/tipo');

    recordPhase5SessionLog('programa_auditoria', newProgramId, 'INSERT', null, {
      accion: 'CREAR_CICLO_STEP3',
      etiqueta,
      nivel_vinculacion: effectiveNivelVinculacion,
      tipo_vinculacion: programTipoVinculacion,
      certificados_count: createdAuditIds.length,
    });

    const firstCodename = createdAudits[0]
      ? formatAuditCodename({
          fechas: createdAudits[0].fechas,
          latestDate: createdAudits[0].latestDate,
          tipo_auditoria: createdAudits[0].tipo_auditoria,
          tipo_abreviacion: createdAudits[0].tipo_auditoria_abreviacion,
        })
      : etiqueta;
    showFloatingToast(`Ciclo creado: ${firstCodename}`, 'success');
    render();
    return {
      ok: true,
      data: { programId: newProgramId, auditIds: createdAuditIds },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo crear el ciclo de auditoría.');
    state.designacionTipoDomain.editErrorMessage = msg;
    render();
    return { ok: false, error: msg };
  }
}

export async function submitAuditWizardBatch(): Promise<
  PersistenceMutationResult<{ programId: string; auditIds: string[] }>
> {
  if (!state.auditWizard) {
    return { ok: false, error: 'El asistente de auditoría no está abierto.' };
  }
  const built = buildStep3NewCycleDraftFromWizard(
    state.auditWizard,
    state.domainData.allVinculos,
    state.domainData.allCertificadosDetailed,
    {
      conglomerados: state.domainData.allConglomerados,
      tiposCatalog: getResolvedTiposCatalog(),
    }
  );
  if (!built.ok) {
    state.auditWizard = {
      ...state.auditWizard,
      errorMessage: built.error,
      isSubmitting: false,
    };
    render();
    return { ok: false, error: built.error };
  }

  state.auditWizard = {
    ...state.auditWizard,
    isSubmitting: true,
    errorMessage: null,
  };
  render();

  const res = await createStep3CampaignCycle(built.draft);
  if (!res.ok) {
    if (state.auditWizard) {
      state.auditWizard = {
        ...state.auditWizard,
        isSubmitting: false,
        errorMessage: res.error ?? null,
      };
      render();
    }
    return res;
  }

  state.auditWizard = null;
  render();
  return res;
}

export async function updateSingleStep3AuditTipo(
  auditId: string,
  idTipoAuditoria: string
): Promise<PersistenceMutationResult<{ auditId: string }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : state.domainData.auditPrograms.flatMap((p) => p.auditorias);
    const tiposCatalog = getResolvedTiposCatalog();

    const certCatalog =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;

    const validation = validateSingleAuditTipoChange({
      auditId,
      idTipoAuditoria,
      audits: auditsPool,
      tiposCatalog,
      certificados: certCatalog,
    });
    if (!validation.valid || !validation.audit || !validation.tipo) {
      const msg = validation.error || 'Seleccione un tipo de auditoría válido.';
      state.designacionTipoDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const validAuditId = assertValidUuid(validation.audit.id, 'auditoría');
    const validTipoId = assertValidUuid(validation.tipo.id, 'tipo de auditoría');
    const tipoObj = validation.tipo;
    const prevTipoLabel = validation.audit.tipo_auditoria || null;

    state.designacionTipoDomain.savingAuditId = validAuditId;
    state.designacionTipoDomain.editErrorMessage = null;
    render();

    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { error: updErr } = await supabase
        .from('auditoria')
        .update({
          id_tipo_auditoria: validTipoId,
          updated_at: new Date().toISOString(),
        })
        .eq('id', validAuditId)
        .is('deleted_at', null);

      if (updErr) {
        if (!isMissingTableOrSchemaError(updErr)) {
          const msg = formatZeroUuidError(
            updErr,
            'No se pudo actualizar el tipo de auditoría.'
          );
          state.designacionTipoDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    if (localFallback) {
      state.domainData.auditPrograms = applySingleAuditTipoUpdateLocally(
        state.domainData.auditPrograms,
        validAuditId,
        tipoObj
      );
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    recordPhase5SessionLog(
      'auditoria',
      validAuditId,
      'UPDATE',
      prevTipoLabel ? { tipo_auditoria: prevTipoLabel } : null,
      {
        accion: 'DESIGNAR_TIPO_AUDITORIA',
        codigo_auditoria: validation.audit.codigo_auditoria,
        tipo_auditoria: tipoObj.tipo,
      }
    );
    showFloatingToast(
      `${validation.audit.codigo_auditoria}: tipo actualizado a ${tipoObj.tipo}.`,
      'success'
    );
    return { ok: true, data: { auditId: validAuditId }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar el tipo de auditoría.');
    state.designacionTipoDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.designacionTipoDomain.savingAuditId = null;
    render();
  }
}

/**
 * Step 3.2 — `1. Relación` (`#/auditorias/relacion`):
 * Actualiza `auditoria.tipo_vinculacion` para una auditoría o lote activo de campaña,
 * sincronizando `programa_auditoria` (`tipo_vinculacion` / `es_vinculada`, o `'Mixta'` si
 * coexisten naturalezas heterogéneas) sin modificar jamás `vinculo` / `vinculo_certificado` (Bloque 2).
 */
export async function updateSingleAuditRelacion(
  auditId: string,
  tipoVinculacion: string,
  options?: { applyToBatchProgram?: boolean }
): Promise<PersistenceMutationResult<{ auditId: string; updatedCount: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : state.domainData.auditPrograms.flatMap((p) => p.auditorias);
    const programsPool = state.domainData.auditPrograms;

    const validation = validateAuditRelacionUpdate({
      auditId,
      tipoVinculacion,
      audits: auditsPool,
      programs: programsPool,
      profile: state.profile,
      applyToBatchProgram: Boolean(options?.applyToBatchProgram),
    });

    if (!validation.ok) {
      state.relacionDomain.editErrorMessage = validation.error;
      showFloatingToast(validation.error, 'warning');
      render();
      return { ok: false, error: validation.error };
    }

    const validAuditId = assertValidUuid(validation.auditId, 'auditoría');
    const validTargetAuditIds = validation.targetAuditIds.map((id) =>
      assertValidUuid(id, 'auditoría')
    );
    const targetIdSet = new Set(validTargetAuditIds);
    const targetAudit = auditsPool.find((a) => a.id === validAuditId) ?? null;
    const prevNature = targetAudit?.tipo_vinculacion ?? null;
    const programId = targetAudit?.id_programa_auditoria ?? null;
    const validProgramId = programId && isValidUuid(programId) ? programId : null;

    state.relacionDomain.savingAuditId = validAuditId;
    state.relacionDomain.editErrorMessage = null;
    render();

    const computeProgramSyncMeta = (
      progId: string
    ): { tipo_vinculacion: AuditLinkNature; es_vinculada: boolean } => {
      const matchedProg = programsPool.find((p) => !p.deleted_at && p.id === progId);
      const progAudits = (
        matchedProg?.auditorias.length
          ? matchedProg.auditorias
          : auditsPool.filter((a) => a.id_programa_auditoria === progId)
      ).filter((a) => !a.deleted_at);

      const distinctNatures = new Set<AuditLinkNature>();
      for (const aud of progAudits) {
        if (targetIdSet.has(aud.id)) {
          distinctNatures.add(validation.tipoVinculacion);
        } else if (aud.tipo_vinculacion) {
          distinctNatures.add(aud.tipo_vinculacion);
        } else if (matchedProg?.tipo_vinculacion) {
          distinctNatures.add(matchedProg.tipo_vinculacion);
        } else {
          distinctNatures.add('Individual');
        }
      }

      if (distinctNatures.size === 1) {
        const onlyNature = Array.from(distinctNatures)[0];
        return {
          tipo_vinculacion: onlyNature,
          es_vinculada: onlyNature !== 'Individual' || progAudits.length > 1,
        };
      }
      return {
        tipo_vinculacion: 'Mixta',
        es_vinculada: true,
      };
    };

    const nowIso = new Date().toISOString();
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { error: updErr } = await supabase
        .from('auditoria')
        .update({
          tipo_vinculacion: validation.updatedAuditPayload.tipo_vinculacion,
          updated_at: nowIso,
        })
        .in('id', validTargetAuditIds)
        .is('deleted_at', null);

      if (updErr) {
        if (!isMissingTableOrSchemaError(updErr)) {
          const msg = formatZeroUuidError(
            updErr,
            'No se pudo actualizar la relación de auditoría.'
          );
          state.relacionDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else if (validProgramId) {
        const progSync = computeProgramSyncMeta(validProgramId);
        const { error: progErr } = await supabase
          .from('programa_auditoria')
          .update({
            tipo_vinculacion: progSync.tipo_vinculacion,
            es_vinculada: progSync.es_vinculada,
            updated_at: nowIso,
          })
          .eq('id', validProgramId)
          .is('deleted_at', null);

        if (progErr && !isMissingTableOrSchemaError(progErr)) {
          const msg = formatZeroUuidError(
            progErr,
            'Se actualizó la auditoría, pero no se pudo sincronizar la campaña.'
          );
          state.relacionDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          await loadLiveAudits();
          return { ok: false, error: msg };
        }
      }
    }

    if (localFallback) {
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((prog) => {
        const touchesProgram =
          prog.id === validProgramId ||
          prog.auditorias.some((a) => targetIdSet.has(a.id));
        if (!touchesProgram) return prog;

        const nextAudits = prog.auditorias.map((aud) =>
          targetIdSet.has(aud.id)
            ? {
                ...aud,
                tipo_vinculacion: validation.tipoVinculacion,
              }
            : aud
        );
        const distinct = new Set<AuditLinkNature>(
          nextAudits
            .filter((a) => !a.deleted_at)
            .map((a) => a.tipo_vinculacion ?? prog.tipo_vinculacion ?? 'Individual')
        );
        const nextProgNature: AuditLinkNature =
          distinct.size === 1 ? Array.from(distinct)[0] : 'Mixta';
        const nextEsVinculada =
          nextProgNature !== 'Individual' || nextAudits.filter((a) => !a.deleted_at).length > 1;

        return {
          ...prog,
          tipo_vinculacion: nextProgNature,
          es_vinculada: nextEsVinculada,
          auditorias: nextAudits,
        };
      });
      state.domainData.programacionAudits = state.domainData.programacionAudits.map((aud) =>
        targetIdSet.has(aud.id)
          ? {
              ...aud,
              tipo_vinculacion: validation.tipoVinculacion,
            }
          : aud
      );
      recomputeLocalAuditPlanningDerivedState();
    } else {
      await loadLiveAudits();
    }

    recordPhase5SessionLog(
      'auditoria',
      validAuditId,
      'UPDATE',
      prevNature ? { tipo_vinculacion: prevNature } : null,
      {
        accion: 'ACTUALIZAR_RELACION_AUDITORIA',
        codigo_auditoria: targetAudit?.codigo_auditoria || 'Auditoría',
        tipo_vinculacion: validation.tipoVinculacion,
        cantidad_auditorias: validTargetAuditIds.length,
      }
    );
    showFloatingToast(
      validTargetAuditIds.length > 1
        ? `Relación de campaña actualizada a ${validation.tipoVinculacion} (${validTargetAuditIds.length} auditorías).`
        : `${targetAudit?.codigo_auditoria || 'Auditoría'}: relación actualizada a ${validation.tipoVinculacion}.`,
      'success'
    );
    return {
      ok: true,
      data: { auditId: validAuditId, updatedCount: validTargetAuditIds.length },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar la relación de auditoría.');
    state.relacionDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.relacionDomain.savingAuditId = null;
    render();
  }
}

/**
 * Step 5.1 — `1.2 Designación → Fecha`: sincronización 1:N de fechas programadas
 * sobre todas las auditorías vinculadas del lote (`programa_auditoria`), conservando `REAL`.
 */
export async function saveLinkedBatchProgrammedDates(
  anchorAuditId: string,
  drafts: ReadonlyArray<PlannedDateRowDraft>
): Promise<PersistenceMutationResult<{ updatedAuditsCount: number; datesCount: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  const validation = validatePlannedDatesList(drafts);
  if (!validation.valid) {
    const msg = validation.error || 'Revise las fechas programadas antes de guardar.';
    state.designacionFechaDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    render();
    return { ok: false, error: msg };
  }

  try {
    const validAnchorId = assertValidUuid(anchorAuditId, 'auditoría');
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : state.domainData.auditPrograms.flatMap((p) => p.auditorias);
    const anchorAudit = auditsPool.find((a) => !a.deleted_at && a.id === validAnchorId) ?? null;
    if (!anchorAudit) {
      const msg = 'No se encontró la auditoría seleccionada para sincronizar fechas.';
      state.designacionFechaDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const linkedCtx = getLinkedSiblingAudits(
      anchorAudit,
      auditsPool,
      state.domainData.auditPrograms
    );
    const batchAudits = linkedCtx.siblings.map((s) => s.audit);
    const syncPlan = buildLinkedBatchDateSyncPlan(batchAudits, validation.normalized);

    state.designacionFechaDomain.saving = true;
    state.designacionFechaDomain.editErrorMessage = null;
    render();

    let localFallback = !(await isStep3RemoteSchemaAvailable());
    const nowIso = new Date().toISOString();

    if (!localFallback) {
      for (const op of syncPlan) {
        const validAuditId = assertValidUuid(op.auditId, 'auditoría del lote');

        // 1. Archive excess planned dates FIRST via soft-delete RPC (never .delete(), never touch REAL)
        for (const arch of op.toArchive) {
          const validDateId = assertValidUuid(arch.dateId, 'fecha programada');
          const { error: archErr } = await supabase.rpc('archive_record', {
            p_table: 'auditoria_fecha',
            p_record_id: validDateId,
            p_reason: 'Fecha programada removida desde Designación → Fecha',
          });
          if (archErr) {
            if (!isMissingTableOrSchemaError(archErr)) {
              const msg = formatZeroUuidError(
                archErr,
                'No se pudo archivar una fecha programada removida.'
              );
              state.designacionFechaDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }
        if (localFallback) break;

        // 2. Update existing planned dates in-place
        for (const upd of op.toUpdate) {
          const validDateId = assertValidUuid(upd.dateId, 'fecha programada');
          const { error: updErr } = await supabase
            .from('auditoria_fecha')
            .update({
              tag: upd.payload.tag,
              tipo_fecha: upd.payload.tipo_fecha,
              anio: upd.payload.anio,
              mes: upd.payload.mes,
              fecha_inicio: upd.payload.fecha_inicio,
              fecha_fin: upd.payload.fecha_fin,
              observacion: upd.payload.observacion,
              updated_at: nowIso,
            })
            .eq('id', validDateId)
            .is('deleted_at', null);

          if (updErr) {
            if (!isMissingTableOrSchemaError(updErr)) {
              const msg = formatZeroUuidError(
                updErr,
                'No se pudo actualizar una fecha programada del lote.'
              );
              state.designacionFechaDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }
        if (localFallback) break;

        // 3. Insert additional planned dates with collision-free sequence numbers
        for (const ins of op.toInsert) {
          const { error: insErr } = await supabase.from('auditoria_fecha').insert({
            id: crypto.randomUUID(),
            id_auditoria: validAuditId,
            numero_secuencia: ins.numero_secuencia,
            tag: ins.payload.tag,
            tipo_fecha: ins.payload.tipo_fecha,
            anio: ins.payload.anio,
            mes: ins.payload.mes,
            fecha_inicio: ins.payload.fecha_inicio,
            fecha_fin: ins.payload.fecha_fin,
            observacion: ins.payload.observacion,
          });
          if (insErr) {
            if (!isMissingTableOrSchemaError(insErr)) {
              const msg = formatZeroUuidError(
                insErr,
                'No se pudo registrar una nueva fecha programada del lote.'
              );
              state.designacionFechaDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }
        if (localFallback) break;
      }

      if (!localFallback) {
        await loadLiveAudits();
      }
    }

    if (localFallback) {
      const opByAuditId = new Map(syncPlan.map((op) => [op.auditId, op]));
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
        ...p,
        auditorias: p.auditorias.map((a) => {
          const op = opByAuditId.get(a.id);
          if (!op) return a;
          const archivedIds = new Set(op.toArchive.map((x) => x.dateId));
          const updatedById = new Map(op.toUpdate.map((x) => [x.dateId, x]));
          const remaining = (a.fechas || [])
            .filter((f) => !f.deleted_at && !archivedIds.has(f.id))
            .map((f) => {
              const upd = updatedById.get(f.id);
              if (!upd) return f;
              return {
                ...f,
                tag: upd.payload.tag,
                tipo_fecha: upd.payload.tipo_fecha,
                anio: upd.payload.anio,
                mes: upd.payload.mes,
                fecha_inicio: upd.payload.fecha_inicio,
                fecha_fin: upd.payload.fecha_fin,
                observacion: upd.payload.observacion,
              };
            });
          const inserted: AuditDateEntry[] = op.toInsert.map((ins) => ({
            id: crypto.randomUUID(),
            id_auditoria: a.id,
            numero_secuencia: ins.numero_secuencia,
            tag: ins.payload.tag,
            tipo_fecha: ins.payload.tipo_fecha,
            anio: ins.payload.anio,
            mes: ins.payload.mes,
            fecha_inicio: ins.payload.fecha_inicio,
            fecha_fin: ins.payload.fecha_fin,
            observacion: ins.payload.observacion,
            deleted_at: null,
          }));
          const nextFechas = [...remaining, ...inserted].sort(
            (x, y) => (x.numero_secuencia || 0) - (y.numero_secuencia || 0)
          );
          const nextLatest = resolveLatestAuditDate(nextFechas);
          const nextPlanned = resolveLatestPlannedDate(nextFechas);
          const nextStart = nextPlanned
            ? nextPlanned.tipo_fecha === 'PROGRAMADA_EXACTA' && nextPlanned.fecha_inicio
              ? nextPlanned.fecha_inicio
              : nextPlanned.anio && nextPlanned.mes
              ? `${nextPlanned.anio}-${String(nextPlanned.mes).padStart(2, '0')}-01`
              : a.fecha_inicio
            : a.fecha_inicio;
          const nextEnd = nextPlanned
            ? nextPlanned.tipo_fecha === 'PROGRAMADA_EXACTA' && nextPlanned.fecha_fin
              ? nextPlanned.fecha_fin
              : nextStart
            : a.fecha_fin;

          return {
            ...a,
            fechas: nextFechas,
            latestDate: nextLatest,
            fecha_inicio: nextStart,
            fecha_fin: nextEnd,
          };
        }),
      }));
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    }

    state.designacionFechaDomain.draftAuditId = null;
    state.designacionFechaDomain.drafts = null;
    state.designacionFechaDomain.editorMode = null;
    state.designacionFechaDomain.editingLocalId = null;
    state.designacionFechaDomain.editorDraft = null;
    state.designacionFechaDomain.editErrorMessage = null;

    recordPhase5SessionLog('auditoria_fecha', validAnchorId, 'UPDATE', null, {
      accion: 'SINCRONIZAR_FECHAS_LOTE',
      auditorias_actualizadas: batchAudits.length,
      fechas_activas: validation.normalized.length,
    });
    showFloatingToast(
      `Fechas programadas sincronizadas en ${batchAudits.length} auditoría(s).`,
      'success'
    );
    return {
      ok: true,
      data: {
        updatedAuditsCount: batchAudits.length,
        datesCount: validation.normalized.length,
      },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudieron sincronizar las fechas programadas.');
    state.designacionFechaDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.designacionFechaDomain.saving = false;
    render();
  }
}

/**
 * 3.4 Paso 4 (`Designación → Sitio`):
 * Selección/exclusión multi-sitio independiente por auditoría con bloqueo obligatorio de `Sitio 0 (HQ)`.
 */

export async function toggleSiteInAudit(
  auditId: string,
  siteId: string,
  sitioAuditoriaId?: string
): Promise<PersistenceMutationResult<{ auditId: string; siteId: string; active: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validAuditId = assertValidUuid(auditId, 'auditoría');
    const validSiteId = assertValidUuid(siteId, 'sitio');

    const audit =
      state.domainData.programacionAudits.find((a) => !a.deleted_at && a.id === validAuditId) ||
      state.domainData.auditPrograms
        .flatMap((p) => p.auditorias)
        .find((a) => !a.deleted_at && a.id === validAuditId) ||
      null;

    const certCatalog =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;
    const certDetail = audit
      ? certCatalog.find((c) => c.id === audit.id_certificado) ?? null
      : null;
    const versionSnapshot = audit
      ? resolveCertVersionSnapshotForAudit(audit, certCatalog)
      : null;
    const certificateSites =
      versionSnapshot &&
      (versionSnapshot.sitios.length > 0 || Boolean(audit?.id_certificado_version))
        ? versionSnapshot.sitios
        : certDetail?.sitios || [];

    const validation = validateAuditSiteToggle({
      audit,
      siteId: validSiteId,
      certificateSites,
      isStaff: isApprovedStaff(),
    });

    if (!validation.valid) {
      const msg = validation.error || 'No se pudo modificar el sitio seleccionado.';
      state.designacionSitioDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const activePlan = (audit?.sitiosPlan || []).filter((sp) => !sp.deleted_at);
    const toggleKey = `${validAuditId}:${validSiteId}`;

    state.designacionSitioDomain.savingSiteToggleKey = toggleKey;
    state.designacionSitioDomain.editErrorMessage = null;
    render();

    if (validation.action === 'REMOVE') {
      const targetSaId = validation.sitioAuditoriaId || sitioAuditoriaId;
      if (!targetSaId) {
        const msg = 'No se encontró la asignación del sitio para remover.';
        state.designacionSitioDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }

      const archiveRes = await runWithPlannerPreservedViewport(() =>
        archiveSitioAuditoria(targetSaId, 'Sitio removido en Designación → Sitio')
      );
      if (!archiveRes.ok) {
        state.designacionSitioDomain.editErrorMessage =
          archiveRes.error || 'No se pudo remover el sitio seleccionado.';
        return {
          ok: false,
          error: state.designacionSitioDomain.editErrorMessage,
          dependencySummary: archiveRes.dependencySummary,
        };
      }

      return {
        ok: true,
        data: { auditId: validAuditId, siteId: validSiteId, active: false },
        localFallback: archiveRes.localFallback,
      };
    }

    // Align with DB trigger `trg_auto_asignar_sitio_principal_auditoria`:
    // ensure Sitio 0 (HQ) exists in plan before adding a secondary site.
    const hqSite = certificateSites.find((s) => Number(s.numero_sitio) === 0);
    if (
      hqSite &&
      hqSite.id !== validSiteId &&
      !activePlan.some((sp) => sp.id_sitio === hqSite.id || Number(sp.numero_sitio) === 0)
    ) {
      await upsertSitioAuditoria(validAuditId, hqSite.id, 0, 'Presencial');
    }

    const upsertRes = await runWithPlannerPreservedViewport(() =>
      upsertSitioAuditoria(validAuditId, validSiteId, 0, 'Presencial')
    );
    if (!upsertRes.ok) {
      state.designacionSitioDomain.editErrorMessage =
        upsertRes.error || 'No se pudo asignar el sitio seleccionado.';
      return {
        ok: false,
        error: state.designacionSitioDomain.editErrorMessage,
      };
    }

    return {
      ok: true,
      data: { auditId: validAuditId, siteId: validSiteId, active: true },
      restored: upsertRes.restored,
      localFallback: upsertRes.localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar la selección de sitio.');
    state.designacionSitioDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.designacionSitioDomain.savingSiteToggleKey = null;
    render();
  }
}

/**
 * 3d. Step 5.1 — `1.4 Designación → Temporal`: Switch maestro ON/OFF y guardado sincronizado del lote
 */
async function isStep5RemoteSchemaAvailable(): Promise<boolean> {
  const [tempCheck, linkCheck] = await Promise.all([
    supabase.from('auditoria_sitio_temporal').select('id').limit(1),
    supabase.from('auditoria_sitio_temporal_certificado').select('id').limit(1),
  ]);
  return !isMissingTableOrSchemaError(tempCheck.error) && !isMissingTableOrSchemaError(linkCheck.error);
}

export async function toggleBatchTemporalSwitch(
  anchorAuditId: string,
  nextEnabled: boolean,
  confirmed = false
): Promise<PersistenceMutationResult<{ enabled: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validAnchorId = assertValidUuid(anchorAuditId, 'auditoría');
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : state.domainData.auditPrograms.flatMap((p) => p.auditorias);
    const activeAudit = auditsPool.find((a) => !a.deleted_at && a.id === validAnchorId) ?? null;
    if (!activeAudit) {
      const msg = 'No se encontró la auditoría activa del lote.';
      state.designacionTemporalDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const resolution = resolveLinkedBatchTemporalState(
      activeAudit,
      auditsPool,
      state.domainData.auditPrograms,
      state.domainData.allTemporalSites
    );

    if (!nextEnabled && resolution.requiresDisableConfirmation && !confirmed) {
      state.designacionTemporalDomain.confirmDisableBatch = true;
      state.designacionTemporalDomain.editErrorMessage = null;
      render();
      return { ok: true, data: { enabled: true } };
    }

    state.designacionTemporalDomain.saving = true;
    state.designacionTemporalDomain.editErrorMessage = null;
    render();

    const batchAudits = resolution.batchAudits;
    const batchAuditIds = batchAudits.map((a) => assertValidUuid(a.id, 'auditoría del lote'));
    const programId = activeAudit.id_programa_auditoria || null;
    let localFallback = !(await isStep5RemoteSchemaAvailable());
    const nowIso = new Date().toISOString();

    if (!localFallback) {
      if (!nextEnabled && resolution.activeTemporalSites.length > 0) {
        const reason = 'Sitio Temporal desactivado (OFF) para el lote vinculado';
        for (const site of resolution.activeTemporalSites) {
          const validSiteId = assertValidUuid(site.id, 'sitio temporal');

          // Archive equipo_auditor_sitio_temporal children first
          const { data: teamRows, error: teamFetchErr } = await supabase
            .from('equipo_auditor_sitio_temporal')
            .select('id')
            .eq('id_sitio_temporal', validSiteId)
            .is('deleted_at', null);
          if (teamFetchErr && !isMissingTableOrSchemaError(teamFetchErr)) {
            const msg = formatZeroUuidError(
              teamFetchErr,
              'No se pudo consultar el equipo temporal antes de desactivar.'
            );
            state.designacionTemporalDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            return { ok: false, error: msg };
          }
          for (const tr of (teamRows as Array<Record<string, unknown>> | null) || []) {
            const trId = String(tr.id || '');
            if (!trId) continue;
            const { error: teamArchErr } = await supabase.rpc('archive_record', {
              p_table: 'equipo_auditor_sitio_temporal',
              p_record_id: trId,
              p_reason: reason,
            });
            if (teamArchErr) {
              const msg = formatZeroUuidError(
                teamArchErr,
                'No se pudo archivar la asignación temporal antes de pasar a OFF.'
              );
              state.designacionTemporalDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
          }

          // Archive M:N certificate links
          const { data: linkRows, error: linkFetchErr } = await supabase
            .from('auditoria_sitio_temporal_certificado')
            .select('id')
            .eq('id_sitio_temporal', validSiteId)
            .is('deleted_at', null);
          if (linkFetchErr && !isMissingTableOrSchemaError(linkFetchErr)) {
            const msg = formatZeroUuidError(
              linkFetchErr,
              'No se pudieron consultar los certificados del sitio temporal.'
            );
            state.designacionTemporalDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            return { ok: false, error: msg };
          }
          for (const lr of (linkRows as Array<Record<string, unknown>> | null) || []) {
            const lrId = String(lr.id || '');
            if (!lrId) continue;
            const { error: linkArchErr } = await supabase.rpc('archive_record', {
              p_table: 'auditoria_sitio_temporal_certificado',
              p_record_id: lrId,
              p_reason: reason,
            });
            if (linkArchErr) {
              const msg = formatZeroUuidError(
                linkArchErr,
                'No se pudo archivar el vínculo del sitio temporal.'
              );
              state.designacionTemporalDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
          }

          // Archive temporal site record
          const { error: siteArchErr } = await supabase.rpc('archive_record', {
            p_table: 'auditoria_sitio_temporal',
            p_record_id: validSiteId,
            p_reason: reason,
          });
          if (siteArchErr) {
            if (!isMissingTableOrSchemaError(siteArchErr)) {
              const msg = formatZeroUuidError(
                siteArchErr,
                'No se pudo archivar el sitio temporal.'
              );
              state.designacionTemporalDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }
      }

      if (!localFallback && programId && isValidUuid(programId)) {
        const { error: progErr } = await supabase
          .from('programa_auditoria')
          .update({ tiene_sitio_temporal: nextEnabled, updated_at: nowIso })
          .eq('id', programId)
          .is('deleted_at', null);
        if (progErr && !isMissingTableOrSchemaError(progErr)) {
          const msg = formatZeroUuidError(
            progErr,
            'No se pudo actualizar el indicador temporal del lote.'
          );
          state.designacionTemporalDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 5500);
          return { ok: false, error: msg };
        }
      }

      if (!localFallback) {
        for (const audId of batchAuditIds) {
          const { error: audErr } = await supabase
            .from('auditoria')
            .update({ tiene_sitio_temporal: nextEnabled, updated_at: nowIso })
            .eq('id', audId)
            .is('deleted_at', null);
          if (audErr) {
            if (!isMissingTableOrSchemaError(audErr)) {
              const msg = formatZeroUuidError(
                audErr,
                'No se pudo actualizar el indicador de sitio temporal en el lote.'
              );
              state.designacionTemporalDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }
      }

      if (!localFallback) {
        await loadLiveAudits();
      }
    }

    if (localFallback) {
      const batchAuditSet = new Set(batchAuditIds);
      const removedSiteIds = new Set(
        nextEnabled ? [] : resolution.activeTemporalSites.map((s) => s.id)
      );
      if (removedSiteIds.size > 0) {
        state.domainData.allTemporalSites = state.domainData.allTemporalSites.filter(
          (t) => !removedSiteIds.has(t.id)
        );
      }
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => {
        const isTargetProg = programId ? p.id === programId : p.auditorias.some((a) => batchAuditSet.has(a.id));
        return {
          ...p,
          tiene_sitio_temporal: isTargetProg ? nextEnabled : p.tiene_sitio_temporal,
          auditorias: p.auditorias.map((a) =>
            batchAuditSet.has(a.id) ? { ...a, tiene_sitio_temporal: nextEnabled } : a
          ),
        };
      });
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    }

    state.designacionTemporalDomain.confirmDisableBatch = false;
    state.designacionTemporalDomain.draftAuditId = null;
    state.designacionTemporalDomain.batchDraft = null;
    state.designacionTemporalDomain.editErrorMessage = null;

    recordPhase5SessionLog('auditoria', validAnchorId, 'UPDATE', null, {
      accion: nextEnabled ? 'ACTIVAR_TEMPORAL_LOTE_ON' : 'DESACTIVAR_TEMPORAL_LOTE_OFF',
      auditorias_count: batchAuditIds.length,
    });
    showFloatingToast(
      nextEnabled
        ? `Sitio Temporal activado (ON) en ${batchAuditIds.length} auditoría(s). Complete los campos requeridos.`
        : `Sitio Temporal desactivado (OFF) en ${batchAuditIds.length} auditoría(s).`,
      'success'
    );
    return { ok: true, data: { enabled: nextEnabled }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo cambiar el estado del Sitio Temporal.');
    state.designacionTemporalDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.designacionTemporalDomain.saving = false;
    render();
  }
}

export async function saveBatchTemporalSite(
  anchorAuditId: string,
  draft: BatchTemporalFormDraft
): Promise<PersistenceMutationResult<{ syncedAuditsCount: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  const validationErr = validateBatchTemporalDraft(draft);
  if (validationErr) {
    state.designacionTemporalDomain.editErrorMessage = validationErr;
    showFloatingToast(validationErr, 'warning');
    render();
    return { ok: false, error: validationErr };
  }

  try {
    const validAnchorId = assertValidUuid(anchorAuditId, 'auditoría');
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }
    const auditsPool =
      state.domainData.programacionAudits.length > 0
        ? state.domainData.programacionAudits
        : state.domainData.auditPrograms.flatMap((p) => p.auditorias);
    const activeAudit = auditsPool.find((a) => !a.deleted_at && a.id === validAnchorId) ?? null;
    if (!activeAudit) {
      const msg = 'No se encontró la auditoría activa del lote.';
      state.designacionTemporalDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const resolution = resolveLinkedBatchTemporalState(
      activeAudit,
      auditsPool,
      state.domainData.auditPrograms,
      state.domainData.allTemporalSites
    );
    const batchAudits = resolution.batchAudits;
    const batchAuditIds = batchAudits.map((a) => assertValidUuid(a.id, 'auditoría del lote'));
    const programId = activeAudit.id_programa_auditoria || null;
    const normalizedLabel = normalizeTemporalSiteLabel(draft.etiqueta);
    const normalizedComment = formatTemporalSiteComment({
      ubicacion: draft.ubicacion,
      fecha_tentativa: draft.fecha_tentativa,
      notas: draft.notas,
    });
    const roundedDays = roundAuditDaysQuarter(draft.tiempo_auditoria);
    const nowIso = new Date().toISOString();

    state.designacionTemporalDomain.saving = true;
    state.designacionTemporalDomain.editErrorMessage = null;
    render();

    let localFallback = !(await isStep5RemoteSchemaAvailable());

    if (!localFallback) {
      if (programId && isValidUuid(programId)) {
        await supabase
          .from('programa_auditoria')
          .update({ tiene_sitio_temporal: true, updated_at: nowIso })
          .eq('id', programId)
          .is('deleted_at', null);
      }

      for (const batchAudit of batchAudits) {
        const validAuditId = assertValidUuid(batchAudit.id, 'auditoría del lote');
        const { error: audErr } = await supabase
          .from('auditoria')
          .update({ tiene_sitio_temporal: true, updated_at: nowIso })
          .eq('id', validAuditId)
          .is('deleted_at', null);

        if (audErr) {
          if (!isMissingTableOrSchemaError(audErr)) {
            const msg = formatZeroUuidError(
              audErr,
              'No se pudo habilitar el indicador temporal en el lote.'
            );
            state.designacionTemporalDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            return { ok: false, error: msg };
          }
          localFallback = true;
          break;
        }

        const existingForAudit = state.domainData.allTemporalSites.find(
          (t) => !t.deleted_at && t.id_auditoria === validAuditId
        );
        const siteId = existingForAudit?.id || crypto.randomUUID();

        if (existingForAudit) {
          const { error: updErr } = await supabase
            .from('auditoria_sitio_temporal')
            .update({
              etiqueta: normalizedLabel,
              comentario: normalizedComment,
              tiempo_auditoria: roundedDays,
              updated_at: nowIso,
            })
            .eq('id', siteId)
            .is('deleted_at', null);
          if (updErr) {
            const msg = formatZeroUuidError(
              updErr,
              'No se pudo actualizar el sitio temporal en una auditoría del lote.'
            );
            state.designacionTemporalDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning', 5500);
            return { ok: false, error: msg };
          }
        } else {
          const { error: insErr } = await supabase.from('auditoria_sitio_temporal').insert({
            id: siteId,
            id_auditoria: validAuditId,
            etiqueta: normalizedLabel,
            comentario: normalizedComment,
            tiempo_auditoria: roundedDays,
          });
          if (insErr) {
            if (!isMissingTableOrSchemaError(insErr)) {
              const msg = formatZeroUuidError(
                insErr,
                'No se pudo registrar el sitio temporal para el lote.'
              );
              state.designacionTemporalDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning', 5500);
              return { ok: false, error: msg };
            }
            localFallback = true;
            break;
          }
        }

        // Ensure M:N link row exists for this audit
        const { data: linkRows } = await supabase
          .from('auditoria_sitio_temporal_certificado')
          .select('id')
          .eq('id_sitio_temporal', siteId)
          .eq('id_auditoria_certificado', validAuditId)
          .is('deleted_at', null);

        if (!Array.isArray(linkRows) || linkRows.length === 0) {
          await supabase.from('auditoria_sitio_temporal_certificado').insert({
            id: crypto.randomUUID(),
            id_sitio_temporal: siteId,
            id_auditoria_certificado: validAuditId,
          });
        }
      }

      if (!localFallback) {
        await loadLiveAudits();
      }
    }

    if (localFallback) {
      const batchAuditSet = new Set(batchAuditIds);
      const nextTemporalSites = state.domainData.allTemporalSites.filter(
        (t) => !(!t.deleted_at && batchAuditSet.has(t.id_auditoria))
      );

      for (const batchAudit of batchAudits) {
        const existingForAudit = state.domainData.allTemporalSites.find(
          (t) => !t.deleted_at && t.id_auditoria === batchAudit.id
        );
        const siteId = existingForAudit?.id || crypto.randomUUID();
        const certLinks: TemporalSiteCertLink[] = [
          {
            id: existingForAudit?.certificados[0]?.id || crypto.randomUUID(),
            id_sitio_temporal: siteId,
            id_auditoria_certificado: batchAudit.id,
            numero_certificado: batchAudit.numero_certificado,
            organizacion_nombre: batchAudit.organizacion_nombre,
            norma_codigo: batchAudit.norma_codigo,
            deleted_at: null,
          },
        ];
        nextTemporalSites.push({
          id: siteId,
          id_auditoria: batchAudit.id,
          etiqueta: normalizedLabel,
          comentario: normalizedComment,
          tiempo_auditoria: roundedDays,
          certificados: certLinks,
          equipoTemporal: existingForAudit?.equipoTemporal || [],
          deleted_at: null,
        });
      }

      state.domainData.allTemporalSites = nextTemporalSites;
      state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => {
        const isTargetProg = programId ? p.id === programId : p.auditorias.some((a) => batchAuditSet.has(a.id));
        return {
          ...p,
          tiene_sitio_temporal: isTargetProg ? true : p.tiene_sitio_temporal,
          auditorias: p.auditorias.map((a) =>
            batchAuditSet.has(a.id) ? { ...a, tiene_sitio_temporal: true } : a
          ),
        };
      });
      state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
        (p) => p.auditorias
      );
      recomputeLocalAuditPlanningDerivedState();
    }

    state.designacionTemporalDomain.confirmDisableBatch = false;
    state.designacionTemporalDomain.draftAuditId = null;
    state.designacionTemporalDomain.batchDraft = null;
    state.designacionTemporalDomain.editErrorMessage = null;

    recordPhase5SessionLog('auditoria_sitio_temporal', validAnchorId, 'UPDATE', null, {
      accion: 'GUARDAR_SITIO_TEMPORAL_LOTE',
      etiqueta: normalizedLabel,
      tiempo_auditoria: roundedDays,
      auditorias_count: batchAudits.length,
    });
    showFloatingToast(
      `Sitio Temporal «${normalizedLabel}» (${roundedDays.toFixed(2)} d) sincronizado en ${batchAudits.length} auditoría(s).`,
      'success'
    );
    return { ok: true, data: { syncedAuditsCount: batchAudits.length }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar el Sitio Temporal del lote.');
    state.designacionTemporalDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.designacionTemporalDomain.saving = false;
    render();
  }
}

/**
 * 3e. Step 6.2 — `Tiempo`: Persistencia de días-auditor (`0.25d`) y modalidad por sitio
 */
function findSitePlanLocation(
  sitePlanId: string,
  auditIdHint?: string
): { auditId: string; sitePlan: AuditoriaSitioPlanItem } | null {
  const pool =
    state.domainData.auditPrograms.length > 0
      ? state.domainData.auditPrograms
      : buildSeededProgramsFallback();
  for (const program of pool) {
    for (const audit of program.auditorias) {
      if (auditIdHint && audit.id !== auditIdHint) continue;
      const found = (audit.sitiosPlan || []).find(
        (sp) => !sp.deleted_at && sp.id === sitePlanId
      );
      if (found) return { auditId: audit.id, sitePlan: found };
    }
  }
  for (const audit of state.domainData.programacionAudits) {
    if (auditIdHint && audit.id !== auditIdHint) continue;
    const found = (audit.sitiosPlan || []).find(
      (sp) => !sp.deleted_at && sp.id === sitePlanId
    );
    if (found) return { auditId: audit.id, sitePlan: found };
  }
  return null;
}

export async function saveSiteAuditTime(
  sitePlanId: string,
  nextDays: number,
  auditIdHint?: string,
  siteNameHint?: string
): Promise<PersistenceMutationResult<{ sitePlanId: string; tiempo_auditoria: number; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validSaId = assertValidUuid(sitePlanId, 'sitio de auditoría');
    if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
      state.domainData.auditPrograms = buildSeededProgramsFallback();
    }
    const loc = findSitePlanLocation(validSaId, auditIdHint);
    const siteName = loc?.sitePlan.nombre_sitio || siteNameHint || 'Sitio';
    const validationErr = validatePositiveSiteTimeUpdate(nextDays, siteName);
    if (validationErr) {
      state.tiempoDomain.editErrorMessage = validationErr;
      showFloatingToast(validationErr, 'warning');
      render();
      return { ok: false, error: validationErr };
    }

    const normalizedDays = roundAuditDaysQuarter(nextDays);
    const resolvedAuditId =
      loc?.auditId || auditIdHint || (await resolveAuditIdForSitioAuditoria(validSaId));

    state.tiempoDomain.savingSitePlanId = validSaId;
    state.tiempoDomain.editErrorMessage = null;
    render();

    let localFallback = !(await isStep3RemoteSchemaAvailable());
    if (!localFallback) {
      const { error: updErr } = await supabase
        .from('sitios_por_auditoria')
        .update({ tiempo_auditoria: normalizedDays })
        .eq('id', validSaId)
        .is('deleted_at', null);

      if (updErr) {
        if (!isMissingTableOrSchemaError(updErr)) {
          const msg = formatZeroUuidError(
            updErr,
            `No se pudo actualizar el tiempo de "${siteName}".`
          );
          state.tiempoDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    if (localFallback && resolvedAuditId) {
      mutateLocalAuditSitiosPlan(resolvedAuditId, (audit) =>
        (audit.sitiosPlan || []).map((sp) =>
          sp.id === validSaId ? { ...sp, tiempo_auditoria: normalizedDays } : sp
        )
      );
    }

    const totalAuditDays = resolvedAuditId
      ? await recalculateAndPersistAuditTotalDays(resolvedAuditId, localFallback)
      : normalizedDays;

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }

    const nextDrafts = { ...state.tiempoDomain.draftTimeBySitePlanId };
    delete nextDrafts[validSaId];
    state.tiempoDomain.draftTimeBySitePlanId = nextDrafts;
    state.tiempoDomain.editErrorMessage = null;

    recordPhase5SessionLog('sitios_por_auditoria', validSaId, 'UPDATE', null, {
      accion: 'ACTUALIZAR_TIEMPO_SITIO',
      sitio: siteName,
      tiempo_auditoria: normalizedDays,
      total_auditoria_dias: totalAuditDays,
    });

    showFloatingToast(
      `Tiempo de "${siteName}" actualizado a ${normalizedDays.toFixed(2)} d.`,
      'success'
    );
    return {
      ok: true,
      data: { sitePlanId: validSaId, tiempo_auditoria: normalizedDays, totalAuditDays },
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar el tiempo del sitio.');
    state.tiempoDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  } finally {
    state.tiempoDomain.savingSitePlanId = null;
    render();
  }
}

