/**
 * 4. Mutaciones Granulares Paso 2 (`Sitios → Procesos → Turnos → Auditores + Días`)
 */
function mutateLocalAuditSitiosPlan(
  auditId: string,
  mutator: (audit: ProgramacionAuditEntity) => AuditoriaSitioPlanItem[]
): void {
  if (state.domainData.auditPrograms.length === 0) {
    state.domainData.auditPrograms = buildSeededProgramsFallback();
  }
  const updateAudit = (a: ProgramacionAuditEntity): ProgramacionAuditEntity => {
    if (a.id !== auditId) return a;
    const nextPlan = mutator(a);
    const totalDays = computeAuditTotalDaysFromActiveSites(nextPlan);
    return {
      ...a,
      sitiosPlan: nextPlan,
      tiempo_auditoria: totalDays,
      dias_auditor: totalDays,
    };
  };
  state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
    ...p,
    auditorias: p.auditorias.map(updateAudit),
  }));
  state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
    (p) => p.auditorias
  );
}
async function recalculateAndPersistAuditTotalDays(
  auditId: string,
  localFallbackMode = false
): Promise<number> {
  const validAuditId = assertValidUuid(auditId, 'auditoría');
  if (!localFallbackMode) {
    const { data: siteRows, error: fetchErr } = await supabase
      .from('sitios_por_auditoria')
      .select('tiempo_auditoria, deleted_at')
      .eq('id_auditoria', validAuditId)
      .is('deleted_at', null);

    if (!fetchErr && Array.isArray(siteRows)) {
      const totalDays = computeAuditTotalDaysFromActiveSites(
        siteRows.map((r: Record<string, unknown>) => ({
          tiempo_auditoria: Number(r.tiempo_auditoria ?? 0),
          deleted_at: null,
        }))
      );
      await supabase
        .from('auditoria')
        .update({
          tiempo_auditoria: totalDays,
          updated_at: new Date().toISOString(),
        })
        .eq('id', validAuditId)
        .is('deleted_at', null);
      return totalDays;
    }
  }

  const localAudit = state.domainData.programacionAudits.find((a) => a.id === validAuditId);
  const totalDays = computeAuditTotalDaysFromActiveSites(localAudit?.sitiosPlan || []);
  state.domainData.auditPrograms = state.domainData.auditPrograms.map((p) => ({
    ...p,
    auditorias: p.auditorias.map((a) =>
      a.id === validAuditId
        ? { ...a, tiempo_auditoria: totalDays, dias_auditor: totalDays }
        : a
    ),
  }));
  state.domainData.programacionAudits = state.domainData.auditPrograms.flatMap(
    (p) => p.auditorias
  );
  return totalDays;
}

async function resolveAuditIdForSitioAuditoria(sitioAuditoriaId: string): Promise<string | null> {
  const validSaId = assertValidUuid(sitioAuditoriaId, 'sitio de auditoría');
  const { data, error } = await supabase
    .from('sitios_por_auditoria')
    .select('id_auditoria')
    .eq('id', validSaId)
    .maybeSingle();

  if (!error && data?.id_auditoria && isValidUuid(data.id_auditoria)) {
    return String(data.id_auditoria);
  }
  for (const audit of state.domainData.programacionAudits) {
    if ((audit.sitiosPlan || []).some((sp) => sp.id === validSaId)) {
      return audit.id;
    }
  }
  return null;
}

async function resolveAuditIdForProcesoSitioAuditoria(
  procesoSitioAuditoriaId: string
): Promise<string | null> {
  const validPsaId = assertValidUuid(procesoSitioAuditoriaId, 'proceso en sitio de auditoría');
  const { data, error } = await supabase
    .from('procesos_sitio_auditoria')
    .select('id_sitios_por_auditoria')
    .eq('id', validPsaId)
    .maybeSingle();

  if (!error && data?.id_sitios_por_auditoria && isValidUuid(data.id_sitios_por_auditoria)) {
    return resolveAuditIdForSitioAuditoria(String(data.id_sitios_por_auditoria));
  }
  for (const audit of state.domainData.programacionAudits) {
    for (const sp of audit.sitiosPlan || []) {
      if ((sp.procesos || []).some((pp) => pp.id === validPsaId)) {
        return audit.id;
      }
    }
  }
  return null;
}

async function syncEquipoAuditorCoherence(auditId: string): Promise<void> {
  const validAuditId = assertValidUuid(auditId, 'auditoría');

  const { data: activeSites, error: sitesErr } = await supabase
    .from('sitios_por_auditoria')
    .select('id')
    .eq('id_auditoria', validAuditId)
    .is('deleted_at', null);

  if (sitesErr || !Array.isArray(activeSites)) return;

  const activeSitePlanIds = activeSites
    .map((r: Record<string, unknown>) => String(r.id || ''))
    .filter((id) => isValidUuid(id));

  let siteAssignments: Array<{ id_auditor: string; rol_auditor: AuditorSiteRole }> = [];
  let processAssignments: Array<{ id_auditor: string; rol_en_proceso: AuditorProcessRole }> = [];

  if (activeSitePlanIds.length > 0) {
    const [siteEqRes, procPlanRes] = await Promise.all([
      supabase
        .from('equipo_auditor_sitio')
        .select('id_auditor, rol_auditor')
        .in('id_sitios_por_auditoria', activeSitePlanIds)
        .is('deleted_at', null),
      supabase
        .from('procesos_sitio_auditoria')
        .select('id')
        .in('id_sitios_por_auditoria', activeSitePlanIds)
        .is('deleted_at', null),
    ]);

    if (!siteEqRes.error && Array.isArray(siteEqRes.data)) {
      siteAssignments = (siteEqRes.data as Array<Record<string, unknown>>).map((r) => ({
        id_auditor: String(r.id_auditor || ''),
        rol_auditor: String(r.rol_auditor || 'AUDITOR') as AuditorSiteRole,
      }));
    }

    const activeProcPlanIds =
      !procPlanRes.error && Array.isArray(procPlanRes.data)
        ? (procPlanRes.data as Array<Record<string, unknown>>)
            .map((r) => String(r.id || ''))
            .filter((id) => isValidUuid(id))
        : [];

    if (activeProcPlanIds.length > 0) {
      const { data: procEqData, error: procEqErr } = await supabase
        .from('equipo_auditor_proceso_sitio')
        .select('id_auditor, rol_en_proceso')
        .in('id_procesos_sitio_auditoria', activeProcPlanIds)
        .is('deleted_at', null);

      if (!procEqErr && Array.isArray(procEqData)) {
        processAssignments = (procEqData as Array<Record<string, unknown>>).map((r) => ({
          id_auditor: String(r.id_auditor || ''),
          rol_en_proceso: String(r.rol_en_proceso || 'EVALUADOR') as AuditorProcessRole,
        }));
      }
    }
  }

  // Include temporal site team assignments linked directly or via M:N certificates (Step 7.1/7.2)
  const [anchorTempRes, linkTempRes] = await Promise.all([
    supabase
      .from('auditoria_sitio_temporal')
      .select('id')
      .eq('id_auditoria', validAuditId)
      .is('deleted_at', null),
    supabase
      .from('auditoria_sitio_temporal_certificado')
      .select('id_sitio_temporal')
      .eq('id_auditoria_certificado', validAuditId)
      .is('deleted_at', null),
  ]);
  const relevantTemporalIds = Array.from(
    new Set(
      [
        ...(Array.isArray(anchorTempRes.data)
          ? (anchorTempRes.data as Array<Record<string, unknown>>).map((r) => String(r.id || ''))
          : []),
        ...(Array.isArray(linkTempRes.data)
          ? (linkTempRes.data as Array<Record<string, unknown>>).map((r) =>
              String(r.id_sitio_temporal || '')
            )
          : []),
      ].filter((id) => isValidUuid(id))
    )
  );
  if (relevantTemporalIds.length > 0) {
    const { data: tempEqData, error: tempEqErr } = await supabase
      .from('equipo_auditor_sitio_temporal')
      .select('id_auditor, rol_auditor')
      .in('id_sitio_temporal', relevantTemporalIds)
      .is('deleted_at', null);
    if (!tempEqErr && Array.isArray(tempEqData)) {
      for (const r of tempEqData as Array<Record<string, unknown>>) {
        siteAssignments.push({
          id_auditor: String(r.id_auditor || ''),
          rol_auditor: String(r.rol_auditor || 'AUDITOR') as AuditorSiteRole,
        });
      }
    }
  }

  const desiredRoles = deriveConsolidatedEquipoAuditorRoles(siteAssignments, processAssignments);

  const { data: currentEquipoRows, error: currentEqErr } = await supabase
    .from('equipo_auditor')
    .select('id_auditor, rol_auditor')
    .eq('id_auditoria', validAuditId);

  if (currentEqErr || !Array.isArray(currentEquipoRows)) return;

  const currentMap = new Map<string, string>();
  for (const row of currentEquipoRows as Array<Record<string, unknown>>) {
    const aid = String(row.id_auditor || '');
    if (isValidUuid(aid)) {
      currentMap.set(aid, String(row.rol_auditor || 'AUDITOR'));
    }
  }

  for (const [auditorId, desiredRole] of desiredRoles.entries()) {
    const existingRole = currentMap.get(auditorId);
    if (!existingRole) {
      await supabase.from('equipo_auditor').insert({
        id_auditoria: validAuditId,
        id_auditor: auditorId,
        rol_auditor: desiredRole,
      });
    } else if (existingRole !== desiredRole) {
      await supabase
        .from('equipo_auditor')
        .update({ rol_auditor: desiredRole })
        .eq('id_auditoria', validAuditId)
        .eq('id_auditor', auditorId);
    }
  }

  for (const existingAuditorId of currentMap.keys()) {
    if (!desiredRoles.has(existingAuditorId)) {
      await supabase
        .from('equipo_auditor')
        .delete()
        .eq('id_auditoria', validAuditId)
        .eq('id_auditor', existingAuditorId);
    }
  }
}

export async function upsertSitioAuditoria(
  auditId: string,
  sitioId: string,
  tiempoDias: number,
  modalidad: SiteEvaluationModality | null = 'Presencial',
  options: UpsertSitioAuditoriaOptions = {}
): Promise<PersistenceMutationResult<{ id: string; restored: boolean; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const built = validateAndBuildSitioAuditoriaPayload(
      auditId,
      sitioId,
      tiempoDias,
      modalidad,
      options
    );
    if (!built.ok) {
      showFloatingToast(built.error, 'warning');
      return { ok: false, error: built.error };
    }

    const payload = built.value;
    let savedId: string = crypto.randomUUID();
    let restored = false;
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { data: existingRows, error: lookupErr } = await supabase
        .from('sitios_por_auditoria')
        .select('id, deleted_at')
        .eq('id_auditoria', payload.id_auditoria)
        .eq('id_sitio', payload.id_sitio)
        .order('created_at', { ascending: false })
        .limit(1);

      if (lookupErr) {
        if (!isMissingTableOrSchemaError(lookupErr)) {
          const msg = formatZeroUuidError(
            lookupErr,
            'No se pudo consultar la asignación del sitio en la auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else {
      const existing = Array.isArray(existingRows)
        ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
        : undefined;

      if (existing?.id) {
        const validExistingId = assertValidUuid(existing.id, 'sitio de auditoría');
        const updateBody: Record<string, unknown> = {
          tiempo_auditoria: payload.tiempo_auditoria,
          modalidad_evaluacion: payload.modalidad_evaluacion,
          fecha_inicio: payload.fecha_inicio,
          fecha_fin: payload.fecha_fin,
          notas_sitio: payload.notas_sitio,
        };
        if (existing.deleted_at) {
          updateBody.deleted_at = null;
          updateBody.deleted_by = null;
          restored = true;
        }

        const { data: updatedRow, error: updErr } = await supabase
          .from('sitios_por_auditoria')
          .update(updateBody)
          .eq('id', validExistingId)
          .select('id')
          .single();

        if (!updErr && updatedRow?.id) {
          savedId = String(updatedRow.id);
        } else if (existing.deleted_at) {
          // WORKER fallback if archived row was matched
          const { data: insertedRow, error: insErr } = await supabase
            .from('sitios_por_auditoria')
            .insert({ id: savedId, ...payload })
            .select('id')
            .single();
          if (insErr) {
            const msg = formatZeroUuidError(insErr, 'No se pudo asignar el sitio a la auditoría.');
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          savedId = String(insertedRow.id);
          restored = false;
        } else {
          const msg = formatZeroUuidError(updErr, 'No se pudo actualizar el sitio de auditoría.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
      } else {
        const { data: insertedRow, error: insErr } = await supabase
          .from('sitios_por_auditoria')
          .insert({ id: savedId, ...payload })
          .select('id')
          .single();

        if (insErr) {
          if (!isMissingTableOrSchemaError(insErr)) {
            const msg = formatZeroUuidError(
              insErr,
              'No se pudo asignar el sitio a la auditoría.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        } else if (insertedRow?.id) {
          savedId = String(insertedRow.id);
        }
      }
      }
    }

    if (localFallback) {
      mutateLocalAuditSitiosPlan(payload.id_auditoria, (audit) => {
        const current = [...(audit.sitiosPlan || [])];
        const idx = current.findIndex((sp) => sp.id_sitio === payload.id_sitio);
        if (idx >= 0) {
          savedId = current[idx].id;
          current[idx] = {
            ...current[idx],
            tiempo_auditoria: payload.tiempo_auditoria,
            modalidad_evaluacion: payload.modalidad_evaluacion || 'Presencial',
            fecha_inicio: payload.fecha_inicio ?? null,
            fecha_fin: payload.fecha_fin ?? null,
            notas_sitio: payload.notas_sitio ?? null,
            deleted_at: null,
          };
          return current;
        }
        const certDetail = (
          state.domainData.allCertificadosDetailed.length > 0
            ? state.domainData.allCertificadosDetailed
            : INITIAL_CERTIFICADOS_DETAILED
        ).find((c) => c.id === audit.id_certificado);
        const siteMeta = certDetail?.sitios.find((s) => s.id === payload.id_sitio);
        return [
          ...current,
          {
            id: savedId,
            id_auditoria: payload.id_auditoria,
            id_sitio: payload.id_sitio,
            numero_sitio: siteMeta?.numero_sitio ?? 0,
            nombre_sitio: siteMeta?.nombre_sitio || 'Sede Operativa',
            direccion_sitio: siteMeta?.direccion_sitio || '',
            modalidad_evaluacion: payload.modalidad_evaluacion || 'Presencial',
            tiempo_auditoria: payload.tiempo_auditoria,
            fecha_inicio: payload.fecha_inicio ?? null,
            fecha_fin: payload.fecha_fin ?? null,
            notas_sitio: payload.notas_sitio ?? null,
            deleted_at: null,
            procesos: [],
            equipoSitio: [],
          },
        ].sort((a, b) => a.numero_sitio - b.numero_sitio);
      });
    }

    const totalAuditDays = await recalculateAndPersistAuditTotalDays(
      payload.id_auditoria,
      localFallback
    );

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }
    const updatedAuditForCache = state.domainData.programacionAudits.find(
      (a) => a.id === payload.id_auditoria
    );
    if (updatedAuditForCache?.id_certificado) {
      refreshCoverageCachesForCert(updatedAuditForCache.id_certificado);
    }

    recordPhase5SessionLog('sitios_por_auditoria', savedId, restored ? 'UPDATE' : 'INSERT', null, {
      accion: 'PLANIFICAR_SITIO_AUDITORIA',
      tiempo_auditoria: payload.tiempo_auditoria,
      modalidad_evaluacion: payload.modalidad_evaluacion,
      total_auditoria_dias: totalAuditDays,
    });

    showFloatingToast(
      `Sitio planificado (${payload.tiempo_auditoria.toFixed(2)} d). Total auditoría: ${totalAuditDays.toFixed(2)} d.`,
      'success'
    );
    render();
    return {
      ok: true,
      data: { id: savedId, restored, totalAuditDays },
      restored,
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar la planificación del sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

export async function archiveSitioAuditoria(
  sitioAuditoriaId: string,
  reason = 'Sitio excluido del plan de auditoría'
): Promise<PersistenceMutationResult<{ id: string; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validSaId = assertValidUuid(sitioAuditoriaId, 'sitio de auditoría');
    const summary = await fetchArchiveDependencySummarySafe('sitios_por_auditoria', validSaId);
    if (!summary.can_archive) {
      const msg = formatDependencyBlockedMessage('el sitio de la auditoría', summary);
      showFloatingToast(msg, 'warning', 6000);
      render();
      return { ok: false, error: msg, dependencySummary: summary };
    }

    const auditId = await resolveAuditIdForSitioAuditoria(validSaId);
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { error: arcErr } = await supabase.rpc('archive_record', {
        p_table: 'sitios_por_auditoria',
        p_record_id: validSaId,
        p_reason: sanitizeArchiveReason(reason) || 'Sitio excluido del plan de auditoría',
      });

      if (arcErr) {
        if (!isMissingTableOrSchemaError(arcErr)) {
          const msg = formatZeroUuidError(arcErr, 'No se pudo excluir el sitio de la auditoría.');
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    if (localFallback && auditId) {
      mutateLocalAuditSitiosPlan(auditId, (audit) =>
        (audit.sitiosPlan || []).filter((sp) => sp.id !== validSaId)
      );
    }

    let totalAuditDays = 0;
    if (auditId) {
      totalAuditDays = await recalculateAndPersistAuditTotalDays(auditId, localFallback);
      if (!localFallback) {
        await syncEquipoAuditorCoherence(auditId);
      }
    }

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }
    if (auditId) {
      const archivedAuditForCache = state.domainData.programacionAudits.find(
        (a) => a.id === auditId
      );
      if (archivedAuditForCache?.id_certificado) {
        refreshCoverageCachesForCert(archivedAuditForCache.id_certificado);
      }
    }

    recordPhase5SessionLog(
      'sitios_por_auditoria',
      validSaId,
      'UPDATE',
      { deleted_at: null },
      { accion: 'EXCLUIR_SITIO_AUDITORIA', total_auditoria_dias: totalAuditDays }
    );
    showFloatingToast('Sitio excluido de la planificación de la auditoría.', 'success');
    render();
    return { ok: true, data: { id: validSaId, totalAuditDays }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo excluir el sitio de la auditoría.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

export async function toggleProcesoSitioAuditoria(
  sitioAuditoriaId: string,
  procesoPorSitioId: string,
  fallbackProcesoId?: string
): Promise<PersistenceMutationResult<{ id: string; active: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validSaId = assertValidUuid(sitioAuditoriaId, 'sitio de auditoría');
    const validPpsId = assertValidUuid(procesoPorSitioId, 'proceso por sitio');

    // Resolve id_proceso from local detailed certificates, fallback param, or DB
    const certsCatalog =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;
    let resolvedProcesoId: string | null = null;
    for (const cert of certsCatalog) {
      for (const site of cert.sitios) {
        const match = (site.procesos_por_sitio || []).find((l) => l.id === validPpsId);
        if (match?.id_proceso) {
          resolvedProcesoId = match.id_proceso;
          break;
        }
      }
      if (resolvedProcesoId) break;
    }

    if (!resolvedProcesoId && fallbackProcesoId && isValidUuid(fallbackProcesoId)) {
      resolvedProcesoId = fallbackProcesoId;
    }

    if (!resolvedProcesoId) {
      const { data: ppsRow, error: ppsErr } = await supabase
        .from('procesos_por_sitio')
        .select('id_proceso')
        .eq('id', validPpsId)
        .is('deleted_at', null)
        .maybeSingle();

      if (ppsErr && !isMissingTableOrSchemaError(ppsErr)) {
        const msg = formatZeroUuidError(ppsErr, 'No se pudo verificar el proceso del sitio.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      if (ppsRow?.id_proceso) {
        resolvedProcesoId = String(ppsRow.id_proceso);
      }
    }

    if (!resolvedProcesoId) {
      const msg = 'No se encontró el proceso asignado al sitio.';
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }
    const validProcesoId = assertValidUuid(resolvedProcesoId, 'proceso');

    const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
    let existingRows: unknown[] | null = null;
    let useLocalFallback = !remoteSchemaReady;

    if (!useLocalFallback) {
      const { data: queriedRows, error: lookupErr } = await supabase
        .from('procesos_sitio_auditoria')
        .select('id, deleted_at')
        .eq('id_sitios_por_auditoria', validSaId)
        .eq('id_procesos_por_sitio', validPpsId)
        .order('created_at', { ascending: false })
        .limit(1);

      if (lookupErr) {
        if (!isMissingTableOrSchemaError(lookupErr)) {
          const msg = formatZeroUuidError(
            lookupErr,
            'No se pudo consultar el proceso en la planificación.'
          );
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
        useLocalFallback = true;
      } else {
        existingRows = queriedRows;
      }
    }

    if (useLocalFallback) {
      const fallbackAuditId = await resolveAuditIdForSitioAuditoria(validSaId);
      let nextActive = true;
      let nextId: string = crypto.randomUUID();
      if (fallbackAuditId) {
        mutateLocalAuditSitiosPlan(fallbackAuditId, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            const currentProcs = [...(sp.procesos || [])];
            const existingIdx = currentProcs.findIndex(
              (p) => !p.deleted_at && p.id_procesos_por_sitio === validPpsId
            );
            if (existingIdx >= 0) {
              nextActive = false;
              nextId = currentProcs[existingIdx].id;
              return {
                ...sp,
                procesos: currentProcs.filter((_, i) => i !== existingIdx),
              };
            }
            const certsPoolForMeta =
              state.domainData.allCertificadosDetailed.length > 0
                ? state.domainData.allCertificadosDetailed
                : INITIAL_CERTIFICADOS_DETAILED;
            const certDetail = certsPoolForMeta.find((c) => c.id === audit.id_certificado);
            const versionSnapshot = resolveCertVersionSnapshotForAudit(audit, certsPoolForMeta);
            const scopedSites =
              versionSnapshot.sitios.length > 0 || Boolean(audit.id_certificado_version)
                ? versionSnapshot.sitios
                : certDetail?.sitios || [];
            const ppsMeta = scopedSites
              .flatMap((s) => s.procesos_por_sitio || [])
              .find((l) => l.id === validPpsId);
            return {
              ...sp,
              procesos: [
                ...currentProcs,
                {
                  id: nextId,
                  id_sitios_por_auditoria: validSaId,
                  id_procesos_por_sitio: validPpsId,
                  id_proceso: validProcesoId,
                  proceso_nombre: ppsMeta?.nombre_proceso || 'Proceso Operativo',
                  turnos: [],
                  equipoProceso: [],
                  deleted_at: null,
                },
              ],
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
      }
      showFloatingToast(
        nextActive
          ? 'Proceso incluido en la planificación del sitio.'
          : 'Proceso retirado del alcance de este sitio en la auditoría.',
        nextActive ? 'success' : 'info'
      );
      render();
      return { ok: true, data: { id: nextId, active: nextActive }, localFallback: true };
    }

    const existing = Array.isArray(existingRows)
      ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
      : undefined;

    if (existing?.id && !existing.deleted_at) {
      const validExistingId = assertValidUuid(existing.id, 'proceso en sitio de auditoría');
      const depSummary = await fetchArchiveDependencySummarySafe(
        'procesos_sitio_auditoria',
        validExistingId
      );
      if (!depSummary.can_archive) {
        const msg = formatDependencyBlockedMessage('el proceso en la auditoría', depSummary);
        showFloatingToast(msg, 'warning', 6000);
        render();
        return { ok: false, error: msg, dependencySummary: depSummary };
      }

      const { error: arcErr } = await supabase.rpc('archive_record', {
        p_table: 'procesos_sitio_auditoria',
        p_record_id: validExistingId,
        p_reason: 'Proceso desmarcado en el plan de auditoría del sitio',
      });
      if (arcErr) {
        const msg = formatZeroUuidError(arcErr, 'No se pudo desmarcar el proceso de la auditoría.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }

      await loadLiveAudits();
      recordPhase5SessionLog('procesos_sitio_auditoria', validExistingId, 'UPDATE', null, {
        accion: 'DESMARCAR_PROCESO_AUDITORIA',
      });
      showFloatingToast('Proceso retirado del alcance de este sitio en la auditoría.', 'info');
      render();
      return { ok: true, data: { id: validExistingId, active: false } };
    }

    let savedId: string = crypto.randomUUID();
    let restored = false;

    if (existing?.id && existing.deleted_at) {
      const validExistingId = assertValidUuid(existing.id, 'proceso en sitio de auditoría');
      const { data: restoredRow, error: restoreErr } = await supabase
        .from('procesos_sitio_auditoria')
        .update({
          deleted_at: null,
          deleted_by: null,
          id_proceso: validProcesoId,
          updated_at: new Date().toISOString(),
        })
        .eq('id', validExistingId)
        .select('id')
        .single();

      if (!restoreErr && restoredRow?.id) {
        savedId = String(restoredRow.id);
        restored = true;
      } else {
        const { data: insRow, error: insErr } = await supabase
          .from('procesos_sitio_auditoria')
          .insert({
            id: savedId,
            id_sitios_por_auditoria: validSaId,
            id_procesos_por_sitio: validPpsId,
            id_proceso: validProcesoId,
          })
          .select('id')
          .single();
        if (insErr) {
          const msg = formatZeroUuidError(insErr, 'No se pudo activar el proceso en la auditoría.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        savedId = String(insRow.id);
      }
    } else {
      const { data: insRow, error: insErr } = await supabase
        .from('procesos_sitio_auditoria')
        .insert({
          id: savedId,
          id_sitios_por_auditoria: validSaId,
          id_procesos_por_sitio: validPpsId,
          id_proceso: validProcesoId,
        })
        .select('id')
        .single();
      if (insErr) {
        const msg = formatZeroUuidError(insErr, 'No se pudo activar el proceso en la auditoría.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      savedId = String(insRow.id);
    }

    await loadLiveAudits();
    recordPhase5SessionLog(
      'procesos_sitio_auditoria',
      savedId,
      restored ? 'UPDATE' : 'INSERT',
      null,
      { accion: 'ACTIVAR_PROCESO_AUDITORIA' }
    );
    showFloatingToast('Proceso incluido en la planificación del sitio.', 'success');
    render();
    return { ok: true, data: { id: savedId, active: true }, restored };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar el proceso en el sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 3.8 Step 7.1 (`4. Proceso`) — Selección de Procesos por Sitio
 */
export function pageProgramaCycleWindow(auditId: string, delta: number): void {
  if (!auditId || !Number.isFinite(delta) || delta === 0) return;
  pendingPlannerViewportSnapshot = capturePlannerViewportSnapshot();
  try {
    const currentOffset =
      state.programaProcesosDomain.cycleWindowOffsetByAuditId[auditId] ??
      state.programaDomain.cycleWindowOffsetByAuditId[auditId] ??
      0;
    const nextOffset = currentOffset + Math.trunc(delta);
    state.programaProcesosDomain.cycleWindowOffsetByAuditId = {
      ...state.programaProcesosDomain.cycleWindowOffsetByAuditId,
      [auditId]: nextOffset,
    };
    state.programaDomain.cycleWindowOffsetByAuditId = {
      ...state.programaDomain.cycleWindowOffsetByAuditId,
      [auditId]: nextOffset,
    };
    render();
  } finally {
    pendingPlannerViewportSnapshot = null;
  }
}

export function toggleProcessHistoryDrawer(drawerKey: string): void {
  if (!drawerKey) return;
  pendingPlannerViewportSnapshot = capturePlannerViewportSnapshot();
  try {
    const current = state.programaProcesosDomain.openHistoryDrawerProcessIds;
    const isOpen = current.includes(drawerKey);
    const next = isOpen
      ? current.filter((k) => k !== drawerKey)
      : [...current, drawerKey];
    state.programaProcesosDomain.openHistoryDrawerProcessIds = next;
    state.programaDomain.openHistoryDrawerProcessIds = next;
    render();
  } finally {
    pendingPlannerViewportSnapshot = null;
  }
}

export async function toggleProcessInAuditSite(
  sitePlanId: string,
  ppsLinkId: string,
  procesoId?: string
): Promise<PersistenceMutationResult<{ id: string; active: boolean }>> {
  state.programaProcesosDomain.editErrorMessage = null;
  state.programaDomain.editErrorMessage = null;
  return runWithPlannerPreservedViewport(async () => {
    state.programaProcesosDomain.savingSitePlanId = sitePlanId;
    try {
      const result = await toggleProcesoSitioAuditoria(sitePlanId, ppsLinkId, procesoId);
      if (!result.ok) {
        const errMsg = result.error ?? 'No se pudo actualizar el proceso en el sitio.';
        state.programaProcesosDomain.editErrorMessage = errMsg;
        state.programaDomain.editErrorMessage = errMsg;
        render();
      }
      return result;
    } finally {
      state.programaProcesosDomain.savingSitePlanId = null;
    }
  });
}

export async function applyQuickProcessSelection(
  sitePlanId: string,
  preset: QuickProcessSelectionPreset
): Promise<PersistenceMutationResult<{ count: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.programaProcesosDomain.editErrorMessage = staffCheck.error;
    state.programaDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  state.programaProcesosDomain.editErrorMessage = null;
  state.programaDomain.editErrorMessage = null;
  return runWithPlannerPreservedViewport(async () => {
    state.programaProcesosDomain.savingSitePlanId = sitePlanId;
    try {
      const validSaId = assertValidUuid(sitePlanId, 'sitio de auditoría');

      const auditsPool =
        state.domainData.programacionAudits.length > 0
          ? state.domainData.programacionAudits
          : state.domainData.auditPrograms.length > 0
          ? state.domainData.auditPrograms.flatMap((p) => p.auditorias)
          : buildSeededProgramsFallback().flatMap((p) => p.auditorias);

      let matchedAudit = auditsPool.find((a) =>
        (a.sitiosPlan || []).some((sp) => !sp.deleted_at && sp.id === validSaId)
      );
      let matchedSitePlan = matchedAudit?.sitiosPlan?.find(
        (sp) => !sp.deleted_at && sp.id === validSaId
      );

      if (!matchedAudit || !matchedSitePlan) {
        const msg = 'No se encontró el sitio dentro de la programación del certificado.';
        state.programaDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        render();
        return { ok: false, error: msg };
      }

      const certsPool =
        state.domainData.allCertificadosDetailed.length > 0
          ? state.domainData.allCertificadosDetailed
          : INITIAL_CERTIFICADOS_DETAILED;
      const versionSnapshot = resolveCertVersionSnapshotForAudit(matchedAudit, certsPool);
      const hasScopedSites =
        versionSnapshot.sitios.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const hasScopedProcs =
        versionSnapshot.procesos.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const allProcessesPorSitio = (
        hasScopedSites
          ? versionSnapshot.sitios
          : certsPool.flatMap((c) => c.sitios)
      ).flatMap((s) => s.procesos_por_sitio || []);
      const allProcesses = (
        hasScopedProcs
          ? versionSnapshot.procesos
          : certsPool.flatMap((c) => c.procesos)
      ) as CandidateProcessEntity[];
      const siteLinks = allProcessesPorSitio.filter(
        (l) => !l.deleted_at && l.id_sitio === matchedSitePlan!.id_sitio
      );

      const historyRows = buildProcessHistoryForSite(
        matchedAudit,
        matchedSitePlan,
        siteLinks,
        allProcesses,
        auditsPool
      );
      const targetPpsIds = computeQuickProcessSelectionIds(historyRows, preset);

      if (targetPpsIds.length === 0) {
        showFloatingToast('No hay procesos pendientes que cumplan este criterio rápido.', 'info');
        return { ok: true, data: { count: 0 } };
      }

      const procesoIdByPpsId = new Map<string, string>();
      const nombreByPpsId = new Map<string, string>();
      for (const r of historyRows) {
        procesoIdByPpsId.set(r.ppsLink.id, r.proceso.id);
        nombreByPpsId.set(r.ppsLink.id, r.proceso.nombre_proceso);
      }

      const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
      let existingRows: unknown[] | null = null;
      let useLocalFallback = !remoteSchemaReady;

      if (!useLocalFallback) {
        const { data: queriedRows, error: lookupErr } = await supabase
          .from('procesos_sitio_auditoria')
          .select('id, id_procesos_por_sitio, deleted_at')
          .eq('id_sitios_por_auditoria', validSaId)
          .in('id_procesos_por_sitio', targetPpsIds);

        if (lookupErr) {
          if (!isMissingTableOrSchemaError(lookupErr)) {
            const msg = formatZeroUuidError(
              lookupErr,
              'No se pudo aplicar la selección rápida de procesos.'
            );
            state.programaDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning');
            render();
            return { ok: false, error: msg };
          }
          useLocalFallback = true;
        } else {
          existingRows = queriedRows;
        }
      }

      if (useLocalFallback) {
        mutateLocalAuditSitiosPlan(matchedAudit.id, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            const currentProcs = [...(sp.procesos || [])];
            const activeSet = new Set(
              currentProcs.filter((p) => !p.deleted_at).map((p) => p.id_procesos_por_sitio)
            );
            const appended = targetPpsIds
              .filter((ppsId) => !activeSet.has(ppsId))
              .map((ppsId) => ({
                id: crypto.randomUUID(),
                id_sitios_por_auditoria: validSaId,
                id_procesos_por_sitio: ppsId,
                id_proceso: procesoIdByPpsId.get(ppsId) || '',
                proceso_nombre: nombreByPpsId.get(ppsId) || 'Proceso Operativo',
                turnos: [],
                equipoProceso: [],
                deleted_at: null,
              }));
            return {
              ...sp,
              procesos: [...currentProcs, ...appended],
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
        showFloatingToast(
          `${targetPpsIds.length} proceso(s) añadido(s) al plan del sitio.`,
          'success'
        );
        render();
        return { ok: true, data: { count: targetPpsIds.length }, localFallback: true };
      }

      const existingByPps = new Map<string, { id: string; deleted_at: string | null }>();
      for (const row of (existingRows || []) as Array<{
        id?: string;
        id_procesos_por_sitio?: string;
        deleted_at?: string | null;
      }>) {
        if (row.id && row.id_procesos_por_sitio) {
          existingByPps.set(String(row.id_procesos_por_sitio), {
            id: String(row.id),
            deleted_at: row.deleted_at ?? null,
          });
        }
      }

      const toRestoreIds: string[] = [];
      const toInsertPayloads: Array<{
        id: string;
        id_sitios_por_auditoria: string;
        id_procesos_por_sitio: string;
        id_proceso: string;
      }> = [];

      for (const ppsId of targetPpsIds) {
        const procId = procesoIdByPpsId.get(ppsId);
        if (!procId || !isValidUuid(procId)) continue;
        const existing = existingByPps.get(ppsId);
        if (existing) {
          if (existing.deleted_at) {
            toRestoreIds.push(existing.id);
          }
        } else {
          toInsertPayloads.push({
            id: crypto.randomUUID(),
            id_sitios_por_auditoria: validSaId,
            id_procesos_por_sitio: ppsId,
            id_proceso: procId,
          });
        }
      }

      if (toRestoreIds.length > 0) {
        const { error: restoreErr } = await supabase
          .from('procesos_sitio_auditoria')
          .update({
            deleted_at: null,
            deleted_by: null,
            updated_at: new Date().toISOString(),
          })
          .in('id', toRestoreIds);
        if (restoreErr) {
          const msg = formatZeroUuidError(restoreErr, 'No se pudieron restaurar los procesos seleccionados.');
          state.programaDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      if (toInsertPayloads.length > 0) {
        const { error: insertErr } = await supabase
          .from('procesos_sitio_auditoria')
          .insert(toInsertPayloads);
        if (insertErr) {
          const msg = formatZeroUuidError(insertErr, 'No se pudieron guardar los procesos seleccionados.');
          state.programaDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      const appliedCount = toRestoreIds.length + toInsertPayloads.length;
      await loadLiveAudits();
      recordPhase5SessionLog('procesos_sitio_auditoria', validSaId, 'INSERT', null, {
        accion: `SELECCION_RAPIDA_${preset}`,
        cantidad: appliedCount,
      });
      showFloatingToast(
        `${appliedCount} proceso(s) incluido(s) mediante acción rápida.`,
        'success'
      );
      render();
      return { ok: true, data: { count: appliedCount } };
    } catch (err) {
      const msg = formatZeroUuidError(err, 'No se pudo completar la selección rápida.');
      state.programaProcesosDomain.editErrorMessage = msg;
      state.programaDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    } finally {
      state.programaProcesosDomain.savingSitePlanId = null;
    }
  });
}

export async function selectAllSiteProcesses(
  sitePlanId: string
): Promise<PersistenceMutationResult<{ count: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.programaProcesosDomain.editErrorMessage = staffCheck.error;
    state.programaDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  state.programaProcesosDomain.editErrorMessage = null;
  state.programaDomain.editErrorMessage = null;
  return runWithPlannerPreservedViewport(async () => {
    state.programaProcesosDomain.savingSitePlanId = sitePlanId;
    try {
      const validSaId = assertValidUuid(sitePlanId, 'sitio de auditoría');
      const auditsPool =
        state.domainData.programacionAudits.length > 0
          ? state.domainData.programacionAudits
          : state.domainData.auditPrograms.length > 0
          ? state.domainData.auditPrograms.flatMap((p) => p.auditorias)
          : buildSeededProgramsFallback().flatMap((p) => p.auditorias);

      const matchedAudit = auditsPool.find((a) =>
        (a.sitiosPlan || []).some((sp) => !sp.deleted_at && sp.id === validSaId)
      );
      const matchedSitePlan = matchedAudit?.sitiosPlan?.find(
        (sp) => !sp.deleted_at && sp.id === validSaId
      );

      if (!matchedAudit || !matchedSitePlan) {
        const msg = 'No se encontró el sitio dentro de la programación del certificado.';
        state.programaProcesosDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        render();
        return { ok: false, error: msg };
      }

      const certsPool =
        state.domainData.allCertificadosDetailed.length > 0
          ? state.domainData.allCertificadosDetailed
          : INITIAL_CERTIFICADOS_DETAILED;
      const versionSnapshot = resolveCertVersionSnapshotForAudit(matchedAudit, certsPool);
      const hasScopedSites =
        versionSnapshot.sitios.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const hasScopedProcs =
        versionSnapshot.procesos.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const allProcessesPorSitio = (
        hasScopedSites
          ? versionSnapshot.sitios
          : certsPool.flatMap((c) => c.sitios)
      ).flatMap((s) => s.procesos_por_sitio || []);
      const allProcesses = (
        hasScopedProcs
          ? versionSnapshot.procesos
          : certsPool.flatMap((c) => c.procesos)
      ) as CandidateProcessEntity[];
      const siteLinks = allProcessesPorSitio.filter(
        (l) => !l.deleted_at && l.id_sitio === matchedSitePlan.id_sitio
      );

      const historyRows = buildProcessHistoryForSite(
        matchedAudit,
        matchedSitePlan,
        siteLinks,
        allProcesses,
        auditsPool
      );
      const targetPpsIds = computeSiteSelectAllIds(historyRows);

      if (targetPpsIds.length === 0) {
        showFloatingToast('Todos los procesos de este sitio ya están seleccionados.', 'info');
        return { ok: true, data: { count: 0 } };
      }

      const procesoIdByPpsId = new Map<string, string>();
      const nombreByPpsId = new Map<string, string>();
      for (const r of historyRows) {
        procesoIdByPpsId.set(r.ppsLink.id, r.proceso.id);
        nombreByPpsId.set(r.ppsLink.id, r.proceso.nombre_proceso);
      }

      const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
      let existingRows: unknown[] | null = null;
      let useLocalFallback = !remoteSchemaReady;

      if (!useLocalFallback) {
        const { data: queriedRows, error: lookupErr } = await supabase
          .from('procesos_sitio_auditoria')
          .select('id, id_procesos_por_sitio, deleted_at')
          .eq('id_sitios_por_auditoria', validSaId)
          .in('id_procesos_por_sitio', targetPpsIds);
        if (lookupErr) {
          if (!isMissingTableOrSchemaError(lookupErr)) {
            const msg = formatZeroUuidError(
              lookupErr,
              'No se pudieron seleccionar todos los procesos del sitio.'
            );
            state.programaProcesosDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning');
            render();
            return { ok: false, error: msg };
          }
          useLocalFallback = true;
        } else {
          existingRows = queriedRows;
        }
      }

      if (useLocalFallback) {
        mutateLocalAuditSitiosPlan(matchedAudit.id, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            const currentProcs = [...(sp.procesos || [])];
            const activeSet = new Set(
              currentProcs.filter((p) => !p.deleted_at).map((p) => p.id_procesos_por_sitio)
            );
            const appended = targetPpsIds
              .filter((ppsId) => !activeSet.has(ppsId))
              .map((ppsId) => ({
                id: crypto.randomUUID(),
                id_sitios_por_auditoria: validSaId,
                id_procesos_por_sitio: ppsId,
                id_proceso: procesoIdByPpsId.get(ppsId) || '',
                proceso_nombre: nombreByPpsId.get(ppsId) || 'Proceso Operativo',
                turnos: [],
                equipoProceso: [],
                deleted_at: null,
              }));
            return {
              ...sp,
              procesos: [...currentProcs, ...appended],
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
        showFloatingToast(
          `${targetPpsIds.length} proceso(s) seleccionados en el sitio.`,
          'success'
        );
        render();
        return { ok: true, data: { count: targetPpsIds.length }, localFallback: true };
      }

      const existingByPps = new Map<string, { id: string; deleted_at: string | null }>();
      for (const row of (existingRows || []) as Array<{
        id?: string;
        id_procesos_por_sitio?: string;
        deleted_at?: string | null;
      }>) {
        if (row.id && row.id_procesos_por_sitio) {
          existingByPps.set(String(row.id_procesos_por_sitio), {
            id: String(row.id),
            deleted_at: row.deleted_at ?? null,
          });
        }
      }

      const toRestoreIds: string[] = [];
      const toInsertPayloads: Array<{
        id: string;
        id_sitios_por_auditoria: string;
        id_procesos_por_sitio: string;
        id_proceso: string;
      }> = [];

      for (const ppsId of targetPpsIds) {
        const procId = procesoIdByPpsId.get(ppsId);
        if (!procId || !isValidUuid(procId)) continue;
        const existing = existingByPps.get(ppsId);
        if (existing) {
          if (existing.deleted_at) toRestoreIds.push(existing.id);
        } else {
          toInsertPayloads.push({
            id: crypto.randomUUID(),
            id_sitios_por_auditoria: validSaId,
            id_procesos_por_sitio: ppsId,
            id_proceso: procId,
          });
        }
      }

      if (toRestoreIds.length > 0) {
        const { error: restoreErr } = await supabase
          .from('procesos_sitio_auditoria')
          .update({
            deleted_at: null,
            deleted_by: null,
            updated_at: new Date().toISOString(),
          })
          .in('id', toRestoreIds);
        if (restoreErr) {
          const msg = formatZeroUuidError(
            restoreErr,
            'No se pudieron restaurar todos los procesos del sitio.'
          );
          state.programaProcesosDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      if (toInsertPayloads.length > 0) {
        const { error: insertErr } = await supabase
          .from('procesos_sitio_auditoria')
          .insert(toInsertPayloads);
        if (insertErr) {
          const msg = formatZeroUuidError(
            insertErr,
            'No se pudieron guardar todos los procesos del sitio.'
          );
          state.programaProcesosDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      const appliedCount = toRestoreIds.length + toInsertPayloads.length;
      await loadLiveAudits();
      recordPhase5SessionLog('procesos_sitio_auditoria', validSaId, 'INSERT', null, {
        accion: 'SELECCIONAR_TODOS_PROCESOS_SITIO',
        cantidad: appliedCount,
      });
      showFloatingToast(`${appliedCount} proceso(s) seleccionados en el sitio.`, 'success');
      render();
      return { ok: true, data: { count: appliedCount } };
    } catch (err) {
      const msg = formatZeroUuidError(err, 'No se pudieron seleccionar todos los procesos.');
      state.programaProcesosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    } finally {
      state.programaProcesosDomain.savingSitePlanId = null;
    }
  });
}

export async function clearSiteProcesses(
  sitePlanId: string
): Promise<PersistenceMutationResult<{ count: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.programaProcesosDomain.editErrorMessage = staffCheck.error;
    state.programaDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  state.programaProcesosDomain.editErrorMessage = null;
  state.programaDomain.editErrorMessage = null;
  return runWithPlannerPreservedViewport(async () => {
    state.programaProcesosDomain.savingSitePlanId = sitePlanId;
    try {
      const validSaId = assertValidUuid(sitePlanId, 'sitio de auditoría');
      const auditsPool =
        state.domainData.programacionAudits.length > 0
          ? state.domainData.programacionAudits
          : state.domainData.auditPrograms.length > 0
          ? state.domainData.auditPrograms.flatMap((p) => p.auditorias)
          : buildSeededProgramsFallback().flatMap((p) => p.auditorias);

      const matchedAudit = auditsPool.find((a) =>
        (a.sitiosPlan || []).some((sp) => !sp.deleted_at && sp.id === validSaId)
      );
      const matchedSitePlan = matchedAudit?.sitiosPlan?.find(
        (sp) => !sp.deleted_at && sp.id === validSaId
      );

      if (!matchedAudit || !matchedSitePlan) {
        const msg = 'No se encontró el sitio dentro de la programación del certificado.';
        state.programaProcesosDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        render();
        return { ok: false, error: msg };
      }

      const certsPool =
        state.domainData.allCertificadosDetailed.length > 0
          ? state.domainData.allCertificadosDetailed
          : INITIAL_CERTIFICADOS_DETAILED;
      const versionSnapshot = resolveCertVersionSnapshotForAudit(matchedAudit, certsPool);
      const hasScopedSites =
        versionSnapshot.sitios.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const hasScopedProcs =
        versionSnapshot.procesos.length > 0 || Boolean(matchedAudit.id_certificado_version);
      const allProcessesPorSitio = (
        hasScopedSites
          ? versionSnapshot.sitios
          : certsPool.flatMap((c) => c.sitios)
      ).flatMap((s) => s.procesos_por_sitio || []);
      const allProcesses = (
        hasScopedProcs
          ? versionSnapshot.procesos
          : certsPool.flatMap((c) => c.procesos)
      ) as CandidateProcessEntity[];
      const siteLinks = allProcessesPorSitio.filter(
        (l) => !l.deleted_at && l.id_sitio === matchedSitePlan.id_sitio
      );

      const historyRows = buildProcessHistoryForSite(
        matchedAudit,
        matchedSitePlan,
        siteLinks,
        allProcesses,
        auditsPool
      );
      const clearIds = computeSiteClearRecordIds(historyRows);

      if (clearIds.length === 0) {
        showFloatingToast('No hay procesos activos para desmarcar en este sitio.', 'info');
        return { ok: true, data: { count: 0 } };
      }

      const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
      if (!remoteSchemaReady) {
        const clearIdSet = new Set(clearIds);
        const blockingLocal = (matchedSitePlan.procesos || []).find(
          (psa) =>
            !psa.deleted_at &&
            clearIdSet.has(psa.id) &&
            ((psa.turnos || []).some((t) => !t.deleted_at) ||
              (psa.equipoProceso || []).some((e) => !e.deleted_at))
        );
        if (blockingLocal) {
          const msg =
            'No se pueden limpiar los procesos porque al menos uno ya tiene turnos asignados o auditores vinculados. Retire esas dependencias primero.';
          state.programaProcesosDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 6000);
          render();
          return { ok: false, error: msg };
        }

        mutateLocalAuditSitiosPlan(matchedAudit.id, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            return {
              ...sp,
              procesos: (sp.procesos || []).filter((p) => !clearIdSet.has(p.id)),
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
        showFloatingToast(`${clearIds.length} proceso(s) desmarcados del sitio.`, 'info');
        render();
        return { ok: true, data: { count: clearIds.length }, localFallback: true };
      }

      for (const psaId of clearIds) {
        const validPsaId = assertValidUuid(psaId, 'proceso en sitio de auditoría');
        const depSummary = await fetchArchiveDependencySummarySafe(
          'procesos_sitio_auditoria',
          validPsaId
        );
        if (!depSummary.can_archive) {
          const msg = formatDependencyBlockedMessage('el proceso en la auditoría', depSummary);
          state.programaProcesosDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning', 6000);
          render();
          return { ok: false, error: msg, dependencySummary: depSummary };
        }
      }

      for (const psaId of clearIds) {
        const validPsaId = assertValidUuid(psaId, 'proceso en sitio de auditoría');
        const { error: arcErr } = await supabase.rpc('archive_record', {
          p_table: 'procesos_sitio_auditoria',
          p_record_id: validPsaId,
          p_reason: 'Limpieza en lote de procesos del sitio (4. Proceso)',
        });
        if (arcErr) {
          const msg = formatZeroUuidError(
            arcErr,
            'No se pudieron limpiar los procesos seleccionados del sitio.'
          );
          state.programaProcesosDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      await loadLiveAudits();
      recordPhase5SessionLog('procesos_sitio_auditoria', validSaId, 'UPDATE', null, {
        accion: 'LIMPIAR_PROCESOS_SITIO',
        cantidad: clearIds.length,
      });
      showFloatingToast(`${clearIds.length} proceso(s) desmarcados del sitio.`, 'info');
      render();
      return { ok: true, data: { count: clearIds.length } };
    } catch (err) {
      const msg = formatZeroUuidError(err, 'No se pudo limpiar la selección del sitio.');
      state.programaProcesosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    } finally {
      state.programaProcesosDomain.savingSitePlanId = null;
    }
  });
}

export async function toggleTurnoProcesoSitioAuditoria(
  procesoSitioAuditoriaId: string,
  sitioAuditoriaId: string,
  turnoPorSitioId: string
): Promise<PersistenceMutationResult<{ id: string; active: boolean; turnosSitioAuditoriaId: string }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validPsaId = assertValidUuid(procesoSitioAuditoriaId, 'proceso en sitio de auditoría');
    const validSaId = assertValidUuid(sitioAuditoriaId, 'sitio de auditoría');
    const validTpsId = assertValidUuid(turnoPorSitioId, 'turno por sitio');

    // Step 1: Guarantee active row in `turnos_sitio_auditoria`
    let turnosSitioAuditoriaId: string = crypto.randomUUID();
    const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
    let tsaRows: unknown[] | null = null;
    let useLocalFallback = !remoteSchemaReady;

    if (!useLocalFallback) {
      const { data: queriedTsaRows, error: tsaLookupErr } = await supabase
        .from('turnos_sitio_auditoria')
        .select('id, deleted_at')
        .eq('id_sitios_por_auditoria', validSaId)
        .eq('id_turnos_por_sitio', validTpsId)
        .order('created_at', { ascending: false })
        .limit(1);

      if (tsaLookupErr) {
        if (!isMissingTableOrSchemaError(tsaLookupErr)) {
          const msg = formatZeroUuidError(
            tsaLookupErr,
            'No se pudo verificar el turno del sitio en la auditoría.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        useLocalFallback = true;
      } else {
        tsaRows = queriedTsaRows;
      }
    }

    if (useLocalFallback) {
      const fallbackAuditId = await resolveAuditIdForSitioAuditoria(validSaId);
      let nextActive = true;
      let nextTpsaId: string = crypto.randomUUID();
      if (fallbackAuditId) {
        mutateLocalAuditSitiosPlan(fallbackAuditId, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            const certDetail = (
              state.domainData.allCertificadosDetailed.length > 0
                ? state.domainData.allCertificadosDetailed
                : INITIAL_CERTIFICADOS_DETAILED
            ).find((c) => c.id === audit.id_certificado);
            const tpsMeta = certDetail?.sitios
              .flatMap((s) => s.turnos_por_sitio || [])
              .find((t) => t.id === validTpsId);
            return {
              ...sp,
              procesos: (sp.procesos || []).map((psa) => {
                if (psa.id !== validPsaId) return psa;
                const currentTurnos = [...(psa.turnos || [])];
                const existingIdx = currentTurnos.findIndex(
                  (t) =>
                    !t.deleted_at &&
                    (t.id_turnos_por_sitio === validTpsId ||
                      t.id_turnos_sitio_auditoria === validTpsId)
                );
                if (existingIdx >= 0) {
                  nextActive = false;
                  nextTpsaId = currentTurnos[existingIdx].id;
                  return {
                    ...psa,
                    turnos: currentTurnos.filter((_, i) => i !== existingIdx),
                  };
                }
                return {
                  ...psa,
                  turnos: [
                    ...currentTurnos,
                    {
                      id: nextTpsaId,
                      id_procesos_sitio_auditoria: validPsaId,
                      id_turnos_sitio_auditoria: turnosSitioAuditoriaId,
                      id_turnos_por_sitio: validTpsId,
                      descripcion_turno: tpsMeta?.descripcion || 'Turno Operativo',
                      hora_entrada: tpsMeta?.hora_entrada,
                      hora_salida: tpsMeta?.hora_salida,
                      deleted_at: null,
                    },
                  ],
                };
              }),
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
      }
      showFloatingToast(
        nextActive
          ? 'Turno asignado al proceso correctamente.'
          : 'Turno desvinculado del proceso.',
        nextActive ? 'success' : 'info'
      );
      render();
      return {
        ok: true,
        data: { id: nextTpsaId, active: nextActive, turnosSitioAuditoriaId },
        localFallback: true,
      };
    }

    const existingTsa = Array.isArray(tsaRows)
      ? (tsaRows[0] as { id?: string; deleted_at?: string | null } | undefined)
      : undefined;

    if (existingTsa?.id && !existingTsa.deleted_at) {
      turnosSitioAuditoriaId = assertValidUuid(existingTsa.id, 'turno en sitio de auditoría');
    } else if (existingTsa?.id && existingTsa.deleted_at) {
      const validOldTsaId = assertValidUuid(existingTsa.id, 'turno en sitio de auditoría');
      const { data: restoredTsa, error: restoreTsaErr } = await supabase
        .from('turnos_sitio_auditoria')
        .update({ deleted_at: null, deleted_by: null })
        .eq('id', validOldTsaId)
        .select('id')
        .single();
      if (!restoreTsaErr && restoredTsa?.id) {
        turnosSitioAuditoriaId = String(restoredTsa.id);
      } else {
        const { data: insTsa, error: insTsaErr } = await supabase
          .from('turnos_sitio_auditoria')
          .insert({
            id: turnosSitioAuditoriaId,
            id_sitios_por_auditoria: validSaId,
            id_turnos_por_sitio: validTpsId,
          })
          .select('id')
          .single();
        if (insTsaErr) {
          const msg = formatZeroUuidError(
            insTsaErr,
            'No se pudo habilitar el turno para este sitio.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        turnosSitioAuditoriaId = String(insTsa.id);
      }
    } else {
      const { data: insTsa, error: insTsaErr } = await supabase
        .from('turnos_sitio_auditoria')
        .insert({
          id: turnosSitioAuditoriaId,
          id_sitios_por_auditoria: validSaId,
          id_turnos_por_sitio: validTpsId,
        })
        .select('id')
        .single();
      if (insTsaErr) {
        const msg = formatZeroUuidError(insTsaErr, 'No se pudo habilitar el turno para este sitio.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      turnosSitioAuditoriaId = String(insTsa.id);
    }

    // Step 2: Toggle 1..N link in `turnos_proceso_sitio_auditoria`
    const { data: tpsaRows, error: tpsaLookupErr } = await supabase
      .from('turnos_proceso_sitio_auditoria')
      .select('id, deleted_at')
      .eq('id_procesos_sitio_auditoria', validPsaId)
      .eq('id_turnos_sitio_auditoria', turnosSitioAuditoriaId)
      .order('created_at', { ascending: false })
      .limit(1);

    if (tpsaLookupErr) {
      const msg = formatZeroUuidError(
        tpsaLookupErr,
        'No se pudo consultar los turnos asignados al proceso.'
      );
      showFloatingToast(msg, 'warning');
      return { ok: false, error: msg };
    }

    const existingTpsa = Array.isArray(tpsaRows)
      ? (tpsaRows[0] as { id?: string; deleted_at?: string | null } | undefined)
      : undefined;

    if (existingTpsa?.id && !existingTpsa.deleted_at) {
      const validTpsaId = assertValidUuid(existingTpsa.id, 'turno de proceso en auditoría');
      const { error: arcErr } = await supabase.rpc('archive_record', {
        p_table: 'turnos_proceso_sitio_auditoria',
        p_record_id: validTpsaId,
        p_reason: 'Turno desmarcado en Paso 8B',
      });
      if (arcErr) {
        const msg = formatZeroUuidError(arcErr, 'No se pudo retirar el turno del proceso.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }

      await loadLiveAudits();
      recordPhase5SessionLog('turnos_proceso_sitio_auditoria', validTpsaId, 'UPDATE', null, {
        accion: 'DESVINCULAR_TURNO_PROCESO_AUDITORIA',
      });
      showFloatingToast('Turno desvinculado del proceso.', 'info');
      render();
      return {
        ok: true,
        data: { id: validTpsaId, active: false, turnosSitioAuditoriaId },
      };
    }

    let savedTpsaId: string = crypto.randomUUID();
    let restored = false;

    if (existingTpsa?.id && existingTpsa.deleted_at) {
      const validOldTpsaId = assertValidUuid(existingTpsa.id, 'turno de proceso en auditoría');
      const { data: restoredTpsa, error: restoreErr } = await supabase
        .from('turnos_proceso_sitio_auditoria')
        .update({ deleted_at: null, deleted_by: null })
        .eq('id', validOldTpsaId)
        .select('id')
        .single();
      if (!restoreErr && restoredTpsa?.id) {
        savedTpsaId = String(restoredTpsa.id);
        restored = true;
      } else {
        const { data: insTpsa, error: insErr } = await supabase
          .from('turnos_proceso_sitio_auditoria')
          .insert({
            id: savedTpsaId,
            id_procesos_sitio_auditoria: validPsaId,
            id_turnos_sitio_auditoria: turnosSitioAuditoriaId,
          })
          .select('id')
          .single();
        if (insErr) {
          const msg = formatZeroUuidError(insErr, 'No se pudo asignar el turno al proceso.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        savedTpsaId = String(insTpsa.id);
      }
    } else {
      const { data: insTpsa, error: insErr } = await supabase
        .from('turnos_proceso_sitio_auditoria')
        .insert({
          id: savedTpsaId,
          id_procesos_sitio_auditoria: validPsaId,
          id_turnos_sitio_auditoria: turnosSitioAuditoriaId,
        })
        .select('id')
        .single();
      if (insErr) {
        const msg = formatZeroUuidError(insErr, 'No se pudo asignar el turno al proceso.');
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      savedTpsaId = String(insTpsa.id);
    }

    await loadLiveAudits();
    recordPhase5SessionLog(
      'turnos_proceso_sitio_auditoria',
      savedTpsaId,
      restored ? 'UPDATE' : 'INSERT',
      null,
      { accion: 'ASIGNAR_TURNO_PROCESO_AUDITORIA' }
    );
    showFloatingToast('Turno asignado al proceso correctamente.', 'success');
    render();
    return {
      ok: true,
      data: { id: savedTpsaId, active: true, turnosSitioAuditoriaId },
      restored,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo actualizar el turno del proceso.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 3.9 Step 7.1 (`5. Turno`) — Matriz Anti-Fatiga Proceso × Turno
 */
export function focusTurnoSite(sitePlanId: string): void {
  pendingPlannerViewportSnapshot = capturePlannerViewportSnapshot();
  try {
    state.programaTurnosDomain.focusedSitePlanId = sitePlanId || null;
    state.programaTurnosDomain.editErrorMessage = null;
    render();
  } finally {
    pendingPlannerViewportSnapshot = null;
  }
}

export function toggleTurnoOnlyPending(): void {
  pendingPlannerViewportSnapshot = capturePlannerViewportSnapshot();
  try {
    state.programaTurnosDomain.onlyPending = !state.programaTurnosDomain.onlyPending;
    state.programaTurnosDomain.editErrorMessage = null;
    render();
  } finally {
    pendingPlannerViewportSnapshot = null;
  }
}

export function toggleTurnoBatchChip(sitePlanId: string, tpsId: string): void {
  if (!sitePlanId || !tpsId) return;
  pendingPlannerViewportSnapshot = capturePlannerViewportSnapshot();
  try {
    const current = state.programaTurnosDomain.batchSelectedTpsIdsBySitePlanId[sitePlanId] ?? [];
    const next = current.includes(tpsId)
      ? current.filter((id) => id !== tpsId)
      : [...current, tpsId];
    state.programaTurnosDomain.batchSelectedTpsIdsBySitePlanId = {
      ...state.programaTurnosDomain.batchSelectedTpsIdsBySitePlanId,
      [sitePlanId]: next,
    };
    state.programaTurnosDomain.editErrorMessage = null;
    render();
  } finally {
    pendingPlannerViewportSnapshot = null;
  }
}

function buildTurnoDetailModelForAudit(auditId: string) {
  const auditsPool =
    state.domainData.programacionAudits.length > 0
      ? state.domainData.programacionAudits
      : state.domainData.auditPrograms.length > 0
      ? state.domainData.auditPrograms.flatMap((p) => p.auditorias)
      : buildSeededProgramsFallback().flatMap((p) => p.auditorias);
  const matchedAudit = auditsPool.find((a) => a.id === auditId) ?? null;
  if (!matchedAudit) return null;

  const certsPool =
    state.domainData.allCertificadosDetailed.length > 0
      ? state.domainData.allCertificadosDetailed
      : INITIAL_CERTIFICADOS_DETAILED;
  const allProcessesPorSitio = certsPool.flatMap((c) =>
    c.sitios.flatMap((s) => s.procesos_por_sitio || [])
  );
  const allProcesses = certsPool.flatMap((c) => c.procesos as CandidateProcessEntity[]);
  const allTurnosPorSitio = certsPool.flatMap((c) =>
    c.sitios.flatMap((s) => s.turnos_por_sitio || [])
  );

  return buildAuditTurnoDetail({
    audit: matchedAudit,
    allAudits: auditsPool,
    allProcessesPorSitio,
    allProcesses,
    allTurnosPorSitio,
    certificados: certsPool,
  });
}

async function persistBatchShiftAssignments(
  targets: ReadonlyArray<BatchShiftAssignmentTarget>,
  auditId: string,
  successMessage: string
): Promise<PersistenceMutationResult<{ count: number }>> {
  if (targets.length === 0) {
    showFloatingToast('No hay asignaciones pendientes por aplicar.', 'info');
    return { ok: true, data: { count: 0 } };
  }

  const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
  if (!remoteSchemaReady) {
    const certsPool =
      state.domainData.allCertificadosDetailed.length > 0
        ? state.domainData.allCertificadosDetailed
        : INITIAL_CERTIFICADOS_DETAILED;
    const targetAudit =
      state.domainData.programacionAudits.find((a) => a.id === auditId) ||
      state.domainData.auditPrograms.flatMap((p) => p.auditorias).find((a) => a.id === auditId) ||
      null;
    const versionSnapshot = targetAudit
      ? resolveCertVersionSnapshotForAudit(targetAudit, certsPool)
      : null;
    const scopedTps =
      versionSnapshot && versionSnapshot.sitios.length > 0
        ? versionSnapshot.sitios.flatMap((s) => s.turnos_por_sitio || [])
        : certsPool.flatMap((c) => c.sitios.flatMap((s) => s.turnos_por_sitio || []));
    const tpsMetaById = new Map(scopedTps.map((t) => [t.id, t]));
    const byPsa = new Map<string, BatchShiftAssignmentTarget[]>();
    for (const t of targets) {
      const list = byPsa.get(t.psaId) ?? [];
      list.push(t);
      byPsa.set(t.psaId, list);
    }

    mutateLocalAuditSitiosPlan(auditId, (audit) =>
      (audit.sitiosPlan || []).map((sp) => ({
        ...sp,
        procesos: (sp.procesos || []).map((psa) => {
          const toAdd = byPsa.get(psa.id);
          if (!toAdd || toAdd.length === 0) return psa;
          const existingTpsSet = new Set(
            (psa.turnos || [])
              .filter((t) => !t.deleted_at)
              .map((t) => t.id_turnos_por_sitio || t.id_turnos_sitio_auditoria)
          );
          const appended = toAdd
            .filter((t) => !existingTpsSet.has(t.tpsId))
            .map((t) => {
              const meta = tpsMetaById.get(t.tpsId);
              return {
                id: crypto.randomUUID(),
                id_procesos_sitio_auditoria: psa.id,
                id_turnos_sitio_auditoria: crypto.randomUUID(),
                id_turnos_por_sitio: t.tpsId,
                descripcion_turno: meta?.descripcion || 'Turno Operativo',
                hora_entrada: meta?.hora_entrada,
                hora_salida: meta?.hora_salida,
                deleted_at: null,
              };
            });
          return appended.length > 0
            ? { ...psa, turnos: [...(psa.turnos || []), ...appended] }
            : psa;
        }),
      }))
    );
    recomputeLocalAuditPlanningDerivedState();
    showFloatingToast(successMessage, 'success');
    render();
    return { ok: true, data: { count: targets.length }, localFallback: true };
  }

  // Step 1: Resolve/ensure unique turnos_sitio_auditoria ID per (sitePlanId, tpsId)
  const uniquePairKeys = new Map<string, { sitePlanId: string; tpsId: string }>();
  for (const t of targets) {
    const validSaId = assertValidUuid(t.sitePlanId, 'sitio de auditoría');
    const validTpsId = assertValidUuid(t.tpsId, 'turno por sitio');
    uniquePairKeys.set(`${validSaId}::${validTpsId}`, {
      sitePlanId: validSaId,
      tpsId: validTpsId,
    });
  }

  const tsaIdByPairKey = new Map<string, string>();
  const siteIds = Array.from(new Set(Array.from(uniquePairKeys.values()).map((p) => p.sitePlanId)));
  const tpsIds = Array.from(new Set(Array.from(uniquePairKeys.values()).map((p) => p.tpsId)));

  const { data: existingTsaRows, error: tsaErr } = await supabase
    .from('turnos_sitio_auditoria')
    .select('id, id_sitios_por_auditoria, id_turnos_por_sitio, deleted_at')
    .in('id_sitios_por_auditoria', siteIds)
    .in('id_turnos_por_sitio', tpsIds);

  if (tsaErr) {
    const msg = formatZeroUuidError(tsaErr, 'No se pudieron consultar los turnos habilitados del sitio.');
    state.programaTurnosDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    render();
    return { ok: false, error: msg };
  }

  const tsaMap = new Map<string, { id: string; deleted_at: string | null }>();
  for (const row of (existingTsaRows || []) as Array<{
    id?: string;
    id_sitios_por_auditoria?: string;
    id_turnos_por_sitio?: string;
    deleted_at?: string | null;
  }>) {
    if (row.id && row.id_sitios_por_auditoria && row.id_turnos_por_sitio) {
      tsaMap.set(`${row.id_sitios_por_auditoria}::${row.id_turnos_por_sitio}`, {
        id: String(row.id),
        deleted_at: row.deleted_at ?? null,
      });
    }
  }

  const tsaIdsToRestore: string[] = [];
  const tsaToInsert: Array<{
    id: string;
    id_sitios_por_auditoria: string;
    id_turnos_por_sitio: string;
  }> = [];

  for (const [pairKey, pair] of uniquePairKeys.entries()) {
    const existing = tsaMap.get(pairKey);
    if (existing) {
      tsaIdByPairKey.set(pairKey, existing.id);
      if (existing.deleted_at) {
        tsaIdsToRestore.push(existing.id);
      }
    } else {
      const newId = crypto.randomUUID();
      tsaIdByPairKey.set(pairKey, newId);
      tsaToInsert.push({
        id: newId,
        id_sitios_por_auditoria: pair.sitePlanId,
        id_turnos_por_sitio: pair.tpsId,
      });
    }
  }

  if (tsaIdsToRestore.length > 0) {
    const { error: restoreTsaErr } = await supabase
      .from('turnos_sitio_auditoria')
      .update({ deleted_at: null, deleted_by: null })
      .in('id', tsaIdsToRestore);
    if (restoreTsaErr) {
      const msg = formatZeroUuidError(restoreTsaErr, 'No se pudieron reactivar los turnos del sitio.');
      state.programaTurnosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  }

  if (tsaToInsert.length > 0) {
    const { error: insTsaErr } = await supabase.from('turnos_sitio_auditoria').insert(tsaToInsert);
    if (insTsaErr) {
      const msg = formatZeroUuidError(insTsaErr, 'No se pudieron habilitar los turnos en los sitios.');
      state.programaTurnosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  }

  // Step 2: Restore or insert turnos_proceso_sitio_auditoria rows
  const allTsaIds = Array.from(new Set(tsaIdByPairKey.values()));
  const allPsaIds = Array.from(
    new Set(targets.map((t) => assertValidUuid(t.psaId, 'proceso en sitio de auditoría')))
  );

  const { data: existingTpsaRows, error: existingTpsaErr } = await supabase
    .from('turnos_proceso_sitio_auditoria')
    .select('id, id_procesos_sitio_auditoria, id_turnos_sitio_auditoria, deleted_at')
    .in('id_turnos_sitio_auditoria', allTsaIds)
    .in('id_procesos_sitio_auditoria', allPsaIds);

  if (existingTpsaErr) {
    const msg = formatZeroUuidError(
      existingTpsaErr,
      'No se pudieron consultar los turnos existentes en los procesos.'
    );
    state.programaTurnosDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    render();
    return { ok: false, error: msg };
  }

  const tpsaByComposite = new Map<string, { id: string; deleted_at: string | null }>();
  for (const r of (existingTpsaRows || []) as Array<{
    id?: string;
    id_procesos_sitio_auditoria?: string;
    id_turnos_sitio_auditoria?: string;
    deleted_at?: string | null;
  }>) {
    if (r.id && r.id_procesos_sitio_auditoria && r.id_turnos_sitio_auditoria) {
      tpsaByComposite.set(
        `${r.id_procesos_sitio_auditoria}::${r.id_turnos_sitio_auditoria}`,
        { id: String(r.id), deleted_at: r.deleted_at ?? null }
      );
    }
  }

  const toRestoreIds: string[] = [];
  const toInsertPayloads: Array<{
    id: string;
    id_procesos_sitio_auditoria: string;
    id_turnos_sitio_auditoria: string;
  }> = [];
  const seenInsertKeys = new Set<string>();

  for (const t of targets) {
    const validSaId = assertValidUuid(t.sitePlanId, 'sitio de auditoría');
    const validPsaId = assertValidUuid(t.psaId, 'proceso en sitio de auditoría');
    const validTpsId = assertValidUuid(t.tpsId, 'turno por sitio');
    const tsaId = tsaIdByPairKey.get(`${validSaId}::${validTpsId}`);
    if (!tsaId) continue;
    const compKey = `${validPsaId}::${tsaId}`;
    if (seenInsertKeys.has(compKey)) continue;
    seenInsertKeys.add(compKey);

    const existing = tpsaByComposite.get(compKey);
    if (existing) {
      if (existing.deleted_at) toRestoreIds.push(existing.id);
    } else {
      toInsertPayloads.push({
        id: crypto.randomUUID(),
        id_procesos_sitio_auditoria: validPsaId,
        id_turnos_sitio_auditoria: tsaId,
      });
    }
  }

  if (toRestoreIds.length > 0) {
    const { error: restoreErr } = await supabase
      .from('turnos_proceso_sitio_auditoria')
      .update({ deleted_at: null, deleted_by: null })
      .in('id', toRestoreIds);
    if (restoreErr) {
      const msg = formatZeroUuidError(
        restoreErr,
        'No se pudieron restaurar los turnos en los procesos.'
      );
      state.programaTurnosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  }

  if (toInsertPayloads.length > 0) {
    const { error: insertErr } = await supabase
      .from('turnos_proceso_sitio_auditoria')
      .insert(toInsertPayloads);
    if (insertErr) {
      const msg = formatZeroUuidError(
        insertErr,
        'No se pudieron guardar los turnos asignados en lote.'
      );
      state.programaTurnosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  }

  const appliedCount = toRestoreIds.length + toInsertPayloads.length;
  await loadLiveAudits();
  recordPhase5SessionLog('turnos_proceso_sitio_auditoria', auditId, 'INSERT', null, {
    accion: 'ASIGNACION_LOTE_TURNOS',
    cantidad: appliedCount,
  });
  showFloatingToast(successMessage, 'success');
  render();
  return { ok: true, data: { count: appliedCount } };
}

async function persistBatchShiftRemovals(
  removals: ReadonlyArray<ColumnShiftToggleTarget>,
  auditId: string,
  successMessage: string
): Promise<PersistenceMutationResult<{ count: number }>> {
  if (removals.length === 0) {
    return { ok: true, data: { count: 0 } };
  }

  const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
  if (!remoteSchemaReady) {
    const tpsaSet = new Set(
      removals.map((r) => r.tpsaRecordId).filter((id): id is string => Boolean(id))
    );
    const tpsByPsa = new Map<string, Set<string>>();
    for (const r of removals) {
      const set = tpsByPsa.get(r.psaId) ?? new Set<string>();
      set.add(r.tpsId);
      tpsByPsa.set(r.psaId, set);
    }

    mutateLocalAuditSitiosPlan(auditId, (audit) =>
      (audit.sitiosPlan || []).map((sp) => ({
        ...sp,
        procesos: (sp.procesos || []).map((psa) => {
          const targetTps = tpsByPsa.get(psa.id);
          if (!targetTps) return psa;
          return {
            ...psa,
            turnos: (psa.turnos || []).filter(
              (t) => !tpsaSet.has(t.id) && !targetTps.has(t.id_turnos_por_sitio || '')
            ),
          };
        }),
      }))
    );
    recomputeLocalAuditPlanningDerivedState();
    showFloatingToast(successMessage, 'info');
    render();
    return { ok: true, data: { count: removals.length }, localFallback: true };
  }

  for (const r of removals) {
    if (!r.tpsaRecordId) continue;
    const validTpsaId = assertValidUuid(r.tpsaRecordId, 'turno de proceso en auditoría');
    const { error: arcErr } = await supabase.rpc('archive_record', {
      p_table: 'turnos_proceso_sitio_auditoria',
      p_record_id: validTpsaId,
      p_reason: 'Desmarcado masivo por columna de turno (5. Turno)',
    });
    if (arcErr) {
      const msg = formatZeroUuidError(
        arcErr,
        'No se pudieron retirar los turnos seleccionados de la columna.'
      );
      state.programaTurnosDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  }

  await loadLiveAudits();
  recordPhase5SessionLog('turnos_proceso_sitio_auditoria', auditId, 'UPDATE', null, {
    accion: 'DESVINCULAR_COLUMNA_TURNO',
    cantidad: removals.length,
  });
  showFloatingToast(successMessage, 'info');
  render();
  return { ok: true, data: { count: removals.length } };
}

