export async function applyPrimaryShiftToPendingSiteProcesses(
  auditId: string,
  sitePlanId: string,
  primaryTurnoPorSitioId: string
): Promise<PersistenceMutationResult<{ count: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.programaDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  state.programaDomain.editErrorMessage = null;
  return runWithPlannerPreservedViewport(async () => {
    try {
      const validAuditId = assertValidUuid(auditId, 'auditoría');
      const validSaId = assertValidUuid(sitePlanId, 'sitio de auditoría');
      const validTpsId = assertValidUuid(primaryTurnoPorSitioId, 'turno principal del sitio');

      const auditsPool =
        state.domainData.programacionAudits.length > 0
          ? state.domainData.programacionAudits
          : state.domainData.auditPrograms.length > 0
          ? state.domainData.auditPrograms.flatMap((p) => p.auditorias)
          : buildSeededProgramsFallback().flatMap((p) => p.auditorias);

      const matchedAudit = auditsPool.find(
        (a) =>
          a.id === validAuditId &&
          (a.sitiosPlan || []).some((sp) => !sp.deleted_at && sp.id === validSaId)
      );
      const matchedSitePlan = matchedAudit?.sitiosPlan?.find(
        (sp) => !sp.deleted_at && sp.id === validSaId
      );

      if (!matchedAudit || !matchedSitePlan) {
        const msg = 'No se encontró el sitio dentro del programa de la auditoría.';
        state.programaDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        render();
        return { ok: false, error: msg };
      }

      const pendingProcs = (matchedSitePlan.procesos || []).filter(
        (p) => !p.deleted_at && (p.turnos || []).filter((t) => !t.deleted_at).length === 0
      );

      if (pendingProcs.length === 0) {
        showFloatingToast(
          'Todos los procesos de este sitio ya cuentan con al menos un turno asignado.',
          'info'
        );
        return { ok: true, data: { count: 0 } };
      }

      const pendingProcIds = pendingProcs.map((p) => p.id);
      const certsPool =
        state.domainData.allCertificadosDetailed.length > 0
          ? state.domainData.allCertificadosDetailed
          : INITIAL_CERTIFICADOS_DETAILED;
      const certDetail = certsPool.find((c) => c.id === matchedAudit.id_certificado);
      const tpsMeta = certDetail?.sitios
        .flatMap((s) => s.turnos_por_sitio || [])
        .find((t) => !t.deleted_at && t.id === validTpsId);

      const remoteSchemaReady = await isStep3RemoteSchemaAvailable();
      let useLocalFallback = !remoteSchemaReady;
      let tsaRows: unknown[] | null = null;

      if (!useLocalFallback) {
        const { data: queriedTsa, error: tsaErr } = await supabase
          .from('turnos_sitio_auditoria')
          .select('id, deleted_at')
          .eq('id_sitios_por_auditoria', validSaId)
          .eq('id_turnos_por_sitio', validTpsId)
          .order('created_at', { ascending: false })
          .limit(1);
        if (tsaErr) {
          if (!isMissingTableOrSchemaError(tsaErr)) {
            const msg = formatZeroUuidError(
              tsaErr,
              'No se pudo verificar el turno principal del sitio.'
            );
            state.programaDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning');
            render();
            return { ok: false, error: msg };
          }
          useLocalFallback = true;
        } else {
          tsaRows = queriedTsa;
        }
      }

      if (useLocalFallback) {
        const fallbackTsaId = crypto.randomUUID();
        mutateLocalAuditSitiosPlan(matchedAudit.id, (audit) =>
          (audit.sitiosPlan || []).map((sp) => {
            if (sp.id !== validSaId) return sp;
            return {
              ...sp,
              procesos: (sp.procesos || []).map((psa) => {
                if (!pendingProcIds.includes(psa.id)) return psa;
                const activeTurnos = (psa.turnos || []).filter((t) => !t.deleted_at);
                if (activeTurnos.length > 0) return psa;
                return {
                  ...psa,
                  turnos: [
                    ...(psa.turnos || []),
                    {
                      id: crypto.randomUUID(),
                      id_procesos_sitio_auditoria: psa.id,
                      id_turnos_sitio_auditoria: fallbackTsaId,
                      id_turnos_por_sitio: validTpsId,
                      descripcion_turno: tpsMeta?.descripcion || 'Turno Principal',
                      hora_entrada: tpsMeta?.hora_entrada,
                      hora_salida: tpsMeta?.hora_salida,
                      deleted_at: null,
                    },
                  ],
                };
              }),
            };
          })
        );
        recomputeLocalAuditPlanningDerivedState();
        showFloatingToast(
          `Turno principal aplicado a ${pendingProcIds.length} proceso(s) pendiente(s).`,
          'success'
        );
        render();
        return { ok: true, data: { count: pendingProcIds.length }, localFallback: true };
      }

      let turnosSitioAuditoriaId: string = crypto.randomUUID();
      const existingTsa = Array.isArray(tsaRows)
        ? (tsaRows[0] as { id?: string; deleted_at?: string | null } | undefined)
        : undefined;

      if (existingTsa?.id && !existingTsa.deleted_at) {
        turnosSitioAuditoriaId = assertValidUuid(existingTsa.id, 'turno en sitio de auditoría');
      } else if (existingTsa?.id && existingTsa.deleted_at) {
        const validOldTsaId = assertValidUuid(existingTsa.id, 'turno en sitio de auditoría');
        const { data: restoredTsa, error: restoreTsaErr } = await supabase
          .from('turnos_sitio_auditoria')
          .update({ deleted_at: null, deleted_by: null })
          .eq('id', validOldTsaId)
          .select('id')
          .single();
        if (!restoreTsaErr && restoredTsa?.id) {
          turnosSitioAuditoriaId = String(restoredTsa.id);
        } else {
          const { data: insTsa, error: insTsaErr } = await supabase
            .from('turnos_sitio_auditoria')
            .insert({
              id: turnosSitioAuditoriaId,
              id_sitios_por_auditoria: validSaId,
              id_turnos_por_sitio: validTpsId,
            })
            .select('id')
            .single();
          if (insTsaErr) {
            const msg = formatZeroUuidError(insTsaErr, 'No se pudo activar el turno principal.');
            state.programaDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning');
            render();
            return { ok: false, error: msg };
          }
          turnosSitioAuditoriaId = String(insTsa.id);
        }
      } else {
        const { data: insTsa, error: insTsaErr } = await supabase
          .from('turnos_sitio_auditoria')
          .insert({
            id: turnosSitioAuditoriaId,
            id_sitios_por_auditoria: validSaId,
            id_turnos_por_sitio: validTpsId,
          })
          .select('id')
          .single();
        if (insTsaErr) {
          const msg = formatZeroUuidError(insTsaErr, 'No se pudo activar el turno principal.');
          state.programaDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
        turnosSitioAuditoriaId = String(insTsa.id);
      }

      const { data: existingTpsaRows, error: existingTpsaErr } = await supabase
        .from('turnos_proceso_sitio_auditoria')
        .select('id, id_procesos_sitio_auditoria, deleted_at')
        .eq('id_turnos_sitio_auditoria', turnosSitioAuditoriaId)
        .in('id_procesos_sitio_auditoria', pendingProcIds);

      if (existingTpsaErr) {
        const msg = formatZeroUuidError(
          existingTpsaErr,
          'No se pudo consultar los turnos existentes en los procesos.'
        );
        state.programaDomain.editErrorMessage = msg;
        showFloatingToast(msg, 'warning');
        render();
        return { ok: false, error: msg };
      }

      const existingByProcId = new Map<string, { id: string; deleted_at: string | null }>();
      for (const r of (existingTpsaRows || []) as Array<{
        id?: string;
        id_procesos_sitio_auditoria?: string;
        deleted_at?: string | null;
      }>) {
        if (r.id && r.id_procesos_sitio_auditoria) {
          existingByProcId.set(String(r.id_procesos_sitio_auditoria), {
            id: String(r.id),
            deleted_at: r.deleted_at ?? null,
          });
        }
      }

      const toRestoreIds: string[] = [];
      const toInsertPayloads: Array<{
        id: string;
        id_procesos_sitio_auditoria: string;
        id_turnos_sitio_auditoria: string;
      }> = [];

      for (const procId of pendingProcIds) {
        const existing = existingByProcId.get(procId);
        if (existing) {
          if (existing.deleted_at) toRestoreIds.push(existing.id);
        } else {
          toInsertPayloads.push({
            id: crypto.randomUUID(),
            id_procesos_sitio_auditoria: procId,
            id_turnos_sitio_auditoria: turnosSitioAuditoriaId,
          });
        }
      }

      if (toRestoreIds.length > 0) {
        const { error: restoreErr } = await supabase
          .from('turnos_proceso_sitio_auditoria')
          .update({ deleted_at: null, deleted_by: null })
          .in('id', toRestoreIds);
        if (restoreErr) {
          const msg = formatZeroUuidError(
            restoreErr,
            'No se pudieron restaurar los turnos en los procesos.'
          );
          state.programaDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      if (toInsertPayloads.length > 0) {
        const { error: insertErr } = await supabase
          .from('turnos_proceso_sitio_auditoria')
          .insert(toInsertPayloads);
        if (insertErr) {
          const msg = formatZeroUuidError(
            insertErr,
            'No se pudieron asignar los turnos a los procesos.'
          );
          state.programaDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
      }

      const appliedCount = toRestoreIds.length + toInsertPayloads.length;
      await loadLiveAudits();
      recordPhase5SessionLog('turnos_proceso_sitio_auditoria', validSaId, 'INSERT', null, {
        accion: 'APLICAR_TURNO_PRINCIPAL_SITIO',
        cantidad: appliedCount,
      });
      showFloatingToast(
        `Turno principal aplicado a ${appliedCount} proceso(s) pendiente(s).`,
        'success'
      );
      render();
      return { ok: true, data: { count: appliedCount } };
    } catch (err) {
      const msg = formatZeroUuidError(err, 'No se pudo aplicar el turno principal del sitio.');
      state.programaDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }
  });
}

export async function upsertEquipoAuditorSitio(
  input: UpsertEquipoAuditorSitioInput
): Promise<PersistenceMutationResult<{ id: string; restored: boolean; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const built = validateAndBuildEquipoAuditorSitioPayload(input);
    if (!built.ok) {
      showFloatingToast(built.error, 'warning');
      return { ok: false, error: built.error };
    }

    const payload = built.value;
    let savedId: string = crypto.randomUUID();
    let restored = false;
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { data: existingRows, error: lookupErr } = await supabase
        .from('equipo_auditor_sitio')
        .select('id, deleted_at')
        .eq('id_sitios_por_auditoria', payload.id_sitios_por_auditoria)
        .eq('id_auditor', payload.id_auditor)
        .order('created_at', { ascending: false })
        .limit(1);

      if (lookupErr) {
        if (!isMissingTableOrSchemaError(lookupErr)) {
          const msg = formatZeroUuidError(
            lookupErr,
            'No se pudo consultar la asignación del auditor en el sitio.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else {
        const existing = Array.isArray(existingRows)
          ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
          : undefined;

        if (existing?.id) {
          const validExistingId = assertValidUuid(existing.id, 'asignación de auditor en sitio');
          const updateBody: Record<string, unknown> = {
            rol_auditor: payload.rol_auditor,
            tiempo_auditoria: payload.tiempo_auditoria,
            asignacion_completa_sitio: payload.asignacion_completa_sitio,
            updated_at: new Date().toISOString(),
          };
          if (existing.deleted_at) {
            updateBody.deleted_at = null;
            updateBody.deleted_by = null;
            restored = true;
          }

          const { data: updatedRow, error: updErr } = await supabase
            .from('equipo_auditor_sitio')
            .update(updateBody)
            .eq('id', validExistingId)
            .select('id')
            .single();

          if (!updErr && updatedRow?.id) {
            savedId = String(updatedRow.id);
          } else if (existing.deleted_at) {
            const { data: insRow, error: insErr } = await supabase
              .from('equipo_auditor_sitio')
              .insert({
                id: savedId,
                id_sitios_por_auditoria: payload.id_sitios_por_auditoria,
                id_auditor: payload.id_auditor,
                rol_auditor: payload.rol_auditor,
                tiempo_auditoria: payload.tiempo_auditoria,
                asignacion_completa_sitio: payload.asignacion_completa_sitio,
              })
              .select('id')
              .single();
            if (insErr) {
              const msg = formatZeroUuidError(insErr, 'No se pudo asignar el auditor al sitio.');
              showFloatingToast(msg, 'warning');
              return { ok: false, error: msg };
            }
            savedId = String(insRow.id);
            restored = false;
          } else {
            const msg = formatZeroUuidError(updErr, 'No se pudo actualizar los días del auditor.');
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
        } else {
          const { data: insRow, error: insErr } = await supabase
            .from('equipo_auditor_sitio')
            .insert({
              id: savedId,
              id_sitios_por_auditoria: payload.id_sitios_por_auditoria,
              id_auditor: payload.id_auditor,
              rol_auditor: payload.rol_auditor,
              tiempo_auditoria: payload.tiempo_auditoria,
              asignacion_completa_sitio: payload.asignacion_completa_sitio,
            })
            .select('id')
            .single();

          if (insErr) {
            if (!isMissingTableOrSchemaError(insErr)) {
              const msg = formatZeroUuidError(insErr, 'No se pudo asignar el auditor al sitio.');
              showFloatingToast(msg, 'warning');
              return { ok: false, error: msg };
            }
            localFallback = true;
          } else if (insertedRowId(insRow)) {
            savedId = String(insRow.id);
          }
        }
      }
    }

    const resolvedAuditId =
      payload.auditId || (await resolveAuditIdForSitioAuditoria(payload.id_sitios_por_auditoria));
    let totalAuditDays = 0;

    if (localFallback && resolvedAuditId) {
      const audMeta = (
        state.domainData.allAuditorsDetailed.length > 0
          ? state.domainData.allAuditorsDetailed
          : INITIAL_AUDITORES_DETAILED
      ).find((a) => a.id === payload.id_auditor);
      mutateLocalAuditSitiosPlan(resolvedAuditId, (audit) =>
        (audit.sitiosPlan || []).map((sp) => {
          if (sp.id !== payload.id_sitios_por_auditoria) return sp;
          const currentTeam = [...(sp.equipoSitio || [])];
          const existingIdx = currentTeam.findIndex(
            (m) => !m.deleted_at && m.id_auditor === payload.id_auditor
          );
          if (existingIdx >= 0) {
            savedId = currentTeam[existingIdx].id;
            currentTeam[existingIdx] = {
              ...currentTeam[existingIdx],
              rol_auditor: payload.rol_auditor,
              tiempo_auditoria: payload.tiempo_auditoria,
              asignacion_completa_sitio: payload.asignacion_completa_sitio,
            };
            return { ...sp, equipoSitio: currentTeam };
          }
          return {
            ...sp,
            equipoSitio: [
              ...currentTeam,
              {
                id: savedId,
                id_sitios_por_auditoria: payload.id_sitios_por_auditoria,
                id_auditor: payload.id_auditor,
                auditor_nombre: audMeta?.nombre || 'Auditor',
                rol_auditor: payload.rol_auditor,
                tiempo_auditoria: payload.tiempo_auditoria,
                asignacion_completa_sitio: payload.asignacion_completa_sitio,
                deleted_at: null,
              },
            ],
          };
        })
      );
    }

    if (resolvedAuditId) {
      if (!localFallback) {
        await syncEquipoAuditorCoherence(resolvedAuditId);
      }
      totalAuditDays = await recalculateAndPersistAuditTotalDays(resolvedAuditId, localFallback);
    }

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }

    recordPhase5SessionLog('equipo_auditor_sitio', savedId, restored ? 'UPDATE' : 'INSERT', null, {
      accion: 'ASIGNAR_AUDITOR_SITIO',
      rol_auditor: payload.rol_auditor,
      tiempo_auditoria: payload.tiempo_auditoria,
      asignacion_completa_sitio: payload.asignacion_completa_sitio,
    });

    showFloatingToast(
      `Auditor asignado al sitio (${payload.tiempo_auditoria.toFixed(2)} d).`,
      'success'
    );
    render();
    return {
      ok: true,
      data: { id: savedId, restored, totalAuditDays },
      restored,
      localFallback,
    };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar la asignación del auditor en sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

function insertedRowId(row: { id?: unknown } | null | undefined): row is { id: string } {
  return Boolean(row && typeof row.id === 'string' && row.id.length > 0);
}

export async function archiveEquipoAuditorSitio(
  equipoSitioId: string,
  auditId?: string | null,
  reason = 'Auditor retirado de la asignación del sitio'
): Promise<PersistenceMutationResult<{ id: string; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validEqSitioId = assertValidUuid(equipoSitioId, 'asignación de auditor en sitio');
    let resolvedAuditId =
      auditId && auditId.trim() !== '' ? assertValidUuid(auditId, 'auditoría') : null;

    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!resolvedAuditId && !localFallback) {
      const { data: eqRow } = await supabase
        .from('equipo_auditor_sitio')
        .select('id_sitios_por_auditoria')
        .eq('id', validEqSitioId)
        .maybeSingle();
      if (eqRow?.id_sitios_por_auditoria && isValidUuid(eqRow.id_sitios_por_auditoria)) {
        resolvedAuditId = await resolveAuditIdForSitioAuditoria(
          String(eqRow.id_sitios_por_auditoria)
        );
      }
    } else if (!resolvedAuditId) {
      for (const audit of state.domainData.programacionAudits) {
        if (
          (audit.sitiosPlan || []).some((sp) =>
            (sp.equipoSitio || []).some((m) => m.id === validEqSitioId)
          )
        ) {
          resolvedAuditId = audit.id;
          break;
        }
      }
    }

    if (!localFallback) {
      const { error: arcErr } = await supabase.rpc('archive_record', {
        p_table: 'equipo_auditor_sitio',
        p_record_id: validEqSitioId,
        p_reason: sanitizeArchiveReason(reason) || 'Auditor retirado de la asignación del sitio',
      });

      if (arcErr) {
        if (!isMissingTableOrSchemaError(arcErr)) {
          const msg = formatZeroUuidError(arcErr, 'No se pudo retirar el auditor del sitio.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    let totalAuditDays = 0;
    if (localFallback && resolvedAuditId) {
      mutateLocalAuditSitiosPlan(resolvedAuditId, (audit) =>
        (audit.sitiosPlan || []).map((sp) => ({
          ...sp,
          equipoSitio: (sp.equipoSitio || []).filter((m) => m.id !== validEqSitioId),
        }))
      );
    }
    if (resolvedAuditId) {
      if (!localFallback) {
        await syncEquipoAuditorCoherence(resolvedAuditId);
      }
      totalAuditDays = await recalculateAndPersistAuditTotalDays(resolvedAuditId, localFallback);
    }

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }

    recordPhase5SessionLog('equipo_auditor_sitio', validEqSitioId, 'UPDATE', null, {
      accion: 'RETIRAR_AUDITOR_SITIO',
    });
    showFloatingToast('Auditor retirado del sitio.', 'info');
    render();
    return { ok: true, data: { id: validEqSitioId, totalAuditDays }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo retirar el auditor del sitio.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

export async function upsertRegularSiteAuditor(
  input: UpsertEquipoAuditorSitioInput
): Promise<PersistenceMutationResult<{ id: string; restored: boolean; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.asignacionDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  if (state.domainData.auditPrograms.length === 0 && isApprovedStaff()) {
    state.domainData.auditPrograms = buildSeededProgramsFallback();
  }
  const programsPool = state.domainData.auditPrograms;
  let matchedSite: AuditoriaSitioPlanItem | undefined;
  for (const p of programsPool) {
    for (const a of p.auditorias) {
      if (a.deleted_at) continue;
      const found = (a.sitiosPlan || []).find((sp) => !sp.deleted_at && sp.id === input.sitioAuditoriaId);
      if (found) {
        matchedSite = found;
        break;
      }
    }
    if (matchedSite) break;
  }
  if (!matchedSite) {
    for (const a of state.domainData.programacionAudits) {
      if (a.deleted_at) continue;
      const found = (a.sitiosPlan || []).find(
        (sp) => !sp.deleted_at && sp.id === input.sitioAuditoriaId
      );
      if (found) {
        matchedSite = found;
        break;
      }
    }
  }

  if (matchedSite) {
    const otherSum = roundAuditDaysQuarter(
      (matchedSite.equipoSitio || [])
        .filter((m) => !m.deleted_at && m.id_auditor !== input.auditorId)
        .reduce((sum, m) => sum + m.tiempo_auditoria, 0)
    );
    const validationErr = validateAuditorTimeAssignment(
      input.auditorId,
      input.tiempo_auditoria,
      input.rol_auditor,
      roundAuditDaysQuarter(matchedSite.tiempo_auditoria),
      otherSum
    );
    if (validationErr) {
      state.asignacionDomain.editErrorMessage = validationErr;
      showFloatingToast(validationErr, 'warning');
      render();
      return { ok: false, error: validationErr };
    }
  }

  const res = await upsertEquipoAuditorSitio(input);
  if (res.ok) {
    state.asignacionDomain.draftTargetId = null;
    state.asignacionDomain.editErrorMessage = null;
    render();
  } else {
    state.asignacionDomain.editErrorMessage = res.error ?? 'No se pudo asignar el auditor al sitio.';
    render();
  }
  return res;
}

export async function archiveRegularSiteAuditor(
  equipoSitioId: string,
  auditId?: string | null,
  reason = 'Auditor retirado desde 3. Auditor'
): Promise<PersistenceMutationResult<{ id: string; totalAuditDays: number }>> {
  const res = await archiveEquipoAuditorSitio(equipoSitioId, auditId, reason);
  if (res.ok) {
    state.asignacionDomain.editErrorMessage = null;
  } else {
    state.asignacionDomain.editErrorMessage = res.error ?? 'No se pudo retirar el auditor del sitio.';
  }
  render();
  return res;
}

export interface UpsertTemporalSiteAuditorInput {
  temporalSiteId: string;
  auditorId: string;
  rol_auditor: AuditorSiteRole;
  tiempo_auditoria: number;
  auditId?: string | null;
}

export async function upsertTemporalSiteAuditor(
  input: UpsertTemporalSiteAuditorInput
): Promise<PersistenceMutationResult<{ id: string; restored: boolean }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.asignacionDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validTempSiteId = assertValidUuid(input.temporalSiteId, 'sitio temporal');
    const validAuditorId = assertValidUuid(input.auditorId, 'auditor');
    const matchedTemp = state.domainData.allTemporalSites.find(
      (t) => !t.deleted_at && t.id === validTempSiteId
    );
    if (!matchedTemp) {
      const msg = 'No se encontró el sitio temporal seleccionado.';
      state.asignacionDomain.editErrorMessage = msg;
      showFloatingToast(msg, 'warning');
      render();
      return { ok: false, error: msg };
    }

    const otherSum = roundAuditDaysQuarter(
      (matchedTemp.equipoTemporal || [])
        .filter((m) => !m.deleted_at && m.id_auditor !== validAuditorId)
        .reduce((sum, m) => sum + m.tiempo_auditoria, 0)
    );
    const validationErr = validateAuditorTimeAssignment(
      validAuditorId,
      input.tiempo_auditoria,
      input.rol_auditor,
      roundAuditDaysQuarter(matchedTemp.tiempo_auditoria),
      otherSum
    );
    if (validationErr) {
      state.asignacionDomain.editErrorMessage = validationErr;
      showFloatingToast(validationErr, 'warning');
      render();
      return { ok: false, error: validationErr };
    }

    const normalizedDays = roundAuditDaysQuarter(input.tiempo_auditoria);
    let savedId: string = crypto.randomUUID();
    let restored = false;
    let localFallback = !(await isStep3RemoteSchemaAvailable());

    if (!localFallback) {
      const { data: existingRows, error: lookupErr } = await supabase
        .from('equipo_auditor_sitio_temporal')
        .select('id, deleted_at')
        .eq('id_sitio_temporal', validTempSiteId)
        .eq('id_auditor', validAuditorId)
        .order('created_at', { ascending: false })
        .limit(1);

      if (lookupErr) {
        if (!isMissingTableOrSchemaError(lookupErr)) {
          const msg = formatZeroUuidError(
            lookupErr,
            'No se pudo consultar la asignación del auditor en el sitio temporal.'
          );
          state.asignacionDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
        localFallback = true;
      } else {
        const existing = Array.isArray(existingRows)
          ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
          : undefined;

        if (existing?.id) {
          const validExistingId = assertValidUuid(existing.id, 'asignación temporal');
          const updateBody: Record<string, unknown> = {
            rol_auditor: input.rol_auditor,
            tiempo_auditoria: normalizedDays,
            updated_at: new Date().toISOString(),
          };
          if (existing.deleted_at) {
            updateBody.deleted_at = null;
            updateBody.deleted_by = null;
            restored = true;
          }
          const { data: updRow, error: updErr } = await supabase
            .from('equipo_auditor_sitio_temporal')
            .update(updateBody)
            .eq('id', validExistingId)
            .select('id')
            .single();

          if (!updErr && updRow?.id) {
            savedId = String(updRow.id);
          } else if (existing.deleted_at) {
            const { data: insRow, error: insErr } = await supabase
              .from('equipo_auditor_sitio_temporal')
              .insert({
                id: savedId,
                id_sitio_temporal: validTempSiteId,
                id_auditor: validAuditorId,
                rol_auditor: input.rol_auditor,
                tiempo_auditoria: normalizedDays,
              })
              .select('id')
              .single();
            if (insErr) {
              const msg = formatZeroUuidError(
                insErr,
                'No se pudo asignar el auditor al sitio temporal.'
              );
              state.asignacionDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning');
              render();
              return { ok: false, error: msg };
            }
            savedId = String(insRow.id);
            restored = false;
          } else {
            const msg = formatZeroUuidError(
              updErr,
              'No se pudo actualizar los días del auditor en el sitio temporal.'
            );
            state.asignacionDomain.editErrorMessage = msg;
            showFloatingToast(msg, 'warning');
            render();
            return { ok: false, error: msg };
          }
        } else {
          const { data: insRow, error: insErr } = await supabase
            .from('equipo_auditor_sitio_temporal')
            .insert({
              id: savedId,
              id_sitio_temporal: validTempSiteId,
              id_auditor: validAuditorId,
              rol_auditor: input.rol_auditor,
              tiempo_auditoria: normalizedDays,
            })
            .select('id')
            .single();
          if (insErr) {
            if (!isMissingTableOrSchemaError(insErr)) {
              const msg = formatZeroUuidError(
                insErr,
                'No se pudo asignar el auditor al sitio temporal.'
              );
              state.asignacionDomain.editErrorMessage = msg;
              showFloatingToast(msg, 'warning');
              render();
              return { ok: false, error: msg };
            }
            localFallback = true;
          } else if (insertedRowId(insRow)) {
            savedId = String(insRow.id);
          }
        }
      }
    }

    if (localFallback) {
      if (state.domainData.auditPrograms.length === 0) {
        state.domainData.auditPrograms = buildSeededProgramsFallback();
      }
      const audMeta = (
        state.domainData.allAuditorsDetailed.length > 0
          ? state.domainData.allAuditorsDetailed
          : INITIAL_AUDITORES_DETAILED
      ).find((a) => a.id === validAuditorId);

      state.domainData.allTemporalSites = state.domainData.allTemporalSites.map((t) => {
        if (t.id !== validTempSiteId) return t;
        const currentTeam = [...(t.equipoTemporal || [])];
        const existingIdx = currentTeam.findIndex(
          (m) => !m.deleted_at && m.id_auditor === validAuditorId
        );
        if (existingIdx >= 0) {
          savedId = currentTeam[existingIdx].id;
          currentTeam[existingIdx] = {
            ...currentTeam[existingIdx],
            rol_auditor: input.rol_auditor,
            tiempo_auditoria: normalizedDays,
          };
          return { ...t, equipoTemporal: currentTeam };
        }
        return {
          ...t,
          equipoTemporal: [
            ...currentTeam,
            {
              id: savedId,
              id_sitio_temporal: validTempSiteId,
              id_auditor: validAuditorId,
              auditor_nombre: audMeta?.nombre || 'Auditor',
              rol_auditor: input.rol_auditor,
              tiempo_auditoria: normalizedDays,
              deleted_at: null,
            },
          ],
        };
      });
      recomputeLocalAuditPlanningDerivedState();
    } else {
      const affectedAuditIds = Array.from(
        new Set(
          [
            matchedTemp.id_auditoria,
            ...(input.auditId ? [input.auditId] : []),
            ...matchedTemp.certificados
              .filter((cl) => !cl.deleted_at)
              .map((cl) => cl.id_auditoria_certificado),
          ].filter((id) => isValidUuid(id))
        )
      );
      for (const aid of affectedAuditIds) {
        await syncEquipoAuditorCoherence(aid);
      }
      await loadLiveAudits();
    }

    state.asignacionDomain.draftTargetId = null;
    state.asignacionDomain.editErrorMessage = null;
    recordPhase5SessionLog(
      'equipo_auditor_sitio_temporal',
      savedId,
      restored ? 'UPDATE' : 'INSERT',
      null,
      {
        accion: 'ASIGNAR_AUDITOR_SITIO_TEMPORAL',
        rol_auditor: input.rol_auditor,
        tiempo_auditoria: normalizedDays,
      }
    );
    showFloatingToast(
      `Auditor asignado al sitio temporal (${normalizedDays.toFixed(2)} d).`,
      'success'
    );
    render();
    return { ok: true, data: { id: savedId, restored }, restored, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(
      err,
      'No se pudo guardar la asignación del auditor en el sitio temporal.'
    );
    state.asignacionDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    render();
    return { ok: false, error: msg };
  }
}

export async function archiveTemporalSiteAuditor(
  equipoTemporalId: string,
  temporalSiteId?: string | null,
  auditId?: string | null,
  reason = 'Auditor retirado del sitio temporal'
): Promise<PersistenceMutationResult<{ id: string }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    state.asignacionDomain.editErrorMessage = staffCheck.error;
    showFloatingToast(staffCheck.error, 'warning');
    render();
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validEqTempId = assertValidUuid(equipoTemporalId, 'asignación de auditor temporal');
    const matchedTemp = state.domainData.allTemporalSites.find((t) =>
      (temporalSiteId ? t.id === temporalSiteId : true) &&
      (t.equipoTemporal || []).some((m) => m.id === validEqTempId)
    );

    let localFallback = !(await isStep3RemoteSchemaAvailable());
    if (!localFallback) {
      const { error: arcErr } = await supabase.rpc('archive_record', {
        p_table: 'equipo_auditor_sitio_temporal',
        p_record_id: validEqTempId,
        p_reason: sanitizeArchiveReason(reason) || 'Auditor retirado del sitio temporal',
      });

      if (arcErr) {
        if (!isMissingTableOrSchemaError(arcErr)) {
          const msg = formatZeroUuidError(
            arcErr,
            'No se pudo retirar el auditor del sitio temporal.'
          );
          state.asignacionDomain.editErrorMessage = msg;
          showFloatingToast(msg, 'warning');
          render();
          return { ok: false, error: msg };
        }
        localFallback = true;
      }
    }

    if (localFallback) {
      state.domainData.allTemporalSites = state.domainData.allTemporalSites.map((t) => ({
        ...t,
        equipoTemporal: (t.equipoTemporal || []).filter((m) => m.id !== validEqTempId),
      }));
      recomputeLocalAuditPlanningDerivedState();
    } else {
      const affectedAuditIds = Array.from(
        new Set(
          [
            ...(matchedTemp ? [matchedTemp.id_auditoria] : []),
            ...(auditId ? [auditId] : []),
            ...(matchedTemp
              ? matchedTemp.certificados
                  .filter((cl) => !cl.deleted_at)
                  .map((cl) => cl.id_auditoria_certificado)
              : []),
          ].filter((id) => isValidUuid(id))
        )
      );
      for (const aid of affectedAuditIds) {
        await syncEquipoAuditorCoherence(aid);
      }
      await loadLiveAudits();
    }

    state.asignacionDomain.editErrorMessage = null;
    recordPhase5SessionLog('equipo_auditor_sitio_temporal', validEqTempId, 'UPDATE', null, {
      accion: 'RETIRAR_AUDITOR_SITIO_TEMPORAL',
    });
    showFloatingToast('Auditor retirado del sitio temporal.', 'info');
    render();
    return { ok: true, data: { id: validEqTempId }, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo retirar el auditor del sitio temporal.');
    state.asignacionDomain.editErrorMessage = msg;
    showFloatingToast(msg, 'warning');
    render();
    return { ok: false, error: msg };
  }
}

export async function toggleEquipoAuditorProcesoSitio(
  procesoSitioAuditoriaId: string,
  auditorId: string,
  rolEnProceso: AuditorProcessRole = 'EVALUADOR',
  auditId?: string | null
): Promise<PersistenceMutationResult<{ id: string; active: boolean; totalAuditDays: number }>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const built = validateAndBuildEquipoAuditorProcesoPayload(
      procesoSitioAuditoriaId,
      auditorId,
      rolEnProceso
    );
    if (!built.ok) {
      showFloatingToast(built.error, 'warning');
      return { ok: false, error: built.error };
    }
    const payload = built.value;
    const validExplicitAuditId =
      auditId && auditId.trim() !== '' ? assertValidUuid(auditId, 'auditoría') : null;

    const { data: existingRows, error: lookupErr } = await supabase
      .from('equipo_auditor_proceso_sitio')
      .select('id, deleted_at')
      .eq('id_procesos_sitio_auditoria', payload.id_procesos_sitio_auditoria)
      .eq('id_auditor', payload.id_auditor)
      .order('created_at', { ascending: false })
      .limit(1);

    let localFallback = false;
    let savedId: string = crypto.randomUUID();
    let active = true;
    let restored = false;

    if (lookupErr) {
      if (!isMissingTableOrSchemaError(lookupErr)) {
        const msg = formatZeroUuidError(
          lookupErr,
          'No se pudo consultar la asignación del auditor en el proceso.'
        );
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      localFallback = true;
    } else {
      const existing = Array.isArray(existingRows)
        ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
        : undefined;

      if (existing?.id && !existing.deleted_at) {
        const validExistingId = assertValidUuid(existing.id, 'asignación de auditor en proceso');
        const { error: arcErr } = await supabase.rpc('archive_record', {
          p_table: 'equipo_auditor_proceso_sitio',
          p_record_id: validExistingId,
          p_reason: 'Auditor desvinculado de proceso específico',
        });
        if (arcErr) {
          const msg = formatZeroUuidError(arcErr, 'No se pudo retirar al auditor del proceso.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        savedId = validExistingId;
        active = false;
      } else if (existing?.id && existing.deleted_at) {
        const validExistingId = assertValidUuid(existing.id, 'asignación de auditor en proceso');
        const { data: restoredRow, error: restoreErr } = await supabase
          .from('equipo_auditor_proceso_sitio')
          .update({
            deleted_at: null,
            deleted_by: null,
            rol_en_proceso: payload.rol_en_proceso,
          })
          .eq('id', validExistingId)
          .select('id')
          .single();
        if (!restoreErr && restoredRow?.id) {
          savedId = String(restoredRow.id);
          restored = true;
        } else {
          const { data: insRow, error: insErr } = await supabase
            .from('equipo_auditor_proceso_sitio')
            .insert({ id: savedId, ...payload })
            .select('id')
            .single();
          if (insErr) {
            const msg = formatZeroUuidError(insErr, 'No se pudo asignar el auditor al proceso.');
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          savedId = String(insRow.id);
        }
      } else {
        const { data: insRow, error: insErr } = await supabase
          .from('equipo_auditor_proceso_sitio')
          .insert({ id: savedId, ...payload })
          .select('id')
          .single();
        if (insErr) {
          const msg = formatZeroUuidError(insErr, 'No se pudo asignar el auditor al proceso.');
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
        savedId = String(insRow.id);
      }
    }

    const resolvedAuditId =
      validExplicitAuditId ||
      (await resolveAuditIdForProcesoSitioAuditoria(payload.id_procesos_sitio_auditoria));
    let totalAuditDays = 0;

    if (localFallback && resolvedAuditId) {
      const audMeta = (
        state.domainData.allAuditorsDetailed.length > 0
          ? state.domainData.allAuditorsDetailed
          : INITIAL_AUDITORES_DETAILED
      ).find((a) => a.id === payload.id_auditor);
      mutateLocalAuditSitiosPlan(resolvedAuditId, (audit) =>
        (audit.sitiosPlan || []).map((sp) => ({
          ...sp,
          procesos: (sp.procesos || []).map((psa) => {
            if (psa.id !== payload.id_procesos_sitio_auditoria) return psa;
            const currentEq = [...(psa.equipoProceso || [])];
            const existingIdx = currentEq.findIndex(
              (m) => !m.deleted_at && m.id_auditor === payload.id_auditor
            );
            if (existingIdx >= 0) {
              active = false;
              savedId = currentEq[existingIdx].id;
              return {
                ...psa,
                equipoProceso: currentEq.filter((_, i) => i !== existingIdx),
              };
            }
            active = true;
            return {
              ...psa,
              equipoProceso: [
                ...currentEq,
                {
                  id: savedId,
                  id_procesos_sitio_auditoria: payload.id_procesos_sitio_auditoria,
                  id_auditor: payload.id_auditor,
                  auditor_nombre: audMeta?.nombre || 'Auditor',
                  rol_en_proceso: payload.rol_en_proceso,
                  deleted_at: null,
                },
              ],
            };
          }),
        }))
      );
    }

    if (resolvedAuditId) {
      if (!localFallback) {
        await syncEquipoAuditorCoherence(resolvedAuditId);
      }
      totalAuditDays = await recalculateAndPersistAuditTotalDays(resolvedAuditId, localFallback);
    }

    if (!localFallback) {
      await loadLiveAudits();
    } else {
      recomputeLocalAuditPlanningDerivedState();
    }

    recordPhase5SessionLog(
      'equipo_auditor_proceso_sitio',
      savedId,
      restored || !active ? 'UPDATE' : 'INSERT',
      null,
      {
        accion: active ? 'ASIGNAR_AUDITOR_PROCESO_MN' : 'RETIRAR_AUDITOR_PROCESO_MN',
        rol_en_proceso: payload.rol_en_proceso,
      }
    );

    showFloatingToast(
      active
        ? 'Auditor asignado al proceso correctamente.'
        : 'Auditor desvinculado del proceso.',
      active ? 'success' : 'info'
    );
    render();
    return { ok: true, data: { id: savedId, active, totalAuditDays }, restored, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(
      err,
      'No se pudo actualizar la asignación del auditor en el proceso.'
    );
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

/**
 * 5. Configuración de Alertas (`saveAlertConfigSettings`)
 */
export async function saveAlertConfigSettings(
  input: SaveAlertConfigInput
): Promise<PersistenceMutationResult<AlertConfigEntity>> {
  const staffCheck = assertApprovedStaffForMutation(state.profile);
  if (!staffCheck.ok) {
    showFloatingToast(staffCheck.error, 'warning');
    return { ok: false, error: staffCheck.error };
  }

  try {
    const validated = validateAndNormalizeAlertConfigInput(input);
    if (!validated.ok) {
      showFloatingToast(validated.error, 'warning');
      return { ok: false, error: validated.error };
    }

    const normalized = validated.value;
    const validActorId =
      state.user?.id && isValidUuid(state.user.id)
        ? assertValidUuid(state.user.id, 'usuario')
        : null;

    let savedId = state.domainData.auditAlertConfig.id || crypto.randomUUID();
    let localFallback = false;

    const { data: existingRows, error: lookupErr } = await supabase
      .from('configuracion_alerta_auditoria')
      .select('id, deleted_at')
      .eq('clave', 'DEFAULT')
      .order('created_at', { ascending: false })
      .limit(1);

    if (lookupErr) {
      if (!isMissingTableOrSchemaError(lookupErr)) {
        const msg = formatZeroUuidError(
          lookupErr,
          'No se pudo consultar la configuración actual de alertas.'
        );
        showFloatingToast(msg, 'warning');
        return { ok: false, error: msg };
      }
      localFallback = true;
    } else {
      const existing = Array.isArray(existingRows)
        ? (existingRows[0] as { id?: string; deleted_at?: string | null } | undefined)
        : undefined;

      const dbPayloadBase: Record<string, unknown> = {
        clave: normalized.clave,
        dias_aviso_proxima: normalized.dias_aviso_proxima,
        dias_aviso_preprogramada_sin_confirmar: normalized.dias_aviso_preprogramada_sin_confirmar,
        alertar_atrasadas: normalized.alertar_atrasadas,
        alertar_conflicto_auditor: normalized.alertar_conflicto_auditor,
        alertar_desfase_dias_o_span: normalized.alertar_desfase_dias_o_span,
        ciclos_rotacion_auditor_lider: normalized.ciclos_rotacion_auditor_lider,
        alertas_activas: normalized.alertas_activas,
        updated_by: validActorId,
        updated_at: new Date().toISOString(),
      };
      const dbPayload: Record<string, unknown> = {
        ...dbPayloadBase,
        dias_limite_plan_nc: normalized.dias_limite_plan_nc,
        dias_limite_plan_accion: normalized.dias_limite_plan_accion,
        dias_limite_cierre_nc: normalized.dias_limite_cierre_nc,
      };

      if (existing?.id) {
        const validExistingId = assertValidUuid(existing.id, 'configuración de alertas');
        if (existing.deleted_at) {
          dbPayload.deleted_at = null;
          dbPayload.deleted_by = null;
          dbPayloadBase.deleted_at = null;
          dbPayloadBase.deleted_by = null;
        }
        let { data: updatedRow, error: updErr } = await supabase
          .from('configuracion_alerta_auditoria')
          .update(dbPayload)
          .eq('id', validExistingId)
          .select('id')
          .single();
        if (updErr && isMissingTableOrSchemaError(updErr)) {
          const fallbackUpd = await supabase
            .from('configuracion_alerta_auditoria')
            .update(dbPayloadBase)
            .eq('id', validExistingId)
            .select('id')
            .single();
          updatedRow = fallbackUpd.data;
          updErr = fallbackUpd.error;
        }

        if (!updErr && updatedRow?.id) {
          savedId = String(updatedRow.id);
        } else if (existing.deleted_at) {
          const newId = crypto.randomUUID();
          let { data: insRow, error: insErr } = await supabase
            .from('configuracion_alerta_auditoria')
            .insert({ id: newId, ...dbPayload })
            .select('id')
            .single();
          if (insErr && isMissingTableOrSchemaError(insErr)) {
            const fallbackIns = await supabase
              .from('configuracion_alerta_auditoria')
              .insert({ id: newId, ...dbPayloadBase })
              .select('id')
              .single();
            insRow = fallbackIns.data;
            insErr = fallbackIns.error;
          }
          if (insErr) {
            const msg = formatZeroUuidError(
              insErr,
              'No se pudo guardar la configuración de alertas.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          savedId = String(insRow!.id);
        } else {
          const msg = formatZeroUuidError(
            updErr,
            'No se pudo actualizar la configuración de alertas.'
          );
          showFloatingToast(msg, 'warning');
          return { ok: false, error: msg };
        }
      } else {
        const newId = isValidUuid(savedId) ? savedId : crypto.randomUUID();
        let { data: insRow, error: insErr } = await supabase
          .from('configuracion_alerta_auditoria')
          .insert({ id: newId, ...dbPayload })
          .select('id')
          .single();
        if (insErr && isMissingTableOrSchemaError(insErr)) {
          const fallbackIns = await supabase
            .from('configuracion_alerta_auditoria')
            .insert({ id: newId, ...dbPayloadBase })
            .select('id')
            .single();
          insRow = fallbackIns.data;
          insErr = fallbackIns.error;
        }
        if (insErr) {
          if (!isMissingTableOrSchemaError(insErr)) {
            const msg = formatZeroUuidError(
              insErr,
              'No se pudo guardar la configuración de alertas.'
            );
            showFloatingToast(msg, 'warning');
            return { ok: false, error: msg };
          }
          localFallback = true;
        } else if (insRow?.id) {
          savedId = String(insRow.id);
        }
      }
    }

    const oldSnapshot = { ...state.domainData.auditAlertConfig };
    const nextConfig: AlertConfigEntity = {
      id: savedId,
      ...normalized,
    };

    state.domainData.auditAlertConfig = nextConfig;
    state.domainData.auditAlerts = computeAuditAlerts(
      state.domainData.auditPrograms,
      nextConfig
    );
    resyncLocalOpenNcDeadlines(nextConfig);

    recordPhase5SessionLog(
      'configuracion_alerta_auditoria',
      savedId,
      'UPDATE',
      oldSnapshot,
      {
        dias_aviso_proxima: nextConfig.dias_aviso_proxima,
        dias_aviso_preprogramada_sin_confirmar:
          nextConfig.dias_aviso_preprogramada_sin_confirmar,
        alertar_atrasadas: nextConfig.alertar_atrasadas,
        alertar_conflicto_auditor: nextConfig.alertar_conflicto_auditor,
        alertar_desfase_dias_o_span: nextConfig.alertar_desfase_dias_o_span,
        ciclos_rotacion_auditor_lider: nextConfig.ciclos_rotacion_auditor_lider,
        alertas_activas: nextConfig.alertas_activas,
        dias_limite_plan_nc: nextConfig.dias_limite_plan_nc,
        dias_limite_plan_accion: nextConfig.dias_limite_plan_accion,
        dias_limite_cierre_nc: nextConfig.dias_limite_cierre_nc,
      }
    );

    showFloatingToast(
      `Configuración de alertas guardada (${state.domainData.auditAlerts.length} alerta(s) activa(s) recalculada(s)).`,
      'success'
    );
    render();
    return { ok: true, data: nextConfig, localFallback };
  } catch (err) {
    const msg = formatZeroUuidError(err, 'No se pudo guardar la configuración de alertas.');
    showFloatingToast(msg, 'warning');
    return { ok: false, error: msg };
  }
}

async function loadApprovalProfiles(): Promise<void> {
  if (!isApprovedStaff()) return;

  state.approvals.loading = true;
  state.approvals.errorMessage = null;
  render();

  const { data, error } = await supabase
    .from('profiles')
    .select('id, nombre, role, status, created_at')
    .order('created_at', { ascending: false });

  state.approvals.loading = false;
  if (error) {
    state.approvals.errorMessage = translateDatabaseError(error);
  } else {
    state.approvals.profiles = (data as UserProfile[]) || [];
  }
  render();
}

async function updateProfileStatus(targetId: string, status: UserStatus): Promise<void> {
  if (!isApprovedAdmin()) return;

  state.approvals.updatingId = targetId;
  state.approvals.errorMessage = null;
  state.approvals.successMessage = null;
  render();

  const { error } = await supabase
    .from('profiles')
    .update({ status })
    .eq('id', targetId);

  state.approvals.updatingId = null;

  if (error) {
    state.approvals.errorMessage = translateDatabaseError(error);
    render();
    return;
  }

  const target = state.approvals.profiles.find((p) => p.id === targetId);
  state.approvals.successMessage = target
    ? `Updated status for ${target.nombre} to ${status}.`
    : `Updated user status to ${status}.`;
  await loadApprovalProfiles();
}

async function updateProfileRole(targetId: string, nextRole: string): Promise<void> {
  if (!isApprovedAdmin() || !state.user) return;

  const target = state.approvals.profiles.find((p) => p.id === targetId);
  if (!target) return;

  if (!canModifyProfileRole(target.id, state.user.id, target.status)) {
    return;
  }

  if (!shouldUpdateProfileRole(target.role, nextRole)) {
    return;
  }

  state.approvals.updatingId = targetId;
  state.approvals.errorMessage = null;
  state.approvals.successMessage = null;
  render();

  const { error } = await supabase
    .from('profiles')
    .update({ role: nextRole })
    .eq('id', targetId);

  state.approvals.updatingId = null;

  if (error) {
    state.approvals.errorMessage = translateDatabaseError(error);
    render();
    return;
  }

  state.approvals.successMessage = `Changed role for ${target.nombre} to ${nextRole}.`;
  await loadApprovalProfiles();
}

async function handleUpdateOwnProfile(rawNombre: string): Promise<void> {
  if (!state.user || !state.profile || state.profileForm.savingProfile) return;

  const validation = buildSelfProfileUpdatePayload(rawNombre);
  if (!validation.ok) {
    state.profileForm = {
      ...state.profileForm,
      nombreInput: rawNombre,
      profileError: validation.error,
      profileFeedback: null,
    };
    render();
    return;
  }

  state.profileForm = {
    ...state.profileForm,
    nombreInput: validation.payload.nombre,
    savingProfile: true,
    profileError: null,
    profileFeedback: null,
  };
  render();

  const { data, error } = await supabase
    .from('profiles')
    .update(validation.payload)
    .eq('id', state.user.id)
    .select('id, nombre, role, status, created_at')
    .single();

  if (error || !data) {
    state.profileForm = {
      ...state.profileForm,
      savingProfile: false,
      profileError: translateDatabaseError(error || 'No se pudo actualizar el perfil.'),
      profileFeedback: null,
    };
    render();
    return;
  }

  const updatedProfile = data as UserProfile;
  state.profile = updatedProfile;
  state.profileForm = {
    ...state.profileForm,
    nombreInput: updatedProfile.nombre,
    savingProfile: false,
    profileError: null,
    profileFeedback: 'Nombre actualizado correctamente.',
  };
  render();
}

async function handleUpdateOwnPassword(
  newPassword: string,
  confirmPassword: string
): Promise<void> {
  if (!state.user || !state.profile || state.profileForm.savingPassword) return;

  const validation = validatePasswordChangeInput(newPassword, confirmPassword);
  if (!validation.ok) {
    state.profileForm = {
      ...state.profileForm,
      newPasswordInput: newPassword,
      confirmPasswordInput: confirmPassword,
      passwordError: validation.error,
      passwordFeedback: null,
    };
    render();
    return;
  }

  state.profileForm = {
    ...state.profileForm,
    savingPassword: true,
    passwordError: null,
    passwordFeedback: null,
  };
  render();

  const { data, error } = await supabase.auth.updateUser({
    password: validation.password,
  });

  if (error) {
    state.profileForm = {
      ...state.profileForm,
      savingPassword: false,
      passwordError: translateDatabaseError(error),
      passwordFeedback: null,
    };
    render();
    return;
  }

  if (data.user) {
    state.user = data.user;
  }

  state.profileForm = {
    ...state.profileForm,
    savingPassword: false,
    newPasswordInput: '',
    confirmPasswordInput: '',
    passwordError: null,
    passwordFeedback: 'Contraseña actualizada correctamente.',
  };
  render();
}

function updateHealthCheck(id: string, patch: Partial<HealthCheckItem>): void {
  state.dbCheck.checks = state.dbCheck.checks.map((item) =>
    item.id === id ? { ...item, ...patch } : item
  );
  render();
}

async function runHealthChecks(): Promise<void> {
  if (!isApprovedAdmin() || !state.profile || state.dbCheck.running) return;

  const adminProfile = state.profile;
  state.dbCheck = {
    checks: createInitialChecks(),
    running: true,
    lastCheckedAt: state.dbCheck.lastCheckedAt,
  };
  render();

  // 1. Connection & Login Service
  const t1 = performance.now();
  try {
    const response = await fetch(`${SUPABASE_URL}/auth/v1/health`, {
      headers: {
        apikey: SUPABASE_ANON_KEY,
        Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      },
    });
    const ms1 = Math.round(performance.now() - t1);
    if (response.ok) {
      updateHealthCheck('connection', {
        state: 'pass',
        detail: 'Server online and accepting connections',
        durationMs: ms1,
      });
    } else {
      updateHealthCheck('connection', {
        state: 'fail',
        detail: `Server responded with status ${response.status}`,
        durationMs: ms1,
      });
    }
  } catch (err) {
    updateHealthCheck('connection', {
      state: 'fail',
      detail: translateDatabaseError(err),
      durationMs: Math.round(performance.now() - t1),
    });
  }

  // 2. Administrator Permissions
  const t2 = performance.now();
  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('id, nombre, role, status')
      .eq('id', adminProfile.id)
      .single();
    const ms2 = Math.round(performance.now() - t2);
    const access = evaluateAdminAccess(data as UserProfile | null);
    if (error || !access.allowed) {
      updateHealthCheck('admin', {
        state: 'fail',
        detail: error ? translateDatabaseError(error) : access.reason,
        durationMs: ms2,
      });
    } else {
      updateHealthCheck('admin', {
        state: 'pass',
        detail: `Verified ${data.nombre} (${data.role} · ${data.status})`,
        durationMs: ms2,
      });
    }
  } catch (err) {
    updateHealthCheck('admin', {
      state: 'fail',
      detail: translateDatabaseError(err),
      durationMs: Math.round(performance.now() - t2),
    });
  }

  // 3. Core Business Records
  let sampleCert: { id: string; numero_certificado: string } | null = null;
  const t3 = performance.now();
  try {
    const [orgsRes, certsRes, auditsRes, findingsRes, sampleCertRes] = await Promise.all([
      supabase.from('organizacion').select('id', { count: 'exact', head: true }).is('deleted_at', null),
      supabase.from('certificado').select('id', { count: 'exact', head: true }).is('deleted_at', null),
      supabase.from('auditoria').select('id', { count: 'exact', head: true }).is('deleted_at', null),
      supabase.from('hallazgo').select('id', { count: 'exact', head: true }).is('deleted_at', null),
      supabase.from('certificado').select('id, numero_certificado').is('deleted_at', null).limit(1).maybeSingle(),
    ]);
    const ms3 = Math.round(performance.now() - t3);

    const firstErr =
      orgsRes.error || certsRes.error || auditsRes.error || findingsRes.error || sampleCertRes.error;

    if (firstErr) {
      updateHealthCheck('records', {
        state: 'fail',
        detail: translateDatabaseError(firstErr),
        durationMs: ms3,
      });
    } else {
      sampleCert = sampleCertRes.data as { id: string; numero_certificado: string } | null;
      updateHealthCheck('records', {
        state: 'pass',
        detail: `${orgsRes.count ?? 0} organizations · ${certsRes.count ?? 0} certificates · ${auditsRes.count ?? 0} audits · ${findingsRes.count ?? 0} findings`,
        durationMs: ms3,
      });
    }
  } catch (err) {
    updateHealthCheck('records', {
      state: 'fail',
      detail: translateDatabaseError(err),
      durationMs: Math.round(performance.now() - t3),
    });
  }

  // 4. Standards & Coverage Engine
  const t4 = performance.now();
  try {
    const certId = sampleCert?.id || '00000000-0000-0000-0000-000000000000';
    const { data, error } = await supabase.rpc('cobertura_normativa_certificado', {
      p_id_certificado: certId,
    });
    const ms4 = Math.round(performance.now() - t4);

    if (error) {
      updateHealthCheck('coverage', {
        state: 'fail',
        detail: translateDatabaseError(error),
        durationMs: ms4,
      });
    } else {
      const count = Array.isArray(data) ? data.length : 0;
      updateHealthCheck('coverage', {
        state: 'pass',
        detail: sampleCert
          ? `Evaluated ${count} standard requirements for ${sampleCert.numero_certificado}`
          : 'Coverage calculation engine responded cleanly',
        durationMs: ms4,
      });
    }
  } catch (err) {
    updateHealthCheck('coverage', {
      state: 'fail',
      detail: translateDatabaseError(err),
      durationMs: Math.round(performance.now() - t4),
    });
  }

  // 5. Change History & Client Access
  const t5 = performance.now();
  try {
    const [logsRes, accessRes] = await Promise.all([
      supabase.from('audit_log').select('id', { count: 'exact', head: true }),
      supabase.from('client_organization_access').select('id', { count: 'exact', head: true }).is('deleted_at', null),
    ]);
    const ms5 = Math.round(performance.now() - t5);

    const err = logsRes.error || accessRes.error;
    if (err) {
      updateHealthCheck('governance', {
        state: 'fail',
        detail: translateDatabaseError(err),
        durationMs: ms5,
      });
    } else {
      updateHealthCheck('governance', {
        state: 'pass',
        detail: `${logsRes.count ?? 0} logged changes · ${accessRes.count ?? 0} client access records`,
        durationMs: ms5,
      });
    }
  } catch (err) {
    updateHealthCheck('governance', {
      state: 'fail',
      detail: translateDatabaseError(err),
      durationMs: Math.round(performance.now() - t5),
    });
  }

  state.dbCheck.running = false;
  state.dbCheck.lastCheckedAt = new Date().toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  });
  render();
}

// Close click-toggled dropdown when clicking outside header dropdown containers
document.addEventListener('click', (e) => {
  if (!state.openMenu) return;
  const target = e.target as HTMLElement | null;
  if (!target?.closest('[data-header-dropdown]')) {
    state.openMenu = null;
    render();
  }
});

// Global keyboard shortcuts: / to focus search, Escape to close modals/drawers/clear search
document.addEventListener('keydown', (e) => {
  // '/' shortcut to focus search input
  if (e.key === '/' && !['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName || '')) {
    const searchInput = (document.querySelector('[data-universal-search="true"]') ||
      document.getElementById('programacionSearchInput') ||
      document.getElementById('resultadoSearchInput') ||
      document.getElementById('auditorDirectorySearchInput') ||
      document.getElementById('certDirectorySearchInput') ||
      document.getElementById('certificateSearchInput')) as HTMLInputElement | null;
    if (searchInput) {
      e.preventDefault();
      searchInput.focus();
      searchInput.select();
      return;
    }
  }

  if (e.key !== 'Escape') return;

  if (state.archiveGovernance.modal.isOpen) {
    closeArchiveModal();
    return;
  }

  if (state.auditLogModal.isOpen) {
    closeAuditLogModal();
    return;
  }

  if (state.relacionDomain.pickerTargetGroupKey) {
    state.relacionDomain.pickerTargetGroupKey = null;
    render();
    return;
  }

  if (state.resultadoDomain.isNcOffsetsModalOpen) {
    state.resultadoDomain.isNcOffsetsModalOpen = false;
    state.resultadoDomain.isEditingAlertOffsets = false;
    state.resultadoDomain.alertOffsetError = null;
    render();
    return;
  }

  if (state.resultadoDomain.inspectingFindingId) {
    state.resultadoDomain.inspectingFindingId = null;
    render();
    return;
  }

  if (state.designacionFechaDomain.editorMode !== null) {
    state.designacionFechaDomain.editorMode = null;
    state.designacionFechaDomain.editingLocalId = null;
    state.designacionFechaDomain.editorDraft = null;
    state.designacionFechaDomain.editErrorMessage = null;
    render();
    return;
  }

  if (
    state.designacionSitioDomain.coverageModalCertId !== null ||
    state.designacionSitioDomain.coverageModalAuditId !== null
  ) {
    state.designacionSitioDomain.coverageModalCertId = null;
    state.designacionSitioDomain.coverageModalAuditId = null;
    state.designacionSitioDomain.coverageWindowOffset = 0;
    state.designacionSitioDomain.editErrorMessage = null;
    render();
    return;
  }

  if (state.calendarioDomain.isAlertConfigModalOpen) {
    state.calendarioDomain.isAlertConfigModalOpen = false;
    state.calendarioDomain.alertConfigError = null;
    render();
    return;
  }

  if (state.calendarioDomain.drawerAuditId) {
    state.calendarioDomain.drawerAuditId = null;
    render();
    return;
  }

  if (
    document.activeElement?.id === 'certificateSearchInput' ||
    (document.activeElement instanceof HTMLElement &&
      document.activeElement.dataset.universalSearch === 'true')
  ) {
    (document.activeElement as HTMLElement).blur();
    return;
  }

  if (state.openMenu) {
    state.openMenu = null;
    if (document.activeElement instanceof HTMLElement && document.activeElement.closest('header')) {
      document.activeElement.blur();
    }
    render();
    return;
  }

  if (document.activeElement instanceof HTMLElement && document.activeElement.closest('[data-header-dropdown]')) {
    document.activeElement.blur();
    return;
  }

  if (state.auth.resetModalOpen && !state.auth.resettingDb) {
    state.auth = {
      ...state.auth,
      resetModalOpen: false,
      resetErrorMessage: null,
    };
    render();
  }
});

// History and Hash Navigation: Instant client-side route switching without page reloads
window.addEventListener('hashchange', () => {
  const { route, subview } = parseHashRoute();
  if (canAccessRoute(state.profile, route)) {
    if (state.activeRoute !== route || state.activeSubSection !== subview) {
      state.activeRoute = route;
      state.activeSubSection = subview;
      state.openMenu = null;
      state.breadcrumbs = resetBreadcrumbToDomain(route, subview);
      if (route === 'profile') {
        state.profileForm = {
          ...state.profileForm,
          nombreInput: state.profile?.nombre || '',
          profileFeedback: null,
          profileError: null,
          passwordFeedback: null,
          passwordError: null,
        };
      }
      render();
      if (route === 'approvals' && isApprovedStaff()) {
        void loadApprovalProfiles();
      } else if (route === 'database' && isApprovedAdmin() && state.dbCheck.lastCheckedAt === null) {
        void runHealthChecks();
      }
    }
  }
});

window.addEventListener('popstate', () => {
  const { route, subview } = parseHashRoute();
  if (canAccessRoute(state.profile, route)) {
    if (state.activeRoute !== route || state.activeSubSection !== subview) {
      state.activeRoute = route;
      state.activeSubSection = subview;
      state.openMenu = null;
      state.breadcrumbs = resetBreadcrumbToDomain(route, subview);
      if (route === 'profile') {
        state.profileForm = {
          ...state.profileForm,
          nombreInput: state.profile?.nombre || '',
          profileFeedback: null,
          profileError: null,
          passwordFeedback: null,
          passwordError: null,
        };
      }
      render();
    }
  }
});

// Supabase Auth State Change Listener
supabase.auth.onAuthStateChange((event, session) => {
  if (event === 'SIGNED_OUT') {
    resetClientSessionState();
  } else if (
    (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'USER_UPDATED') &&
    !isSigningOut
  ) {
    if (session?.user && state.user?.id !== session.user.id) {
      void loadUserSession(session.user);
    }
  }
});

async function init(): Promise<void> {
  const initialNav = parseHashRoute();
  state.activeRoute = initialNav.route;
  state.activeSubSection = initialNav.subview;
  render();
  try {
    const { data } = await supabase.auth.getSession();
    if (!state.user && !isSigningOut) {
      await loadUserSession(data.session?.user ?? null);
    }
  } catch (err) {
    console.warn('Failed restoring initial session:', err);
    state.booting = false;
    state.user = null;
    state.profile = null;
    render();
  }
}

void init();
